const PRODUCTS_DEFAULT_PERIOD_DAYS = 7
const PRODUCTS_PERIOD_MAX_DAYS = 90
const PRODUCTS_PERIOD_STORAGE_KEY = 'vella.products.analyticsPeriod'
const DAY_MS = 24 * 60 * 60 * 1000
const ALGORITHM_PRICE_STEP_MAX_PCT = 50
const REPRICER_STATS_PAGE_SIZE = 500
const REPRICER_STATS_MAX_ROWS = 5000
const DIGEST_MAX_DIRECT_DAYS = 14
const DIGEST_FALLBACK_CHUNK_DAYS = 7
const DIGEST_FALLBACK_MAX_ATTEMPTS = 20
void DIGEST_MAX_DIRECT_DAYS
void DIGEST_FALLBACK_CHUNK_DAYS

type ProductsAnalyticsPeriodMode = 'preset' | 'custom'

type ProductsAnalyticsPeriodState = {
  days: number
  fromIso: string
  toIso: string
  label: string
  mode: ProductsAnalyticsPeriodMode
}

type ReportPeriodKey = 'digest' | 'repricer-stats' | 'abc' | 'rnp' | 'pnl' | 'expenses' | 'ads' | 'stock' | 'week'

const REPORT_PERIOD_STORAGE_PREFIX = 'vella.reports.analyticsPeriod.'
const REPORT_PERIOD_EVENT = 'vella:report-period-updated'
const WB_REPORT_PERIOD_KEYS: ReportPeriodKey[] = ['digest', 'repricer-stats', 'abc', 'rnp', 'pnl', 'expenses', 'ads', 'stock', 'week']

function startOfLocalDay(date: Date) {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate())
}

function addLocalDays(date: Date, days: number) {
  const next = startOfLocalDay(date)
  next.setDate(next.getDate() + days)
  return next
}

function toLocalIsoDate(date: Date) {
  const local = startOfLocalDay(date)
  const year = local.getFullYear()
  const month = String(local.getMonth() + 1).padStart(2, '0')
  const day = String(local.getDate()).padStart(2, '0')
  return `${year}-${month}-${day}`
}

function clampDateFromNotFuture(value: string | undefined, fallbackIso: string) {
  const todayIso = toLocalIsoDate(new Date())
  const fallback = /^\d{4}-\d{2}-\d{2}$/.test(fallbackIso) && fallbackIso <= todayIso ? fallbackIso : todayIso
  const normalized = String(value || '').slice(0, 10)
  if (!/^\d{4}-\d{2}-\d{2}$/.test(normalized)) return fallback
  return normalized > todayIso ? fallback : normalized
}

function fromLocalIsoDate(value: string | undefined) {
  if (!value) return null
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value)
  if (!match) return null
  const date = new Date(Number(match[1]), Number(match[2]) - 1, Number(match[3]))
  return Number.isNaN(date.getTime()) ? null : date
}

function dateIsoDaysBetween(fromIso: string, toIso: string) {
  const fromDate = fromLocalIsoDate(fromIso)
  const toDate = fromLocalIsoDate(toIso)
  if (!fromDate || !toDate) return 0
  return Math.max(1, Math.floor((toDate.getTime() - fromDate.getTime()) / DAY_MS) + 1)
}

function chunkDateRanges(fromIso: string, toIso: string, maxDays: number) {
  const rangeFrom = fromLocalIsoDate(fromIso)
  const rangeTo = fromLocalIsoDate(toIso)
  if (!rangeFrom || !rangeTo || maxDays <= 0) {
    return [{ fromIso, toIso }]
  }
  const safeMaxDays = Math.max(1, Math.floor(maxDays))
  const totalDays = Math.max(1, Math.floor((rangeTo.getTime() - rangeFrom.getTime()) / DAY_MS) + 1)
  if (totalDays <= safeMaxDays) return [{ fromIso, toIso }]

  const chunks: Array<{ fromIso: string; toIso: string }> = []
  let cursor = rangeFrom
  while (cursor <= rangeTo && chunks.length < DIGEST_FALLBACK_MAX_ATTEMPTS) {
    const chunkTo = new Date(
      Math.min(rangeTo.getTime(), cursor.getTime() + (safeMaxDays - 1) * DAY_MS),
    )
    chunks.push({
      fromIso: toLocalIsoDate(cursor),
      toIso: toLocalIsoDate(chunkTo),
    })
    cursor = new Date(cursor.getTime() + safeMaxDays * DAY_MS)
  }
  return chunks
}

function parseReportNumber(value: unknown): number | null {
  if (typeof value === 'number' && Number.isFinite(value)) return value
  if (typeof value !== 'string') return null
  const match = value.match(/-?\d+(?:[.,]\d+)?/)
  if (!match) return null
  const normalized = match[0].replace(/\s/g, '').replace(',', '.')
  const parsed = Number(normalized)
  return Number.isFinite(parsed) ? parsed : null
}

function clampProductsPeriodDays(value: number) {
  if (!Number.isFinite(value)) return PRODUCTS_DEFAULT_PERIOD_DAYS
  return Math.max(1, Math.min(PRODUCTS_PERIOD_MAX_DAYS, Math.round(value)))
}

function productsPeriodAnchorIso() {
  return lastClosedWbDay()
}

function productsPeriodStartIso(days: number) {
  return resolvePresetPeriodRange(clampProductsPeriodDays(days)).dateFrom
}

function productsPeriodDaysFromRange(fromIso: string, toIso = productsPeriodAnchorIso()) {
  const anchor = fromLocalIsoDate(productsPeriodAnchorIso()) ?? startOfLocalDay(new Date())
  const earliest = addLocalDays(anchor, -(PRODUCTS_PERIOD_MAX_DAYS - 1))
  const parsedTo = fromLocalIsoDate(toIso) ?? anchor
  const boundedTo = parsedTo > anchor ? anchor : parsedTo
  const minForTo = addLocalDays(boundedTo, -(PRODUCTS_PERIOD_MAX_DAYS - 1))
  const parsedFrom = fromLocalIsoDate(fromIso) ?? boundedTo
  const lowerBound = minForTo < earliest ? earliest : minForTo
  const boundedFrom = parsedFrom > boundedTo ? boundedTo : parsedFrom < lowerBound ? lowerBound : parsedFrom
  const days = clampProductsPeriodDays(Math.floor((boundedTo.getTime() - boundedFrom.getTime()) / DAY_MS) + 1)
  return { days, fromIso: toLocalIsoDate(boundedFrom), toIso: toLocalIsoDate(boundedTo) }
}

function formatProductsPeriodDate(fromIso: string) {
  const date = fromLocalIsoDate(fromIso)
  if (!date) return ''
  return date.toLocaleDateString('ru-RU', { day: '2-digit', month: '2-digit' })
}

function makeProductsPeriodLabel(days: number, fromIso: string, toIso: string) {
  const normalizedDays = clampProductsPeriodDays(days)
  const anchorIso = productsPeriodAnchorIso()
  const fromLabel = formatProductsPeriodDate(fromIso)
  const toLabel = toIso === anchorIso ? 'вчера' : formatProductsPeriodDate(toIso)
  return normalizedDays === 1
    ? (toIso === anchorIso ? 'вчера' : fromLabel)
    : `с ${fromLabel} по ${toLabel} · ${normalizedDays} дн`
}

function createProductsPeriodState(
  days: number,
  mode: ProductsAnalyticsPeriodMode,
  fromIso = productsPeriodStartIso(days),
  toIso = productsPeriodAnchorIso(),
): ProductsAnalyticsPeriodState {
  const range = mode === 'custom'
    ? productsPeriodDaysFromRange(fromIso, toIso)
    : productsPeriodDaysFromRange(productsPeriodStartIso(days), productsPeriodAnchorIso())
  const normalizedDays = range.days
  return {
    days: normalizedDays,
    fromIso: range.fromIso,
    toIso: range.toIso,
    label: makeProductsPeriodLabel(normalizedDays, range.fromIso, range.toIso),
    mode,
  }
}

function readProductsPeriodState(): ProductsAnalyticsPeriodState {
  if (typeof window === 'undefined') {
    return createProductsPeriodState(PRODUCTS_DEFAULT_PERIOD_DAYS, 'preset')
  }
  const stored = (() => {
    try {
      return JSON.parse(window.localStorage.getItem(PRODUCTS_PERIOD_STORAGE_KEY) ?? '{}') as Partial<ProductsAnalyticsPeriodState>
    } catch {
      return {}
    }
  })()
  const mode = window.__vellaProductsPeriodMode ?? stored.mode ?? 'preset'
  const days = clampProductsPeriodDays(window.__vellaProductsPeriodDays ?? stored.days ?? PRODUCTS_DEFAULT_PERIOD_DAYS)
  const fromIso = window.__vellaProductsPeriodFromIso ?? stored.fromIso ?? productsPeriodStartIso(days)
  const toIso = window.__vellaProductsPeriodToIso ?? stored.toIso ?? productsPeriodAnchorIso()
  return createProductsPeriodState(days, mode, fromIso, toIso)
}

function reportPeriodKeyForTab(tab: string | null | undefined): ReportPeriodKey | null {
  if (tab === 'digest' || tab === 'repricer-stats' || tab === 'abc' || tab === 'rnp' || tab === 'pnl' || tab === 'expenses' || tab === 'ads' || tab === 'stock' || tab === 'week') {
    return tab
  }
  return null
}

function reportPeriodEventMatches(event: Event | undefined, reportKey: ReportPeriodKey) {
  if (!(event instanceof CustomEvent)) return true
  const eventKey = event.detail?.reportKey
  return eventKey === reportKey || eventKey === 'all'
}

function readReportPeriodState(reportKey: ReportPeriodKey): ProductsAnalyticsPeriodState {
  if (typeof window === 'undefined') {
    return createProductsPeriodState(PRODUCTS_DEFAULT_PERIOD_DAYS, 'preset')
  }
  const runtime = window.__vellaReportPeriods?.[reportKey]
  if (runtime) return createProductsPeriodState(runtime.days, runtime.mode, runtime.fromIso, runtime.toIso)
  const stored = (() => {
    try {
      return JSON.parse(window.localStorage.getItem(`${REPORT_PERIOD_STORAGE_PREFIX}${reportKey}`) ?? '{}') as Partial<ProductsAnalyticsPeriodState>
    } catch {
      return {}
    }
  })()
  if (stored.fromIso && stored.toIso) {
    return createProductsPeriodState(stored.days ?? dateIsoDaysBetween(stored.fromIso, stored.toIso), stored.mode ?? 'custom', stored.fromIso, stored.toIso)
  }
  return createProductsPeriodState(PRODUCTS_DEFAULT_PERIOD_DAYS, 'preset')
}

function applyReportPeriodState(reportKey: ReportPeriodKey, next: ProductsAnalyticsPeriodState, options: { silent?: boolean } = {}) {
  window.__vellaReportPeriods = { ...(window.__vellaReportPeriods ?? {}), [reportKey]: next }
  window.__vellaReportPeriodManual = { ...(window.__vellaReportPeriodManual ?? {}), [reportKey]: !options.silent }
  try {
    window.localStorage.setItem(`${REPORT_PERIOD_STORAGE_PREFIX}${reportKey}`, JSON.stringify(next))
  } catch {
    // localStorage can be blocked in private or embedded contexts.
  }
  window.dispatchEvent(new CustomEvent(REPORT_PERIOD_EVENT, { detail: { reportKey, period: next } }))
  if (!options.silent) window.showToast?.(`Период отчета применён: ${next.label}`, 'info')
}

function applyAllWbReportPeriodStates(next: ProductsAnalyticsPeriodState) {
  applyProductsPeriodState(next)
  const nextPeriods = { ...(window.__vellaReportPeriods ?? {}) }
  const nextManual = { ...(window.__vellaReportPeriodManual ?? {}) }
  for (const reportKey of WB_REPORT_PERIOD_KEYS) {
    nextPeriods[reportKey] = next
    nextManual[reportKey] = true
    try {
      window.localStorage.setItem(`${REPORT_PERIOD_STORAGE_PREFIX}${reportKey}`, JSON.stringify(next))
    } catch {
      // localStorage can be blocked in private or embedded contexts.
    }
  }
  window.__vellaReportPeriods = nextPeriods
  window.__vellaReportPeriodManual = nextManual
  const activeReport = reportPeriodKeyForTab(resolveParityRouteTarget(window.location.pathname, window.location.search).tab)
  if (activeReport) {
    window.dispatchEvent(new CustomEvent(REPORT_PERIOD_EVENT, { detail: { reportKey: activeReport, period: next } }))
  }
}

function reportCacheMissingMessage(period: Pick<ProductsAnalyticsPeriodState, 'fromIso' | 'toIso' | 'label'>) {
  return `За период ${period.label} данных пока нет. Выберите доступные даты в календаре данных.`
}

function digestWaitingMessageFromWbState(
  syncStatus?: LiveRepricerSyncStatus | null,
  snapshotsStatus?: LiveRepricerReportSnapshotsStatus | null,
) {
  const syncRecord = (syncStatus ?? {}) as Record<string, unknown>
  const syncSteps = Array.isArray(syncRecord.steps) ? syncRecord.steps as Array<Record<string, unknown>> : []
  const activeStep = syncSteps.find((step) => {
    const status = String(step.status ?? step.state ?? '').toLowerCase()
    return ['running', 'queued', 'retrying', 'pending'].includes(status)
  })
  const activeSource = String(activeStep?.source ?? syncRecord.currentSource ?? syncRecord.source ?? '').toLowerCase()
  const activeMessage = String(activeStep?.message ?? syncRecord.message ?? syncRecord.label ?? '')
  const snapshotRecord = (snapshotsStatus ?? {}) as Record<string, unknown>
  const snapshotState = String(snapshotRecord.state ?? '').toLowerCase()
  const snapshotStage = String(snapshotRecord.stage ?? '').toLowerCase()
  const snapshotLabel = String(snapshotRecord.label ?? snapshotRecord.message ?? '')
  const missingSources = Array.isArray(snapshotRecord.missingSources)
    ? snapshotRecord.missingSources.map(String)
    : []
  const waitingSnapshots = ['queued', 'running', 'waiting_daily_detail', 'waiting_baskets_detail'].includes(snapshotState)
    || ['queued', 'running', 'waiting_daily_detail', 'waiting_baskets_detail'].includes(snapshotStage)
  const waitingBaskets = activeSource.includes('basket')
    || activeMessage.toLowerCase().includes('корзин')
    || snapshotLabel.toLowerCase().includes('корзин')
    || missingSources.includes('baskets')

  if (waitingBaskets) {
    return 'Воронка продаж ждёт корзины WB: сейчас загружаются дневные данные за выбранный период. Остальные отчёты доступны из готового кэша.'
  }
  if (waitingSnapshots) {
    return 'Воронка продаж ждёт сборку отчёта: данные WB уже загружаются, экран обновится автоматически.'
  }
  return null
}

function dateRangeToReportPeriod(dateRange: unknown): ProductsAnalyticsPeriodState | null {
  if (!dateRange || typeof dateRange !== 'object') return null
  const range = dateRange as { from?: unknown; to?: unknown }
  const fromIso = typeof range.from === 'string' ? range.from.slice(0, 10) : ''
  const toIso = typeof range.to === 'string' ? range.to.slice(0, 10) : ''
  if (!fromLocalIsoDate(fromIso) || !fromLocalIsoDate(toIso)) return null
  const days = dateIsoDaysBetween(fromIso, toIso)
  return createProductsPeriodState(days, 'custom', fromIso, toIso)
}

function applyReportPeriodFromPayload(reportKey: ReportPeriodKey, payload: unknown) {
  const reportPayload = payload as { filters?: { dateRange?: unknown }; cache?: { requestedRange?: unknown } } | null | undefined
  const next = dateRangeToReportPeriod(reportPayload?.filters?.dateRange) ?? dateRangeToReportPeriod(reportPayload?.cache?.requestedRange)
  if (!next) return null
  const current = readReportPeriodState(reportKey)
  if (current.fromIso !== next.fromIso || current.toIso !== next.toIso) {
    applyReportPeriodState(reportKey, next, { silent: true })
  }
  return next
}

function applyRepricerStatsCachePeriod(payload: LiveRepricerStatsResponse | null | undefined) {
  if (!payload) return null
  const rangePayload = payload.cache?.statsRangeAdjusted
    ? payload.cache?.statsSourceRange
    : { from: payload.dateFrom, to: payload.dateTo }
  const next = dateRangeToReportPeriod(rangePayload)
  if (!next) return null
  const current = readReportPeriodState('repricer-stats')
  if (current.fromIso !== next.fromIso || current.toIso !== next.toIso || current.mode !== next.mode) {
    applyReportPeriodState('repricer-stats', next, { silent: true })
    if (payload.cache?.statsRangeAdjusted) {
      window.showToast?.(`Статистика репрайсера показана из кэша: ${next.label}`, 'info')
    }
  }
  return next
}

function syncLegacyWbPeriodRuntime(next: ProductsAnalyticsPeriodState) {
  const legacyPeriod = next.mode === 'preset' && [1, 7, 14, 30].includes(next.days)
    ? String(next.days)
    : 'custom'
  const label = next.label
  const activeTab = resolveParityRouteTarget(window.location.pathname, window.location.search).tab
  const productsActive = shouldLoadPeriodSurface(activeTab, 'products')
  const abcActive = activeTab === 'abc'
  window.eval?.(`
    (function(){
      if (typeof currentPeriod !== 'undefined') currentPeriod = ${JSON.stringify(legacyPeriod)};
      document.querySelectorAll('[data-period-control] .period-btn').forEach(function(btn){
        btn.classList.toggle('active', btn.dataset.period === ${JSON.stringify(legacyPeriod)});
      });
      document.querySelectorAll('[data-period-copy]').forEach(function(el){
        el.textContent = ${JSON.stringify(label)};
      });
      if (${JSON.stringify(productsActive)} && typeof renderTable === 'function') renderTable();
      if (${JSON.stringify(abcActive)} && typeof renderAbcDemoRows === 'function') renderAbcDemoRows();
    })();
  `)
}

function applyProductsPeriodState(next: ProductsAnalyticsPeriodState) {
  window.__vellaProductsPeriodDays = next.days
  window.__vellaProductsPeriodFromIso = next.fromIso
  window.__vellaProductsPeriodToIso = next.toIso
  window.__vellaProductsPeriodLabel = next.label
  window.__vellaProductsPeriodMode = next.mode
  window.__vellaProductsListState = { ...(window.__vellaProductsListState ?? {}), page: 1 }
  try {
    window.localStorage.setItem(PRODUCTS_PERIOD_STORAGE_KEY, JSON.stringify(next))
  } catch {
    // localStorage can be blocked in private or embedded contexts.
  }
  resetLiveRepricerParityCache()
  syncLegacyWbPeriodRuntime(next)
  window.dispatchEvent(new CustomEvent('vella:products-period-updated', { detail: next }))
  const activeTab = resolveParityRouteTarget(window.location.pathname, window.location.search).tab
  if (shouldLoadPeriodSurface(activeTab, 'products')) {
    void window.__vellaLoadLiveRepricerProducts?.()
  }
}

function productsCoverageStateLabel(state: string | null | undefined) {
  if (state === 'complete') return 'есть все источники'
  if (state === 'partial') return 'есть часть источников'
  return 'нет данных'
}

function monthStartIso(value: string | undefined) {
  const date = fromLocalIsoDate(value) ?? new Date()
  return toLocalIsoDate(new Date(date.getFullYear(), date.getMonth(), 1))
}

function addIsoMonths(monthIso: string, months: number) {
  const date = fromLocalIsoDate(monthIso) ?? new Date()
  return toLocalIsoDate(new Date(date.getFullYear(), date.getMonth() + months, 1))
}

function formatProductsCalendarMonth(monthIso: string) {
  const date = fromLocalIsoDate(monthIso)
  return date
    ? date.toLocaleDateString('ru-RU', { month: 'long', year: 'numeric' })
    : ''
}

function productsPeriodRequest(): LiveRepricerPeriodRequest {
  const state = readProductsPeriodState()
  return {
    periodDays: state.days,
    dateFrom: state.fromIso,
    dateTo: state.toIso,
  }
}

function repricerStatsPeriodRequest(): LiveRepricerPeriodRequest {
  const state = readReportPeriodState('repricer-stats')
  return {
    periodDays: state.days,
    dateFrom: state.fromIso,
    dateTo: state.toIso,
  }
}

function installReactLegacyDomMutationGuard() {
  if (typeof window === 'undefined' || typeof Node === 'undefined') return
  const guardedWindow = window as Window & {
    __vellaReactLegacyDomMutationGuardInstalled?: boolean
  }
  if (guardedWindow.__vellaReactLegacyDomMutationGuardInstalled) return
  guardedWindow.__vellaReactLegacyDomMutationGuardInstalled = true

  const originalRemoveChild = Node.prototype.removeChild
  const originalInsertBefore = Node.prototype.insertBefore
  const guardedRemoveChild = function <T extends Node>(this: Node, child: T): T {
    if (child.parentNode === this) return originalRemoveChild.call(this, child) as T
    if (child.parentNode) {
      try {
        return originalRemoveChild.call(child.parentNode, child) as T
      } catch {
        return child
      }
    }
    return child
  }
  Node.prototype.removeChild = guardedRemoveChild as typeof Node.prototype.removeChild
  const guardedInsertBefore = function <T extends Node>(this: Node, newNode: T, referenceNode: Node | null): T {
    if (referenceNode === null || referenceNode.parentNode === this) {
      return originalInsertBefore.call(this, newNode, referenceNode) as T
    }
    return originalInsertBefore.call(this, newNode, null) as T
  }
  Node.prototype.insertBefore = guardedInsertBefore as typeof Node.prototype.insertBefore
}

installReactLegacyDomMutationGuard()

