function settingsAccessInitialsFromName(name: string, email: string) {
  const parts = name.split(/\s+/).map((part) => part.trim()).filter(Boolean)
  if (parts.length > 0) return parts.slice(0, 2).map((part) => part[0]?.toUpperCase() ?? '').join('')
  return settingsAccessInitialsFromEmail(email)
}

function settingsAccessModulesFromPermissions(permissions: string[]) {
  const modules = new Set<string>()
  if (permissions.includes('settings:read') || permissions.includes('price:send')) modules.add('repricer')
  if (permissions.includes('settings:read') || permissions.includes('finance:read')) modules.add('reports')
  if (permissions.includes('reviews:read') || permissions.includes('reviews:write')) modules.add('reviews')
  if (permissions.includes('integrations:read')) modules.add('avito')
  if (permissions.includes('finance:read')) modules.add('reports')
  return Array.from(modules)
}

function settingsAccessRightsFromPermissions(permissions: string[]) {
  const rights = new Set<string>()
  if (permissions.includes('finance:read')) rights.add('finance')
  if (permissions.includes('price:send')) rights.add('price_send')
  if (permissions.includes('team:write') || permissions.includes('settings:activate')) rights.add('admin')
  return Array.from(rights)
}

function mapBackendAccessUser(user: SettingsUserAccessProfile): SettingsAccessUser {
  const permissions = user.permissions ?? []
  return {
    id: user.id,
    name: user.name,
    initials: user.initials || settingsAccessInitialsFromName(user.name, user.email),
    email: user.email,
    role: PERMISSION_PROFILE_TO_SETTINGS_ROLE[user.permissionProfile] ?? 'viewer',
    status: user.status === 'active' ? 'active' : 'invited',
    last: user.lastActiveAt || 'активен',
    access: {
      modules: settingsAccessModulesFromPermissions(permissions),
      rights: settingsAccessRightsFromPermissions(permissions),
    },
    scopes: user.scopes.map((scope) => ({
      marketplace: scope.marketplace === 'wb' ? 'WB' : 'Avito',
      status: scope.status,
      modules: [...scope.modules],
      accounts: [...scope.accountIds],
      permissions: [...scope.dangerousPermissions],
    })),
  }
}

function shortNameFromFullName(name: string) {
  const parts = name.split(/\s+/).map((part) => part.trim()).filter(Boolean)
  if (parts.length <= 1) return name
  return `${parts[0]} ${parts[1]?.[0] ?? ''}.`.trim()
}

function managersFromAccessUsers(users: SettingsAccessUser[]): RuntimeManager[] {
  return users
    .filter((user) => user.status === 'active')
    .filter((user) => user.role === 'admin' || user.role === 'manager' || user.access.rights.includes('price_send'))
    .map((user) => ({
      id: user.id,
      code: user.initials || settingsAccessInitialsFromName(user.name, user.email),
      name: user.name,
      shortName: shortNameFromFullName(user.name),
      active: true,
      planRub: null,
    }))
}

function backendPasswordForInvite(email: string) {
  const random = Math.random().toString(36).slice(2, 10)
  const checksum = Math.abs(email.split('').reduce((acc, char) => acc + char.charCodeAt(0), 0)) % 100
  return `Team${random}${checksum}!`
}

function publishRuntimeManagersToVella(users: SettingsAccessUser[], currentManagerId: string) {
  const managers = managersFromAccessUsers(users)
  try {
    window.eval?.(`
      (function(){
        if (typeof MANAGERS === 'undefined' || typeof MANAGER_BY_ID === 'undefined' || typeof MANAGER_BY_CODE === 'undefined' || typeof MGR_NAMES === 'undefined') return;
        const nextManagers = ${JSON.stringify(managers)};
        MANAGERS.splice(0, MANAGERS.length, ...nextManagers);
        Object.keys(MANAGER_BY_ID).forEach(function(key){ delete MANAGER_BY_ID[key]; });
        Object.keys(MANAGER_BY_CODE).forEach(function(key){ delete MANAGER_BY_CODE[key]; });
        Object.keys(MGR_NAMES).forEach(function(key){ delete MGR_NAMES[key]; });
        MANAGERS.forEach(function(manager){
          MANAGER_BY_ID[manager.id] = manager;
          MANAGER_BY_CODE[manager.code] = manager;
          MGR_NAMES[manager.code] = manager.name;
        });
        managerFilterMatches = function(rowManagerId, filter){
          if (!filter || filter === 'all') return true;
          if (filter === 'mine') return rowManagerId === ${JSON.stringify(currentManagerId)};
          if (filter === 'unassigned') return !rowManagerId;
          return rowManagerId === filter;
        };
        if (typeof renderTable === 'function') renderTable();
        if (typeof renderAbcDemoRows === 'function') renderAbcDemoRows();
        window.dispatchEvent(new CustomEvent('vella:products-managers-updated'));
      })()
    `)
  } catch (error) {
    console.warn('Failed to publish backend managers to Vella runtime', error)
  }
}

function resolveParityRouteTarget(pathname: string, search: string) {
  const params = new URLSearchParams(search)
  const routePathname = pathname.replace(/^\/internal\/vella-parity(?=\/|$)/, '') || '/'
  const routeState = routeStateFromPath(routePathname, search)
  const routeTab = typeof routeState === 'string' ? routeState : routeState.tab
  const routeMode = typeof routeState === 'string' ? 'now' : routeState.mode
  const skuMatch = routePathname.match(/\/repricer\/sku\/([^/?#]+)/)
  return {
    tab: params.get('tab') || routeTab,
    mode: params.get('mode') === 'period' ? 'period' : routeMode,
    sku: params.get('sku') || (skuMatch ? decodeURIComponent(skuMatch[1]) : null),
  }
}

function isCanonicalProductsRoute(pathname: string) {
  const routePathname = pathname.replace(/^\/internal\/vella-parity(?=\/|$)/, '') || '/'
  const normalized = routePathname.replace(/\/$/, '') || '/'
  if (normalized === '/wb/repricer') return true
  if (normalized === '/internal/vella-preview/repricer') return true
  return /\/repricer\/sku\/[^/?#]+$/.test(normalized)
}

const WB_REPORT_PERIOD_TABS = new Set(['digest', 'repricer-stats', 'report-rules', 'abc', 'rnp', 'pnl', 'expenses', 'ads', 'stock', 'week'])

function usesLiveWbPeriodControl(tab: string) {
  return tab === 'products' || WB_REPORT_PERIOD_TABS.has(tab)
}

function routePinnedReportTab() {
  if (typeof window === 'undefined') return null
  const tab = resolveParityRouteTarget(window.location.pathname, window.location.search).tab
  return WB_REPORT_PERIOD_TABS.has(tab) ? tab : null
}

function routeSafeTabFromEvent(nextTab: string) {
  const pinnedTab = routePinnedReportTab()
  if (pinnedTab && nextTab !== pinnedTab) {
    window._goSubtabSilent?.(pinnedTab, { preserveDigestMode: true })
    return pinnedTab
  }
  return nextTab
}

