function hasProductsPeriodData(result?: { products?: unknown[]; total?: number; summary?: LiveRepricerSkuListSummary; cache?: Window['__vellaProductsCacheMeta'] }) {
  const summary = result?.summary ?? window.__vellaProductsSummary
  const summaryRecord = (summary ?? {}) as Record<string, unknown>
  const cache = result?.cache ?? window.__vellaProductsCacheMeta
  const periodMetricKeys = [
    'revenueKopecks',
    'marginKopecks',
    'cogsKopecks',
    'expensesKopecks',
    'ordersUnits',
    'salesUnits',
    'returnsUnits',
    'adSpendKopecks',
    'adImpressions',
    'adClicks',
    'adCartAdds',
    'adOrders',
    'adRevenueKopecks',
    'totalBaskets',
  ]
  if (periodMetricKeys.some((key) => productNumber(summaryRecord, key) > 0)) return true
  if (Number(cache?.basketsMatchedNmIds ?? 0) > 0) return true
  if (Number(cache?.financeMatchedNmIds ?? 0) > 0) return true
  if (Number(cache?.adsSpendKopecks ?? 0) > 0) return true
  if (Number(cache?.adsCount ?? 0) > 0 || Number(cache?.adsCampaignCount ?? 0) > 0) return true

  const products = Array.isArray(result?.products) && result.products.length
    ? result.products
    : Array.isArray(window.PRODUCTS)
      ? window.PRODUCTS
      : []
  return products.some((product) => {
    if (!product || typeof product !== 'object') return false
    const record = product as Record<string, unknown>
    const analytics = record.analytics && typeof record.analytics === 'object'
      ? record.analytics as Record<string, unknown>
      : null
    if (String(record.financeState ?? analytics?.financeState ?? 'no_data') !== 'no_data') return true
    return productNumber(record, 'bsk') > 0
      || productNumber(record, 'ordersPeriod') > 0
      || productNumber(record, 'salesUnits') > 0
      || productNumber(record, 'revenue') > 0
      || productNumber(record, 'adSpend') > 0
      || (analytics != null && (
        productNumber(analytics, 'baskets') > 0
        || productNumber(analytics, 'ordersUnits') > 0
        || productNumber(analytics, 'salesUnits') > 0
        || productNumber(analytics, 'revenueKopecks') > 0
        || productNumber(analytics, 'adSpendKopecks') > 0
      ))
  })
}

