function renderReviewApprovalGuardDom(review: VellaReview | undefined) {
  const el = document.getElementById('reviewApprovalGuard')
  if (!el) return
  const hasDraft = Boolean(review?.draftId)
  const isBlocked = !hasDraft || review?.status === 'blocked' || review?.status === 'error'
  el.className = `review-approval-guard ${isBlocked ? 'blocked' : 'ok'}`
  el.dataset.reviewCanApprove = hasDraft ? 'true' : 'false'
  el.dataset.reviewCanSend = hasDraft ? 'true' : 'false'
  el.innerHTML = `
    <div class="review-approval-guard-top">
      <div class="review-approval-guard-title">${hasDraft ? 'Черновик готов к ручному решению' : 'Сначала сгенерируйте черновик'}</div>
      <span class="review-approval-guard-state">${hasDraft ? 'draft-only' : 'нет draft'}</span>
    </div>
    <div class="review-approval-guard-meta">${hasDraft ? 'Ответ остается внутри сервиса; live-отправка в WB отключена backend policy.' : 'Данные отзыва загружены с бэка, но AI-ответ еще не создан.'}</div>
  `
}

function openBackendReviewDrawer(review: VellaReview) {
  window.__vellaCurrentReviewId = review.id
  setReviewText('reviewDrawerSku', `${review.sku} · ${review.nm}`)
  setReviewText('reviewDrawerTitle', review.product)
  setReviewText('reviewDrawerMeta', `${review.brand} · ${review.rating} звезд · ${review.age}`)
  setReviewText('reviewDrawerStars', reviewStars(review.rating))
  setReviewText('reviewDrawerText', review.text || 'Покупатель оставил оценку без текста.')
  setReviewText('reviewDrawerMedia', review.media)
  setReviewText('reviewDrawerProduct', `${review.product} · ${review.size}`)
  setReviewText('reviewDrawerNm', `SKU ${review.sku} · nmId ${review.nm}`)
  const risk = document.getElementById('reviewDrawerRisk')
  if (risk) risk.innerHTML = `<span class="review-risk ${review.risk}">${REVIEW_RISK_LABELS[review.risk] ?? review.risk}</span>`
  setReviewText('reviewDrawerReason', review.reason)
  const textarea = document.getElementById('reviewDraftText') as HTMLTextAreaElement | null
  if (textarea) textarea.value = review.draft || 'AI-черновик еще не создан.'
  const meta = reviewStatusMeta(review.status)
  const status = document.getElementById('reviewDrawerStatus')
  if (status) {
    status.className = `review-status ${meta.cls}`
    status.innerHTML = `<span class="review-status-dot"></span>${meta.label}`
  }
  const stopWords = document.getElementById('reviewStopWordsState')
  if (stopWords) {
    stopWords.className = review.risk === 'high' ? 'reviews-rule danger' : 'reviews-rule ok'
    stopWords.textContent = review.risk === 'high' ? `риск: ${review.topic}` : 'стоп-слова: чисто'
  }
  setReviewText('reviewToneState', 'WB draft-only · без автопубликации')
  const audit = document.getElementById('reviewAuditTrail')
  if (audit) {
    audit.innerHTML = review.audit.map((item) => `<div class="review-audit-item"><b>${item.split(' · ')[0]}</b>${item.includes(' · ') ? `<br>${item.split(' · ').slice(1).join(' · ')}` : ''}</div>`).join('')
  }
  renderReviewApprovalGuardDom(review)
  const approveBtn = document.getElementById('reviewApproveBtn') as HTMLButtonElement | null
  if (approveBtn) {
    approveBtn.disabled = !review.draftId
    approveBtn.textContent = review.draftId ? 'Одобрить' : 'Нужен draft'
  }
  const sendBtn = document.getElementById('reviewSendNowBtn') as HTMLButtonElement | null
  if (sendBtn) {
    sendBtn.disabled = !review.draftId
    sendBtn.dataset.tip = 'Backend вернет blocked/dry-run: live-отправка в WB отключена'
  }
  document.getElementById('reviewDrawerOverlay')?.classList.add('open')
  document.getElementById('reviewDrawer')?.classList.add('open')
  window.switchReviewDrawerTab?.('answer')
  window.setTimeout(() => textarea?.focus(), 0)
  window.syncHiddenA11y?.()
}

function updateBackendReviewsKpi() {
  const reviews = window.__vellaReviewsData ?? []
  const open = reviews.filter((review) => !['sent', 'sent_pending_verify'].includes(review.status)).length
  const queue = reviews.filter((review) => ['pending_review', 'blocked', 'error', 'new'].includes(review.status)).length
  const auto = reviews.filter((review) => ['scheduled', 'sent', 'sent_pending_verify'].includes(review.status)).length
  const blocked = reviews.filter((review) => ['blocked', 'error'].includes(review.status)).length
  const set = (id: string, value: string | number) => {
    const el = document.getElementById(id)
    if (el) el.textContent = String(value)
  }
  set('reviewsKpiOpen', open)
  set('reviewsKpiQueue', queue)
  set('reviewsKpiAuto', auto)
  set('reviewsKpiBlocked', blocked)
  set('navReviewsCount', queue)
}

function patchReviewRow(review: VellaReview, options: { refreshDrawer?: boolean } = {}) {
  window.__vellaReviewsData = (window.__vellaReviewsData ?? []).map((row) => row.id === review.id ? review : row)
  window.__vellaReactRenderReviews?.()
  updateBackendReviewsKpi()
  if (options.refreshDrawer !== false) openBackendReviewDrawer(review)
}

function reviewBrandVoiceId(review: VellaReview) {
  const brand = review.brand.toLowerCase()
  if (brand.includes('anomie')) return 'anomie-studio'
  if (brand.includes('bless')) return 'bless-t'
  return 'wb-default'
}

function loadReviewPromptMatrix() {
  if (typeof window === 'undefined') return DEFAULT_REVIEW_PROMPT_MATRIX
  try {
    const raw = window.localStorage.getItem(REVIEW_PROMPT_MATRIX_STORAGE_KEY)
    return raw ? normalizeReviewPromptMatrix(JSON.parse(raw)) : DEFAULT_REVIEW_PROMPT_MATRIX
  } catch {
    return DEFAULT_REVIEW_PROMPT_MATRIX
  }
}

function saveReviewPromptMatrix(matrix: ReviewPromptMatrix) {
  if (typeof window === 'undefined') return
  window.localStorage.setItem(REVIEW_PROMPT_MATRIX_STORAGE_KEY, JSON.stringify(normalizeReviewPromptMatrix(matrix)))
}

function wbReviewPromptContext(review: VellaReview) {
  const text = [review.text, review.reason, review.topic].filter(Boolean).join(' ')
  const normalized = text.toLocaleLowerCase('ru-RU')
  return {
    rating: review.rating,
    hasText: Boolean(review.text?.trim()),
    hasPhoto: review.media.toLocaleLowerCase('ru-RU').includes('фото') || reviewTextHasPhotoHint(text),
    text,
    orderState: normalized.includes('возврат') || normalized.includes('отказ') ? 'return' as const : 'buyout' as const,
  }
}

function avitoReviewPromptContext(review: AvitoReviewRow) {
  const text = review.text || ''
  const normalized = [text, review.stage].join(' ').toLocaleLowerCase('ru-RU')
  return {
    rating: review.score,
    hasText: Boolean(text.trim()),
    hasPhoto: review.images.length > 0 || reviewTextHasPhotoHint(text),
    text,
    orderState: normalized.includes('возврат') || normalized.includes('отказ') ? 'return' as const : 'buyout' as const,
  }
}

function wbReviewPromptInstruction(review: VellaReview, matrix = loadReviewPromptMatrix()) {
  return buildReviewPromptInstruction({ matrix, context: wbReviewPromptContext(review), platform: 'wb' })
}

function avitoReviewPromptInstruction(review: AvitoReviewRow, matrix = loadReviewPromptMatrix()) {
  return buildReviewPromptInstruction({ matrix, context: avitoReviewPromptContext(review), platform: 'avito' })
}

function reviewModalSelectValue(id: string, fallback: string) {
  return (document.getElementById(id) as HTMLSelectElement | null)?.value || fallback
}

function setReviewModalSelectValue(id: string, value: string) {
  const select = document.getElementById(id) as HTMLSelectElement | null
  if (select) select.value = value
}

function reviewModalSettingsFromDom(): WbReviewAutomationSettings {
  const delayLabel = reviewModalSelectValue('reviewSettingsDelay', '15 минут')
  const delay = Number.parseInt(delayLabel.replace(/\D+/g, ''), 10)
  const chipActive = (label: string) => {
    const chip = [...document.querySelectorAll<HTMLElement>('#m-reviewSettings .review-rule-chip')]
      .find((item) => item.textContent?.trim().toLowerCase() === label.toLowerCase())
    return chip?.classList.contains('active') ?? true
  }
  return {
    automationMode: reviewModalSelectValue('reviewSettingsMode', DEFAULT_REVIEW_AUTOMATION_SETTINGS.automationMode) as WbReviewAutomationSettings['automationMode'],
    replyDelayMinutes: Number.isFinite(delay) ? delay : DEFAULT_REVIEW_AUTOMATION_SETTINGS.replyDelayMinutes,
    threeStarAction: reviewModalSelectValue('reviewSettingsThreeStar', DEFAULT_REVIEW_AUTOMATION_SETTINGS.threeStarAction) as WbReviewAutomationSettings['threeStarAction'],
    lowStarsAction: reviewModalSelectValue('reviewSettingsLowStars', DEFAULT_REVIEW_AUTOMATION_SETTINGS.lowStarsAction) as WbReviewAutomationSettings['lowStarsAction'],
    anomieTone: reviewModalSelectValue('reviewToneAnomie', DEFAULT_REVIEW_AUTOMATION_SETTINGS.anomieTone),
    blessTone: reviewModalSelectValue('reviewToneBless', DEFAULT_REVIEW_AUTOMATION_SETTINGS.blessTone),
    avitoTone: window.__vellaReviewSyncSettings?.reviewSettings?.avitoTone ?? DEFAULT_REVIEW_AUTOMATION_SETTINGS.avitoTone,
    quoteMode: reviewModalSelectValue('reviewQuoteMode', DEFAULT_REVIEW_AUTOMATION_SETTINGS.quoteMode) as WbReviewAutomationSettings['quoteMode'],
    validateName: chipActive('валидировать имя'),
    recommendations30d: chipActive('рекомендации 30 дней'),
    quotesApproval: chipActive('цитаты через approval'),
    candidateSearch: chipActive('поиск новых кандидатов'),
  }
}

function renderReviewStopTopicChips(bundle: WbReviewSettingsBundle | undefined) {
  const row = document.getElementById('reviewStopTopicChips')
  if (!row) return
  const defaults = ['брак', 'возврат', 'доставка', 'размер', 'печать', 'конкурент', 'цена', 'компенсация']
  const topics = [...(bundle?.stopTopics ?? [])]
  const known = new Set(topics.map((topic) => topic.phrase.trim().toLowerCase()))
  for (const phrase of defaults) {
    if (!known.has(phrase)) topics.push({
      stopTopicId: 0,
      brandVoiceId: null,
      phrase,
      matchType: 'contains',
      action: phrase === 'компенсация' || phrase === 'конкурент' || phrase === 'брак' ? 'block_send' : 'manual_review',
      isActive: true,
      createdByActorId: 'local',
      createdAt: '',
      updatedAt: '',
    })
  }
  row.innerHTML = topics
    .sort((a, b) => a.phrase.localeCompare(b.phrase, 'ru'))
    .map((topic) => `<button class="review-rule-chip ${topic.isActive ? 'active' : ''}" type="button" data-stop-topic-id="${topic.stopTopicId}" data-stop-topic-action="${topic.action}">${topic.phrase}</button>`)
    .join('')
  row.querySelectorAll<HTMLButtonElement>('.review-rule-chip').forEach((chip) => {
    chip.addEventListener('click', () => {
      chip.classList.toggle('active')
      window.applyReviewSettingsPreview?.()
    })
  })
}

function renderReviewPromptMatrixDom(container: HTMLElement, matrix = loadReviewPromptMatrix()) {
  if (!document.getElementById('reviewPromptMatrixStyle')) {
    const style = document.createElement('style')
    style.id = 'reviewPromptMatrixStyle'
    style.textContent = `
      #m-reviewSettings .modal{max-height:min(860px,calc(100vh - 48px));display:flex;flex-direction:column}
      #m-reviewSettings .modal-body{overflow:auto;min-height:0}
      #reviewPromptMatrixSettings{display:block;width:100%;grid-column:1/-1}
      .review-prompt-matrix{display:grid;grid-template-columns:1fr;gap:14px;margin-top:10px;width:100%}
      .review-prompt-rule-list{display:flex;align-content:flex-start;align-items:flex-start;flex-wrap:wrap;gap:6px;max-height:128px;overflow:auto}
      .review-prompt-editor{display:grid;gap:7px;min-width:0;width:100%}
      .review-prompt-editor textarea{width:100%!important;max-width:none!important;min-height:118px;box-sizing:border-box}
    `
    document.head.appendChild(style)
  }
  let root = document.getElementById('reviewPromptMatrixSettings') as HTMLElement | null
  if (!root) {
    root = document.createElement('div')
    root.id = 'reviewPromptMatrixSettings'
    root.className = 'review-setting'
    root.style.marginBottom = '12px'
    container.insertBefore(root, container.firstChild)
  }
  const activeRuleId = root.dataset.activeRuleId || matrix.rules[0]?.id || ''
  const activeRule = matrix.rules.find((rule) => rule.id === activeRuleId) ?? matrix.rules[0]
  root.dataset.activeRuleId = activeRule?.id ?? ''
  root.innerHTML = `
    <div class="review-setting-label">Промпты по условиям отзыва</div>
    <div class="review-setting-note">Дефолты взяты из Excel: рейтинг, текст, фото, выкуп/возврат и отдельные причины. Каждую строку можно редактировать.</div>
    <div class="review-prompt-matrix">
      <div class="review-prompt-rule-list">
        ${matrix.rules.map((rule) => `<button class="review-rule-chip ${rule.id === activeRule?.id ? 'active' : ''}" type="button" data-rule-id="${rule.id}">${rule.title}</button>`).join('')}
      </div>
      <div class="review-prompt-editor">
        <label class="review-setting-label" for="reviewPromptRulePrompt">Промпт</label>
        <textarea id="reviewPromptRulePrompt" class="s-input" style="width:100%;height:115px;resize:vertical">${activeRule?.prompt ?? ''}</textarea>
        <label class="review-setting-label" for="reviewPromptRuleExample" style="margin-top:10px">Пример ответа</label>
        <textarea id="reviewPromptRuleExample" class="s-input" style="width:100%;height:95px;resize:vertical">${activeRule?.example ?? ''}</textarea>
        <label class="review-setting-label" for="reviewPromptQuotes" style="margin-top:10px">Цитаты, по одной на строку</label>
        <textarea id="reviewPromptQuotes" class="s-input" style="width:100%;height:95px;resize:vertical">${matrix.quotes.join('\n')}</textarea>
        <div class="settings-card-actions" style="margin-top:10px">
          <button class="btn btn-primary btn-sm" id="reviewPromptMatrixSaveBtn" type="button">Сохранить промпты</button>
          <button class="btn btn-default btn-sm" id="reviewPromptMatrixResetBtn" type="button">Вернуть Excel-дефолты</button>
          <span class="settings-save-state" id="reviewPromptMatrixSaveState"></span>
        </div>
      </div>
    </div>
  `
  root.querySelectorAll<HTMLButtonElement>('[data-rule-id]').forEach((button) => {
    button.addEventListener('click', () => {
      root.dataset.activeRuleId = button.dataset.ruleId || ''
      renderReviewPromptMatrixDom(container, readReviewPromptMatrixFromDom(matrix, root))
    })
  })
  root.querySelector<HTMLButtonElement>('#reviewPromptMatrixSaveBtn')?.addEventListener('click', () => {
    const next = readReviewPromptMatrixFromDom(matrix, root)
    saveReviewPromptMatrix(next)
    renderReviewPromptMatrixDom(container, next)
    const state = document.getElementById('reviewPromptMatrixSaveState')
    if (state) state.textContent = 'сохранено'
    window.showToast?.('Промпты отзывов сохранены', 'success')
  })
  root.querySelector<HTMLButtonElement>('#reviewPromptMatrixResetBtn')?.addEventListener('click', () => {
    saveReviewPromptMatrix(DEFAULT_REVIEW_PROMPT_MATRIX)
    renderReviewPromptMatrixDom(container, DEFAULT_REVIEW_PROMPT_MATRIX)
    window.showToast?.('Вернули промпты из Excel по умолчанию', 'info')
  })
}

function readReviewPromptMatrixFromDom(matrix: ReviewPromptMatrix, root: HTMLElement): ReviewPromptMatrix {
  const activeRuleId = root.dataset.activeRuleId || matrix.rules[0]?.id || ''
  const prompt = (root.querySelector('#reviewPromptRulePrompt') as HTMLTextAreaElement | null)?.value ?? ''
  const example = (root.querySelector('#reviewPromptRuleExample') as HTMLTextAreaElement | null)?.value ?? ''
  const quotesText = (root.querySelector('#reviewPromptQuotes') as HTMLTextAreaElement | null)?.value ?? ''
  return normalizeReviewPromptMatrix({
    ...matrix,
    quotes: quotesText.split(/\r?\n/).map((line) => line.trim()).filter(Boolean),
    rules: matrix.rules.map((rule) => rule.id === activeRuleId ? { ...rule, prompt, example } : rule),
  })
}

function populateReviewSettingsModal(settings: WbReviewSyncSettings, bundle?: WbReviewSettingsBundle) {
  const reviewSettings = { ...DEFAULT_REVIEW_AUTOMATION_SETTINGS, ...(settings.reviewSettings ?? {}) }
  setReviewModalSelectValue('reviewSettingsMode', reviewSettings.automationMode)
  setReviewModalSelectValue('reviewSettingsDelay', `${reviewSettings.replyDelayMinutes} минут`)
  setReviewModalSelectValue('reviewSettingsThreeStar', reviewSettings.threeStarAction)
  setReviewModalSelectValue('reviewSettingsLowStars', reviewSettings.lowStarsAction)
  setReviewModalSelectValue('reviewToneAnomie', reviewSettings.anomieTone)
  setReviewModalSelectValue('reviewToneBless', reviewSettings.blessTone)
  setReviewModalSelectValue('reviewQuoteMode', reviewSettings.quoteMode)
  const telegram = document.getElementById('reviewSettingsTelegram') as HTMLSelectElement | null
  if (telegram) {
    telegram.value = 'off'
    telegram.disabled = true
    telegram.title = 'Telegram не подключаем в этой итерации'
  }
  document.querySelectorAll<HTMLElement>('#m-reviewSettings .review-rule-chip').forEach((chip) => {
    const text = chip.textContent?.trim().toLowerCase()
    const active = text === 'валидировать имя' ? reviewSettings.validateName
      : text === 'рекомендации 30 дней' ? reviewSettings.recommendations30d
        : text === 'цитаты через approval' ? reviewSettings.quotesApproval
          : text === 'поиск новых кандидатов' ? reviewSettings.candidateSearch
            : undefined
    if (active !== undefined) chip.classList.toggle('active', active)
  })
  renderReviewStopTopicChips(bundle)
  const wbStatus = [...document.querySelectorAll<HTMLElement>('#m-reviewSettings .modal-summary div')]
    .find((item) => item.textContent?.includes('WB API'))
  const syncStatus = window.__vellaReviewsLoadState?.syncStatus
  if (wbStatus) wbStatus.innerHTML = `<span>WB API</span><b>статус: ${syncStatus?.lastError ? 'ошибка' : syncStatus?.lastRunAt ? 'подключен' : 'ожидает sync'}</b>`
  const saveButton = [...document.querySelectorAll<HTMLButtonElement>('#m-reviewSettings .modal-foot .btn-primary')][0]
  if (saveButton) {
    saveButton.textContent = 'Сохранить настройки'
    saveButton.onclick = (event) => {
      event.preventDefault()
      void window.__vellaSaveReviewModalSettings?.()
    }
  }
}

async function upsertReviewUiRules(accessToken: string, settings: WbReviewAutomationSettings, bundle: WbReviewSettingsBundle | undefined) {
  const rules = bundle?.moderationRules ?? []
  const upsertRule = async (name: string, payload: Parameters<typeof createWbReviewModerationRule>[1]) => {
    const existing = rules.find((rule) => rule.name === name)
    if (existing) return updateWbReviewModerationRule(accessToken, existing.ruleId, payload)
    return createWbReviewModerationRule(accessToken, payload)
  }
  await upsertRule('UI: 1-2 stars policy', {
    brandVoiceId: null,
    name: 'UI: 1-2 stars policy',
    conditionType: 'low_rating',
    action: settings.lowStarsAction === 'alert-block' ? 'block_send' : 'manual_review',
    thresholdInt: 2,
    keywords: [],
    isActive: true,
  })
  await upsertRule('UI: 3 stars policy', {
    brandVoiceId: null,
    name: 'UI: 3 stars policy',
    conditionType: 'low_rating',
    action: 'manual_review',
    thresholdInt: 3,
    keywords: [],
    isActive: settings.threeStarAction !== 'auto-low',
  })
}

async function upsertReviewStopTopicsFromModal(accessToken: string, bundle: WbReviewSettingsBundle | undefined) {
  const existing = bundle?.stopTopics ?? []
  const chips = [...document.querySelectorAll<HTMLElement>('#reviewStopTopicChips .review-rule-chip')]
  for (const chip of chips) {
    const phrase = chip.textContent?.trim()
    if (!phrase) continue
    const active = chip.classList.contains('active')
    const match = existing.find((topic) => topic.phrase.trim().toLowerCase() === phrase.toLowerCase())
    const payload = {
      brandVoiceId: null,
      phrase,
      matchType: 'contains' as const,
      action: (chip.dataset.stopTopicAction === 'block_send' || ['компенсация', 'конкурент', 'брак'].includes(phrase.toLowerCase())) ? 'block_send' as const : 'manual_review' as const,
      isActive: active,
    }
    if (match) await updateWbReviewStopTopic(accessToken, match.stopTopicId, payload)
    else await createWbReviewStopTopic(accessToken, payload)
  }
}

async function upsertReviewToneTemplates(accessToken: string, settings: WbReviewAutomationSettings, bundle: WbReviewSettingsBundle | undefined) {
  const templates = bundle?.templates ?? []
  const upsertTemplate = async (brandVoiceId: string, title: string, tone: string) => {
    const existing = templates.find((template) => template.brandVoiceId === brandVoiceId && template.title === title)
    const payload = {
      brandVoiceId,
      title,
      bodyTemplate: `Тон бренда: ${tone}. Ответьте покупателю по товару {productName}; опирайтесь на текст отзыва: {text}`,
      ratingFrom: 1,
      ratingTo: 5,
      keywords: [],
      keywordMode: 'any' as const,
      isActive: true,
    }
    if (existing) return updateWbReviewTemplate(accessToken, existing.templateId, payload)
    return createWbReviewTemplate(accessToken, payload)
  }
  await upsertTemplate('anomie-studio', 'UI tone: Anomie studio', settings.anomieTone)
  await upsertTemplate('bless-t', 'UI tone: Bless T', settings.blessTone)
}

async function upsertReviewPromptMatrixTemplates(accessToken: string, matrix: ReviewPromptMatrix, bundle: WbReviewSettingsBundle | undefined) {
  const templates = bundle?.templates ?? []
  for (const rule of matrix.rules) {
    if (rule.platform === 'avito') continue
    const title = `UI prompt: ${rule.title}`
    const existing = templates.find((template) => template.brandVoiceId === 'wb-default' && template.title === title)
    const payload = {
      brandVoiceId: 'wb-default',
      title,
      bodyTemplate: buildReviewPromptInstruction({
        matrix,
        platform: 'wb',
        context: {
          rating: rule.ratingTo,
          hasText: rule.hasText ?? true,
          hasPhoto: rule.hasPhoto ?? false,
          text: rule.keywords?.join(' ') ?? '',
          orderState: rule.orderState ?? 'unknown',
        },
      }),
      ratingFrom: rule.ratingFrom,
      ratingTo: rule.ratingTo,
      keywords: rule.keywords ?? [],
      keywordMode: 'any' as const,
      isActive: rule.isActive,
    }
    if (existing) await updateWbReviewTemplate(accessToken, existing.templateId, payload)
    else await createWbReviewTemplate(accessToken, payload)
  }
}

function installReviewsReactRowsBridge(accessToken: string | null, shouldLoad = false) {
  window.__vellaReviewsAccessToken = accessToken
  if (window.__vellaReviewsReactRowsBridgeInstalled) {
    if (shouldLoad) void window.__vellaLoadLiveReviews?.()
    return
  }
  window.__vellaReviewsReactRowsBridgeInstalled = true
  window.__vellaReviewsData = []
  window.__vellaReviewsFilters = window.__vellaReviewsFilters ?? { status: 'all', brand: 'all' }
  window.__vellaReviewsLoadState = { status: 'idle' }
  const originalOpenReviewsSettings = window.openReviewsSettings
  window.openReviewsSettings = () => {
    originalOpenReviewsSettings?.()
    window.setTimeout(() => {
      const modalBody = document.querySelector('#m-reviewSettings .modal-body') as HTMLElement | null
      if (!modalBody) return
      renderReviewPromptMatrixDom(modalBody)
      if (!document.getElementById('reviewAiPrompt')) {
        const promptCard = document.createElement('div')
        promptCard.className = 'review-setting'
        promptCard.style.marginTop = '0'
        promptCard.style.marginBottom = '12px'
        promptCard.innerHTML = `
          <div class="review-setting-label">Промпт ChatGPT</div>
          <div class="review-setting-note">Обязательный system prompt для генерации черновиков ответов WB. Без него генерация заблокирована.</div>
          <textarea id="reviewAiPrompt" class="s-input" style="width:100%;height:180px;text-align:left;resize:vertical" placeholder="Напишите prompt для ChatGPT"></textarea>
          <div class="settings-card-actions" style="margin-top:10px">
            <button class="btn btn-primary btn-sm" id="reviewAiPromptSaveBtn" type="button">Сохранить prompt</button>
            <span class="settings-save-state" id="reviewAiPromptSaveState"></span>
          </div>
        `
        modalBody.insertBefore(promptCard, modalBody.firstChild)
      }
      const textarea = document.getElementById('reviewAiPrompt') as HTMLTextAreaElement | null
      if (textarea) textarea.value = window.__vellaReviewSyncSettings?.aiPrompt ?? ''
      const promptSaveButton = document.getElementById('reviewAiPromptSaveBtn') as HTMLButtonElement | null
      if (promptSaveButton) promptSaveButton.onclick = () => {
        const prompt = textarea?.value ?? ''
        window.__vellaSaveReviewAiPrompt?.(prompt)
      }
      const token = window.__vellaReviewsAccessToken
      if (!token) return
      Promise.all([getWbReviewSyncSettings(token), getWbReviewSettingsBundle(token)])
        .then(([settings, bundle]) => {
          window.__vellaReviewSyncSettings = settings
          window.__vellaReviewSettingsBundle = bundle
          if (textarea) textarea.value = settings.aiPrompt ?? ''
          populateReviewSettingsModal(settings, bundle)
        })
        .catch((error) => window.showToast?.(error instanceof Error ? error.message : 'Не удалось загрузить настройки отзывов', 'warn'))
    }, 0)
  }

  window.__vellaSaveReviewModalSettings = async () => {
    const token = window.__vellaReviewsAccessToken
    if (!token) return
    const saveButton = [...document.querySelectorAll<HTMLButtonElement>('#m-reviewSettings .modal-foot .btn-primary')][0]
    const originalLabel = saveButton?.textContent ?? 'Сохранить настройки'
    if (saveButton) {
      saveButton.disabled = true
      saveButton.textContent = 'Сохраняем...'
    }
    try {
      const current = window.__vellaReviewSyncSettings ?? await getWbReviewSyncSettings(token)
      const bundle = window.__vellaReviewSettingsBundle ?? await getWbReviewSettingsBundle(token)
      const reviewSettings = reviewModalSettingsFromDom()
      const promptMatrixRoot = document.getElementById('reviewPromptMatrixSettings') as HTMLElement | null
      const promptMatrix = promptMatrixRoot ? readReviewPromptMatrixFromDom(loadReviewPromptMatrix(), promptMatrixRoot) : loadReviewPromptMatrix()
      saveReviewPromptMatrix(promptMatrix)
      const aiPrompt = (document.getElementById('reviewAiPrompt') as HTMLTextAreaElement | null)?.value ?? current.aiPrompt
      const saved = await updateWbReviewSyncSettings(token, {
        enabled: current.enabled,
        intervalMinutes: current.intervalMinutes,
        tokenType: current.tokenType,
        unansweredOnly: current.unansweredOnly,
        take: current.take,
        lookbackDays: current.lookbackDays,
        aiPrompt,
        reviewSettings,
      })
      await upsertReviewUiRules(token, reviewSettings, bundle)
      await upsertReviewStopTopicsFromModal(token, bundle)
      await upsertReviewToneTemplates(token, reviewSettings, bundle)
      await upsertReviewPromptMatrixTemplates(token, promptMatrix, bundle)
      const refreshedBundle = await getWbReviewSettingsBundle(token)
      window.__vellaReviewSyncSettings = saved
      window.__vellaReviewSettingsBundle = refreshedBundle
      populateReviewSettingsModal(saved, refreshedBundle)
      window.renderReviews?.()
      window.showToast?.('Настройки отзывов сохранены в backend', 'success')
    } catch (error) {
      window.showToast?.(error instanceof Error ? error.message : 'Не удалось сохранить настройки отзывов', 'warn')
    } finally {
      if (saveButton) {
        saveButton.disabled = false
        saveButton.textContent = originalLabel
      }
    }
  }

  window.renderReviews = () => {
    window.__vellaReactRenderReviews?.()
    updateBackendReviewsKpi()
  }
  window.setReviewsFilter = (chip: HTMLElement) => {
    const group = chip.dataset.reviewFilter ?? ''
    window.__vellaReviewsFilters = { ...(window.__vellaReviewsFilters ?? {}), [group]: chip.dataset.value ?? 'all' }
    document.querySelectorAll(`[data-review-filter="${group}"]`).forEach((item) => item.classList.toggle('active', item === chip))
    window.renderReviews?.()
  }
  window.resetReviewsFilters = () => {
    window.__vellaReviewsFilters = { status: 'all', brand: 'all' }
    const search = document.getElementById('reviewsSearch') as HTMLInputElement | null
    if (search) search.value = ''
    document.querySelectorAll('[data-review-filter]').forEach((chip) => chip.classList.toggle('active', (chip as HTMLElement).dataset.value === 'all'))
    window.renderReviews?.()
  }
  window.openReviewDrawer = (id: string) => {
    const review = (window.__vellaReviewsData ?? []).find((row) => row.id === id)
    if (review) openBackendReviewDrawer(review)
  }
  window.__vellaLoadLiveReviews = async (options: { syncFirst?: boolean } = {}) => {
    const token = window.__vellaReviewsAccessToken
    if (!token) {
      window.__vellaReviewsLoadState = { status: 'error', error: 'Нужна авторизация для загрузки отзывов' }
      window.__vellaReviewsData = []
      window.renderReviews?.()
      console.warn('[wb-reviews] load skipped: auth token is missing')
      return
    }
    window.__vellaReviewsLoadState = { status: options.syncFirst ? 'syncing' : 'loading' }
    window.renderReviews?.()
    console.info(options.syncFirst ? '[wb-reviews] sync started' : '[wb-reviews] load started')
    try {
      if (options.syncFirst) await syncWbReviewFeedbacks(token)
      const response = await listWbReviewFeedbacks(token)
      const syncStatus = await getWbReviewSyncStatus(token).catch(() => null)
      window.__vellaReviewsData = (response?.items ?? []).map(mapWbFeedbackToVellaReview)
      window.__vellaReviewsLoadState = { status: 'ready', syncStatus: syncStatus ?? undefined }
      window.renderReviews?.()
      console.info('[wb-reviews] feedbacks loaded', { count: window.__vellaReviewsData.length, syncFirst: Boolean(options.syncFirst) })
      if (options.syncFirst) window.showToast?.('Отзывы WB обновлены с backend', 'success')
    } catch (error) {
      window.__vellaReviewsLoadState = { status: 'error', error: error instanceof Error ? error.message : 'Не удалось загрузить отзывы' }
      window.__vellaReviewsData = []
      window.renderReviews?.()
      console.error('[wb-reviews] load failed', error)
    }
  }
  window.approveReviewDraft = async () => {
    const review = (window.__vellaReviewsData ?? []).find((row) => row.id === window.__vellaCurrentReviewId)
    const token = window.__vellaReviewsAccessToken
    if (!token || !review?.draftId) return window.showToast?.('Сначала сгенерируйте черновик', 'warn')
    try {
      const draft = await approveWbReviewDraft(token, review.draftId, 'approved from reviews page')
      patchReviewRow(mergeWbDraftIntoVellaReview(review, draft))
      window.showToast?.('Черновик одобрен, отправка в WB остается отключенной', 'success')
    } catch (error) {
      window.showToast?.(error instanceof Error ? error.message : 'Не удалось одобрить черновик', 'warn')
    }
  }
  window.saveReviewDraft = () => {
    const review = (window.__vellaReviewsData ?? []).find((row) => row.id === window.__vellaCurrentReviewId)
    if (!review) return
    const draft = (document.getElementById('reviewDraftText') as HTMLTextAreaElement | null)?.value ?? review.draft
    patchReviewRow({ ...review, draft, audit: ['Черновик отредактирован на странице · backend PATCH пока не подключен', ...review.audit] })
    window.showToast?.('Правка сохранена в текущей сессии страницы', 'info')
  }
  window.regenerateReviewDraft = async () => {
    const review = (window.__vellaReviewsData ?? []).find((row) => row.id === window.__vellaCurrentReviewId)
    const token = window.__vellaReviewsAccessToken
    if (!token || !review) return
    try {
      patchReviewRow({ ...review, status: 'generating', draft: '', audit: ['AI-генерация запущена · сейчас', ...review.audit] })
      const draft = await generateWbReviewDraft(token, review.id, true, reviewBrandVoiceId(review), wbReviewPromptInstruction(review))
      patchReviewRow(mergeWbDraftIntoVellaReview(review, draft))
      window.showToast?.('AI-черновик получен с backend', 'success')
    } catch (error) {
      patchReviewRow({ ...review, status: 'error', reason: error instanceof Error ? error.message : 'Ошибка генерации' })
    }
  }
  window.sendReviewNow = async () => {
    const review = (window.__vellaReviewsData ?? []).find((row) => row.id === window.__vellaCurrentReviewId)
    const token = window.__vellaReviewsAccessToken
    if (!token || !review?.draftId) return window.showToast?.('Сначала нужен черновик', 'warn')
    const result = await requestWbReviewSend(token, review.draftId)
    patchReviewRow({ ...review, status: result.status === 'blocked' ? 'blocked' : 'sent_pending_verify', reason: result.resultMessage, audit: [`Send request: ${result.status} · ${result.resultMessage}`, ...review.audit] })
    window.showToast?.(result.resultMessage, result.status === 'blocked' ? 'warn' : 'success')
  }
  window.rejectReviewDraft = async () => {
    const review = (window.__vellaReviewsData ?? []).find((row) => row.id === window.__vellaCurrentReviewId)
    const token = window.__vellaReviewsAccessToken
    if (!token || !review?.draftId) return window.showToast?.('Сначала нужен черновик', 'warn')
    const draft = await rejectWbReviewDraft(token, review.draftId, 'rejected from reviews page')
    patchReviewRow(mergeWbDraftIntoVellaReview(review, draft))
    window.showToast?.('Черновик отклонен', 'warn')
  }
  if (shouldLoad) void window.__vellaLoadLiveReviews()
}

function installProductsSavedViewsBridge() {
  if (window.__vellaProductsSavedViewsBridgeInstalled || typeof window.renderSavedViews !== 'function') return
  window.__vellaProductsSavedViewsBridgeInstalled = true
  window.eval?.(`
    window.__vellaSavedViewsSnapshot = function(){
      const view = savedViewById(activeSavedViewId);
      const dirty = savedViewIsDirty(view);
      const allChips = segmentCriteriaChips(view);
      const chips = allChips.slice(0, 3);
      return {
        views: SAVED_VIEWS.map(function(item){
          return {
            id: item.id,
            name: item.name,
            description: item.description || '',
            active: item.id === activeSavedViewId,
            count: PRODUCTS.filter(function(product){ return matchesSavedView(product, item); }).length
          };
        }),
        active: {
          id: view.id,
          name: view.name,
          dirty: dirty,
          count: activeSavedViewCount(view),
          access: accessLabel(view.access),
          conditions: allChips.length,
          chips: chips,
          extra: Math.max(0, allChips.length - chips.length),
          canUpdate: !isSystemSavedView(view),
          canDelete: !isSystemSavedView(view)
        }
      };
    };
    renderSavedViews = function(){
      if (window.__vellaReactRenderSavedViews) window.__vellaReactRenderSavedViews();
    };
  `)
  window.__vellaReactRenderSavedViews?.()
}

function installProductsTableRowsBridge() {
  if (window.__vellaProductsTableRowsBridgeInstalled || typeof window.renderTable !== 'function') return
  window.__vellaProductsTableRowsBridgeInstalled = true
  window.eval?.(`
    (function(){
      if (typeof tplHTML === 'function' && !window.__vellaTplHtmlPatched) {
        window.__vellaTplHtmlPatched = true;
        var originalTplHTML = tplHTML;
        tplHTML = function(p){
          if (!p.tpl) return originalTplHTML(p);
          var t = (typeof TPL !== 'undefined') ? TPL[p.tpl] : null;
          var label = p.strategyName || (t ? t.label : '');
          if (!label) return originalTplHTML(p);
          var cls = t ? t.cls : 'tpl-cust';
          var dot = p.strategyColor || (t ? t.dot : '#64748B');
          var inner = '<span class="tpl-chip ' + cls + '"><span class="tpl-color-dot" style="background:' + dot + ';width:6px;height:6px"></span>' + label + '</span>';
          return '<div class="cell-drop-wrap" onclick="openCellDrop(event,this,\\'tpl\\',\\'' + p.sku + '\\')">' + inner + '</div>';
        };
      }
      if (!window.__vellaBasketsOrdersCellsPatched) {
        window.__vellaBasketsOrdersCellsPatched = true;
        var wrapWbFunnelRefreshingCell = function(html){
          if (!window.__vellaBasketsDetailRefreshing) return html;
          return '<div class="wb-funnel-refreshing-cell" data-tip="Данные обновятся после загрузки дневной воронки WB"><div class="wb-funnel-refreshing-value">' + html + '</div><span class="wb-funnel-refreshing-badge"><span class="vella-products-loading-spinner small"></span>Обновляем WB</span></div>';
        };
        if (typeof bskCellHTML === 'function') {
          var originalBskCellHTML = bskCellHTML;
          bskCellHTML = function(p){
            return wrapWbFunnelRefreshingCell(originalBskCellHTML(p));
          };
        }
        if (typeof ordersCellHTML === 'function') {
          var originalOrdersCellHTML = ordersCellHTML;
          ordersCellHTML = function(p){
            if (p && Object.prototype.hasOwnProperty.call(p, 'ordersTrend')) {
              if (p.periodStatsState === 'no_data') return wrapWbFunnelRefreshingCell('<span class="metric-main" data-tip="Заказы появятся после обновления периода WB Statistics">нет данных</span>');
              var trend = p.ordersTrend === 'up' ? '<span class="up">↑</span>' : (p.ordersTrend === 'down' ? '<span class="down">↓</span>' : '');
              var bars = Array.isArray(p.bskBars) ? p.bskBars : [];
              return wrapWbFunnelRefreshingCell('<div class="bsk"><span class="bsk-num">' + (p.ordersPeriod || 0) + ' ' + trend + '</span><div class="bsk-spark mid">' + bars.map(function(v){ return '<span style="height:' + (v * 2 + 3) + 'px;opacity:' + (v ? 0.9 : 0.18) + '"></span>'; }).join('') + '</div></div>');
            }
            return wrapWbFunnelRefreshingCell(originalOrdersCellHTML(p));
          };
        }
      }
      var originalRenderTable = renderTable;
      if (typeof updateChipCounts === 'function' && !window.__vellaProductChipCountsPatched) {
        window.__vellaProductChipCountsPatched = true;
        updateChipCounts = function(){
          window.dispatchEvent(new CustomEvent('vella:products-filter-updated'));
        };
      }
      window.__vellaProductRowsSnapshot = function(){
        var tbody = document.getElementById('tbody');
        var html = window.__vellaProductsRowsHtml || (tbody ? tbody.innerHTML : '');
        return {
          html: html,
          count: (html.match(/<tr\\b[^>]*data-sku=/g) || []).length
        };
      };
      renderTable = function(){
        var descriptor = Object.getOwnPropertyDescriptor(Element.prototype, 'innerHTML');
        var captured = null;
        var originalDocumentGetElementById = Document.prototype.getElementById;
        var mutedCounter = { textContent: '' };
        var shadowTbody = document.createElement('tbody');
        shadowTbody.id = 'tbody';
        Document.prototype.getElementById = function(id){
          if (id === 'visibleCount' || id === 'totalCount') return mutedCounter;
          var found = originalDocumentGetElementById.call(this, id);
          if (id === 'tbody') return found || shadowTbody;
          return found;
        };
        if (!descriptor || !descriptor.get || !descriptor.set || !descriptor.configurable) {
          try {
            originalRenderTable();
          } finally {
            Document.prototype.getElementById = originalDocumentGetElementById;
          }
          window.__vellaProductsRowsHtml = captured || shadowTbody.innerHTML || document.getElementById('tbody')?.innerHTML || '';
          if (typeof window.__vellaSyncProductsEmptyStateAfterRender === 'function') window.__vellaSyncProductsEmptyStateAfterRender();
          window.dispatchEvent(new CustomEvent('vella:products-rows-updated'));
          return;
        }
        Object.defineProperty(Element.prototype, 'innerHTML', {
          configurable: descriptor.configurable,
          enumerable: descriptor.enumerable,
          get: descriptor.get,
          set: function(value){
            if (this instanceof HTMLTableSectionElement && this.id === 'tbody') {
              captured = String(value);
              if (this === shadowTbody) descriptor.set.call(this, value);
              return;
            }
            descriptor.set.call(this, value);
          }
        });
        try {
          originalRenderTable();
        } finally {
          Object.defineProperty(Element.prototype, 'innerHTML', descriptor);
          Document.prototype.getElementById = originalDocumentGetElementById;
        }
        if (captured !== null) window.__vellaProductsRowsHtml = captured;
        if (typeof window.__vellaSyncProductsEmptyStateAfterRender === 'function') window.__vellaSyncProductsEmptyStateAfterRender();
        window.dispatchEvent(new CustomEvent('vella:products-rows-updated'));
      };
    })();
  `)
  window.__vellaSyncProductsEmptyStateAfterRender = syncProductsEmptyStateAfterRender
  window.renderTable?.()
}

const BACKEND_STRATEGY_MISSING_DATA: Record<string, string[]> = {
  cross_marketplace: [
    'маппинг WB nmId/vendorCode к Ozon offer_id/SKU',
    'актуальные цены и скидки Ozon',
    'правила сравнения цены между маркетплейсами',
  ],
  bundles: [
    'состав комплекта: компоненты, SKU и количество',
    'цены и себестоимость компонентов',
    'правило сборки цены комплекта',
  ],
}

const TEMP_DISABLED_STRATEGY_IDS = new Set(['cross_marketplace', 'bundles'])
const CONFIGURABLE_STRATEGY_IDS = new Set(['schedule', 'plan_fact_group'])

function missingDataForBackendStrategy(strategyId: string) {
  return BACKEND_STRATEGY_MISSING_DATA[strategyId] ?? []
}

function isStrategyTemporarilyDisabled(strategy: Pick<VellaStrategySnapshotItem, 'id' | 'status'>) {
  return TEMP_DISABLED_STRATEGY_IDS.has(strategy.id) || strategy.status === 'disabled'
}

function installStrategiesReactBridge() {
  if (window.__vellaStrategiesReactBridgeInstalled || typeof window.renderStrategies !== 'function') return
  window.__vellaStrategiesReactBridgeInstalled = true
  window.eval?.(`
    function vellaStrategyBadge(status){
      if (status === 'disabled') return { cls:'special', text:'выключено' };
      if (status === 'blocked') return { cls:'special', text:'нужны данные' };
      if (status === 'special') return { cls:'special', text:'особый' };
      return { cls:'active', text:'активный' };
    }
    var __vellaLegacyStrategyRulesHTML = strategyRulesHTML;
    strategyRulesHTML = function(strategy){
      if (strategy && Array.isArray(strategy.backendRules) && strategy.backendRules.length) {
        return strategy.backendRules.map(function(rule){ return [rule.label, rule.value]; });
      }
      return __vellaLegacyStrategyRulesHTML(strategy);
    };
    window.__vellaStrategiesSnapshot = function(){
      syncStrategyTplContract();
      return STRATEGIES.map(function(strategy){
        var badge = vellaStrategyBadge(strategy.status);
        var rules = Array.isArray(strategy.backendRules) && strategy.backendRules.length
          ? strategy.backendRules
          : strategyRulesHTML(strategy).map(function(rule){ return { label: rule[0], value: rule[1] }; });
        return {
          id: strategy.id,
          typedStrategyId: strategy.typedStrategyId,
          type: strategy.type,
          name: strategy.name,
          color: strategy.color,
          description: strategy.description,
          applied: strategy.applied,
          status: strategy.status,
          badgeClass: strategy.badgeClass || badge.cls,
          badgeText: strategy.badgeText || badge.text,
          rules: rules,
          missingData: Array.isArray(strategy.missingData) ? strategy.missingData : [],
          disabled: !!strategy.disabled || strategy.status === 'disabled',
          config: strategy.config || {}
        };
      });
    };
    function ensureBackendStrategyPanel(){
      var body = document.querySelector('#m-createTpl .modal-body');
      if (!body) return null;
      var panel = document.getElementById('backendStrategyRulesPanel');
      if (!panel) {
        panel = document.createElement('div');
        panel.id = 'backendStrategyRulesPanel';
        panel.style.display = 'none';
        panel.style.marginTop = '12px';
        body.appendChild(panel);
      }
      return panel;
    }
    function resetBackendStrategyEditor(){
      var panel = ensureBackendStrategyPanel();
      if (panel) {
        panel.style.display = 'none';
        panel.innerHTML = '';
      }
      var grid = document.querySelector('#m-createTpl .d-grid');
      if (grid) grid.style.display = '';
      ['strategyName','strategyDescription'].forEach(function(id){
        var input = document.getElementById(id);
        if (input) input.readOnly = false;
      });
      var type = document.getElementById('strategyType');
      if (type) type.disabled = false;
      var errorBox = document.getElementById('strategyFormError');
      if (errorBox) {
        errorBox.textContent = '';
        errorBox.classList.remove('show');
      }
      var save = document.getElementById('strategySaveBtn');
      if (save) {
        save.disabled = false;
        save.textContent = strategyModalMode === 'edit' ? 'Сохранить' : 'Создать';
        save.onclick = null;
      }
    }
    function selectedConfiguredArticleIds(){
      var pending = window.__vellaPendingConfiguredStrategy || {};
      if (Array.isArray(pending.articleIds) && pending.articleIds.length) return pending.articleIds;
      if (!Array.isArray(window.PRODUCTS)) return [];
      return window.PRODUCTS
        .filter(function(product){ return product && product.sel && product.sku; })
        .map(function(product){ return String(product.sku); });
    }
    function defaultIsoDate(){
      return new Date().toISOString().slice(0, 10);
    }
    function readConfiguredStrategyConfig(strategy){
      if (strategy.id === 'schedule') {
        var mode = (document.getElementById('cfgScheduleMode') || {}).value || 'set_price';
        var days = Array.prototype.slice.call(document.querySelectorAll('[data-cfg-weekday]:checked')).map(function(input){
          return Number(input.getAttribute('data-cfg-weekday'));
        }).filter(Boolean);
        var rule = {
          dateFrom: (document.getElementById('cfgScheduleDateFrom') || {}).value || null,
          dateTo: (document.getElementById('cfgScheduleDateTo') || {}).value || null,
          timeFrom: (document.getElementById('cfgScheduleTimeFrom') || {}).value || '00:00',
          timeTo: (document.getElementById('cfgScheduleTimeTo') || {}).value || '23:59',
          daysOfWeek: days.length ? days : [1,2,3,4,5,6,7],
          mode: mode
        };
        if (mode === 'set_price') {
          rule.priceKopecks = Math.max(0, Math.round(Number((document.getElementById('cfgSchedulePriceRub') || {}).value || 0) * 100));
        }
        if (mode === 'delta_pct') {
          rule.deltaPct = Number((document.getElementById('cfgScheduleDeltaPct') || {}).value || 0);
        }
        return { scheduleRules: [rule] };
      }
      if (strategy.id === 'plan_fact_group') {
        var groupSelect = document.getElementById('cfgGroupExistingSelect');
        var selectedGroupId = groupSelect ? groupSelect.value : '__new';
        if (selectedGroupId && selectedGroupId !== '__new') {
          return {
            groupId: selectedGroupId,
            planOrders: Math.max(1, Math.round(Number((document.getElementById('cfgGroupPlanOrders') || {}).value || 0)))
          };
        }
        return {
          groupName: (document.getElementById('cfgGroupName') || {}).value || '',
          planOrders: Math.max(1, Math.round(Number((document.getElementById('cfgGroupPlanOrders') || {}).value || 0))),
          groupArticleIds: selectedConfiguredArticleIds()
        };
      }
      return {};
    }
    function renderConfiguredStrategyEditor(strategy){
      var panel = ensureBackendStrategyPanel();
      if (!panel) return;
      var grid = document.querySelector('#m-createTpl .d-grid');
      if (grid) grid.style.display = 'none';
      setStrategyValue('strategyEditingId', strategy.id);
      setStrategyValue('strategyName', strategy.name);
      setStrategyValue('strategyDescription', strategy.description);
      ['strategyName','strategyDescription'].forEach(function(id){
        var input = document.getElementById(id);
        if (input) input.readOnly = true;
      });
      var type = document.getElementById('strategyType');
      if (type) type.disabled = true;
      var selectedIds = selectedConfiguredArticleIds();
      var rules = Array.isArray(strategy.backendRules) ? strategy.backendRules : [];
      var rulesHtml = rules.map(function(rule){
        return '<div class="tpl-rule"><span>' + escapeHtml(rule.label) + '</span><b>' + escapeHtml(rule.value) + '</b></div>';
      }).join('');
      var formHtml = '';
      if (strategy.id === 'schedule') {
        var today = defaultIsoDate();
        formHtml =
          '<div class="d-grid two">' +
            '<label>Дата от<input id="cfgScheduleDateFrom" class="s-input" type="date" value="' + today + '"></label>' +
            '<label>Дата до<input id="cfgScheduleDateTo" class="s-input" type="date" value="' + today + '"></label>' +
            '<label>Время от<input id="cfgScheduleTimeFrom" class="s-input" type="time" value="00:00"></label>' +
            '<label>Время до<input id="cfgScheduleTimeTo" class="s-input" type="time" value="23:59"></label>' +
            '<label>Действие<select id="cfgScheduleMode" class="s-input"><option value="set_price">Задать цену</option><option value="delta_pct">Изменить на %</option><option value="hold">Держать цену</option></select></label>' +
            '<label>Цена, ₽<input id="cfgSchedulePriceRub" class="s-input" type="number" min="1" step="1" placeholder="1290"></label>' +
            '<label>Изменение, %<input id="cfgScheduleDeltaPct" class="s-input" type="number" step="0.5" value="0"></label>' +
          '</div>' +
          '<div class="segment-chipline" style="margin-top:10px">' +
            [1,2,3,4,5,6,7].map(function(day){ return '<label class="segment-mini-chip" style="cursor:pointer"><input type="checkbox" data-cfg-weekday="' + day + '" checked> ' + ['Пн','Вт','Ср','Чт','Пт','Сб','Вс'][day - 1] + '</label>'; }).join('') +
          '</div>';
      } else if (strategy.id === 'plan_fact_group') {
        var groups = typeof window.__vellaSkuGroupsSnapshot === 'function' ? (window.__vellaSkuGroupsSnapshot() || []) : [];
        var groupOptions = '<option value="__new">Новая из выбранных SKU</option>' + groups.map(function(group){
          return '<option value="' + escapeHtml(group.groupId || '') + '">' + escapeHtml((group.groupName || 'Группа') + ' · ' + ((group.articleIds || []).length || 0) + ' SKU') + '</option>';
        }).join('');
        formHtml =
          '<div class="d-grid two">' +
            '<label>Группа<select id="cfgGroupExistingSelect" class="s-input">' + groupOptions + '</select></label>' +
            '<label>Название группы<input id="cfgGroupName" class="s-input" type="text" value="Группа ' + selectedIds.length + ' SKU"></label>' +
            '<label>План заказов<input id="cfgGroupPlanOrders" class="s-input" type="number" min="1" step="1" value="' + Math.max(1, selectedIds.length * 5) + '"></label>' +
          '</div>' +
          '<div class="modal-summary" style="margin-top:12px"><div><span>Выбрано сейчас</span><b>' + selectedIds.length + ' SKU</b></div><div><span>Сохранённых групп</span><b>' + groups.length + '</b></div></div>';
      }
      panel.innerHTML =
        '<div class="strategy-form-warning" style="margin-bottom:12px;background:#F8FAFC;color:#334155;border:1px solid #E2E8F0">' +
          'Настройки сохранятся вместе с назначением стратегии для выбранных SKU.' +
        '</div>' +
        (rulesHtml ? '<div class="tpl-rules" style="margin-bottom:12px">' + rulesHtml + '</div>' : '') +
        formHtml;
      panel.style.display = 'block';
      if (strategy.id === 'plan_fact_group') {
        var groupSelect = document.getElementById('cfgGroupExistingSelect');
        if (groupSelect) {
          groupSelect.onchange = function(){
            var groups = typeof window.__vellaSkuGroupsSnapshot === 'function' ? (window.__vellaSkuGroupsSnapshot() || []) : [];
            var group = groups.find(function(item){ return item.groupId === groupSelect.value; });
            var nameInput = document.getElementById('cfgGroupName');
            var planInput = document.getElementById('cfgGroupPlanOrders');
            if (nameInput) {
              nameInput.value = group ? (group.groupName || '') : ('Группа ' + selectedIds.length + ' SKU');
              nameInput.disabled = !!group;
            }
            if (planInput && group && group.planOrders) {
              planInput.value = String(group.planOrders);
            }
          };
        }
      }
      var save = document.getElementById('strategySaveBtn');
      if (save) {
        save.disabled = false;
        save.textContent = 'Применить стратегию';
        save.onclick = function(){
          var ids = selectedConfiguredArticleIds();
          if (!ids.length) {
            if (window.showToast) window.showToast('Выберите хотя бы один SKU', 'warn');
            return;
          }
          var config = readConfiguredStrategyConfig(strategy);
          if (window.__vellaApplyConfiguredStrategy) {
            window.__vellaApplyConfiguredStrategy(strategy.name, config, ids);
          } else if (window.showToast) {
            window.showToast('Форма готова, но API-применение еще не подключено', 'warn');
          }
        };
      }
    }
    function renderBackendStrategyEditor(strategy){
      var panel = ensureBackendStrategyPanel();
      if (!panel) return;
      var grid = document.querySelector('#m-createTpl .d-grid');
      if (grid) grid.style.display = 'none';
      setStrategyValue('strategyEditingId', strategy.id);
      setStrategyValue('strategyName', strategy.name);
      setStrategyValue('strategyDescription', strategy.description);
      var type = document.getElementById('strategyType');
      if (type) {
        var value = strategy.type || 'system';
        var option = Array.prototype.find.call(type.options, function(item){ return item.value === value; });
        if (!option) {
          option = document.createElement('option');
          option.value = value;
          option.textContent = value;
          type.appendChild(option);
        }
        type.value = value;
        type.disabled = true;
      }
      ['strategyName','strategyDescription'].forEach(function(id){
        var input = document.getElementById(id);
        if (input) input.readOnly = true;
      });
      var save = document.getElementById('strategySaveBtn');
      if (save) {
        save.disabled = true;
        save.textContent = 'Системная стратегия';
      }
      var badge = vellaStrategyBadge(strategy.status);
      var rules = Array.isArray(strategy.backendRules) && strategy.backendRules.length
        ? strategy.backendRules
        : strategyRulesHTML(strategy).map(function(rule){ return { label: rule[0], value: rule[1] }; });
      var missing = Array.isArray(strategy.missingData) ? strategy.missingData : [];
      var rulesHtml = rules.map(function(rule){
        return '<div class="tpl-rule"><span>' + escapeHtml(rule.label) + '</span><b>' + escapeHtml(rule.value) + '</b></div>';
      }).join('');
      var missingHtml = missing.length
        ? missing.map(function(item){ return '<div><span>Нужно</span><b>' + escapeHtml(item) + '</b></div>'; }).join('')
        : '<div><span>Данные</span><b>Данных хватает для расчета</b></div>';
      panel.innerHTML =
        '<div class="strategy-form-warning" style="margin-bottom:12px;background:#F8FAFC;color:#334155;border:1px solid #E2E8F0">' +
          'Это системная стратегия из Excel/backend. Правила ниже применяются алгоритмом; generic-поля маржи, шага и корзин для нее скрыты.' +
        '</div>' +
        '<div class="tpl-rules" style="margin-bottom:12px">' + rulesHtml + '</div>' +
        '<div class="modal-summary" style="margin-top:0">' + missingHtml + '</div>' +
        '<div style="display:flex;justify-content:flex-end;margin-top:12px"><span class="tpl-badge ' + escapeHtml(strategy.badgeClass || badge.cls) + '">' + escapeHtml(strategy.badgeText || badge.text) + '</span></div>';
      panel.style.display = 'block';
    }
    var __vellaLegacyOpenCreateStrategy = openCreateStrategy;
    openCreateStrategy = function(){
      resetBackendStrategyEditor();
      return __vellaLegacyOpenCreateStrategy();
    };
    window.openCreateStrategy = openCreateStrategy;
    var __vellaLegacyOpenEditStrategy = openEditStrategy;
    openEditStrategy = function(id){
      var strategy = strategyById(id);
      if (!strategy) return;
      if (strategy.disabled || strategy.status === 'disabled') {
        if (window.showToast) window.showToast('Стратегия «' + strategy.name + '» временно выключена', 'warn');
        return;
      }
      if (strategy.id === 'schedule' || strategy.id === 'plan_fact_group') {
        strategyModalMode = 'edit';
        document.getElementById('strategyModalTitle').textContent = 'Настроить стратегию';
        document.getElementById('strategyModalCopy').textContent = 'Задайте параметры и примените стратегию к выбранным SKU.';
        window.__vellaPendingConfiguredStrategy = Object.assign({ strategyId: strategy.id, strategyName: strategy.name }, window.__vellaPendingConfiguredStrategy || {});
        renderConfiguredStrategyEditor(strategy);
        openModal('createTpl');
        return;
      }
      if (!Array.isArray(strategy.backendRules) || !strategy.backendRules.length) {
        resetBackendStrategyEditor();
        return __vellaLegacyOpenEditStrategy(id);
      }
      strategyModalMode = 'edit';
      document.getElementById('strategyModalTitle').textContent = 'Правила стратегии';
      document.getElementById('strategyModalCopy').textContent = 'Системная стратегия рассчитывается по правилам из Excel. Ниже показаны формула и недостающие данные, если они есть.';
      renderBackendStrategyEditor(strategy);
      openModal('createTpl');
    };
    window.openEditStrategy = openEditStrategy;
    window.__vellaOpenConfiguredStrategyModal = function(strategyId, options){
      var strategy = strategyById(strategyId);
      if (!strategy) return;
      window.__vellaPendingConfiguredStrategy = Object.assign({ strategyId: strategy.id, strategyName: strategy.name }, options || {});
      openEditStrategy(strategy.id);
    };
    renderStrategies = function(){
      syncStrategyTplContract();
      if (window.__vellaReactRenderStrategies) window.__vellaReactRenderStrategies();
      window.dispatchEvent(new CustomEvent('vella:strategies-updated'));
      if (typeof initTooltips === 'function') initTooltips();
    };
  `)
  window.__vellaReactRenderStrategies?.()
  window.dispatchEvent(new CustomEvent('vella:strategies-updated'))
}

function syncBackendStrategiesToLegacyRuntime(strategies: VellaStrategySnapshotItem[]) {
  if (!strategies.length) return
  const payload = strategies.map((strategy) => ({
    id: strategy.id,
    typedStrategyId: strategy.typedStrategyId ?? null,
    type: strategy.type,
    name: strategy.name,
    color: strategy.color,
    chipClass: TPL_CHIP_CLASS_BY_ID[strategy.id] ?? 'tpl-cust',
    description: strategy.description,
    margin: strategy.type === 'liquidation' ? -5 : 25,
    step: strategy.type === 'liquidation' ? 3 : 5,
    stepTime: strategy.type === 'liquidation' ? 'каждые 24 часа' : 'каждый день',
    basketsUp: 30,
    basketsDown: 5,
    launchDays: 10,
    launchMinBaskets: 40,
    nightWindow: '23:00–06:00 МСК',
    nightApplyAt: '06:00 МСК',
    liquidationFloor: 0,
    applied: strategy.applied,
    status: strategy.status,
    badgeClass: strategy.badgeClass,
    badgeText: strategy.badgeText,
    backendRules: strategy.rules,
    missingData: strategy.missingData ?? missingDataForBackendStrategy(strategy.id),
    disabled: strategy.disabled ?? isStrategyTemporarilyDisabled(strategy),
    config: strategy.config ?? {},
  }))
  const serialized = JSON.stringify(payload)
  window.eval?.(`
    (function(nextStrategies){
      if (typeof STRATEGIES === 'undefined' || !Array.isArray(STRATEGIES)) return;
      STRATEGIES.splice(0, STRATEGIES.length);
      nextStrategies.forEach(function(strategy){ STRATEGIES.push(strategy); });
      if (typeof syncStrategyTplContract === 'function') syncStrategyTplContract();
      if (typeof syncAdvancedStrategyOptions === 'function') syncAdvancedStrategyOptions();
    })(${serialized});
  `)
}

function installPromotionsReactBridge() {
  if (window.__vellaPromotionsReactBridgeInstalled) return
  window.__vellaPromotionsReactBridgeInstalled = true
  window.eval?.(`
    window.__vellaPromoCalcOpen = window.__vellaPromoCalcOpen || false;
    window.__vellaPromoFilterState = window.__vellaPromoFilterState || { filter: 'all', query: '' };
    window.__vellaPromoDetailState = window.__vellaPromoDetailState || { open: false, index: null };
    window.__vellaPromoProductsSnapshot = function(){
      var products = (typeof PRODUCTS !== 'undefined') ? PRODUCTS : [];
      return products.map(function(p){
        return {
          sku: p.sku,
          name: p.name,
          price: Number(p.price) || 0,
          cogs: Number(p.cogs) || 0,
          pmin: Number(p.pmin) || 0,
          storagePerSku: Number(p.storagePerSku) || 0
        };
      });
    };
    window.__vellaSetPromoCalcOpen = function(open){
      window.__vellaPromoCalcOpen = !!open;
      window.dispatchEvent(new CustomEvent('vella:promos-calc-updated'));
      if (window.__vellaReactRenderPromotions) window.__vellaReactRenderPromotions();
    };
    window.__vellaSetPromoFilterState = function(next){
      window.__vellaPromoFilterState = Object.assign({ filter: 'all', query: '' }, window.__vellaPromoFilterState || {}, next || {});
      window.dispatchEvent(new CustomEvent('vella:promos-filter-updated'));
      if (window.__vellaReactRenderPromotions) window.__vellaReactRenderPromotions();
    };
    window.__vellaSetPromoDetailState = function(next){
      window.__vellaPromoDetailState = Object.assign({ open: false, index: null }, next || {});
      document.body.style.overflow = window.__vellaPromoDetailState.open ? 'hidden' : '';
      window.dispatchEvent(new CustomEvent('vella:promos-detail-updated'));
      if (window.__vellaReactRenderPromotions) window.__vellaReactRenderPromotions();
    };
    recalcPromoCalc = function(){
      window.dispatchEvent(new CustomEvent('vella:promos-calc-updated'));
      if (window.__vellaReactRenderPromotions) window.__vellaReactRenderPromotions();
    };
    togglePromoCalcTable = function(){
      window.__vellaSetPromoCalcOpen(!window.__vellaPromoCalcOpen);
    };
    setPromoFilter = function(key){
      window.__vellaSetPromoFilterState({ filter: key || 'all' });
    };
    filterPromos = function(){
      var input = document.getElementById('promoSearch');
      window.__vellaSetPromoFilterState({ query: input ? input.value : '' });
    };
    openPromoDetail = function(idx){
      window.__vellaSetPromoDetailState({ open: true, index: Number(idx) || 0 });
    };
    closePromoDetail = function(){
      window.__vellaSetPromoDetailState({ open: false, index: null });
    };
  `)
  window.__vellaReactRenderPromotions?.()
}

function installPromotionLabelBridge() {
  if (window.__vellaPromotionLabelBridgeInstalled) return
  window.__vellaPromotionLabelBridgeInstalled = true
  window.eval?.(`
    (function(){
      function esc(value){
        if (typeof escapeHtml === 'function') return escapeHtml(value);
        return String(value == null ? '' : value)
          .replace(/&/g, '&amp;')
          .replace(/</g, '&lt;')
          .replace(/>/g, '&gt;')
          .replace(/"/g, '&quot;')
          .replace(/'/g, '&#039;');
      }
      function promoLabel(value){
        var text = String(value == null ? '' : value).trim();
        var lower = text.toLowerCase();
        if (lower.indexOf('не участвует:') === 0) return { on: false, label: text };
        if (!text || lower === 'нет' || lower === 'no' || lower === 'false') return { on: false, label: 'нет' };
        if (lower === 'да' || lower === 'yes' || lower === 'true') return { on: true, label: 'да' };
        return { on: true, label: text };
      }
      window.promoStateHTML = function(value, tip){
        var state = promoLabel(value);
        var fallbackTip = state.on ? ('Акция WB: ' + state.label) : 'Не участвует в акции WB';
        return '<span class="promo-state ' + (state.on ? 'on' : 'off') + '" data-tip="' + esc(tip || fallbackTip) + '">' + esc(state.label) + '</span>';
      };
      window.promoHTML = function(p){
        var active = !!(p && p.promoActive);
        var label = p && (p.promoState || p.promotionStatusText || p.promotionName || p.promoName);
        var labelText = String(label || '').trim();
        if (!active && labelText.toLowerCase().indexOf('не участвует:') === 0) {
          return window.promoStateHTML(labelText, labelText);
        }
        if (active && (!labelText || labelText.toLowerCase() === 'да' || labelText === 'В акции') && p && p.promotionId != null) {
          labelText = 'Акция ' + p.promotionId;
        }
        if (active && labelText && labelText.toLowerCase() !== 'да') {
          var label = labelText;
          return window.promoStateHTML(label, 'Акция WB: ' + label);
        }
        return window.promoStateHTML(active ? 'да' : 'нет', active ? 'Участвует в акции WB' : 'Не участвует в акции');
      };
    })();
  `)
}

function installAvitoListingsReactBridge() {
  if (window.__vellaAvitoListingsReactBridgeInstalled) return
  window.__vellaAvitoListingsReactBridgeInstalled = true
  const period = defaultAvitoStatsPeriod()
  window.__vellaAvitoListingsState = window.__vellaAvitoListingsState || {
    filter: 'all',
    query: '',
    pageSize: '100',
    selectedKey: '',
    detailPeriod: '7',
    detailChartMode: 'traffic',
    dateFrom: period.from,
    dateTo: period.to,
    dateFromDraft: period.from,
    dateToDraft: period.to,
    requestSeq: 0,
    forceRefresh: false,
  }
  window.__vellaSetAvitoListingsState = (next) => {
    const fallbackPeriod = defaultAvitoStatsPeriod()
    window.__vellaAvitoListingsState = {
      filter: 'all',
      query: '',
      pageSize: '100',
      selectedKey: '',
      detailPeriod: '7',
      detailChartMode: 'traffic',
      dateFrom: fallbackPeriod.from,
      dateTo: fallbackPeriod.to,
      dateFromDraft: fallbackPeriod.from,
      dateToDraft: fallbackPeriod.to,
      requestSeq: 0,
      forceRefresh: false,
      ...(window.__vellaAvitoListingsState ?? {}),
      ...(next ?? {}),
    }
    window.dispatchEvent(new CustomEvent('vella:avito-listings-updated'))
    window.__vellaReactRenderAvitoListings?.()
  }
  window.applyAvitoListingsFilters = () => {
    const searchInput = document.getElementById('avitoListingsSearch')
    const query = searchInput instanceof HTMLInputElement ? searchInput.value : ''
    window.__vellaSetAvitoListingsState?.({ query })
  }
  window.updateAvitoListingsControls = () => {
    const pageSizeSelect = document.getElementById('avitoListingsPageSize')
    const pageSize = pageSizeSelect instanceof HTMLSelectElement ? pageSizeSelect.value : '100'
    window.__vellaSetAvitoListingsState?.({ pageSize: pageSize || '100' })
  }
  window.setAvitoListingsFilter = (button?: HTMLElement | null) => {
    const filter = button?.dataset.avitoListingsFilter || 'all'
    window.__vellaSetAvitoListingsState?.({ filter: filter as AvitoListingsFilter })
  }
  window.renderAvitoListingDetail = (key?: string) => {
    window.__vellaSetAvitoListingsState?.({ selectedKey: isAvitoListingKey(key) ? key : '' })
  }
  window.selectAvitoListing = (_row?: HTMLElement | null, key?: string) => {
    const selectedKey = isAvitoListingKey(key) ? key : ''
    window.__vellaSetAvitoListingsState?.({ selectedKey })
  }
  window.applyAvitoListingsPeriod = () => {
    const state: Partial<AvitoListingsState> = window.__vellaAvitoListingsState ?? {}
    const fallbackPeriod = defaultAvitoStatsPeriod()
    window.__vellaSetAvitoListingsState?.({
      dateFrom: state.dateFromDraft || state.dateFrom || fallbackPeriod.from,
      dateTo: state.dateToDraft || state.dateTo || fallbackPeriod.to,
      requestSeq: (state.requestSeq ?? 0) + 1,
      forceRefresh: false,
    })
  }
  window.refreshAvitoListings = () => {
    if (showAvitoCooldownToast(window.__vellaAvitoListingsLiveState?.data)) return
    const state: Partial<AvitoListingsState> = window.__vellaAvitoListingsState ?? {}
    window.__vellaSetAvitoListingsState?.({ requestSeq: (state.requestSeq ?? 0) + 1, forceRefresh: true })
  }
  window.openAvitoListingPopup = (key?: string, row?: HTMLElement | null) => {
    window.selectAvitoListing?.(row ?? null, key)
  }
  window.closeAvitoPopup = (kind?: string) => {
    document.getElementById('avitoPopupBackdrop')?.classList.remove('open')
    document.body.classList.remove('avito-popup-open')
    document.querySelectorAll('.avito-detail-panel.open').forEach((panel) => panel.classList.remove('open'))
    if (kind === 'stats') {
      window.__vellaSetAvitoStatsState?.({ selectedKey: '' })
      return
    }
    if (kind === 'listings') {
      window.__vellaSetAvitoListingsState?.({ selectedKey: '' })
      return
    }
    window.__vellaSetAvitoListingsState?.({ selectedKey: '' })
    window.__vellaSetAvitoStatsState?.({ selectedKey: '' })
  }
  window.setAvitoDetailPeriod = (period?: string) => {
    window.__vellaSetAvitoListingsState?.({ detailPeriod: isAvitoDetailPeriod(period) ? period : '7' })
  }
  window.setAvitoDetailChartMode = (mode?: string) => {
    window.__vellaSetAvitoListingsState?.({ detailChartMode: isAvitoDetailChartMode(mode) ? mode : 'traffic' })
  }
  window.__vellaReactRenderAvitoListings?.()
}

