type BackgroundReportId = 'digest' | 'abc' | 'rnp' | 'pnl' | 'expenses' | 'ads' | 'stock' | 'week-over-week'
type RefreshableReportId = Exclude<BackgroundReportId, 'expenses'>
type BackgroundReportSource = 'operational' | 'financial'
type PnlReportMode = 'operational' | 'financial'

type ReportSourcesRefreshBarProps = {
  reportId: RefreshableReportId
  period: Pick<ProductsAnalyticsPeriodState, 'fromIso' | 'toIso'>
  groupBy?: string
  source?: string
  label: string
  onCompleted: () => void
}

function reportJobStatusPath(reportId: RefreshableReportId, period: Pick<ProductsAnalyticsPeriodState, 'fromIso' | 'toIso'>, groupBy = 'sku', source = 'operational') {
  const params = new URLSearchParams({
    preset: 'custom',
    from: period.fromIso,
    to: period.toIso,
    groupBy,
    source,
  })
  return reportId === 'digest'
    ? `/api/wb/reports/digest/status?${params.toString()}`
    : `/api/wb/reports/${reportId}/jobs?${params.toString()}`
}

function backgroundReportJobStartPath(reportId: BackgroundReportId, period: Pick<ProductsAnalyticsPeriodState, 'fromIso' | 'toIso'>, groupBy = 'sku', source = 'operational') {
  const params = new URLSearchParams({
    preset: 'custom',
    from: period.fromIso,
    to: period.toIso,
    groupBy,
    source,
  })
  return reportId === 'digest'
    ? `/api/wb/reports/digest/refresh?${params.toString()}`
    : `/api/wb/reports/${reportId}/jobs?${params.toString()}`
}

function backgroundReportJobStatusPath(reportId: BackgroundReportId, period: Pick<ProductsAnalyticsPeriodState, 'fromIso' | 'toIso'>, groupBy = 'sku', source = 'operational') {
  const params = new URLSearchParams({
    preset: 'custom',
    from: period.fromIso,
    to: period.toIso,
    groupBy,
    source,
  })
  return reportId === 'digest'
    ? `/api/wb/reports/digest/status?${params.toString()}`
    : `/api/wb/reports/${reportId}/jobs?${params.toString()}`
}

function reportSourcesRefreshPath(reportId: RefreshableReportId, period: Pick<ProductsAnalyticsPeriodState, 'fromIso' | 'toIso'>, groupBy = 'sku', source = 'operational') {
  const params = new URLSearchParams({
    preset: 'custom',
    from: period.fromIso,
    to: period.toIso,
    groupBy,
    source,
  })
  return `/api/wb/reports/${reportId}/refresh-sources-job?${params.toString()}`
}

function ReportSourcesRefreshBar({ reportId, period, groupBy = 'sku', source = 'operational', label, onCompleted }: ReportSourcesRefreshBarProps) {
  const { accessToken } = useAuth()
  const [job, setJob] = useState<PnlReportJobView | null>(null)
  const running = !!job && !job.terminal && job.state !== 'idle'
  const failed = job?.state === 'failed'
  const completed = job?.state === 'completed'
  const percent = job?.displayPercent ?? job?.percent ?? 0
  void label

  useEffect(() => {
    setJob(null)
  }, [groupBy, period.fromIso, period.toIso, reportId, source])

  useEffect(() => {
    if (!accessToken || !running) return
    let cancelled = false
    let timer: number | null = null
    const authToken = accessToken

    async function poll() {
      try {
        const payload = await apiRequest<PnlReportJobPayload>(reportJobStatusPath(reportId, period, groupBy, source), {
          headers: authorizationHeaders(authToken),
        })
        if (cancelled) return
        const nextJob = describePnlReportJob(payload)
        setJob(nextJob)
        if (!nextJob.terminal) {
          timer = window.setTimeout(() => void poll(), 2000)
          return
        }
        if (nextJob.state === 'completed') onCompleted()
      } catch (error) {
        if (!cancelled) {
          setJob(describePnlReportJob({
            state: 'failed',
            stage: 'poll',
            label: error instanceof ApiError ? error.message : 'Не удалось проверить обновление данных',
            percent: 100,
          }))
        }
      }
    }

    timer = window.setTimeout(() => void poll(), 1200)
    return () => {
      cancelled = true
      if (timer !== null) window.clearTimeout(timer)
    }
  }, [accessToken, groupBy, onCompleted, period.fromIso, period.toIso, reportId, running, source])

  async function startRefresh() {
    if (!accessToken || running) return
    try {
      const payload = await apiRequest<PnlReportJobPayload>(reportSourcesRefreshPath(reportId, period, groupBy, source), {
        method: 'POST',
        headers: authorizationHeaders(accessToken),
      })
      setJob(describePnlReportJob(payload))
    } catch (error) {
      setJob(describePnlReportJob({
        state: 'failed',
        stage: 'start',
        label: error instanceof ApiError ? error.message : 'Не удалось запустить обновление данных',
        percent: 100,
      }))
    }
  }

  return (
    <div className={`report-refresh-bar${failed ? ' is-failed' : completed ? ' is-completed' : running ? ' is-running' : ''}`} data-vella-island={`${reportId}-refresh-sources-action`} data-vella-island-status="explicit-jsx">
      <style>{`
        .vella-html-parity-root .report-refresh-bar {
          margin: 0 20px 12px;
          display: grid;
          grid-template-columns: minmax(0, 1fr) auto;
          gap: 10px 12px;
          align-items: center;
          padding: 10px 12px;
          border: 1px solid var(--gray-200);
          border-radius: 10px;
          background: var(--white);
          box-shadow: var(--shadow-sm);
        }
        .vella-html-parity-root .report-refresh-bar.is-running {
          border-color: #BFDBFE;
          background: #EFF6FF;
        }
        .vella-html-parity-root .report-refresh-bar.is-failed {
          border-color: #FECACA;
          background: #FEF2F2;
        }
        .vella-html-parity-root .report-refresh-bar.is-completed {
          border-color: #BBF7D0;
          background: #F0FDF4;
        }
        .vella-html-parity-root .report-refresh-copy {
          min-width: 0;
          color: var(--gray-600);
          font-size: 13px;
          font-weight: 650;
          line-height: 1.35;
        }
        .vella-html-parity-root .report-refresh-track {
          grid-column: 1 / -1;
          height: 7px;
          overflow: hidden;
          border-radius: 999px;
          background: #DBEAFE;
        }
        .vella-html-parity-root .report-refresh-track i {
          display: block;
          height: 100%;
          border-radius: inherit;
          background: linear-gradient(90deg, #2563EB, #06B6D4);
          transition: width .35s ease;
        }
        .vella-html-parity-root .report-refresh-bar.is-failed .report-refresh-track {
          background: #FEE2E2;
        }
        .vella-html-parity-root .report-refresh-bar.is-failed .report-refresh-track i {
          background: linear-gradient(90deg, #DC2626, #F97316);
        }
        .vella-html-parity-root .report-refresh-bar.is-completed .report-refresh-track {
          background: #DCFCE7;
        }
        .vella-html-parity-root .report-refresh-bar.is-completed .report-refresh-track i {
          background: linear-gradient(90deg, #16A34A, #22C55E);
        }
      `}</style>
      <span className="report-refresh-copy">
        {failed ? 'Не удалось обновить отчет' : completed ? 'Отчет обновлен' : running ? 'Обновляем отчет. Можно продолжать работу.' : 'Обновить данные отчета'}
      </span>
      <button className="btn btn-default btn-sm" type="button" disabled={!accessToken || running} onClick={() => void startRefresh()}>
        {running ? 'Обновляем' : completed ? 'Готово' : 'Обновить'}
      </button>
      {running ? <div className="report-refresh-track"><i style={{ width: `${Math.max(8, percent)}%` }} /></div> : null}
    </div>
  )
}

function ReportHelpTip({ tip, className = '' }: { tip: string; className?: string }) {
  return <span className={`stat-tip report-help-tip${className ? ` ${className}` : ''}`} data-tip={tip}>?</span>
}

function ReportHeaderCell({ label, tip, className }: { label: string; tip: string; className?: string }) {
  return (
    <th className={className}>
      {label} <ReportHelpTip tip={tip} />
    </th>
  )
}

