type DigestLiveState = {
  loading: boolean
  error: string | null
  digest: DigestResponse | null
  debug: DigestLiveDebug | null
}

type DigestLiveDebug = {
  requestId: number
  status: 'idle' | 'auth-missing' | 'loading' | 'success' | 'waiting' | 'error'
  path: string
  url: string
  requestKey: string
  startedAt: string
  finishedAt?: string
  durationMs?: number
  hasAccessToken: boolean
  strategy?: 'single' | 'chunks'
  chunkCount?: number
  chunkIndex?: number
  chunkFrom?: string
  chunkTo?: string
  httpStatus?: number
  errorName?: string
  errorMessage?: string
  errorCode?: string
  details?: string
  jobState?: string
  jobStage?: string
  jobLabel?: string
  jobPercent?: number
}

function formatDigestInt(value: unknown) {
  const numeric = typeof value === 'number' && Number.isFinite(value) ? value : 0
  return Math.round(numeric).toLocaleString('ru-RU')
}

function formatDigestKopecks(value: unknown) {
  if (typeof value !== 'number' || !Number.isFinite(value)) return '—'
  const numeric = value
  return `${Math.round(numeric / 100).toLocaleString('ru-RU')} ₽`
}

function formatDigestPct(value: unknown) {
  return typeof value === 'number' && Number.isFinite(value) ? `${value.toLocaleString('ru-RU', { maximumFractionDigits: 1 })}%` : '—'
}

function findDigestKpi(kpis: ReportKpi[] | undefined, id: string) {
  const aliases: Record<string, string[]> = {
    sales_revenue: ['sales_revenue', 'revenue'],
    orders_qty: ['orders_qty', 'orders'],
    returns_qty: ['returns_qty', 'returns'],
  }
  const ids = aliases[id] ?? [id]
  return kpis?.find((kpi) => ids.includes(kpi.id))
}

function digestKpiValue(kpis: ReportKpi[] | undefined, id: string) {
  const value = findDigestKpi(kpis, id)?.value
  if (value == null) return undefined
  const numeric = Number(value)
  if (!Number.isFinite(numeric)) return value
  if (id === 'sales_revenue' || id === 'margin_profit') return formatDigestKopecks(numeric)
  if (id === 'orders_qty' || id === 'returns_qty') return formatDigestInt(numeric)
  return value
}

function digestKpiDelta(kpis: ReportKpi[] | undefined, id: string) {
  const delta = findDigestKpi(kpis, id)?.delta
  return delta?.label || 'данные загружены'
}

function digestToneClass(kpis: ReportKpi[] | undefined, id: string) {
  const tone = findDigestKpi(kpis, id)?.delta?.tone
  if (tone === 'good') return 'up'
  if (tone === 'bad' || tone === 'warning') return 'down'
  return 'neutral'
}

function digestProblemRoute(row: TableRow) {
  const kind = String(row.kind ?? row.type ?? '').toLowerCase()
  if (kind.includes('ads')) return 'ads'
  if (kind.includes('margin') || kind.includes('pnl')) return 'pnl'
  return 'stock'
}

function digestProblemType(row: TableRow) {
  const route = digestProblemRoute(row)
  if (route === 'ads') return 'Реклама'
  if (route === 'pnl') return 'P&L'
  return 'Остатки'
}

function digestProblemTitle(row: TableRow) {
  return String(row.title ?? row.name ?? row.sku ?? row.id ?? 'Событие требует внимания')
}

function digestProblemMeta(row: TableRow) {
  return sanitizeDigestProblemMeta(row.details ?? row.description ?? row.recommendation ?? row.reason ?? row.meta)
}

function sanitizeDigestProblemMeta(value: unknown) {
  const raw = String(value ?? '').trim()
  if (!raw) return 'Проверьте товары и примите решение в нужном отчете.'
  const withoutTechIds = raw
    .replace(/NM_\d+/gi, '')
    .replace(/\bnmID\s*\d+/gi, '')
    .replace(/\bbackend\b/gi, 'сервиса')
    .replace(/\bSKU\b/g, 'товаров')
    .replace(/\s*,\s*(?=,|\.|;|$)/g, '')
    .replace(/:\s*(?:,|\.\.\.|$)/g, '.')
    .replace(/\s{2,}/g, ' ')
    .trim()
  return withoutTechIds || 'Проверьте товары и примите решение в нужном отчете.'
}

function normalizeDigestProblemRows(rows: TableRow[]) {
  const normalized: TableRow[] = []
  const oosRows = rows.filter((row) => String(row.reason ?? row.kind ?? '').includes('oos_risk'))
  const weakAdsRows = rows.filter((row) => String(row.reason ?? row.kind ?? '').includes('weak_ads_attribution'))
  const used = new Set([...oosRows, ...weakAdsRows])
  if (oosRows.length) {
    const affectedSkuCount = oosRows.reduce((total, row) => total + (Number(row.skuCount) || 1), 0)
    const details = 'Проверьте товары с нулевым или низким доступным остатком.'
    normalized.push({
      id: 'oos-risk-ui',
      kind: 'oos_risk',
      title: `${affectedSkuCount} товаров с риском закончиться`,
      details,
      reason: 'oos_risk',
      metric: 'Остатки',
    })
  }
  if (weakAdsRows.length) {
    const samples = weakAdsRows.map((row) => String(row.campaignName ?? row.title ?? row.campaignId ?? '')).filter(Boolean).slice(0, 3)
    normalized.push({
      id: 'weak-ads-attribution-ui',
      kind: 'weak_ads_attribution',
      title: `${weakAdsRows.length} кампании требуют проверки`,
      details: `По рекламе не хватает части данных${samples.length ? `: ${samples.join(', ')}` : ''}. Проверьте кампании перед изменениями.`,
      reason: 'weak_ads_attribution',
      metric: 'Реклама',
    })
  }
  rows.forEach((row) => {
    if (!used.has(row)) normalized.push(row)
  })
  return normalized
}

function mergeDigestPointValues(values: Array<{
  label?: string
  date?: string
  value?: number | string | null
  compareValue?: number | string | null
  returnsUnits?: number | string | null
  ordersKopecks?: number | string | null
  salesKopecks?: number | string | null
  buyoutPct?: number | string | null
}>) {
  const map = new Map<string, {
    label: string
    date?: string
    value: number
    compareValue: number
    returnsUnits: number
    ordersKopecks: number
    salesKopecks: number
    buyoutPct: number | null
  }>()
  for (const value of values) {
    const label = String(value.date || value.label || '')
    if (!label) continue
    const existing = map.get(label)
    if (!existing) {
      map.set(label, {
        label,
        value: parseReportNumber(value.value) ?? 0,
        compareValue: parseReportNumber(value.compareValue) ?? 0,
        returnsUnits: parseReportNumber(value.returnsUnits) ?? 0,
        date: typeof value.date === 'string' ? value.date : undefined,
        ordersKopecks: parseReportNumber(value.ordersKopecks) ?? 0,
        salesKopecks: parseReportNumber(value.salesKopecks) ?? 0,
        buyoutPct: parseReportNumber(value.buyoutPct),
      })
      continue
    }
    existing.value += parseReportNumber(value.value) ?? 0
    existing.compareValue += parseReportNumber(value.compareValue) ?? 0
    existing.returnsUnits += parseReportNumber(value.returnsUnits) ?? 0
    existing.ordersKopecks += parseReportNumber(value.ordersKopecks) ?? 0
    existing.salesKopecks += parseReportNumber(value.salesKopecks) ?? 0
    const buyout = parseReportNumber(value.buyoutPct)
    if (buyout !== null) {
      existing.buyoutPct = existing.buyoutPct == null ? buyout : existing.buyoutPct + buyout
    }
  }
  const sorted = Array.from(map.values()).sort((left, right) => {
    const leftDate = left.date ?? left.label
    const rightDate = right.date ?? right.label
    return leftDate.localeCompare(rightDate)
  })
  return sorted.map((point) => ({
    label: point.label,
    value: point.value,
    compareValue: point.compareValue,
    returnsUnits: point.returnsUnits,
    ordersKopecks: point.ordersKopecks,
    salesKopecks: point.salesKopecks,
    buyoutPct: point.value
      ? Math.round((point.salesKopecks / point.value) * 100) / 100
      : point.buyoutPct,
    date: point.date,
  }))
}

function mergeDigestResponses(chunks: DigestResponse[], period: ProductsAnalyticsPeriodState): DigestResponse {
  if (!chunks.length) {
    throw new Error('No digest chunks to merge')
  }

  const ordered = [...chunks]
  const first = ordered[0]

  const mergedKpis = new Map<string, ReportKpi>()
  const kpiTotals = new Map<string, number>([])
  for (const chunk of ordered) {
    for (const kpi of chunk.kpis || []) {
      const existing = mergedKpis.get(kpi.id)
      const parsedValue = parseReportNumber(kpi.value)
      if (parsedValue == null) {
        if (!existing) mergedKpis.set(kpi.id, { ...kpi })
        continue
      }
      kpiTotals.set(kpi.id, (kpiTotals.get(kpi.id) ?? 0) + parsedValue)
      mergedKpis.set(kpi.id, {
        id: kpi.id,
        label: existing?.label ?? kpi.label,
        value: String((kpiTotals.get(kpi.id) ?? 0).toFixed(0)),
        hint: existing?.hint ?? kpi.hint ?? `Итог за период ${period.fromIso}–${period.toIso}`,
        delta: existing?.delta ?? kpi.delta,
      })
    }
  }

  const planFactRowsByOwner = new Map<string, typeof first['planFactRows'][number]>()
  for (const chunk of ordered) {
    for (const row of chunk.planFactRows || []) {
      const key = row.ownerId
      const existing = planFactRowsByOwner.get(key)
      if (!existing) {
        const totalPlanKopecks = parseReportNumber(row.planKopecks) ?? 0
        const totalFactKopecks = parseReportNumber(row.factKopecks) ?? 0
        const totalForecastKopecks = parseReportNumber(row.forecastKopecks) ?? 0
        const totalUnallocatedCostKopecks = parseReportNumber(row.unallocatedCostKopecks) ?? 0
        planFactRowsByOwner.set(key, {
          ...row,
          planKopecks: totalPlanKopecks,
          factKopecks: totalFactKopecks,
          forecastKopecks: totalForecastKopecks,
          completionPct: totalPlanKopecks ? Math.round((totalFactKopecks / totalPlanKopecks) * 10000) / 100 : 0,
          deltaPct: totalPlanKopecks ? Math.round(((totalFactKopecks - totalPlanKopecks) / totalPlanKopecks) * 10000) / 100 : 0,
          unallocatedCostKopecks: totalUnallocatedCostKopecks,
          needPerDayKopecks: totalPlanKopecks
            ? Math.max(0, Math.round((totalPlanKopecks - totalFactKopecks) / dateIsoDaysBetween(period.fromIso, period.toIso)))
            : null,
        })
        continue
      }
      const chunkPlan = parseReportNumber(row.planKopecks) ?? 0
      const chunkFact = parseReportNumber(row.factKopecks) ?? 0
      const chunkForecast = parseReportNumber(row.forecastKopecks) ?? 0
      const chunkUnallocatedCost = parseReportNumber(row.unallocatedCostKopecks) ?? 0
      existing.planKopecks = (existing.planKopecks ?? 0) + chunkPlan
      existing.factKopecks = (existing.factKopecks ?? 0) + chunkFact
      existing.forecastKopecks = (existing.forecastKopecks ?? 0) + chunkForecast
      existing.unallocatedCostKopecks = (existing.unallocatedCostKopecks ?? 0) + chunkUnallocatedCost
      if (row.status === 'no_plan') {
        existing.status = 'no_plan'
      }
      existing.completionPct = existing.planKopecks
        ? Math.round(((existing.factKopecks ?? 0) / (existing.planKopecks || 1)) * 10000) / 100
        : 0
      existing.deltaPct = existing.planKopecks
        ? Math.round(((existing.factKopecks ?? 0) - (existing.planKopecks ?? 0)) / (existing.planKopecks || 1) * 10000) / 100
        : 0
      existing.needPerDayKopecks = existing.planKopecks
        ? Math.max(
            0,
            Math.round((existing.planKopecks - (existing.factKopecks ?? 0)) / Math.max(1, dateIsoDaysBetween(period.fromIso, period.toIso))),
          )
        : null
      if (existing.name !== row.name) {
        existing.name = row.name
      }
      if (existing.factFreshness == null && row.factFreshness) {
        existing.factFreshness = row.factFreshness
      }
    }
  }

  const freshness = new Map<string, FreshnessItem>()
  const freshnessRank = {
    fresh: 0,
    partial: 1,
    pending_financial: 1,
    stale: 2,
  } satisfies Record<'fresh' | 'partial' | 'pending_financial' | 'stale', number>

  for (const chunk of ordered) {
    for (const item of chunk.freshness || []) {
      const existing = freshness.get(item.id)
      if (!existing) {
        freshness.set(item.id, {
          id: item.id,
          label: item.label,
          sourceType: item.sourceType,
          state: item.state,
          updatedAt: item.updatedAt,
          message: item.message,
        })
        continue
      }
      if (freshnessRank[existing.state] < freshnessRank[item.state]) {
        existing.state = item.state
      }
      if (new Date(item.updatedAt).getTime() > new Date(existing.updatedAt).getTime()) {
        existing.updatedAt = item.updatedAt
        existing.message = item.message
        existing.label = item.label
      }
    }
  }

  const problemRowsMap = new Map<string, TableRow>()
  for (const chunk of ordered) {
    for (const row of chunk.problemRows || []) {
      const rowKey = String(row.id || `${row.sku}-${row.kind}-${row.title}`)
      if (!problemRowsMap.has(rowKey)) problemRowsMap.set(rowKey, row)
    }
  }

  const alertRowsMap = new Map<string, ReportAlert>()
  for (const chunk of ordered) {
    for (const row of chunk.alerts || []) {
      const rowKey = String(row.id || `${row.title}-${row.createdAt}`)
      if (!alertRowsMap.has(rowKey)) alertRowsMap.set(rowKey, row)
    }
  }

  const chartPoints = mergeDigestPointValues(
    ordered.flatMap((chunk) => chunk.charts?.[0]?.points ?? []),
  )

  const weeklyPoints = mergeDigestPointValues(
    ordered.flatMap((chunk) => chunk.weeklyBalance?.points ?? []),
  ).slice(-14)

  const mergedQuickLinks = new Map<string, { title: string; description: string; href: string }>()
  for (const chunk of ordered) {
    for (const link of chunk.quickLinks || []) {
      if (!mergedQuickLinks.has(link.href)) {
        mergedQuickLinks.set(link.href, link)
      }
    }
  }

  const mergedPeriodCards = ordered.flatMap((chunk) => chunk.periodCards || []).slice(0, 3)

  const [firstQuickLink] = mergedQuickLinks.values()

  return {
    ...first,
    dateRange: {
      ...first.dateRange,
      from: period.fromIso,
      to: period.toIso,
    },
    kpis: Array.from(mergedKpis.values()),
    planFactRows: Array.from(planFactRowsByOwner.values()) as NonNullable<DigestResponse['planFactRows']>,
    freshness: Array.from(freshness.values()),
    alerts: Array.from(alertRowsMap.values()) as NonNullable<DigestResponse['alerts']>,
    charts: first.charts
      ? [
          {
            ...first.charts[0],
            points: chartPoints,
          },
        ]
      : [],
    weeklyBalance: first.weeklyBalance
      ? {
          ...first.weeklyBalance,
          points: weeklyPoints,
        }
      : undefined,
    periodCards: mergedPeriodCards,
    problemRows: Array.from(problemRowsMap.values()),
    quickLinks: firstQuickLink ? Array.from(mergedQuickLinks.values()) : first.quickLinks || [],
  }
}

function currentDigestLiveState(): DigestLiveState {
  return {
    loading: !!window.__vellaDigestLiveLoading,
    error: window.__vellaDigestLiveError ?? null,
    digest: window.__vellaDigestLiveReport ?? null,
    debug: window.__vellaDigestLiveDebug ?? null,
  }
}

function emitDigestLiveStateUpdated() {
  window.dispatchEvent(new CustomEvent('vella:digest-live-updated'))
}

function buildDigestReportPath(fromIso: string, toIso: string, mode: ProductsAnalyticsPeriodMode, days: number) {
  const preset = mode === 'preset' && [1, 7, 14, 30].includes(days)
    ? `${days}d`
    : 'custom'
  const params = new URLSearchParams({
    preset,
    from: fromIso,
    to: toIso,
  })
  return `/api/wb/reports/digest?${params.toString()}`
}

function currentDigestReportPath(period = readReportPeriodState('digest')) {
  const preset = period.mode === 'preset' && [1, 7, 14, 30].includes(period.days)
    ? `${period.days}d`
    : 'custom'
  const params = new URLSearchParams({
    preset,
    from: period.fromIso,
    to: period.toIso,
  })
  return `/api/wb/reports/digest?${params.toString()}`
}

function nextDigestDebugRequestId() {
  window.__vellaDigestLiveDebugSeq = (window.__vellaDigestLiveDebugSeq ?? 0) + 1
  return window.__vellaDigestLiveDebugSeq
}

function updateDigestLiveDebug(debug: DigestLiveDebug) {
  window.__vellaDigestLiveDebug = debug
  emitDigestLiveStateUpdated()
}

const digestReportMemoryCache = new Map<string, { report: DigestResponse; cachedAt: number }>()
let digestReportMemoryToken: string | null = null
let digestPrefetchAnchor = ''

function digestReportRequestKey(period: Pick<ProductsAnalyticsPeriodState, 'fromIso' | 'toIso' | 'mode' | 'days'>) {
  return `${period.fromIso}:${period.toIso}:${period.mode}:${period.days}`
}

function cacheDigestReport(requestKey: string, report: DigestResponse) {
  digestReportMemoryCache.set(requestKey, { report, cachedAt: Date.now() })
}

function prefetchDigestPresets(accessToken: string) {
  const anchor = productsPeriodAnchorIso()
  if (digestPrefetchAnchor === anchor) return
  digestPrefetchAnchor = anchor
  const currentKey = digestReportRequestKey(readReportPeriodState('digest'))
  void Promise.all([1, 7, 14, 30].map(async (days) => {
    const period = createProductsPeriodState(days, 'preset')
    const requestKey = digestReportRequestKey(period)
    if (requestKey === currentKey || digestReportMemoryCache.has(requestKey)) return
    const report = await requestLatestReportCache<DigestResponse>('digest', 'digest', accessToken, 'sku', period, 'operational')
    if (report) cacheDigestReport(requestKey, report)
  })).catch(() => {
    digestPrefetchAnchor = ''
  })
}

function installDigestLiveDataBridge(accessToken: string | null) {
  // Kept for the legacy static parity renderer; live digest now reads WB sync cache only.
  void chunkDateRanges
  void mergeDigestResponses
  void buildDigestReportPath

  window.__vellaLoadLiveDigestReport = async () => {
    const activeTab = resolveParityRouteTarget(window.location.pathname, window.location.search).tab
    if (activeTab !== 'digest') return null
    const period = readReportPeriodState('digest')
    const path = currentDigestReportPath(period)
    const url = buildApiUrl(path)
    const requestKey = digestReportRequestKey(period)
    if (window.__vellaDigestLiveRequestKey === requestKey && window.__vellaDigestLiveReport) {
      return window.__vellaDigestLiveReport
    }
    const memoryEntry = digestReportMemoryCache.get(requestKey)
    if (memoryEntry && Date.now() - memoryEntry.cachedAt < 5 * 60_000) {
      window.__vellaDigestLiveLoading = false
      window.__vellaDigestLiveError = undefined
      window.__vellaDigestLiveReport = memoryEntry.report
      window.__vellaDigestLiveRequestKey = requestKey
      emitDigestLiveStateUpdated()
      return memoryEntry.report
    }
    if (window.__vellaDigestLiveLoading) {
      if (window.__vellaDigestLiveRequestKey === requestKey) return window.__vellaDigestLiveReport ?? null
      window.__vellaDigestLiveAbortController?.abort()
    }
    if (!accessToken) {
      window.__vellaDigestLiveAbortController = undefined
      updateDigestLiveDebug({
        requestId: nextDigestDebugRequestId(),
        status: 'auth-missing',
        path,
        url,
        requestKey,
        startedAt: new Date().toISOString(),
        hasAccessToken: false,
        errorMessage: 'Нет access token в контексте фронта',
      })
      window.__vellaDigestLiveLoading = false
      window.__vellaDigestLiveError = 'Нужна авторизация'
      window.__vellaDigestLiveReport = null
      emitDigestLiveStateUpdated()
      return null
    }
    const controller = new AbortController()
    window.__vellaDigestLiveAbortController = controller
    window.__vellaDigestLiveLoading = true
    window.__vellaDigestLiveRequestKey = requestKey
    // Keep the previous report rendered while the new one loads; wiping it here
    // blanked the chart on every reload, which read as flicker.
    window.__vellaDigestLiveError = undefined
    emitDigestLiveStateUpdated()
    try {
      const latest = await loadLatestReportCache<DigestResponse>('digest', 'digest', accessToken, 'sku', period, 'operational', {
        signal: controller.signal,
        onJob: (job) => {
          if (window.__vellaDigestLiveAbortController !== controller) return
          updateDigestLiveDebug({
            requestId: nextDigestDebugRequestId(),
            status: job.state === 'failed' ? 'error' : job.terminal ? 'success' : 'loading',
            path,
            url,
            requestKey,
            startedAt: new Date().toISOString(),
            hasAccessToken: true,
            strategy: 'single',
            chunkCount: 1,
            jobState: job.state,
            jobStage: job.stage ?? undefined,
            jobLabel: job.label,
            jobPercent: job.displayPercent,
            errorMessage: job.error ?? undefined,
          })
        },
      })
      if (controller.signal.aborted || window.__vellaDigestLiveAbortController !== controller) return null
      if (latest) {
        cacheDigestReport(requestKey, latest)
        window.__vellaDigestLiveReport = latest
        window.__vellaDigestLiveError = undefined
        window.__vellaDigestLiveRequestKey = requestKey
        updateDigestLiveDebug({
          requestId: nextDigestDebugRequestId(),
          status: 'success',
          path,
          url,
          requestKey,
          strategy: 'single',
          chunkCount: 1,
          startedAt: new Date().toISOString(),
          finishedAt: new Date().toISOString(),
          durationMs: 0,
          hasAccessToken: true,
          details: 'Последний свежий кэш digest за 24 часа',
        })
        return latest
      }
      let waitingMessage: string | null = null
      try {
        const [syncStatus, snapshotsStatus] = await Promise.all([
          loadLiveRepricerSyncStatus(accessToken),
          loadLiveRepricerReportSnapshotsStatus(accessToken),
        ])
        waitingMessage = digestWaitingMessageFromWbState(syncStatus, snapshotsStatus)
      } catch (statusError) {
        console.warn('Failed to inspect WB sync state for digest empty cache', statusError)
      }
      if (controller.signal.aborted || window.__vellaDigestLiveAbortController !== controller) return null
      window.__vellaDigestLiveError = waitingMessage ?? reportCacheMissingMessage(period)
      const startedAt = new Date()
      updateDigestLiveDebug({
        requestId: nextDigestDebugRequestId(),
        status: waitingMessage ? 'waiting' : 'error',
        path,
        url,
        requestKey,
        strategy: 'single',
        chunkCount: 1,
        startedAt: startedAt.toISOString(),
        finishedAt: startedAt.toISOString(),
        durationMs: 0,
        hasAccessToken: true,
        errorMessage: window.__vellaDigestLiveError,
        details: waitingMessage ? 'Кэш digest еще не готов, WB sync/report snapshots выполняются' : 'Кэш для выбранного периода не найден',
      })
      return null
    } catch (error) {
      if (isReportLoadAbort(error) || controller.signal.aborted || window.__vellaDigestLiveAbortController !== controller) return null
      const message = error instanceof Error ? error.message : 'Не удалось получить воронку продаж'
      window.__vellaDigestLiveReport = null
      window.__vellaDigestLiveError = message
      updateDigestLiveDebug({
        requestId: nextDigestDebugRequestId(),
        status: 'error',
        path,
        url,
        requestKey,
        strategy: 'single',
        chunkCount: 1,
        startedAt: new Date().toISOString(),
        finishedAt: new Date().toISOString(),
        durationMs: 0,
        hasAccessToken: true,
        errorMessage: message,
      })
      return null
    } finally {
      if (window.__vellaDigestLiveAbortController === controller) {
        window.__vellaDigestLiveAbortController = undefined
        window.__vellaDigestLiveLoading = false
        emitDigestLiveStateUpdated()
      }
    }
  }

  if (accessToken !== digestReportMemoryToken) {
    // The access token rotates on a timer, but the cached reports belong to the
    // organisation, not to one token.  Dropping them on every rotation refired
    // the four preset prefetches and reloaded the visible report each time.
    digestReportMemoryToken = accessToken
  }
  if (accessToken && resolveParityRouteTarget(window.location.pathname, window.location.search).tab === 'digest') {
    prefetchDigestPresets(accessToken)
  }
}

function useDigestLiveState(): DigestLiveState {
  const [state, setState] = useState<DigestLiveState>(currentDigestLiveState)

  useEffect(() => {
    const refresh = () => setState(currentDigestLiveState())
    window.addEventListener('vella:digest-live-updated', refresh)
    refresh()
    return () => window.removeEventListener('vella:digest-live-updated', refresh)
  }, [])

  return state
}

