function ManagerSignalPanelIsland({ replacementKey }: { replacementKey: string }) {
  const { accessToken } = useAuth()
  const state = useDigestLiveState()
  const rows = state.digest?.planFactRows ?? []
  const company = rows.find((row) => row.owner === 'company')
  const [editing, setEditing] = useState(false)
  const [saving, setSaving] = useState(false)
  const [loadingPlan, setLoadingPlan] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [companyRevenue, setCompanyRevenue] = useState('')
  const [companyMargin, setCompanyMargin] = useState('')
  const [managerPlans, setManagerPlans] = useState<Array<{ id: string; name: string; revenue: string; margin: string }>>([])
  const month = state.digest?.dateRange?.to?.slice(0, 7) ?? new Date().toISOString().slice(0, 7)

  useEffect(() => {
    if (!editing || !accessToken) return
    let cancelled = false
    setLoadingPlan(true)
    void apiRequest<{ company?: { revenuePlanKopecks?: number; marginPlanKopecks?: number }; managers?: Array<{ id: string; name: string; revenuePlanKopecks?: number; marginPlanKopecks?: number }> }>(`/api/wb/reports/digest/plan?month=${encodeURIComponent(month)}`, { headers: authorizationHeaders(accessToken) })
      .then((plan) => {
        if (cancelled) return
        const digestPlan = plan ?? {}
        const planManagers = digestPlan.managers ?? []
        const fallbackManagers = planManagers.length
          ? []
          : runtimeProductManagers().filter((manager) => manager.active)
        setCompanyRevenue(String(Math.round((digestPlan.company?.revenuePlanKopecks ?? 0) / 100) || ''))
        setCompanyMargin(String(Math.round((digestPlan.company?.marginPlanKopecks ?? 0) / 100) || ''))
        setManagerPlans((planManagers.length ? planManagers : fallbackManagers).map((manager) => ({ id: manager.id, name: manager.name, revenue: String(Math.round(((manager as { revenuePlanKopecks?: number }).revenuePlanKopecks ?? 0) / 100) || ''), margin: String(Math.round(((manager as { marginPlanKopecks?: number }).marginPlanKopecks ?? 0) / 100) || '') })))
      })
      .catch((loadError) => !cancelled && setError(loadError instanceof Error ? loadError.message : 'Не удалось загрузить менеджеров проекта.'))
      .finally(() => {
        if (!cancelled) setLoadingPlan(false)
      })
    return () => { cancelled = true }
  }, [accessToken, editing, month])

  const openEditor = () => {
    setError(null)
    setEditing(true)
  }
  const savePlan = async () => {
    if (!accessToken) return setError('Нет авторизации для сохранения плана.')
    const toKopecks = (value: string) => Math.max(0, Math.round((Number(value.replace(',', '.')) || 0) * 100))
    setSaving(true)
    setError(null)
    try {
      await apiRequest('/api/wb/reports/digest/plan', {
        method: 'POST',
        headers: authorizationHeaders(accessToken),
        body: JSON.stringify({
          month,
          company: { revenuePlanKopecks: toKopecks(companyRevenue), marginPlanKopecks: toKopecks(companyMargin) },
          managers: managerPlans.map((manager) => ({
            id: manager.id,
            name: manager.name,
            revenuePlanKopecks: toKopecks(manager.revenue),
            marginPlanKopecks: toKopecks(manager.margin),
          })),
        }),
      })
      setEditing(false)
      window.__vellaDigestLiveRequestKey = ''
      void window.__vellaLoadLiveDigestReport?.()
    } catch (saveError) {
      setError(saveError instanceof Error ? saveError.message : 'Не удалось сохранить план.')
    } finally {
      setSaving(false)
    }
  }
  const note = state.loading
    ? 'загружаем план-факт'
    : rows.length
      ? company?.status === 'no_fact'
        ? 'Данные воронки продаж для расчёта ещё не готовы'
        : `${company?.metricLabel ?? 'Маржа'}: ${formatDigestPct(company?.completionPct)} · ${formatDigestKopecks(company?.needPerDayKopecks)} нужно в день`
      : 'План не создан'
  const managerCount = Math.max(0, rows.length - 1)
  const tag = rows.length ? managerCount ? `Компания + ${managerCount} менеджера` : 'Компания' : 'нет плана'
  return (
    <div
      key={replacementKey}
      className="report-panel report-panel-pad manager-signal-panel"
      data-tip="Выполнение плана по маржинальной прибыли: компания первая, затем 3 менеджера"
      data-vella-island="manager-signal-panel"
      data-vella-island-status="explicit-jsx"
    >
      <div className="report-chart-head">
        <div>
          <div className="report-card-title">Выполнение плана</div>
          <div className="report-card-note">{note}</div>
        </div>
        <div className="manager-signal-actions"><span className="report-tag fin">{tag}</span><button type="button" className="manager-plan-button" onClick={openEditor}>{rows.length ? 'Изменить план' : 'Создать план'}</button></div>
      </div>
      {editing ? <div className="manager-plan-editor" aria-label="Создание плана">
        <b>План на {month}</b><span>Укажите план компании и менеджеров в рублях.</span>
        <div className="manager-plan-fields"><label>Компания: выручка<input type="number" min="0" value={companyRevenue} onChange={(event) => setCompanyRevenue(event.target.value)} /></label><label>Компания: маржа<input type="number" min="0" value={companyMargin} onChange={(event) => setCompanyMargin(event.target.value)} /></label></div>
        {managerPlans.map((manager, index) => <div className="manager-plan-fields" key={manager.id}><label>{manager.name}: выручка<input type="number" min="0" value={manager.revenue} onChange={(event) => setManagerPlans((current) => current.map((item, itemIndex) => itemIndex === index ? { ...item, revenue: event.target.value } : item))} /></label><label>{manager.name}: маржа<input type="number" min="0" value={manager.margin} onChange={(event) => setManagerPlans((current) => current.map((item, itemIndex) => itemIndex === index ? { ...item, margin: event.target.value } : item))} /></label></div>)}
        {loadingPlan ? <div className="manager-plan-note">Загружаем менеджеров проекта…</div> : null}
        {!loadingPlan && !managerPlans.length ? <div className="manager-plan-note">Пока нет менеджеров для индивидуального плана. План компании можно сохранить отдельно.</div> : null}
        {error ? <div className="manager-plan-error">{error}</div> : null}
        <div className="manager-plan-actions"><button type="button" onClick={() => setEditing(false)}>Отмена</button><button type="button" className="manager-plan-button" disabled={saving} onClick={() => void savePlan()}>{saving ? 'Сохраняю…' : 'Сохранить план'}</button></div>
      </div> : null}
      <div className="manager-signal-grid" aria-live="polite">
        {rows.map((row) => (
          <div className={`manager-signal-card ${row.owner === 'company' ? 'company' : ''}`.trim()} key={row.ownerId}>
            <span>{row.name}</span>
            <b className="manager-signal-pct">{formatDigestPct(row.completionPct)}</b>
            <em>{row.status === 'no_plan' ? 'нет плана' : row.status === 'no_fact' ? 'данные ещё не готовы' : row.status === 'risk' ? 'прогноз ниже плана' : row.factFreshness === 'final' ? 'факт финальный' : 'факт предварительный'}</em>
            <div className="manager-signal-metrics">
              <div className="manager-signal-metric">{row.metricLabel ?? 'Маржа'}: факт <b>{formatDigestKopecks(row.factKopecks)}</b></div>
              <div className="manager-signal-metric">{row.metricLabel ?? 'Маржа'}: план <b>{row.planKopecks == null ? '—' : formatDigestKopecks(row.planKopecks)}</b></div>
              <div className="manager-signal-metric">Прогноз <b>{row.forecastKopecks == null ? '—' : formatDigestKopecks(row.forecastKopecks)}</b></div>
              <div className="manager-signal-metric">Мин. в день <b>{row.needPerDayKopecks == null ? '—' : formatDigestKopecks(row.needPerDayKopecks)}</b></div>
              {row.revenuePlanKopecks != null ? <><div className="manager-signal-metric">Выручка факт <b>{formatDigestKopecks(row.revenueFactKopecks)}</b></div><div className="manager-signal-metric">Выручка план <b>{formatDigestKopecks(row.revenuePlanKopecks)}</b></div></> : null}
            </div>
          </div>
        ))}
      </div>
      <div className="manager-signal-empty" id="digestManagerSignalEmpty">
        {!state.loading && !rows.length ? 'План не создан.' : ''}
      </div>
      <div className="manager-signal-overflow" id="digestManagerSignalOverflow" />
    </div>
  )
}

