function applyGenericReportFilterFromElement(element: HTMLElement) {
  const tab = element.closest<HTMLElement>('.tab-content')
  if (tab) window.applyGenericReportFilter?.(tab)
}

function getGenericReportChipSegment(chip: HTMLElement) {
  const parent = chip.parentElement
  if (!parent) return [chip]
  const children = Array.from(parent.children)
  const index = children.indexOf(chip)
  let start = index
  let end = index
  while (start > 0 && !children[start - 1].classList.contains('chips-divider')) start -= 1
  while (end < children.length - 1 && !children[end + 1].classList.contains('chips-divider')) end += 1
  return children.slice(start, end + 1).filter((item): item is HTMLElement => item instanceof HTMLElement && item.classList.contains('chip'))
}

function activateGenericReportChip(chip: HTMLElement) {
  getGenericReportChipSegment(chip).forEach((item) => item.classList.remove('active'))
  chip.classList.add('active')
  applyGenericReportFilterFromElement(chip)
  window.showToast?.(`Фильтр: ${chip.textContent?.trim() || ''}`, 'info')
}

function updateGenericReportSelect(event: ChangeEvent<HTMLSelectElement>) {
  event.preventDefault()
  event.stopPropagation()
  applyGenericReportFilterFromElement(event.currentTarget)
  window.showToast?.(`Выбрано: ${event.currentTarget.value}`, 'info')
}

function exportGenericReportXlsx(event: MouseEvent<HTMLButtonElement>) {
  event.preventDefault()
  event.stopPropagation()
  window.showToast?.('XLSX будет сформирован по текущим фильтрам', 'info')
}

function normalizeRnpFilterText(value: unknown) {
  return String(value ?? '').trim().toLocaleLowerCase('ru-RU')
}

function rnpFilterKey(label: string) {
  const normalized = normalizeRnpFilterText(label)
  if (normalized.includes('нов')) return 'new'
  if (normalized.includes('без движения')) return 'no-movement'
  return 'all'
}

function getRnpActiveChip(tab: HTMLElement, selector: string, fallback: string) {
  return tab.querySelector<HTMLElement>(`${selector}.active`)?.dataset.rnpGroup
    ?? tab.querySelector<HTMLElement>(`${selector}.active`)?.dataset.rnpFilter
    ?? fallback
}

function managerMatchesRnpRow(row: HTMLElement, manager: string) {
  if (manager === 'all' || manager === 'mine') return true
  if (manager === 'unassigned') return (row.dataset.manager ?? row.dataset.managerId) === 'unassigned'
  const rowManager = normalizeRnpFilterText(row.dataset.manager ?? row.dataset.managerId)
  const normalizedManager = normalizeRnpFilterText(manager)
  if (!rowManager) return false
  if (rowManager === normalizedManager) return true
  if (normalizedManager.includes('мария')) return rowManager.includes('мд') || rowManager.includes('maria')
  if (normalizedManager.includes('анна')) return rowManager.includes('ап') || rowManager.includes('anna')
  if (normalizedManager.includes('ирина')) return rowManager.includes('ик') || rowManager.includes('irina')
  if (normalizedManager.includes('светлана')) return rowManager.includes('св') || rowManager.includes('svetlana')
  return false
}

function updateRnpFilterEmptyState(tab: HTMLElement) {
  const table = tab.querySelector<HTMLTableElement>('.report-table-wrap table')
  const tbody = table?.tBodies?.[0]
  if (!table || !tbody) return
  const rows = Array.from(tbody.querySelectorAll<HTMLElement>('tr[data-report-row="rnp"]'))
  const visibleCount = rows.filter((row) => row.style.display !== 'none').length
  let empty = tbody.querySelector<HTMLTableRowElement>('tr[data-report-empty="rnp-filter"]')
  if (!empty) {
    empty = document.createElement('tr')
    empty.dataset.reportEmpty = 'rnp-filter'
    const cell = document.createElement('td')
    cell.colSpan = table.querySelectorAll('thead th').length || 1
    cell.innerHTML = '<div class="report-empty-note visible"><b>Нет строк по выбранным фильтрам</b><br><span>Смените срез, статус или поисковый запрос.</span></div>'
    empty.appendChild(cell)
    tbody.appendChild(empty)
  }
  empty.style.display = visibleCount ? 'none' : ''
}

function applyRnpReportFilter(tab: HTMLElement) {
  const query = normalizeRnpFilterText(tab.querySelector<HTMLInputElement>('.search input')?.value)
  const group = getRnpActiveChip(tab, '[data-rnp-group]', 'sku')
  const filter = getRnpActiveChip(tab, '[data-rnp-filter]', 'all')
  const managerSelect = Array.from(tab.querySelectorAll<HTMLSelectElement>('select.adv-select')).find((select) => /менеджер/i.test(select.options?.[0]?.textContent ?? ''))
  const manager = managerSelect?.value || 'all'
  tab.querySelectorAll<HTMLElement>('tbody tr[data-report-row="rnp"]').forEach((row) => {
    const searchText = normalizeRnpFilterText(row.dataset.search || row.textContent)
    const tags = normalizeRnpFilterText(row.dataset.reportTags).split('|').filter(Boolean)
    const groupOk = group === 'sku' || tags.includes(group)
    const filterOk = filter === 'all' || tags.includes(filter)
    const queryOk = !query || searchText.includes(query)
    row.style.display = groupOk && filterOk && queryOk && managerMatchesRnpRow(row, manager) ? '' : 'none'
  })
  updateRnpFilterEmptyState(tab)
}

function applyRnpReportFilterFromElement(element: HTMLElement) {
  const tab = element.closest<HTMLElement>('#tab-rnp')
  if (tab) applyRnpReportFilter(tab)
}

function activateRnpReportChip(chip: HTMLElement) {
  getGenericReportChipSegment(chip).forEach((item) => item.classList.remove('active'))
  chip.classList.add('active')
  applyRnpReportFilterFromElement(chip)
  window.showToast?.(`Фильтр: ${chip.textContent?.trim() || ''}`, 'info')
}

function updateRnpReportSelect(event: ChangeEvent<HTMLSelectElement>) {
  event.preventDefault()
  event.stopPropagation()
  applyRnpReportFilterFromElement(event.currentTarget)
  window.showToast?.(`Выбрано: ${event.currentTarget.value}`, 'info')
}

