function cleanReportStateMessage(message: unknown) {
  return String(message ?? '')
    .replace(/\bbackend\b/gi, 'сервис')
    .replace(/\bбэкенд\b/gi, 'сервис')
    .replace(/\bБэк\b/g, 'Сервис')
    .replace(/\bAPI\b/g, 'данные')
    .trim()
}

