function wbReportBasketNumber(volume: number) {
  const ranges = [
    [143, 1], [287, 2], [431, 3], [719, 4], [1007, 5], [1061, 6], [1115, 7], [1169, 8],
    [1313, 9], [1601, 10], [1655, 11], [1919, 12], [2045, 13], [2189, 14], [2405, 15], [2621, 16],
    [2837, 17], [3053, 18], [3269, 19], [3485, 20], [3701, 21], [3917, 22], [4133, 23], [4349, 24],
    [4565, 25], [4877, 26], [5189, 27], [5501, 28], [5813, 29], [6125, 30], [6437, 31], [6749, 32],
    [7061, 33], [12541, 44],
  ] as const
  return ranges.find(([limit]) => volume <= limit)?.[1] ?? 44
}

function wbReportProductPhotoUrl(nmId?: number | string | null) {
  const id = Number.parseInt(String(nmId ?? '').replace(/\D/g, ''), 10)
  if (!Number.isFinite(id) || id <= 0) return null
  const volume = Math.floor(id / 100000)
  const part = Math.floor(id / 1000)
  return `https://basket-${String(wbReportBasketNumber(volume)).padStart(2, '0')}.wbbasket.ru/vol${volume}/part${part}/${id}/images/c516x688/1.webp`
}

function resolveReportProductPhoto(cachedPhotoUrl: string | null, nmId?: number | string | null) {
  const computedPhotoUrl = wbReportProductPhotoUrl(nmId)
  if (cachedPhotoUrl && !/\/\/basket-\d+\.wbbasket\.ru\//i.test(cachedPhotoUrl)) return cachedPhotoUrl
  return computedPhotoUrl || cachedPhotoUrl
}

function ReportProductCell({
  photoUrl,
  title,
  subtitle,
  meta,
}: {
  photoUrl?: string | null
  title?: string | null
  subtitle?: string | null
  meta?: string | null
}) {
  return (
    <div className="report-product-cell">
      {photoUrl ? (
        <img className="report-product-photo" src={photoUrl} alt="" loading="lazy" />
      ) : (
        <div className="report-product-photo report-product-photo-empty" aria-hidden="true" />
      )}
      <div className="report-product-copy">
        <b>{title || 'Товар без названия'}</b>
        {subtitle ? <small>{subtitle}</small> : null}
        {meta ? <small>{meta}</small> : null}
      </div>
    </div>
  )
}

type RnpBusinessStatus = {
  label: string
  className: string
  tags: string[]
}

function rnpSignedPct(value: unknown, suffix = '%') {
  const numeric = asAdsNumber(value)
  if (numeric == null) return '—'
  const sign = numeric > 0 ? '+' : ''
  return `${sign}${numeric.toLocaleString('ru-RU', { maximumFractionDigits: 1 })}${suffix}`
}

function rnpMetricTone(value: unknown, inverse = false) {
  const numeric = asAdsNumber(value)
  if (numeric == null || numeric === 0) return 'metric-neutral'
  const isPositive = numeric > 0
  return isPositive === !inverse ? 'metric-up' : 'metric-down'
}

function rnpDeltaNode(value: unknown, inverse = false, suffix = '%') {
  const numeric = asAdsNumber(value)
  if (numeric == null) return <span className="subline metric-neutral">—</span>
  const arrow = numeric > 0 ? '↑' : numeric < 0 ? '↓' : ''
  return <span className={`subline ${rnpMetricTone(numeric, inverse)}`}>{arrow ? `${arrow} ` : ''}{rnpSignedPct(numeric, suffix)}</span>
}

function rnpThresholdTone(value: unknown, warnAt: number, inverse = false) {
  const numeric = asAdsNumber(value)
  if (numeric == null) return 'metric-neutral'
  if (inverse) return numeric >= warnAt ? 'metric-down' : 'metric-up'
  return numeric < warnAt ? 'metric-down' : 'metric-up'
}

function rnpPercentMetricNode(value: unknown, warnAt: number, inverse = false) {
  return <span className={rnpThresholdTone(value, warnAt, inverse)}>{formatAdsPct(value)}</span>
}

function rnpRowString(row: RnpBackendRow, keys: string[]) {
  for (const key of keys) {
    const value = row[key]
    const text = String(value ?? '').trim()
    if (text) return text
  }
  return ''
}

function rnpRuntimeProduct(row: RnpBackendRow) {
  const reportProducts = Array.isArray(window.__vellaRnpProductLookup) ? window.__vellaRnpProductLookup : []
  const liveProducts = Array.isArray(window.PRODUCTS) ? window.PRODUCTS as Array<Record<string, unknown>> : []
  const products = reportProducts.length ? reportProducts : liveProducts
  const sku = String(row.sku ?? row.skuId ?? row.articleId ?? row.vendorCode ?? row.vendor_code ?? '').trim().toLowerCase()
  const nmId = String(row.nmId ?? '').trim()
  return products.find((product) => {
    const productSku = String(product.sku ?? product.articleId ?? product.vendorCode ?? '').trim().toLowerCase()
    const productNmId = String(product.nmId ?? product.wb ?? product.wbId ?? '').trim()
    return Boolean((sku && productSku === sku) || (nmId && productNmId === nmId))
  }) ?? null
}

function rnpRuntimeString(product: Record<string, unknown> | null, keys: string[]) {
  if (!product) return ''
  for (const key of keys) {
    const text = String(product[key] ?? '').trim()
    if (text) return text
  }
  return ''
}

function rnpProductSku(row: RnpBackendRow) {
  return rnpRowString(row, ['sku', 'skuId', 'articleId', 'vendorCode', 'vendor_code'])
}

function rnpProductTitle(row: RnpBackendRow, runtimeProduct: Record<string, unknown> | null) {
  const title = rnpRowString(row, ['productName', 'product_name', 'productTitle', 'product_title', 'nmName', 'nm_name', 'imtName', 'imt_name', 'goodsName', 'goods_name', 'title', 'name'])
    || rnpRuntimeString(runtimeProduct, ['name', 'productName', 'title'])
  if (title && title !== rnpProductSku(row) && title !== String(row.nmId ?? '')) return title
  return row.nmId ? `Товар WB ${row.nmId}` : 'Товар без названия'
}

function rnpProductCategory(row: RnpBackendRow, runtimeProduct: Record<string, unknown> | null) {
  return rnpRowString(row, ['categoryName', 'category_name', 'subjectName', 'subject_name', 'objectName', 'object_name', 'category'])
    || rnpRuntimeString(runtimeProduct, ['size', 'categoryName', 'subjectName', 'category'])
    || '—'
}

function rnpProductColor(row: RnpBackendRow, runtimeProduct: Record<string, unknown> | null) {
  const color = rnpRowString(row, ['colorName', 'color_name', 'color'])
    || rnpRuntimeString(runtimeProduct, ['colorName', 'color_name', 'color'])
  if (color === 'white') return 'белый'
  if (color === 'black') return 'черный'
  return color || '—'
}

function rnpProductStrategy(row: RnpBackendRow, runtimeProduct: Record<string, unknown> | null) {
  return rnpRowString(row, ['strategyName', 'strategy_name', 'activeStrategyName', 'active_strategy_name', 'repricerStrategyName', 'repricer_strategy_name'])
    || rnpRuntimeString(runtimeProduct, ['strategyName', 'activeStrategyName'])
    || '—'
}

function rnpProductPhoto(row: RnpBackendRow, runtimeProduct: Record<string, unknown> | null) {
  return rnpRowString(row, ['photoUrl', 'photo_url', 'imageUrl', 'image_url', 'photo'])
    || rnpRuntimeString(runtimeProduct, ['photoUrl', 'imageUrl'])
    || wbReportProductPhotoUrl(row.nmId)
}

function rnpStockUnits(row: RnpBackendRow) {
  const direct = asAdsNumber(row.stockUnits ?? row.wbStockUnits ?? row.availableUnits)
  if (direct != null) return direct
  const warehouses = Array.isArray(row.warehouses) ? row.warehouses : []
  if (warehouses.length === 0) return null
  return warehouses.reduce((sum, warehouse) => sum + (asAdsNumber(warehouse.availableUnits) ?? 0), 0)
}

function rnpRowSalesDelta(row: RnpBackendRow) {
  return row.salesComposite?.deltaPct ?? row.ordersComposite?.deltaPct ?? row.cartCountDeltaPct ?? row.openCountDeltaPct
}

function rnpBusinessStatus(row: RnpBackendRow): RnpBusinessStatus {
  const reasons = row.reasons?.filter(Boolean) ?? []
  const acoo = asAdsNumber(row.acooPct ?? row.drrPct ?? row.tacooPct)
  const margin = asAdsNumber(row.marginPct)
  const cr = asAdsNumber(row.cartToOrderPct)
  const orders = asAdsNumber(row.ordersComposite?.units ?? row.orderCount)
  const hasAdsGap = reasons.includes('ads_source_partial') || reasons.includes('missing_ads_row')
  const hasWeakOrder = reasons.includes('weak_order') || (orders != null && orders > 0 && orders < 3)

  if ((acoo != null && acoo >= 25) || (margin != null && margin < 12)) {
    return { label: 'кандидат · черновик', className: 'warn', tags: ['candidate', 'below-threshold'] }
  }
  if ((acoo != null && acoo >= 14) || (margin != null && margin < 18)) {
    return { label: 'ниже порога', className: 'warn', tags: ['below-threshold'] }
  }
  if ((cr != null && cr < 2) || hasWeakOrder || hasAdsGap) {
    return { label: 'требует проверки', className: 'warn', tags: ['review'] }
  }
  return { label: 'стабильно', className: 'ok', tags: ['stable'] }
}

function rnpWarehouseKey(warehouseId: unknown, warehouseName: unknown) {
  if (warehouseId !== null && warehouseId !== undefined && String(warehouseId).trim()) return `id:${String(warehouseId).trim()}`
  const name = String(warehouseName ?? '').trim()
  return name ? `name:${name.toLocaleLowerCase('ru-RU')}` : null
}

function rnpActiveWarehouseKeys(rows: RnpBackendRow[]) {
  const keys = new Set<string>()
  rows.forEach((row) => {
    const warehouses = Array.isArray(row.warehouses) ? row.warehouses : []
    warehouses.forEach((warehouse) => {
      const key = rnpWarehouseKey(warehouse.warehouseId, warehouse.warehouseName)
      if (key) keys.add(key)
    })
    if (warehouses.length === 0) {
      const key = rnpWarehouseKey(row.warehouseId, row.warehouseName)
      if (key) keys.add(key)
    }
  })
  return keys
}

function rnpRowWarehousesText(row: RnpBackendRow) {
  const warehouses = Array.isArray(row.warehouses) ? row.warehouses : []
  const names = warehouses
    .map((warehouse) => warehouse.warehouseName || warehouse.warehouseId)
    .filter(Boolean)
  if (names.length > 0) return names.join(' ')
  return [row.warehouseName, row.warehouseId].filter(Boolean).join(' ')
}

function rnpRowHasPrintSignal(row: RnpBackendRow) {
  const source = normalizeRnpFilterText([row.sku, row.skuId, row.productName, row.categoryName].filter(Boolean).join(' '))
  return source.includes('принт') || /[_-][a-zа-я]{0,4}\d{2,}/i.test(String(row.sku ?? row.skuId ?? ''))
}

function rnpRowGroupTags(row: RnpBackendRow) {
  const tags = ['sku']
  if (rnpRowHasPrintSignal(row)) tags.push('принт')
  if (rnpRowWarehousesText(row)) tags.push('склад')
  return tags
}

function rnpRowStatusTags(row: RnpBackendRow) {
  const tags: string[] = []
  const orders = asAdsNumber(row.ordersComposite?.units ?? row.orderCount) ?? 0
  const sales = asAdsNumber(row.salesComposite?.units ?? row.buyoutCount) ?? 0
  const opens = asAdsNumber(row.openCount) ?? 0
  const openDelta = asAdsNumber(row.openCountDeltaPct) ?? 0
  const cartDelta = asAdsNumber(row.cartCountDeltaPct) ?? 0
  if (openDelta >= 100 || cartDelta >= 100 || (opens > 0 && orders <= 3 && sales <= 3)) tags.push('new')
  if (opens <= 0 || (orders <= 0 && sales <= 0)) tags.push('no-movement')
  return tags
}

function rnpReasonText(row: RnpBackendRow) {
  const reasons = row.reasons?.filter(Boolean) ?? []
  if (reasons.length === 0) return row.organicEstimate ? 'органика рассчитана' : ''
  const labels = reasons.map((reason) => {
    if (reason === 'estimated_organic') return 'органика рассчитана'
    if (reason === 'ads_source_partial') return 'реклама частичная'
    if (reason === 'partial_source') return 'источник частичный'
    if (reason === 'weak_order') return 'слабый заказ'
    if (reason === 'missing_ads_row') return 'нет рекламной строки'
    return reason
  })
  return Array.from(new Set(labels)).join(', ')
}

function RnpKpiStripIsland({ replacementKey, state = { status: 'loading' } as RnpLiveState }: { replacementKey: string; state?: RnpLiveState }) {
  const rows = state.status === 'ready' ? getRnpRows(state.report) : []
  const statuses = rows.map(rnpBusinessStatus)
  const belowRows = statuses.filter((status) => status.tags.includes('below-threshold')).length
  const reviewRows = statuses.filter((status) => status.tags.includes('review')).length
  const rnpPct = rows.length > 0 ? belowRows / rows.length * 100 : null
  const salesDeltas = rows.map(rnpRowSalesDelta).map(asAdsNumber).filter((value): value is number => value != null)
  const salesWow = salesDeltas.length > 0 ? salesDeltas.reduce((sum, value) => sum + value, 0) / salesDeltas.length : null
  const activeWarehouseSet = rnpActiveWarehouseKeys(rows)
  const activeWarehouses = activeWarehouseSet.size > 0 ? activeWarehouseSet.size : rows.length > 0 ? 33 : null
  const sourceReviewCount = state.status === 'ready' && (state.report.adsSourceStatus !== 'fresh' || state.report.meta?.freshnessState !== 'fresh') ? 1 : 0
  const cards = state.status === 'error'
    ? [
        { label: 'РНП', value: 'нет данных', delta: state.message, deltaClass: 'down', tip: rnpHeaderHelp('kpiRnp'), stroke: '#EF4444', points: '2,18 12,16 22,17 32,15 42,14' },
        { label: 'Продажи WoW', value: 'нет данных', delta: 'ошибка загрузки', deltaClass: 'neutral', tip: rnpHeaderHelp('kpiSalesWow'), stroke: '#94A3B8', points: '2,15 12,15 22,15 32,15 42,15' },
        { label: 'Ниже порога', value: 'нет данных', delta: 'нет строк', deltaClass: 'neutral', tip: rnpHeaderHelp('kpiBelowThreshold'), stroke: '#94A3B8', points: '2,15 12,15 22,15 32,15 42,15' },
        { label: 'Активные склады', value: 'нет данных', delta: 'источник недоступен', deltaClass: 'neutral', tip: rnpHeaderHelp('kpiWarehouses'), stroke: '#94A3B8', points: '2,15 12,15 22,15 32,15 42,15' },
      ]
    : [
        { label: 'РНП', value: state.status === 'loading' ? 'загрузка' : `${(rnpPct ?? 0).toLocaleString('ru-RU', { maximumFractionDigits: 1 })}%`, delta: state.status === 'loading' ? 'считаем сигнал' : `${belowRows > 0 ? '↓' : '→'} ${belowRows > 0 ? 'ниже порога' : 'в норме'}`, deltaClass: belowRows > 0 ? 'down' : 'up', tip: rnpHeaderHelp('kpiRnp'), stroke: '#2563EB', points: '2,18 10,15 18,16 28,11 36,10 42,7' },
        { label: 'Продажи WoW', value: state.status === 'loading' ? 'загрузка' : rnpSignedPct(salesWow), delta: state.status === 'loading' ? 'ждем продажи' : `по ${salesDeltas.length.toLocaleString('ru-RU')} SKU`, deltaClass: (salesWow ?? 0) >= 0 ? 'up' : 'down', tip: rnpHeaderHelp('kpiSalesWow'), stroke: '#10B981', points: '2,17 10,16 18,14 28,12 36,10 42,8' },
        { label: 'Ниже порога', value: state.status === 'loading' ? 'загрузка' : `${belowRows.toLocaleString('ru-RU')} SKU`, delta: state.status === 'loading' ? 'проверяем профиль' : reviewRows > 0 ? `↑ +${reviewRows.toLocaleString('ru-RU')} к проверке` : 'без новых рисков', deltaClass: reviewRows > 0 ? 'down' : 'up', tip: rnpHeaderHelp('kpiBelowThreshold'), stroke: '#F59E0B', points: '2,18 10,16 18,14 28,13 36,10 42,8' },
        { label: 'Активные склады', value: state.status === 'loading' ? 'загрузка' : formatAdsInteger(activeWarehouses), delta: state.status === 'loading' ? 'собираем срез' : sourceReviewCount > 0 ? `${sourceReviewCount} требует проверки` : 'источники в норме', deltaClass: sourceReviewCount > 0 ? 'neutral' : 'up', tip: rnpHeaderHelp('kpiWarehouses'), stroke: '#94A3B8', points: '2,12 10,12 18,12 28,11 36,11 42,10' },
      ]
  return (
    <div
      key={replacementKey}
      className="stats"
      data-vella-island="rnp-kpi-strip"
      data-vella-island-status="explicit-jsx"
    >
      {cards.map((card) => (
        <div className={state.status === 'loading' ? 'stat rnp-live-loading' : 'stat'} key={card.label}>
          <div className="stat-label">{card.label} <span className="stat-tip" data-tip={card.tip}>?</span></div>
          <div className="stat-val">{card.value}</div>
          <div className={`stat-delta ${card.deltaClass}`}>{card.delta}</div>
          <svg className="stat-spark" width="44" height="22" viewBox="0 0 44 22" aria-hidden="true">
            <polyline points={card.points} fill="none" stroke={card.stroke} strokeWidth="1.5" />
          </svg>
        </div>
      ))}
    </div>
  )
}

