function backgroundReportLatestCachePath(
  reportId: BackgroundReportId,
  groupBy = 'sku',
  source = 'operational',
  period?: Pick<ProductsAnalyticsPeriodState, 'fromIso' | 'toIso'>,
) {
  const params = new URLSearchParams({ groupBy, source })
  if (period) {
    params.set('preset', 'custom')
    params.set('from', period.fromIso)
    params.set('to', period.toIso)
  }
  return `/api/wb/reports/${reportId}/latest-cache?${params.toString()}`
}

type LoadLatestReportCacheOptions = {
  signal?: AbortSignal
  onJob?: (job: PnlReportJobView) => void
}

function isReportLoadAbort(error: unknown) {
  return error instanceof DOMException && error.name === 'AbortError'
}

function backgroundReportPollDelay(signal?: AbortSignal) {
  return new Promise<void>((resolve, reject) => {
    if (signal?.aborted) {
      reject(new DOMException('Report loading aborted', 'AbortError'))
      return
    }
    const onAbort = () => {
      window.clearTimeout(timer)
      reject(new DOMException('Report loading aborted', 'AbortError'))
    }
    const timer = window.setTimeout(() => {
      signal?.removeEventListener('abort', onAbort)
      resolve()
    }, 2000)
    signal?.addEventListener('abort', onAbort, { once: true })
  })
}

async function requestLatestReportCache<T>(
  reportKey: ReportPeriodKey,
  reportId: BackgroundReportId,
  accessToken: string,
  groupBy: string,
  period: Pick<ProductsAnalyticsPeriodState, 'fromIso' | 'toIso'> | undefined,
  source: BackgroundReportSource,
  signal?: AbortSignal,
) {
  try {
    const payload = await apiRequest<T>(backgroundReportLatestCachePath(reportId, groupBy, source, period), {
      headers: authorizationHeaders(accessToken),
      signal,
    })
    applyReportPeriodFromPayload(reportKey, payload)
    return payload ?? null
  } catch (error) {
    if (error instanceof ApiError && error.status === 404) return null
    throw error
  }
}

async function loadLatestReportCache<T>(
  reportKey: ReportPeriodKey,
  reportId: BackgroundReportId,
  accessToken: string,
  groupBy = 'sku',
  period?: Pick<ProductsAnalyticsPeriodState, 'fromIso' | 'toIso'>,
  source: BackgroundReportSource = 'operational',
  options: LoadLatestReportCacheOptions = {},
): Promise<T | null> {
  const cached = await requestLatestReportCache<T>(reportKey, reportId, accessToken, groupBy, period, source, options.signal)
  if (cached || !period) return cached

  const headers = authorizationHeaders(accessToken)
  let payload: PnlReportJobPayload = await apiRequest<PnlReportJobPayload>(backgroundReportJobStartPath(reportId, period, groupBy, source), {
    method: 'POST',
    headers,
    signal: options.signal,
  }) ?? { state: 'idle' }
  let job = describePnlReportJob(payload)
  options.onJob?.(job)

  let pollAttempts = 0
  while (shouldPollBackgroundReportJob(payload, pollAttempts)) {
    await backgroundReportPollDelay(options.signal)
    payload = await apiRequest<PnlReportJobPayload>(backgroundReportJobStatusPath(reportId, period, groupBy, source), {
      headers: authorizationHeaders(accessToken),
      signal: options.signal,
    }) ?? { state: 'idle' }
    pollAttempts += 1
    job = describePnlReportJob(payload)
    options.onJob?.(job)
  }

  if (payload.state === 'failed') {
    throw new Error(payload.error?.trim() || payload.label?.trim() || 'Сборка отчёта завершилась с ошибкой')
  }

  for (let attempt = 0; attempt < 3; attempt += 1) {
    const latest = await requestLatestReportCache<T>(reportKey, reportId, accessToken, groupBy, period, source, options.signal)
    if (latest) return latest
    if (attempt < 2) await backgroundReportPollDelay(options.signal)
  }
  return null
}

function removeLegacyReportTableFallbacks(tabId: 'rnp' | 'pnl' | 'ads' | 'stock' | 'week') {
  const root = document.getElementById(`tab-${tabId}`)
  if (!root) return
  const liveBindings: Record<typeof tabId, string> = {
    rnp: 'backend-rnp',
    pnl: 'backend-pnl',
    ads: 'backend-ads',
    stock: 'backend-stock',
    'week': 'backend-week-over-week',
  }
  const binding = liveBindings[tabId]
  root.querySelectorAll<HTMLElement>('.report-table-wrap').forEach((tableShell) => {
    if (tableShell.dataset.vellaRuntimeBinding === binding) return
    if (tableShell.querySelector('table.report-mid')) tableShell.remove()
  })
}

function getStockRows(report: StockBackendReport | null) {
  return Array.isArray(report?.rows) ? report.rows : []
}

function getStockKpis(report: StockBackendReport | null) {
  return Array.isArray(report?.kpis) ? report.kpis : []
}

function formatStockInteger(value: unknown) {
  return typeof value === 'number' && Number.isFinite(value) ? Math.round(value).toLocaleString('ru-RU') : 'нет данных'
}

function formatStockNumber(value: unknown, digits = 1) {
  return typeof value === 'number' && Number.isFinite(value)
    ? value.toLocaleString('ru-RU', { maximumFractionDigits: digits })
    : 'нет данных'
}

function formatStockKopecks(value: unknown) {
  return typeof value === 'number' && Number.isFinite(value)
    ? `${Math.round(value / 100).toLocaleString('ru-RU')} ₽`
    : 'нет данных'
}

function stockRowString(row: StockBackendRow, keys: Array<keyof StockBackendRow>) {
  for (const key of keys) {
    const text = String(row[key] ?? '').trim()
    if (text) return text
  }
  return ''
}

function stockProductTitle(row: StockBackendRow) {
  return stockRowString(row, ['productName', 'product_name', 'title', 'name'])
    || (row.nmId ? `Товар WB ${row.nmId}` : row.sku ? `Товар ${row.sku}` : 'Товар без названия')
}

function stockProductSubtitle(row: StockBackendRow) {
  const parts = [
    stockRowString(row, ['category', 'categoryName', 'category_name']),
    stockRowString(row, ['brand', 'brandName', 'brand_name']),
  ].filter(Boolean)
  return parts.length ? parts.join(' · ') : null
}

function stockProductMeta(row: StockBackendRow) {
  if (row.sku && row.nmId) return `Арт. ${row.sku} · WB ${row.nmId}`
  if (row.sku) return `Арт. ${row.sku}`
  if (row.nmId) return `WB ${row.nmId}`
  return null
}

function stockProductPhoto(row: StockBackendRow) {
  return resolveReportProductPhoto(stockRowString(row, ['photoUrl', 'photo_url', 'imageUrl', 'image_url', 'photo']) || null, row.nmId)
}

function stockKpiDisplayValue(kpi: StockBackendKpi) {
  if (typeof kpi.value === 'number') return kpi.value.toLocaleString('ru-RU')
  return kpi.value ?? 'нет данных'
}

