function StockKpiStripIsland({ replacementKey, state }: { replacementKey: string; state: StockLiveState }) {
  const report = state.status === 'ready' ? state.report : null
  const kpis = state.status === 'loading'
    ? [{ label: 'Остатки', value: 'загрузка', hint: 'получаем данные WB' }]
    : state.status === 'error'
      ? [{ label: 'Остатки', value: 'ошибка', hint: cleanReportStateMessage(state.message) }]
      : getStockKpis(report)
  const stockKpiTip = (label?: string | null, hint?: string | null) => {
    if (hint && !hint.startsWith('/api/')) return hint
    const normalized = String(label ?? '').toLowerCase()
    if (normalized.includes('oos')) return 'OOS риск: товары, у которых доступного остатка может не хватить до следующей поставки. Формула: доступный остаток / средние заказы в день.'
    if (normalized.includes('остат')) return 'Остатки WB по товарам и складам. В отчете отдельно показываем общий, доступный и клиентский остаток.'
    if (normalized.includes('логист')) return 'Логистика WB на единицу товара. Помогает понять, где склад или кластер делает продажу дороже.'
    if (normalized.includes('локал')) return 'Локализация показывает, насколько товар расположен близко к покупательскому спросу. Чем ниже показатель, тем чаще логистика может дорожать.'
    return 'Показатель отчета остатков WB за выбранный период. Наведите на заголовки таблицы ниже, чтобы увидеть формулу по каждой колонке.'
  }
  return (
    <div
      key={replacementKey}
      className="stats"
      data-vella-island="stock-kpi-strip"
      data-vella-island-status="explicit-jsx"
    >
      {kpis.map((stat, index) => (
        <div className="stat" key={`${stat.label ?? 'stock-kpi'}-${index}`}>
          <div className="stat-label">
            {stat.label ?? 'Метрика'}
            {' '}
            <ReportHelpTip tip={stockKpiTip(stat.label, stat.hint)} />
          </div>
          <div className="stat-val">{stockKpiDisplayValue(stat)}</div>
          <svg className="stat-spark" width="44" height="22" viewBox="0 0 44 22">
            <polyline points="0,14 6,12 12,13 18,10 24,11 30,8 36,9 44,7" fill="none" stroke="#2563EB" strokeWidth="1.5" />
          </svg>
        </div>
      ))}
    </div>
  )
}

