function currentPnlReportPath(
  period: Pick<ProductsAnalyticsPeriodState, 'fromIso' | 'toIso'> = readReportPeriodState('pnl'),
  source: BackgroundReportSource = 'financial',
) {
  const params = new URLSearchParams({
    preset: 'custom',
    from: period.fromIso,
    to: period.toIso,
    source,
    groupBy: 'sku',
  })
  return `/api/wb/reports/pnl?${params.toString()}`
}

function asPnlNumber(value: unknown) {
  return typeof value === 'number' && Number.isFinite(value) ? value : null
}

function formatPnlKopecks(value: unknown) {
  const kopecks = asPnlNumber(value)
  if (kopecks === null) return 'нет данных'
  return `${Math.round(kopecks / 100).toLocaleString('ru-RU')} ₽`
}

function formatPnlPercent(value: unknown) {
  const pct = asPnlNumber(value)
  if (pct === null) return 'нет данных'
  return `${pct.toLocaleString('ru-RU', { maximumFractionDigits: 1 })}%`
}

function sumPnlRows(rows: PnlBackendRow[], field: keyof PnlBackendRow) {
  return rows.reduce((sum, row) => sum + (asPnlNumber(row[field]) ?? 0), 0)
}

function getPnlKpiValue(report: PnlBackendReport, id: string) {
  const value = report.kpis?.find((kpi) => kpi.id === id)?.value
  if (id === 'revenue' || id === 'net_profit') {
    const numeric = typeof value === 'string' && value.trim() ? Number(value) : value
    return formatPnlKopecks(numeric)
  }
  if (id === 'margin_pct') {
    if (typeof value === 'string' && value.trim()) {
      const numeric = Number(value.replace('%', '').replace(',', '.'))
      return Number.isFinite(numeric) ? formatPnlPercent(numeric) : value
    }
    return formatPnlPercent(value)
  }
  if (typeof value === 'string' && value.trim()) return value
  if (typeof value === 'number' && Number.isFinite(value)) return value.toLocaleString('ru-RU')
  return null
}

function getPnlRows(report: PnlBackendReport) {
  return Array.isArray(report.rows) ? report.rows : []
}

function getPnlCashFlowRows(report: PnlBackendReport | null) {
  const rows = report?.cashFlow?.data?.rows
  return Array.isArray(rows) ? rows : []
}

