function WeekReportActiveIsland({ replacementKey }: { replacementKey: string }) {
  const { accessToken } = useAuth()
  const activeTab = useContext(ActiveParityTabContext)
  const weekActive = shouldLoadPeriodSurface(activeTab, 'week')
  const [state, setState] = useState<WeekLiveState>({ status: 'loading' })
  const [periodState, setPeriodState] = useState(() => readReportPeriodState('week'))
  const weekRows = state.status === 'ready' ? getWeekRows(state.report) : []
  const weekHasRows = state.status === 'ready' && weekRows.length > 0
  const weekStateVariant: 'loading' | 'empty' | 'error' = state.status === 'loading'
    ? 'loading'
    : state.status === 'error'
      ? 'error'
      : 'empty'
  const weekStateTitle = state.status === 'loading'
    ? 'Загружаем сравнение недель'
    : state.status === 'error'
      ? 'Сравнение недель не загрузилось'
      : 'За выбранный период нет сравнения'
  const weekStateMessage = state.status === 'loading'
    ? 'Сравниваем продажи, заказы, маржу и остатки с прошлым периодом.'
    : state.status === 'error'
      ? cleanReportStateMessage(state.message)
      : 'Попробуйте выбрать другой период, где есть продажи и история остатков WB.'

  useEffect(() => {
    if (!weekActive) return
    let cancelled = false
    const controller = new AbortController()
    const reportPath = currentWeekReportPath(periodState)
    const cachePath = backgroundReportLatestCachePath('week-over-week', 'sku', 'operational', periodState)
    const debug: WeekDebugStep[] = [{ stage: 'cache', method: 'GET', path: cachePath, status: 'planned' }]
    const publishDebug = () => {
      if (!cancelled) setState({ status: 'loading', debug: [...debug] })
    }
    async function loadCache(authToken: string) {
      const cacheDebugIndex = debug.findIndex((step) => step.stage === 'cache')
      debug[cacheDebugIndex] = { stage: 'cache', method: 'GET', path: cachePath, status: 'started' }
      publishDebug()
      const report = await loadLatestReportCache<WeekBackendReport>('week', 'week-over-week', authToken, 'sku', periodState, 'operational', {
        signal: controller.signal,
        onJob: (job) => {
          if (!cancelled) setState({ status: 'loading', debug: [...debug], job })
        },
      })
      if (cancelled) return
      if (report && weekReportMatchesPeriod(report, periodState)) {
        debug[cacheDebugIndex] = { stage: 'cache', method: 'GET', path: cachePath, status: 'latest-cache' }
        setState({ status: 'ready', report, debug })
      } else {
        debug[cacheDebugIndex] = { stage: 'cache', method: 'GET', path: cachePath, status: 'missing' }
        setState({ status: 'ready', report: report ?? {}, debug })
      }
    }
    async function load() {
      if (!accessToken) {
        setState({ status: 'error', message: 'Сессия истекла. Войдите снова, чтобы открыть сравнение недель.', debug: [{ stage: 'auth', status: 'missing_token', path: reportPath }], job: describePnlReportJob({ state: 'failed', stage: 'auth', label: 'Нет доступа', percent: 100 }) })
        return
      }
      const authToken = accessToken
      try {
        publishDebug()
        await loadCache(authToken)
      } catch (error) {
        if (!cancelled && !isReportLoadAbort(error)) {
          const reportError = weekApiErrorDebug('cache', cachePath, error)
          setState({
            status: 'error',
            message: reportError.error ? `Не удалось загрузить сравнение недель: ${reportError.error}` : 'Не удалось загрузить сравнение недель',
            debug: [...debug, reportError],
          })
        }
      }
    }
    void load()
    return () => {
      cancelled = true
      controller.abort()
    }
  }, [accessToken, periodState.fromIso, periodState.toIso, weekActive])

  useEffect(() => {
    const render = (event?: Event) => {
      if (!reportPeriodEventMatches(event, 'week')) return
      setPeriodState(readReportPeriodState('week'))
    }
    window.addEventListener(REPORT_PERIOD_EVENT, render)
    return () => window.removeEventListener(REPORT_PERIOD_EVENT, render)
  }, [])

  useEffect(() => {
    const root = document.getElementById('tab-week')
    removeLegacyReportTableFallbacks('week')
    if (root) window.applyGenericReportFilter?.(root)
    window.initTooltips?.()
  }, [state])

  return (
    <div
      key={replacementKey}
      className="tab-content"
      id="tab-week"
      data-vella-island="week"
      data-vella-island-status="explicit-jsx"
    >
      <WeekTableScrollStyles />
      {weekHasRows ? (
        <>
          <SimpleReportToolbarIsland
            replacementKey={`${replacementKey}-toolbar`}
            islandName="week-toolbar"
            placeholder="Артикул, товар или сегмент..."
            chips={['Все', 'Рост', 'Ниже порога', 'Маржа ниже']}
          />
          <WeekWorkbenchIsland replacementKey={`${replacementKey}-workbench`} state={state} />
          <WeekTableShellIsland replacementKey={`${replacementKey}-table`} state={state} />
        </>
      ) : state.status === 'loading' ? (
        <ReportProgressPanelIsland
          replacementKey={`${replacementKey}-progress`}
          tabId="week"
          title="Сравнение недель"
          state="loading"
          job={state.job}
          steps={BACKGROUND_REPORT_PROGRESS_STEPS}
          fallbackDetail="Сравниваем продажи, заказы, маржу и остатки с прошлым периодом."
        />
      ) : (
        <ReportDataStateIsland
          replacementKey={`${replacementKey}-state`}
          tabId="week"
          variant={weekStateVariant}
          title={weekStateTitle}
          message={weekStateMessage}
        />
      )}
    </div>
  )
}

