function formatDrawerKopecks(value: number | null | undefined) {
  if (value == null || !Number.isFinite(value)) return '—'
  return `${Math.round(value / 100).toLocaleString('ru-RU')} ₽`
}

function formatDrawerDateTime(timestamp: string | null | undefined) {
  if (!timestamp) return '—'
  const date = new Date(timestamp)
  if (Number.isNaN(date.getTime())) return '—'
  return date.toLocaleString('ru-RU', { day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' })
}

function formatWorkStatusDateTime(timestamp: string | null | undefined) {
  if (!timestamp) return '—'
  const date = new Date(timestamp)
  if (Number.isNaN(date.getTime())) return '—'
  return date.toLocaleString('ru-RU', { day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit' })
}

function workStatusDueLabel(timestamp: string | null | undefined, futureLabel: string, overdueLabel: string) {
  if (!timestamp) return `${futureLabel}: —`
  const date = new Date(timestamp)
  if (Number.isNaN(date.getTime())) return `${futureLabel}: —`
  const formatted = formatWorkStatusDateTime(timestamp)
  if (date.getTime() < Date.now()) return `${overdueLabel}: должен был быть ${formatted}`
  return `${futureLabel}: ${formatted}`
}

function drawerDecisionTrendLabel(value: string) {
  if (value === 'up') return 'растут'
  if (value === 'down') return 'снижаются'
  if (value === 'flat') return 'без резкого изменения'
  return value
}

function drawerReadableDecisionReason(reason: string | null | undefined) {
  const text = reason?.trim()
  if (!text) return ''
  const matrixMatch = text.match(/matrix:\s*baskets=([a-z_]+),\s*orders=([a-z_]+),\s*rawDelta=([+-]?\d+(?:\.\d+)?)%\s*->\s*cappedDelta=([+-]?\d+(?:\.\d+)?)%\s*\(cap=([+-]?\d+(?:\.\d+)?)%\)/i)
  if (matrixMatch) {
    const [, baskets, orders, , cappedDelta, cap] = matrixMatch
    return `Корзины ${drawerDecisionTrendLabel(baskets)}, заказы ${drawerDecisionTrendLabel(orders)}: изменение цены ${cappedDelta}% (лимит ${cap}%).`
  }
  const revenueMatch = text.match(/mode=([a-z_]+),\s*revenueTrendPct=([+-]?\d+(?:\.\d+)?)%\s*->\s*rawDelta=([+-]?\d+(?:\.\d+)?)%/i)
  if (revenueMatch) {
    const [, mode, revenue, delta] = revenueMatch
    return `Режим ${mode}: выручка ${revenue}%, изменение цены ${delta}%.`
  }
  return text.replace(/^\d+\s+/, '')
}

function drawerPricingStageLabel(status: PricingStatusResponse | null | undefined) {
  if (!status) return 'Статус ценообразования'
  if (status.stage === 'active_liquidation') return 'Ликвидация активна'
  if (status.stage === 'liquidation_pending') return 'Ликвидация ожидает запуска'
  if (status.stage === 'warmup') return 'Прогрев товара'
  if (status.stage === 'manual_hold') return 'Ручной режим'
  if (!drawerAssignedStrategyName(status, null)) return 'Ценообразование без стратегии'
  return 'Стратегия ценообразования'
}

function drawerPricingProgressLabel(status: PricingStatusResponse, product?: DrawerLiveProduct | null) {
  const progress = status.progress
  if ((progress.kind === 'liquidation' || progress.kind === 'warmup') && progress.currentDay && progress.totalDays) {
    return `день ${progress.currentDay} из ${progress.totalDays}`
  }
  if (progress.kind === 'pricing') {
    if (!drawerAssignedStrategyName(status, product)) return 'активного цикла нет'
    return `цикл каждые ${progress.syncIntervalHours} ч`
  }
  return 'прогресс не рассчитан'
}

function drawerPricingNextStepLabel(status: PricingStatusResponse, product?: DrawerLiveProduct | null) {
  const progress = status.progress
  if (progress.kind === 'liquidation') return workStatusDueLabel(progress.nextStepAt, 'Следующий шаг', 'Шаг ликвидации просрочен')
  if (progress.kind === 'warmup') return progress.daysLeft > 0 ? `Осталось ${progress.daysLeft} дн.` : 'Прогрев завершён'
  if (!drawerAssignedStrategyName(status, product)) return 'Цена не будет меняться без стратегии, ликвидации или ручного действия'
  return workStatusDueLabel(progress.nextStepAt, 'Следующий пересчёт', 'Пересчёт просрочен')
}

function drawerPricingLastDecisionText(status: PricingStatusResponse, product?: DrawerLiveProduct | null) {
  const decision = status.lastDecision
  if (!drawerAssignedStrategyName(status, product) && status.progress.kind === 'pricing' && !decision?.timestamp) {
    return 'Стратегия не назначена: фоновое изменение цены для этого SKU не активно.'
  }
  if (!decision?.timestamp && !decision?.reason) {
    return 'Последнее решение появится после фонового цикла стратегии.'
  }
  const priceText = decision.oldPriceKopecks && decision.newPriceKopecks
    ? `${formatDrawerKopecks(decision.oldPriceKopecks)} → ${formatDrawerKopecks(decision.newPriceKopecks)}`
    : null
  return [drawerReadableDecisionReason(decision.reason), priceText, formatDrawerDateTime(decision.timestamp)].filter(Boolean).join(' · ')
}

function ProductDrawerPricingStatusIsland({ replacementKey }: { replacementKey: string }) {
  const product = useDrawerLiveProduct()
  const { data, loading, error } = useDrawerPricingStatusState()
  const status = data
  const strategyName = drawerAssignedStrategyName(status, product)
  const progressPct = status?.progress.currentDay && status.progress.totalDays
    ? Math.max(4, Math.min(100, Math.round((status.progress.currentDay / status.progress.totalDays) * 100)))
    : null

  return (
    <div
      key={replacementKey}
      className="d-section drawer-pricing-status"
      data-vella-island="product-drawer-pricing-status"
      data-vella-island-status="explicit-jsx"
    >
      <div className="d-section-title">
        {drawerPricingStageLabel(status)}
        {loading ? <span className="report-tag" style={{ marginLeft: 8 }}>загрузка</span> : null}
      </div>
      {error ? (
        <div className="report-comment-history-row">
          <div className="report-comment-history-text">{error}</div>
          <div className="report-comment-history-meta">Источник: /api/v1/wb-repricer/sku/{'{articleId}'}/pricing-status</div>
        </div>
      ) : status ? (
        <>
          <div className="calc-block" style={{ marginBottom: 10 }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', gap: 12, alignItems: 'flex-start' }}>
              <div>
                <div style={{ fontSize: 12, color: 'var(--gray-500)', marginBottom: 3 }}>Текущий этап</div>
                <div style={{ fontSize: 15, fontWeight: 700, color: 'var(--gray-900)' }}>{drawerPricingProgressLabel(status, product)}</div>
                <div style={{ fontSize: 11.5, color: 'var(--gray-500)', marginTop: 3 }}>{drawerPricingNextStepLabel(status, product)}</div>
              </div>
              <span className={`report-tag ${status.progress.kind === 'liquidation' ? 'warn' : status.stage === 'manual_hold' ? '' : 'ok'}`.trim()}>
                {status.progress.kind === 'liquidation' ? 'ликвидация' : status.progress.kind === 'warmup' ? 'прогрев' : strategyName ? 'pricing' : 'нет правила'}
              </span>
            </div>
            {progressPct != null ? (
              <div style={{ marginTop: 10, height: 7, borderRadius: 999, background: 'var(--gray-100)', overflow: 'hidden' }}>
                <div style={{ width: `${progressPct}%`, height: '100%', background: status.progress.kind === 'liquidation' ? 'var(--orange-mid)' : 'var(--brand)' }} />
              </div>
            ) : null}
          </div>
          <div className="d-grid" style={{ marginBottom: 10 }}>
            <div className="d-row"><span className="d-label">Стратегия</span><span className="d-val">{strategyName || '— нет —'}</span></div>
            <div className="d-row"><span className="d-label">Текущая цена</span><span className="d-val">{formatDrawerKopecks(status.current.priceKopecks)}</span></div>
            <div className="d-row"><span className="d-label">P_MIN / P_MAX</span><span className="d-val">{formatDrawerKopecks(status.current.pMinKopecks)} / {formatDrawerKopecks(status.current.pMaxKopecks)}</span></div>
            <div className="d-row"><span className="d-label">Маржа</span><span className="d-val">{status.current.marginPct == null ? '—' : `${Math.round(status.current.marginPct)}%`}</span></div>
          </div>
          <div className="report-comment-history-row">
            <div className="report-comment-history-text">{drawerPricingLastDecisionText(status, product)}</div>
            <div className="report-comment-history-meta">Последнее решение алгоритма или менеджера</div>
          </div>
        </>
      ) : (
        <div className="report-comment-history-row">
          <div className="report-comment-history-text">Загрузка…</div>
          <div className="report-comment-history-meta">Ждём актуальный статус для этого SKU.</div>
        </div>
      )}
    </div>
  )
}

