function ProductDrawerOverviewPriceHistoryIsland({ replacementKey }: { replacementKey: string }) {
  const history = useDrawerHistoryState()

  return (
    <div
      key={replacementKey}
      className="d-section"
      data-vella-island="product-drawer-overview-price-history"
      data-vella-island-status="explicit-jsx"
    >
      <div className="d-section-title">История цены</div>
      {history.loading ? (
        <div className="report-comment-history-row">
          <div className="report-comment-history-text">Загружаем журнал изменений цены…</div>
          <div className="report-comment-history-meta">Источник: /api/v1/wb-repricer/sku/&#123;articleId&#125;/changelog</div>
        </div>
      ) : history.error ? (
        <div style={{ padding: '12px 14px', border: '1px dashed var(--gray-200)', borderRadius: 10, background: 'var(--gray-50)', fontSize: 12, lineHeight: 1.5, color: 'var(--gray-500)' }}>
          {history.error}
        </div>
      ) : history.entries?.length ? (
        <div className="history-list">
          {history.entries.map((entry, index) => {
            const parts = formatDrawerDateParts(entry.timestamp)
            const oldRub = Math.round(entry.oldPriceKopecks / 100)
            const newRub = Math.round(entry.newPriceKopecks / 100)
            const changeText = entry.changePct === 0
              ? '±0%'
              : `${entry.changePct > 0 ? '+' : ''}${entry.changePct.toFixed(1)}%`
            const arrowClass = entry.changePct > 0 ? 'up' : entry.changePct < 0 ? 'dn' : 'same'
            const priceText = oldRub === newRub
              ? `${oldRub.toLocaleString('ru-RU')} ₽`
              : <>{oldRub.toLocaleString('ru-RU')} ₽ → <b>{newRub.toLocaleString('ru-RU')} ₽</b></>
            return (
              <div className="history-row" key={`${entry.timestamp}-${index}`}>
                <span className="h-time">{parts.day}<span className="h-clock">{parts.time}</span></span>
                <span className={`h-arrow ${arrowClass}`}>{changeText}</span>
                <span className="h-text">{priceText}</span>
                <span className="h-trigger">{drawerTriggerLabel(entry.trigger, entry.reason)}</span>
              </div>
            )
          })}
        </div>
      ) : (
        <div className="report-comment-history-row">
          <div className="report-comment-history-text">В журнале пока нет записей для этого SKU.</div>
          <div className="report-comment-history-meta">История появится после применения стратегий или ручного изменения цены.</div>
        </div>
      )}
      <div style={{ marginTop: '10px', paddingTop: '10px', borderTop: '1px solid var(--gray-100)' }}>
        <div style={{ fontSize: '11px', color: 'var(--gray-500)', fontWeight: 600, marginBottom: '6px' }}>Изменения P_MIN</div>
        <div className="report-comment-history-row">
          <div className="report-comment-history-text">История изменений P_min появится здесь после сохранения границ цены.</div>
        </div>
      </div>
    </div>
  )
}

