function ProductDrawerAlgoCogsIsland({ replacementKey }: { replacementKey: string }) {
  const product = useDrawerLiveProduct()
  const settings = product?.settings ?? {}
  const settingsCogs = drawerNumber(settings.cogsKopecks) == null ? null : Math.round(Number(settings.cogsKopecks) / 100)
  const settingsLogistics = drawerNumber(settings.logisticsKopecks) == null ? null : Math.round(Number(settings.logisticsKopecks) / 100)
  const commissionPct = drawerNumber(product?.commissionPct ?? settings.wbCommissionPct ?? product?.baseWbCommissionPct)
  const sellerPrice = drawerNumber(product?.price)
  const unitCommissionRub = sellerPrice == null || commissionPct == null ? null : sellerPrice * commissionPct / 100
  const rows = [
    ['Себестоимость', settingsCogs == null ? 'нет данных' : formatDrawerRub(settingsCogs)],
    ['Комиссия WB', unitCommissionRub == null ? 'нет данных' : `${formatDrawerRub(unitCommissionRub)}${commissionPct == null ? '' : ` (${Number(commissionPct.toFixed(1))}%)`}`],
    ['Логистика', settingsLogistics == null ? 'нет данных' : formatDrawerRub(settingsLogistics)],
    ['Маржа в ₽', product?.mgRub == null ? 'нет данных' : formatDrawerRub(product.mgRub), 'margin'],
  ] as const
  const skuPrefix = String(product?.sku ?? '').trim().charAt(0).toUpperCase()
  const garmentLabel = skuPrefix === 'H' ? 'худи' : skuPrefix === 'L' ? 'лонгслива' : 'футболки'
  const cogsSourceText = settingsCogs == null
    ? 'Себестоимость для этого SKU ещё не задана.'
    : `Сейчас показано значение ${formatDrawerRub(settingsCogs)} из SKU-настроек. Если файл себестоимости ещё не загружался, это стартовое значение для ${garmentLabel}.`

  return (
    <div
      key={replacementKey}
      className="d-section"
      data-vella-island="product-drawer-algo-cogs"
      data-vella-island-status="explicit-jsx"
    >
      <div className="d-section-title">
        Себестоимость и расчёт <button className="help-btn" data-vella-react-handlers="onclick" onClick={() => window.showHelp?.('cogs-calc')}>?</button>
      </div>
      <div className="report-comment-history-row" style={{ marginBottom: 10 }}>
        <div className="report-comment-history-text">{cogsSourceText}</div>
        <div className="report-comment-history-meta">После импорта Excel или ручной правки SKU это значение заменится. Детализация по компонентам пока не хранится отдельно.</div>
      </div>
      {rows.map(([label, value, tone]) => (
        <div className="d-row" key={label}>
          <span className="d-label">
            {tone === 'margin'
                ? <b style={{ color: 'var(--gray-900)' }}>{label}</b>
                : label}
          </span>
          <span className={tone === 'margin' ? 'd-val mg-high' : 'd-val'}>
            {value}
          </span>
        </div>
      ))}
    </div>
  )
}

