function ProductDrawerTabContentIsland({ replacementKey, sourceElement }: { replacementKey: string; sourceElement?: HTMLElement | SVGElement }) {
  const tab = sourceElement instanceof HTMLElement ? sourceElement : null
  const tabId = tab?.id || ''
  const replacements = tabId === 'dr-overview'
    ? productDrawerOverviewReplacements
    : tabId === 'dr-algo'
      ? productDrawerAlgoReplacements
      : tabId === 'dr-comments'
        ? productDrawerCommentsReplacements
        : tabId === 'dr-misc'
          ? productDrawerMiscReplacements
      : []
  return (
    <div
      key={replacementKey}
      className={tab?.className || 'dr-tab-content'}
      id={tabId}
      data-vella-island={productDrawerTabIslandById[tabId] || 'product-drawer-tab'}
      data-vella-island-status="explicit-jsx"
    >
      {htmlToReactFragment(tab?.innerHTML || '', `${replacementKey}-content`, replacements)}
    </div>
  )
}

