function defaultAvitoStatsPeriod() {
  const to = toLocalIsoDate(new Date())
  const from = toLocalIsoDate(addLocalDays(new Date(), -29))
  return { from, to }
}

function defaultAvitoOverviewState(): AvitoOverviewState {
  const period = defaultAvitoStatsPeriod()
  return {
    filter: 'all',
    query: '',
    periodId: '30',
    dateFrom: period.from,
    dateTo: period.to,
    dateFromDraft: period.from,
    dateToDraft: period.to,
    requestSeq: 0,
    forceRefresh: false,
  }
}

function useAvitoOverviewState() {
  const [state, setState] = useState<AvitoOverviewState>(() => ({ ...defaultAvitoOverviewState(), ...(window.__vellaAvitoOverviewState ?? {}) }))
  useEffect(() => {
    const render = () => setState({ ...defaultAvitoOverviewState(), ...(window.__vellaAvitoOverviewState ?? {}) })
    window.__vellaReactRenderAvitoOverview = render
    window.addEventListener('vella:avito-overview-updated', render)
    render()
    return () => {
      if (window.__vellaReactRenderAvitoOverview === render) delete window.__vellaReactRenderAvitoOverview
      window.removeEventListener('vella:avito-overview-updated', render)
    }
  }, [])
  return state
}

function useAvitoOverviewLiveState() {
  const [state, setState] = useState<AvitoOverviewLiveState>(() => ({ ...EMPTY_AVITO_OVERVIEW_LIVE_STATE, ...(window.__vellaAvitoOverviewLiveState ?? {}) }))
  useEffect(() => {
    const render = () => setState({ ...EMPTY_AVITO_OVERVIEW_LIVE_STATE, ...(window.__vellaAvitoOverviewLiveState ?? {}) })
    window.__vellaReactRenderAvitoOverviewLive = render
    window.addEventListener('vella:avito-overview-live-updated', render)
    render()
    return () => {
      if (window.__vellaReactRenderAvitoOverviewLive === render) delete window.__vellaReactRenderAvitoOverviewLive
      window.removeEventListener('vella:avito-overview-live-updated', render)
    }
  }, [])
  return state
}

function setAvitoOverviewLiveState(next: AvitoOverviewLiveState) {
  window.__vellaAvitoOverviewLiveState = next
  window.dispatchEvent(new CustomEvent('vella:avito-overview-live-updated'))
  window.__vellaReactRenderAvitoOverviewLive?.()
}

function avitoOverviewDataForPeriod(state: AvitoOverviewState, live: AvitoOverviewLiveState) {
  const data = live.data
  if (!data) return null
  return data.period.dateFrom === state.dateFrom && data.period.dateTo === state.dateTo ? data : null
}

function avitoOverviewFriendlyMessage(value: string | null | undefined) {
  if (!value) return ''
  const text = String(value)
  if (text.includes('429') || text.toLocaleLowerCase('ru-RU').includes('too many requests')) {
    return 'Авито временно ограничил частоту запросов. Подождите минуту и обновите данные.'
  }
  if (text.toLocaleLowerCase('ru-RU').includes('stats')) return 'Статистика Авито временно недоступна.'
  if (text.toLocaleLowerCase('ru-RU').includes('listings')) return 'Объявления Авито временно недоступны.'
  if (text.toLocaleLowerCase('ru-RU').includes('нужна активная сессия')) return 'Нужно войти в аккаунт.'
  return text.replace(/Client error '[^']+' for url '[^']+'.*/i, 'Авито временно не ответил на запрос.')
}

function avitoSourceErrorFromPayload(payload: { source?: Record<string, unknown> } | null | undefined) {
  const source = payload?.source
  if (!source || typeof source !== 'object') return null
  const error = source.error
  if (error && typeof error === 'object') return error as Record<string, unknown>
  const errors = source.errors
  if (errors && typeof errors === 'object') {
    return Object.values(errors as Record<string, unknown>).find((item): item is Record<string, unknown> => Boolean(item && typeof item === 'object')) ?? null
  }
  return null
}

function avitoBackendErrorMessage(payload: { status?: string; source?: Record<string, unknown> } | null | undefined) {
  if (!payload || payload.status !== 'blocked') return null
  const error = avitoSourceErrorFromPayload(payload)
  const code = String(error?.code ?? '').toLocaleLowerCase('ru-RU')
  const message = String(error?.message ?? '')
  const blockers = Array.isArray(error?.blockerIds) ? error.blockerIds.map(String).join(' ').toLocaleLowerCase('ru-RU') : ''
  if (code === 'rate_limited' || message.includes('429') || blockers.includes('avito_rate_limit')) {
    return 'Авито ограничил частые запросы. Кнопка включится автоматически после паузы.'
  }
  if (code === 'forbidden_scope') return 'Авито не дал доступ к этому API. Проверьте права приложения и токен.'
  if (code === 'auth_required') return 'Авито просит заново подключить аккаунт.'
  return avitoOverviewFriendlyMessage(message || code || null) || 'Источник Авито временно недоступен.'
}

function avitoOverviewFriendlyEvent(event: AvitoOverviewBackendResponse['events'][number]) {
  const title = event.title || ''
  const meta = event.meta || ''
  const lower = `${title} ${meta}`.toLocaleLowerCase('ru-RU')
  if (lower.includes('429') || lower.includes('too many requests')) {
    return {
      ...event,
      title: title.includes('listings') ? 'Объявления временно недоступны' : 'Статистика временно недоступна',
      meta: 'Авито ограничил частоту запросов. Данные можно обновить чуть позже.',
    }
  }
  if (title.includes(': источник недоступен')) {
    return {
      ...event,
      title: title.replace('stats: источник недоступен', 'Статистика временно недоступна').replace('listings: источник недоступен', 'Объявления временно недоступны'),
      meta: avitoOverviewFriendlyMessage(meta) || 'Проверьте доступы или обновите данные позже.',
    }
  }
  let friendlyTitle = title
  let friendlyMeta = meta
  if (lower.includes('avito messenger') || lower.includes('inbox')) {
    friendlyMeta = 'Есть новые сообщения от покупателей.'
  }
  if (lower.includes('ratings api')) {
    friendlyMeta = 'На эти отзывы можно ответить.'
  }
  if (lower.includes('core/v1/items')) {
    friendlyMeta = 'Проверьте карточки и при необходимости обновите объявления.'
  }
  if (lower.includes('кэш') || lower.includes('cache') || lower.includes('просит паузу')) {
    friendlyTitle = friendlyTitle.replace('Статистика: Авито просит паузу', 'Статистика обновится позже')
    friendlyMeta = 'Авито просит сделать паузу. Мы обновим данные при следующей попытке.'
  }
  return { ...event, title: friendlyTitle, meta: friendlyMeta }
}

function isAvitoStatsFilter(value: unknown): value is AvitoStatsFilter {
  return typeof value === 'string' && value.length > 0
}

function isAvitoChatsFilter(value: unknown): value is AvitoChatsFilter {
  return value === 'all' || value === 'unread' || value === 'withItems'
}

function isAvitoChatsSort(value: unknown): value is AvitoChatsSort {
  return value === 'new' || value === 'unread' || value === 'with_item'
}

function isAvitoStatsMode(value: unknown): value is AvitoStatsMode {
  return value === 'traffic' || value === 'funnel' || value === 'sales'
}

function isAvitoStatsKey(value: unknown): value is AvitoStatsKey {
  return typeof value === 'string' && value.length > 0
}

