function backendNotificationFreshnessLabel(item: BackendNotificationEvent) {
  if (!item.freshness) return ''
  const updatedAt = new Date(item.freshness.updatedAt)
  const time = Number.isNaN(updatedAt.getTime())
    ? ''
    : updatedAt.toLocaleString('ru-RU', { day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' })
  const normalizedState = String(item.freshness.state || '').toLocaleLowerCase('ru-RU')
  const stateLabel = normalizedState === 'fresh' || normalizedState === 'актуально'
    ? 'актуально'
    : normalizedState === 'partial' || normalizedState === 'частично'
      ? 'частично'
      : normalizedState === 'stale' || normalizedState === 'устарело' || normalizedState === 'требует проверки'
        ? 'требует проверки'
        : 'ожидается'
  return [stateLabel, time].filter(Boolean).join(' · ')
}

function legacyNotificationFromBackend(item: BackendNotificationEvent) {
  const category = BACKEND_NOTIFICATION_CATEGORY_LABELS[item.category] ?? 'Система'
  return {
    id: item.id,
    type: BACKEND_NOTIFICATION_TYPE_BY_CATEGORY[item.category] ?? 'report_stale',
    severity: item.severity,
    title: item.title,
    body: item.details,
    detail: item.details,
    category,
    manager: item.manager,
    source: item.source,
    freshness: backendNotificationFreshnessLabel(item),
    entityType: item.entityType,
    entityId: item.entityId,
    route: item.route ?? '/notifications',
    blockedActions: [...item.blockedActions],
    why: item.details,
    link: item.route ?? '/notifications',
    linkLabel: 'Открыть раздел',
    timestamp: item.createdAt,
    read: Boolean(item.readAt),
    reportFile: item.reportFile ? { ...item.reportFile } : undefined,
  }
}

