function AvitoRefreshButton({
  loading,
  onClick,
  cooldownUntil,
  className = '',
}: {
  loading?: boolean
  onClick: () => void
  cooldownUntil?: string | null
  className?: string
}) {
  const [now, setNow] = useState(() => Date.now())
  const cooldownRemaining = avitoCooldownRemainingMs(cooldownUntil, now)
  useEffect(() => {
    if (!cooldownUntil || cooldownRemaining <= 0) return
    const timer = window.setInterval(() => setNow(Date.now()), 1000)
    return () => window.clearInterval(timer)
  }, [cooldownUntil, cooldownRemaining])
  const disabled = Boolean(loading) || cooldownRemaining > 0
  const label = loading
    ? 'Обновляем...'
    : cooldownRemaining > 0
      ? `Пауза ${formatAvitoRefreshCountdown(cooldownRemaining)}`
      : 'Обновить данные'
  return (
    <>
      <AvitoControlStyles />
      <button
        className={`btn btn-default avito-action-btn is-refresh ${className}`.trim()}
        type="button"
        data-vella-react-handlers="onclick"
        disabled={disabled}
        data-tip={cooldownRemaining > 0 ? 'Авито ограничил частые запросы. Кнопка включится автоматически.' : 'Обновить данные Авито'}
        onClick={onClick}
      >
        <AvitoRefreshIcon />
        {label}
      </button>
    </>
  )
}

function showAvitoCooldownToast(payload: unknown) {
  const cooldownUntil = avitoCooldownUntilFromPayload(payload)
  const remaining = avitoCooldownRemainingMs(cooldownUntil)
  if (remaining <= 0) return false
  window.showToast?.(`Авито просит паузу. Повтор через ${formatAvitoRefreshCountdown(remaining)}`, 'warn')
  return true
}

function AvitoAutoRefreshTimer({
  lastRefreshAt,
  intervalMs,
  loading,
}: {
  lastRefreshAt: number
  intervalMs: number
  loading?: boolean
}) {
  const [now, setNow] = useState(() => Date.now())
  useEffect(() => {
    const timer = window.setInterval(() => setNow(Date.now()), 1000)
    return () => window.clearInterval(timer)
  }, [])
  const elapsed = Math.max(0, now - lastRefreshAt)
  const remaining = Math.max(0, intervalMs - elapsed)
  const progress = Math.min(100, Math.max(0, (elapsed / intervalMs) * 100))
  return (
    <div
      className="avito-refresh-timer"
      aria-label={loading ? 'Обновляем данные Авито' : `До автообновления ${formatAvitoRefreshCountdown(remaining)}`}
      data-tip={loading ? 'Сейчас обновляем данные Авито' : 'Автообновление данных Авито'}
      style={{ '--avito-refresh-progress': `${progress}%` } as CSSProperties}
    >
      <span className="avito-refresh-timer-ring" aria-hidden="true" />
      <span className="avito-refresh-timer-copy">
        <span>{loading ? 'Авито' : 'автообновление'}</span>
        <b>{loading ? 'обновляем...' : formatAvitoRefreshCountdown(remaining)}</b>
      </span>
    </div>
  )
}

function AvitoDateRangeActions({
  from,
  to,
  fromLabel = 'с',
  toLabel = 'по',
  fromAria,
  toAria,
  loading,
  cooldownUntil,
  onFromChange,
  onToChange,
  onApply,
  onRefresh,
  extra,
}: {
  from: string
  to?: string
  fromLabel?: string
  toLabel?: string
  fromAria: string
  toAria?: string
  loading?: boolean
  cooldownUntil?: string | null
  onFromChange: (value: string) => void
  onToChange?: (value: string) => void
  onApply: (values?: { from: string; to?: string }) => void
  onRefresh: (values?: { from: string; to?: string }) => void
  extra?: ReactNode
}) {
  const fromInputRef = useRef<HTMLInputElement | null>(null)
  const toInputRef = useRef<HTMLInputElement | null>(null)
  const currentValues = () => ({
    from: fromInputRef.current?.value || from,
    to: to != null ? (toInputRef.current?.value || to) : undefined,
  })
  return (
    <div className="avito-range-actions">
      <AvitoControlStyles />
      <div className="avito-date-range-card">
        <span className="avito-date-range-icon"><AvitoDateIcon /></span>
        <label className="avito-date-field">
          <span>{fromLabel}</span>
          <input ref={fromInputRef} type="date" aria-label={fromAria} value={from} onChange={(event) => onFromChange(event.currentTarget.value)} />
        </label>
        {to != null && onToChange ? (
          <>
            <span className="avito-range-separator">-</span>
            <label className="avito-date-field">
              <span>{toLabel}</span>
              <input ref={toInputRef} type="date" aria-label={toAria} value={to} onChange={(event) => onToChange(event.currentTarget.value)} />
            </label>
          </>
        ) : null}
      </div>
      {extra}
      <button
        className="btn btn-primary avito-action-btn"
        type="button"
        data-vella-react-handlers="onclick"
        onClick={() => onApply(currentValues())}
        disabled={loading}
      >
        Применить
      </button>
      <AvitoRefreshButton loading={loading} cooldownUntil={cooldownUntil} onClick={() => onRefresh(currentValues())} />
    </div>
  )
}

const AVITO_OVERVIEW_PERIOD_OPTIONS = [
  { id: '1', label: 'Сегодня', days: 1 },
  { id: '7', label: '7 дней', days: 7 },
  { id: '14', label: '14 дней', days: 14 },
  { id: '30', label: 'Месяц', days: 30 },
] as const

function avitoOverviewPeriodForDays(days: number) {
  const safeDays = Math.max(1, Math.min(30, Math.round(days || 30)))
  const to = toLocalIsoDate(new Date())
  const from = toLocalIsoDate(addLocalDays(new Date(), -(safeDays - 1)))
  return { from, to }
}

function AvitoOverviewPeriodSegments({ state, loading, cooldownUntil }: { state: AvitoOverviewState; loading?: boolean; cooldownUntil?: string | null }) {
  const activeId = state.periodId || '30'
  const applyPeriod = (period: string) => {
    const option = AVITO_OVERVIEW_PERIOD_OPTIONS.find((item) => item.id === String(period))
    const { from, to } = avitoOverviewPeriodForDays(option?.days ?? 30)
    window.__vellaSetAvitoOverviewState?.({
      dateFrom: from,
      dateTo: to,
      dateFromDraft: from,
      dateToDraft: to,
      periodId: option?.id ?? '30',
      forceRefresh: false,
      requestSeq: (window.__vellaAvitoOverviewState?.requestSeq ?? 0) + 1,
    })
  }
  return (
    <div className="avito-range-actions" aria-label="Период обзора Авито">
      <AvitoControlStyles />
      <div className="avito-period-segments" role="tablist" aria-label="Период статистики Авито">
        {AVITO_OVERVIEW_PERIOD_OPTIONS.map((option) => (
          <button
            key={option.id}
            type="button"
            role="tab"
            aria-selected={activeId === option.id}
            className={activeId === option.id ? 'avito-period-segment active' : 'avito-period-segment'}
            data-vella-react-handlers="onclick"
            onClick={() => applyPeriod(option.id)}
          >
            {option.label}
          </button>
        ))}
      </div>
      <AvitoRefreshButton loading={loading} cooldownUntil={cooldownUntil} onClick={() => window.refreshAvitoOverview?.()} />
    </div>
  )
}

function AvitoOverviewToolbarIsland() {
  const state = useAvitoOverviewState()
  const live = useAvitoOverviewLiveState()
  const chatsLive = useAvitoChatsLiveState()
  const data = avitoOverviewDataForPeriod(state, live)
  const cooldownUntil = avitoCooldownUntilFromPayload(live.data)
  const summary = data?.summary
  const chatsSummary = avitoChatsSummary(chatsLive.data)
  const unreadChats = chatsLive.data ? chatsSummary.unread : summary?.unreadChats ?? 0
  const chips = [
    ['all', 'Все', formatAvitoInt((data?.events.length ?? 0) + (data?.topItems.length ?? 0)), ''],
    ['events', 'События', formatAvitoInt(data?.events.length ?? 0), ''],
    ['blockers', 'Блокировки', formatAvitoInt(summary?.blockers ?? 0), '#DC2626'],
    ['chats', 'Чаты', formatAvitoInt(unreadChats), unreadChats ? '#DC2626' : ''],
    ['reviews', 'Отзывы', formatAvitoInt(summary?.unansweredReviews ?? 0), summary?.unansweredReviews ? '#DC2626' : ''],
  ] as const
  return (
    <div
      className="toolbar"
      data-vella-island="avito-overview-toolbar"
      data-vella-island-status="explicit-jsx"
      data-vella-event-owner="react"
    >
      <div className="search">
        <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
          <circle cx="11" cy="11" r="8" />
          <line x1="21" y1="21" x2="16.65" y2="16.65" />
        </svg>
        <input
          type="text"
          aria-label="Поиск по Авито"
          autoComplete="off"
          placeholder="Аккаунт, объявление или событие"
          value={state.query}
          onInput={(event) => window.__vellaSetAvitoOverviewState?.({ query: event.currentTarget.value })}
        />
      </div>
      <div className="chips">
        {chips.map(([filter, label, count, color]) => (
          <button
            type="button"
            className={state.filter === filter ? 'chip active' : 'chip'}
            data-vella-react-handlers="onclick"
            onClick={() => window.__vellaSetAvitoOverviewState?.({ filter })}
            key={filter}
          >
            {label} <span className="chip-count" style={color ? { color } : undefined}>{count}</span>
          </button>
        ))}
      </div>
      <div className="toolbar-right">
        <AvitoOverviewPeriodSegments state={state} loading={live.loading} cooldownUntil={cooldownUntil} />
      </div>
    </div>
  )
}

function AvitoOverviewReportShellIsland() {
  const state = useAvitoOverviewState()
  const live = useAvitoOverviewLiveState()
  const [selectedItemId, setSelectedItemId] = useState('')
  const data = avitoOverviewDataForPeriod(state, live)
  const summary = data?.summary
  const query = state.query.trim().toLocaleLowerCase('ru-RU')
  const topItems = (data?.topItems ?? []).filter((row) => !query || `${row.title} ${row.itemId} ${row.accountName} ${row.category ?? ''}`.toLocaleLowerCase('ru-RU').includes(query))
  const events = (data?.events ?? []).map(avitoOverviewFriendlyEvent).filter((event) => {
    if (state.filter === 'blockers' && event.severity !== 'danger') return false
    if (state.filter === 'chats' && event.source !== 'Сообщения') return false
    if (state.filter === 'reviews' && event.source !== 'Отзывы') return false
    if (state.filter === 'events' && event.severity === 'danger') return false
    if (!query) return true
    return `${event.source} ${event.title} ${event.meta}`.toLocaleLowerCase('ru-RU').includes(query)
  })
  const spendPerView = summary?.spendKopecks != null && summary.views ? `${formatAvitoRub(summary.spendKopecks / summary.views)} за просмотр` : 'ждём расходы'
  const eventClass = (severity: string) => severity === 'danger' ? 'danger' : severity === 'warn' ? 'warn' : 'new'
  const eventColor = (severity: string) => severity === 'danger' ? '#DC2626' : severity === 'warn' ? '#F59E0B' : '#2563EB'
  const selectedItem = (data?.topItems ?? []).find((row) => row.itemId === selectedItemId)
  const openAvitoOverviewItem = (itemId: string) => setSelectedItemId(itemId)
  if (!data && (live.loading || live.error)) {
    return (
      <div className="report-shell" data-vella-island="avito-overview-report-shell" data-vella-island-status="explicit-jsx">
        <AvitoDataState
          kind={live.loading ? 'loading' : 'error'}
          title={live.loading ? 'Загружаем обзор Авито' : 'Обзор временно недоступен'}
          subtitle={live.loading ? 'Собираем объявления, чаты, отзывы и статистику.' : avitoOverviewFriendlyMessage(live.error) || 'Проверьте подключение Авито и обновите данные.'}
        />
      </div>
    )
  }
  return (
    <div
      className="report-shell"
      data-vella-island="avito-overview-report-shell"
      data-vella-island-status="explicit-jsx"
    >
      <div className="report-grid">
        <section className="avito-period-group" aria-label="Обзор и топ позиций Авито за период">
          <div className="avito-period-group-grid">
            <section className="report-panel report-panel-pad">
              <div className="report-chart-head">
                <div><div className="report-card-title">Операционный обзор Авито</div><div className="report-card-note">Аккаунты, чаты, объявления, кошельки и заказы.</div></div>
              </div>
              <div className="report-mini-grid">
                <div className="report-mini-card"><div className="report-mini-label">Просмотры</div><div className="report-mini-value">{summary ? formatAvitoMetric(summary.views) : '—'}</div><div className="report-mini-note">{summary ? `${formatAvitoPctNullable(summary.conversionPct)} в контакт` : 'ждём данные'}</div></div>
                <div className="report-mini-card"><div className="report-mini-label">Контакты</div><div className="report-mini-value">{summary ? formatAvitoMetric(summary.contacts) : '—'}</div><div className="report-mini-note">{summary ? `${formatAvitoMetric(summary.orders)} заказов · ${formatAvitoPctNullable(summary.orderConversionPct)} в заказ` : 'ждём данные'}</div></div>
                <div className="report-mini-card"><div className="report-mini-label">Избранное</div><div className="report-mini-value">{summary ? formatAvitoMetric(summary.favorites) : '—'}</div><div className="report-mini-note">{summary ? `${formatAvitoMetric(summary.impressions)} показов` : 'ждём данные'}</div></div>
                <div className="report-mini-card"><div className="report-mini-label">Расходы</div><div className="report-mini-value">{summary ? formatAvitoRubNullable(summary.spendKopecks) : '—'}</div><div className="report-mini-note">{spendPerView}</div></div>
              </div>
            </section>
            <section className="report-panel report-panel-pad">
              <div className="report-chart-head">
                <div><div className="report-card-title">Позиции по метрикам</div><div className="report-card-note">Объявления по просмотрам и контактам за выбранный период.</div></div>
              </div>
              <div className="attention-list">
                {topItems.length ? topItems.map((row) => (
                  <div
                    className="attention-item"
                    style={{ cursor: 'pointer' }}
                    data-vella-react-handlers="onclick"
                    onClick={() => openAvitoOverviewItem(row.itemId)}
                    key={row.itemId}
                  >
                    <div className="attention-bullet" style={{ color: '#2563EB' }} />
                    <div className="attention-copy">
                      <div className="attention-title">{row.title}</div>
                      <div className="attention-meta">{formatAvitoMetric(row.views)} просмотров · {formatAvitoMetric(row.contacts)} контактов · {row.accountName}</div>
                    </div>
                  </div>
                )) : (
                  <AvitoDataState
                    kind={live.loading ? 'loading' : 'empty'}
                    title={live.loading ? 'Загружаем объявления' : 'Нет объявлений за период'}
                    subtitle={live.loading ? 'Собираем топ по просмотрам и контактам.' : 'Попробуйте другой период или обновите данные из Авито.'}
                  />
                )}
              </div>
            </section>
          </div>
        </section>
        <section className="report-panel report-panel-pad">
          <div className="report-chart-head">
            <div><div className="report-card-title">События по Авито</div><div className="report-card-note">Публикация, кошельки и сообщения.</div></div>
          </div>
          <div className="attention-list">
            {events.length ? events.map((event) => (
              <div className={`attention-item ${eventClass(event.severity)}`} key={`${event.kind}:${event.title}`}>
                <div className="attention-bullet" style={{ color: eventColor(event.severity) }} />
                <div className="attention-copy"><div className="attention-title">{event.title}</div><div className="attention-meta">{event.meta}</div></div>
              </div>
            )) : (
              <AvitoDataState
                kind={live.loading ? 'loading' : 'empty'}
                title={live.loading ? 'Загружаем события' : 'Событий нет'}
                subtitle={live.loading ? 'Проверяем сообщения, отзывы и объявления.' : 'По текущему фильтру важных событий не найдено.'}
              />
            )}
          </div>
        </section>
      </div>

      <div className="report-table-wrap">
        <table className="report-mid">
          <thead><tr><th>Статус</th><th>Раздел</th><th>Аккаунт</th><th>Событие</th><th>Что сделать</th></tr></thead>
          <tbody>
            {events.length ? events.map((event) => (
              <tr key={`row:${event.kind}:${event.title}`}>
                <td><span className={`report-tag ${eventClass(event.severity)}`}>{event.severity === 'danger' ? 'Блок' : event.severity === 'warn' ? 'Контроль' : 'Новое'}</span></td>
                <td>{event.source}</td>
                <td>{data?.accounts[0]?.accountName ?? 'Все аккаунты'}</td>
                <td><b>{event.title}</b><span className="sub">{event.meta}</span></td>
                <td><button className="btn btn-default btn-sm" type="button" onClick={() => event.source === 'Сообщения' ? window.goSubtab?.('avito-inbox') : event.source === 'Отзывы' ? window.goSubtab?.('avito-reviews') : event.source === 'Объявления' ? window.goSubtab?.('avito-listings') : window.goSubtab?.('avito-stats')}>{event.action}</button></td>
              </tr>
            )) : (
              <tr>
                <td colSpan={5}>
                  <AvitoDataState
                    kind={live.loading ? 'loading' : 'empty'}
                    title={live.loading ? 'Загружаем обзор Авито' : 'Нет событий за период'}
                    subtitle={live.loading ? 'Подготавливаем сводку по Авито.' : 'Попробуйте другой период или обновите данные.'}
                  />
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
      {selectedItem ? (
        <div
          className="modal-overlay open avito-overview-item-modal"
          data-vella-island="avito-overview-item-modal"
          data-vella-island-status="explicit-jsx"
          onClick={(event) => {
            if (event.target === event.currentTarget) setSelectedItemId('')
          }}
        >
          <div className="modal xl" style={{ width: 'min(920px, calc(100vw - 48px))', maxHeight: 'calc(100vh - 72px)', overflow: 'auto' }}>
            <div className="modal-head">
              <div className="modal-icon brand">A</div>
              <h2>{selectedItem.title}</h2>
              <p>{selectedItem.category ?? 'Категория Авито'} · {selectedItem.accountName}</p>
              <button className="icon-btn" type="button" data-tip="Закрыть" onClick={() => setSelectedItemId('')}>×</button>
            </div>
            <div className="modal-body">
              <div className="avito-detail-grid five">
                <AvitoDetailKpi label="Просмотры" value={formatAvitoMetric(selectedItem.views)} id="avitoOverviewItemViews" note="за период" />
                <AvitoDetailKpi label="Контакты" value={formatAvitoMetric(selectedItem.contacts)} id="avitoOverviewItemContacts" note="за период" />
                <AvitoDetailKpi label="Избранное" value={formatAvitoMetric(selectedItem.favorites)} id="avitoOverviewItemFavorites" note="за период" />
                <AvitoDetailKpi label="Расходы" value={formatAvitoRubNullable(selectedItem.spendKopecks)} id="avitoOverviewItemSpend" note="продвижение" />
                <AvitoDetailKpi label="Конверсия" value={formatAvitoPctNullable(selectedItem.conversionPct)} id="avitoOverviewItemConversion" note="контакты / просмотры" />
              </div>
              <div className="avito-two-col" style={{ marginTop: 12 }}>
                <div className="avito-field-row"><span>Аккаунт</span><b>{selectedItem.accountName}</b></div>
                <div className="avito-field-row"><span>Заказы</span><b>{formatAvitoMetric(selectedItem.orders)}</b></div>
                <div className="avito-field-row"><span>Выкупы</span><b>{formatAvitoMetric(selectedItem.buyouts)}</b></div>
                <div className="avito-field-row"><span>Объявление</span><b>{selectedItem.url ? <a href={selectedItem.url} target="_blank" rel="noreferrer">Открыть в Авито</a> : '—'}</b></div>
              </div>
            </div>
            <div className="modal-foot">
              <button className="btn btn-default" type="button" onClick={() => window.goSubtab?.('avito-listings')}>Открыть объявления</button>
              <button className="btn btn-primary" type="button" onClick={() => setSelectedItemId('')}>Закрыть</button>
            </div>
          </div>
        </div>
      ) : null}
    </div>
  )
}

function AvitoOverviewIsland({ replacementKey }: { replacementKey: string }) {
  const location = useLocation()
  const { accessToken } = useAuth()
  const state = useAvitoOverviewState()
  const isAvitoOverviewRoute = resolveParityRouteTarget(location.pathname, location.search).tab === 'avito-overview'

  useEffect(() => {
    scrubAvitoOverviewLegacyMocks(document.body)
  })

  useEffect(() => {
    if (!isAvitoOverviewRoute) return
    if (!accessToken) {
      setAvitoOverviewLiveState({ loading: false, error: 'Нужна активная сессия', data: null })
      setAvitoChatsLiveState({ loading: false, error: 'Нужна активная сессия', data: null })
      return
    }
    const controller = new AbortController()
    setAvitoOverviewLiveState({ loading: true, error: null, data: window.__vellaAvitoOverviewLiveState?.data ?? null })
    setAvitoChatsLiveState({ loading: true, error: null, data: window.__vellaAvitoChatsLiveState?.data ?? null })
    void loadLiveAvitoOverview(accessToken, { dateFrom: state.dateFrom, dateTo: state.dateTo, forceRefresh: state.forceRefresh }, controller.signal)
      .then((data) => {
        if (controller.signal.aborted) return
        if (!data) throw new Error('Пустой ответ обзора Авито')
        setAvitoOverviewLiveState({ loading: false, error: null, data })
        if (state.forceRefresh) window.__vellaSetAvitoOverviewState?.({ forceRefresh: false })
      })
      .catch((error) => {
        if (controller.signal.aborted) return
        setAvitoOverviewLiveState({ loading: false, error: error instanceof Error ? error.message : 'Не удалось загрузить обзор Авито', data: null })
      })
    void loadLiveAvitoChats(accessToken, { limit: 50, offset: 0, forceRefresh: state.forceRefresh }, controller.signal)
      .then((data) => {
        if (controller.signal.aborted) return
        if (!data) throw new Error('Пустой ответ сообщений Авито')
        setAvitoChatsLiveState({ loading: false, error: null, data })
      })
      .catch((error) => {
        if (controller.signal.aborted) return
        setAvitoChatsLiveState({ loading: false, error: error instanceof Error ? error.message : 'Не удалось загрузить сообщения Авито', data: window.__vellaAvitoChatsLiveState?.data ?? null })
      })
    return () => controller.abort()
  }, [accessToken, isAvitoOverviewRoute, state.dateFrom, state.dateTo, state.forceRefresh, state.requestSeq])

  useEffect(() => {
    window.applyAvitoOverviewPeriod = (values) => {
      const current = window.__vellaAvitoOverviewState ?? defaultAvitoOverviewState()
      const dateFrom = values?.from || current.dateFromDraft || current.dateFrom
      const dateTo = values?.to || current.dateToDraft || current.dateTo
      if (dateFrom > dateTo) {
        window.showToast?.('Дата начала обзора Авито позже даты конца', 'warn')
        return
      }
      window.__vellaSetAvitoOverviewState?.({
        dateFrom,
        dateTo,
        dateFromDraft: dateFrom,
        dateToDraft: dateTo,
        periodId: '',
        forceRefresh: false,
        requestSeq: current.requestSeq + 1,
      })
    }
    window.refreshAvitoOverview = (values) => {
      if (showAvitoCooldownToast(window.__vellaAvitoOverviewLiveState?.data)) return
      const current = window.__vellaAvitoOverviewState ?? defaultAvitoOverviewState()
      const dateFrom = values?.from || current.dateFromDraft || current.dateFrom
      const dateTo = values?.to || current.dateToDraft || current.dateTo
      if (dateFrom > dateTo) {
        window.showToast?.('Дата начала обзора Авито позже даты конца', 'warn')
        return
      }
      window.__vellaSetAvitoOverviewState?.({
        dateFrom,
        dateTo,
        dateFromDraft: dateFrom,
        dateToDraft: dateTo,
        periodId: '',
        forceRefresh: true,
        requestSeq: current.requestSeq + 1,
      })
    }
    window.setAvitoOverviewPeriod = (period) => {
      const option = AVITO_OVERVIEW_PERIOD_OPTIONS.find((item) => item.id === String(period))
      const { from, to } = avitoOverviewPeriodForDays(option?.days ?? 30)
      window.__vellaSetAvitoOverviewState?.({
        dateFrom: from,
        dateTo: to,
        dateFromDraft: from,
        dateToDraft: to,
        periodId: option?.id ?? '30',
        forceRefresh: false,
        requestSeq: (window.__vellaAvitoOverviewState?.requestSeq ?? 0) + 1,
      })
    }
    return () => {
      clearVellaWindowProperty(window, 'applyAvitoOverviewPeriod')
      clearVellaWindowProperty(window, 'refreshAvitoOverview')
    }
  }, [])

  return (
    <div
      key={replacementKey}
      className="tab-content"
      id="tab-avito-overview"
      data-vella-island="avito-overview"
      data-vella-island-status="explicit-jsx"
    >
      <AvitoOverviewKpiStripIsland />
      <AvitoOverviewToolbarIsland />
      <AvitoOverviewReportShellIsland />
    </div>
  )
}

function defaultAvitoChatsState(): AvitoChatsState {
  return {
    filter: 'all',
    query: '',
    accountId: 'all',
    sort: 'new',
    selectedChatId: '',
    limit: 50,
    offset: 0,
    requestSeq: 0,
    forceRefresh: false,
    sending: false,
  }
}

function useAvitoChatsState() {
  const [state, setState] = useState<AvitoChatsState>(() => ({ ...defaultAvitoChatsState(), ...(window.__vellaAvitoChatsState ?? {}) }))
  useEffect(() => {
    const render = () => setState({ ...defaultAvitoChatsState(), ...(window.__vellaAvitoChatsState ?? {}) })
    window.__vellaReactRenderAvitoChats = render
    window.addEventListener('vella:avito-chats-updated', render)
    render()
    return () => {
      if (window.__vellaReactRenderAvitoChats === render) delete window.__vellaReactRenderAvitoChats
      window.removeEventListener('vella:avito-chats-updated', render)
    }
  }, [])
  return state
}

function useAvitoChatsLiveState() {
  const [state, setState] = useState<AvitoChatsLiveState>(() => ({ ...EMPTY_AVITO_CHATS_LIVE_STATE, ...(window.__vellaAvitoChatsLiveState ?? {}) }))
  useEffect(() => {
    const render = () => setState({ ...EMPTY_AVITO_CHATS_LIVE_STATE, ...(window.__vellaAvitoChatsLiveState ?? {}) })
    window.__vellaReactRenderAvitoChatsLive = render
    window.addEventListener('vella:avito-chats-live-updated', render)
    render()
    return () => {
      if (window.__vellaReactRenderAvitoChatsLive === render) delete window.__vellaReactRenderAvitoChatsLive
      window.removeEventListener('vella:avito-chats-live-updated', render)
    }
  }, [])
  return state
}

function setAvitoChatsLiveState(next: AvitoChatsLiveState) {
  window.__vellaAvitoChatsLiveState = next
  window.dispatchEvent(new CustomEvent('vella:avito-chats-live-updated'))
  window.__vellaReactRenderAvitoChatsLive?.()
}

function avitoChatsSummary(data: AvitoChatsBackendResponse | null) {
  const chats = data?.chats ?? []
  return {
    total: data?.summary.total ?? chats.length,
    unread: chats.filter((chat) => chat.unread).length,
    withItems: data?.summary.withItems ?? chats.filter((chat) => Boolean(chat.itemId)).length,
    messages: data?.summary.messages ?? Object.values(data?.messages ?? {}).reduce((sum, rows) => sum + rows.length, 0),
  }
}

function avitoChatTimeLabel(value: string | null | undefined) {
  if (!value) return '—'
  const date = new Date(value)
  if (Number.isNaN(date.getTime())) return value
  return date.toLocaleString('ru-RU', { day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' })
}

function avitoChatSearchText(chat: AvitoChatsBackendChat, messages: AvitoChatsBackendMessage[] = []) {
  return [
    chat.chatId,
    chat.accountId,
    chat.accountName,
    chat.buyerId,
    chat.buyerName,
    chat.itemId,
    chat.itemTitle,
    chat.itemPrice,
    chat.preview,
    ...messages.slice(-5).map((message) => message.text),
  ].filter(Boolean).join(' ').toLocaleLowerCase('ru-RU')
}

function avitoVisibleChats(data: AvitoChatsBackendResponse | null, state: AvitoChatsState) {
  const query = state.query.trim().toLocaleLowerCase('ru-RU')
  const rows = (data?.chats ?? []).filter((chat) => {
    if (state.filter === 'unread' && !chat.unread) return false
    if (state.filter === 'withItems' && !chat.itemId) return false
    if (state.accountId !== 'all' && chat.accountId !== state.accountId) return false
    if (query && !avitoChatSearchText(chat, data?.messages[chat.chatId]).includes(query)) return false
    return true
  })
  return [...rows].sort((left, right) => {
    if (state.sort === 'unread' && left.unread !== right.unread) return left.unread ? -1 : 1
    if (state.sort === 'with_item' && Boolean(left.itemId) !== Boolean(right.itemId)) return left.itemId ? -1 : 1
    return String(right.updatedAt || right.lastMessageAt || '').localeCompare(String(left.updatedAt || left.lastMessageAt || ''))
  })
}

function avitoMessagesChronological(messages: AvitoChatsBackendMessage[]) {
  return [...messages].sort((left, right) => {
    const leftTime = new Date(left.createdAt || 0).getTime()
    const rightTime = new Date(right.createdAt || 0).getTime()
    if (Number.isNaN(leftTime) && Number.isNaN(rightTime)) return String(left.messageId).localeCompare(String(right.messageId))
    if (Number.isNaN(leftTime)) return 1
    if (Number.isNaN(rightTime)) return -1
    return leftTime - rightTime
  })
}

function avitoChatsDiagnosticsLabel(data: AvitoChatsBackendResponse | null) {
  if (!data) return 'Данные появятся после обновления Авито.'
  const summary = avitoChatsSummary(data)
  const chatsCount = summary.total
  const unreadCount = summary.unread
  const messagesCount = summary.messages
  return `${formatAvitoInt(chatsCount)} диалогов · ${formatAvitoInt(unreadCount)} непрочитанных · ${formatAvitoInt(messagesCount)} сообщений`
}

function avitoChatTypeLabel(type: string | null | undefined) {
  const normalized = String(type ?? '').toLocaleLowerCase('ru-RU')
  if (!normalized) return '—'
  if (normalized.includes('item') || normalized.includes('listing')) return 'По объявлению'
  if (normalized.includes('messenger') || normalized.includes('chat')) return 'Сообщение'
  if (normalized.includes('support')) return 'Поддержка'
  return 'Диалог'
}

function avitoChatsFriendlyError(error: string | null | undefined) {
  if (!error) return null
  if (/429|too many|rate/i.test(error)) return 'Авито временно ограничил частые запросы. Попробуйте обновить чуть позже.'
  if (/auth|token|401|403/i.test(error)) return 'Нужно проверить подключение аккаунта Авито.'
  return 'Не удалось загрузить сообщения Авито.'
}

function AvitoInboxToolbarIsland() {
  const state = useAvitoChatsState()
  const live = useAvitoChatsLiveState()
  const data = live.data
  const summary = avitoChatsSummary(data)
  const accountOptions = Array.from(new Map((data?.chats ?? []).map((chat) => [chat.accountId, chat.accountName])).entries())
  const chips: Array<[AvitoChatsFilter, string, string, string]> = [
    ['all', 'Все', formatAvitoInt(summary.total), ''],
    ['unread', 'Непрочитанные', formatAvitoInt(summary.unread), '#DC2626'],
    ['withItems', 'С объявлениями', formatAvitoInt(summary.withItems), ''],
  ]
  return (
    <div
      className="toolbar"
      data-vella-island="avito-inbox-toolbar"
      data-vella-island-status="explicit-jsx"
      data-vella-event-owner="react"
    >
      <div className="search">
        <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
          <circle cx="11" cy="11" r="8" />
          <line x1="21" y1="21" x2="16.65" y2="16.65" />
        </svg>
        <input
          id="avitoInboxSearch"
          type="text"
          aria-label="Поиск по сообщениям Авито"
          autoComplete="off"
          placeholder="Покупатель, объявление или текст сообщения…"
          value={state.query}
          data-vella-react-handlers="oninput"
          onInput={(event) => window.__vellaSetAvitoChatsState?.({ query: event.currentTarget.value })}
        />
      </div>
      <div className="chips">
        {chips.map(([filter, label, count, color]) => (
          <button
            className={state.filter === filter ? 'chip active' : 'chip'}
            type="button"
            data-avito-inbox-filter={filter}
            data-vella-react-handlers="onclick"
            onClick={(event) => window.setAvitoInboxFilter?.(event.currentTarget)}
            key={filter}
          >
            {label} <span className="chip-count" style={color ? { color } : undefined}>{count}</span>
          </button>
        ))}
      </div>
      <div className="toolbar-right">
        <select
          id="avitoInboxAccount"
          className="adv-select"
          style={{ height: '30px', padding: '4px 8px', fontSize: '12px' }}
          data-tip="Фильтр по аккаунтам Авито"
          value={state.accountId}
          data-vella-react-handlers="onchange"
          onChange={(event) => window.__vellaSetAvitoChatsState?.({ accountId: event.currentTarget.value })}
        >
          <option value="all">Все аккаунты</option>
          {accountOptions.map(([accountId, accountName]) => <option value={accountId} key={accountId}>{accountName}</option>)}
        </select>
        <button className="btn btn-default btn-sm" type="button" disabled={live.loading} data-vella-react-handlers="onclick" onClick={() => window.refreshAvitoChats?.()}>{live.loading ? 'Загрузка' : 'Обновить'}</button>
      </div>
    </div>
  )
}

function AvitoConversationRowsIsland() {
  const state = useAvitoChatsState()
  const live = useAvitoChatsLiveState()
  const visibleChats = avitoVisibleChats(live.data, state)
  return (
    <div
      className="avito-conversation-list"
      data-vella-island="avito-inbox-conversation-list"
      data-vella-island-status="explicit-jsx"
    >
      {visibleChats.map((item) => (
        <div
          className={state.selectedChatId === item.chatId ? 'avito-conversation active' : 'avito-conversation'}
          data-avito-inbox-row
          data-conversation-key={item.chatId}
          data-filter={item.unread ? 'all unread' : 'all'}
          data-account={item.accountId}
          data-search={avitoChatSearchText(item, live.data?.messages[item.chatId])}
          data-vella-react-handlers="onclick"
          onClick={(event) => window.selectAvitoConversation?.(event.currentTarget, item.chatId)}
          key={item.chatId}
        >
          <div className="avito-conv-top">
            <span className={item.unread ? 'avito-account-dot orange' : 'avito-account-dot green'} />
            <span className="avito-conv-buyer">{item.buyerName}</span>
            <span className="avito-conv-time">{avitoChatTimeLabel(item.updatedAt || item.lastMessageAt)}</span>
          </div>
          <div className="avito-conv-listing">{item.itemTitle || `Диалог ${item.chatId}`}</div>
          <div className="avito-conv-preview">{item.preview || 'Сообщений нет'}</div>
          <div className="avito-conv-meta">
            {item.unread ? <span className="avito-pill red">новое</span> : null}
            <span className="avito-pill">{item.accountName}</span>
          </div>
        </div>
      ))}
      {!visibleChats.length ? (
        <div className="avito-inbox-empty" id="avitoInboxEmpty">
          {live.loading ? (
            <AvitoDataState kind="loading" title="Загружаем диалоги" subtitle="Собираем сообщения покупателей Авито." />
          ) : live.error ? (
            <AvitoDataState kind="error" title="Сообщения временно недоступны" subtitle={avitoChatsFriendlyError(live.error) ?? undefined} />
          ) : (
            <AvitoDataState kind="empty" title="Диалогов нет" subtitle="По выбранным фильтрам сообщений не найдено." />
          )}
        </div>
      ) : null}
    </div>
  )
}

function AvitoMessageAttachment({ attachment }: { attachment: AvitoMessageAttachmentSnapshot }) {
  return (
    <div className="avito-message-attachment">
      {attachment.url ? (
        <img className="avito-message-attachment-image" src={attachment.url} alt={attachment.name || 'Изображение'} loading="lazy" />
      ) : (
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.9" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
          <rect x="3" y="5" width="18" height="14" rx="2" />
          <circle cx="8.5" cy="10" r="1.5" />
          <path d="M21 15l-4.5-4.5L9 18" />
        </svg>
      )}
      <span>{attachment.name || 'изображение'}</span>
      <small>{attachment.size || 'файл'}</small>
    </div>
  )
}

function avitoMessageSnapshot(message: AvitoChatsBackendMessage): AvitoMessageSnapshot {
  return {
    type: message.direction || 'in',
    text: message.text || (message.imageUrl ? 'Изображение' : 'Сообщение Авито'),
    meta: avitoChatTimeLabel(message.createdAt),
    attachments: message.imageUrl ? [{ name: 'Изображение Авито', size: 'файл', kind: 'image', url: message.imageUrl }] : [],
  }
}

function AvitoMessageItem({ message, index }: { message: AvitoChatsBackendMessage; index: number }) {
  const snapshot = avitoMessageSnapshot(message)
  const toneClass = snapshot.type === 'out' ? ' out' : snapshot.type === 'note' ? ' note' : ''
  return (
    <div
      className={`avito-msg${toneClass}`}
      data-vella-island="avito-inbox-message"
      data-vella-island-status="explicit-jsx"
      data-avito-message-type={snapshot.type || 'in'}
      key={`${message.messageId}-${index}`}
    >
      <div className="avito-msg-text">{snapshot.text}</div>
      {snapshot.attachments.length > 0 ? (
        <div className="avito-msg-attachments">
          {snapshot.attachments.map((attachment, attachmentIndex) => (
            <AvitoMessageAttachment attachment={attachment} key={`${attachment.name}-${attachmentIndex}`} />
          ))}
        </div>
      ) : null}
      <div className="avito-msg-meta">{snapshot.meta}</div>
    </div>
  )
}

function AvitoMessageStreamIsland() {
  const state = useAvitoChatsState()
  const live = useAvitoChatsLiveState()
  const messages = avitoMessagesChronological(state.selectedChatId ? live.data?.messages[state.selectedChatId] ?? [] : [])

  return (
    <div
      className="avito-message-stream"
      id="avitoMessageStream"
      data-vella-island="avito-inbox-message-stream"
      data-vella-island-status="explicit-jsx"
      data-vella-row-count={messages.length}
      data-avito-conversation-key={state.selectedChatId}
    >
      {messages.length ? messages.map((message, index) => <AvitoMessageItem message={message} index={index} key={`${message.messageId}-${index}`} />) : (
        <AvitoDataState
          kind={live.loading ? 'loading' : live.error ? 'error' : 'empty'}
          title={live.loading ? 'Загружаем сообщения' : live.error ? 'Сообщения временно недоступны' : 'Сообщений нет'}
          subtitle={live.loading ? 'Открываем переписку с покупателем.' : live.error ? avitoChatsFriendlyError(live.error) ?? undefined : 'Выберите другой диалог или обновите данные.'}
        />
      )}
    </div>
  )
}

