function AvitoListingsDetailBodyIsland({ sourceElement }: { replacementKey: string; sourceElement?: HTMLElement | SVGElement }) {
  const state = useAvitoListingsState()
  const live = useAvitoListingsLiveState()
  const details = avitoBackendListingDetails(live.data)
  const detail = state.selectedKey ? details[state.selectedKey] : undefined
  if (!detail) return null
  const current = getAvitoDetailTotals(detail)
  const sourceStateClass = detail.registry === 'Актуально' ? 'up' : detail.registry === 'Требует проверки' ? 'warn' : 'down'
  const conversionText = current.views ? `${current.conversion.toFixed(2)}%` : '—'
  const periodLabel = live.data ? `${live.data.period.dateFrom} — ${live.data.period.dateTo}` : 'выбранный период'
  return (
    <div
      id={sourceElement instanceof HTMLElement ? sourceElement.id || undefined : 'avitoDetailBody'}
      className={sourceElement instanceof HTMLElement ? sourceElement.className : 'avito-detail-body'}
      style={sourceElement instanceof HTMLElement ? styleAttributeToObject(sourceElement.getAttribute('style') ?? '') : undefined}
      data-vella-island="avito-listings-detail-body"
      data-vella-island-status="explicit-jsx"
    >
      <section className="avito-detail-section guard" id="avito-sec-overview">
        <h3>Объявление Авито</h3>
        <div id="avitoDetailGuard">{detail.guard}</div>
      </section>
      <section className="avito-detail-section">
        <h3>Обзор</h3>
        <div className="avito-detail-grid">
          <div className="avito-detail-kpi" data-tip="Контакты относительно просмотров за выбранный период"><span>Конверсия</span><b className={detail.registry === 'Актуально' ? 'warn' : 'danger'} id="avitoDetailConversion">{conversionText}</b></div>
          <div className="avito-detail-kpi" data-tip="Свежесть реестра и статистики объявления"><span>Свежесть данных</span><b className={detail.registry === 'Актуально' ? 'warn' : 'danger'} id="avitoDetailFreshness">{detail.freshness}</b></div>
        </div>
        <div className="avito-two-col">
          <div className="avito-field-row avito-overview-status"><span>Аккаунт<br /><small>{detail.id}</small></span><b>{detail.account}</b></div>
          <div className="avito-field-row avito-overview-status"><span>Цена<br /><small>из реестра Avito</small></span><b>{detail.price}</b></div>
          <div className="avito-field-row avito-overview-status"><span>Период<br /><small>выбранный диапазон</small></span><b>{periodLabel}</b></div>
          <div className="avito-field-row avito-overview-status"><span>Данные<br /><small>объявления и статистика</small></span><b className={sourceStateClass} id="avitoDetailSourceState">{detail.registry === 'Актуально' ? 'актуальны' : detail.registry === 'Требует проверки' ? 'требуют проверки' : 'нужно обновить'}</b></div>
        </div>
      </section>
      <section className="avito-detail-section" id="avito-sec-metrics">
        <h3>Метрики</h3>
        <div className="avito-detail-grid five">
          <AvitoDetailKpi label="Просмотры" value={formatAvitoInt(current.views)} id="avitoDetailViews" />
          <AvitoDetailKpi label="Контакты" value={formatAvitoInt(current.contacts)} id="avitoDetailContacts" />
          <AvitoDetailKpi label="Избранное" value={formatAvitoInt(current.favorites)} id="avitoDetailFavorites" />
          <AvitoDetailKpi label="Заказы" value={formatAvitoInt(current.orders)} id="avitoDetailOrders" note="доставка" />
          <AvitoDetailKpi label="Конверсия" value={conversionText} id="avitoDetailMetricConversion" note="контакты / просмотры" />
        </div>
        <AvitoUnavailableDailyDynamics source="Avito stats" />
      </section>
      <section className="avito-detail-section" id="avito-sec-draft">
        <h3>Контроль</h3>
        <div className="avito-field-row"><span>Статус объявления</span><b id="avitoDetailDraftListingState">{detail.registry}</b></div>
        <div className="avito-field-row"><span>Причина</span><b id="avitoDetailReason">{detail.reason}</b></div>
        <div className="avito-field-row"><span>Рекомендация</span><b id="avitoDetailDraftNext">{detail.recommendation}</b></div>
      </section>
    </div>
  )
}

