function avitoRepricerSignalLabel(signal: AvitoRepricerFilter) {
  if (signal === 'raise') return 'Поднять'
  if (signal === 'lower') return 'Снизить'
  if (signal === 'keep') return 'Оставить'
  if (signal === 'no_data') return 'Нет данных'
  if (signal === 'blocked') return 'Блок'
  return 'Все'
}

function avitoRepricerSignalClass(signal: AvitoRepricerFilter) {
  return `avito-decision-badge ${signal}`
}

function avitoPriceHistoryActionLabel(action: string) {
  if (action === 'auto_applied') return 'Авто-применено'
  if (action === 'approved') return 'Одобрено'
  if (action === 'rejected') return 'Отклонено'
  if (action === 'recommended') return 'Рекомендация'
  return action || 'Событие'
}

function avitoPriceHistorySourceLabel(source: string | null | undefined) {
  if (source === 'manual_approval') return 'Ручное решение'
  if (source === 'worker') return 'Worker'
  if (source === 'worker_auto_apply') return 'Авто-применение'
  if (source === 'apply_failed') return 'Нужна проверка'
  if (source === 'avito_repricer') return 'Репрайсер'
  return 'Репрайсер'
}

function avitoPriceHistoryTone(action: string) {
  if (action === 'auto_applied' || action === 'approved') return 'up'
  if (action === 'rejected') return 'down'
  return 'same'
}

function avitoPriceHistoryTime(value: string) {
  const parsed = new Date(value)
  if (Number.isNaN(parsed.getTime())) return value
  return parsed.toLocaleString('ru-RU', { day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit' })
}

function avitoWorkerCountdownLabel(seconds: number | null | undefined) {
  if (seconds == null) return 'ожидаем первый запуск'
  if (seconds <= 0) return 'готов к ближайшему проходу'
  const hours = Math.floor(seconds / 3600)
  const minutes = Math.floor((seconds % 3600) / 60)
  const rest = seconds % 60
  if (hours > 0) return `${hours} ч ${minutes} мин`
  if (minutes > 0) return `${minutes} мин ${rest.toString().padStart(2, '0')} сек`
  return `${rest} сек`
}

function avitoApprovalErrorLabel(error: unknown) {
  const message = error instanceof Error ? error.message : String(error || '')
  if ((error instanceof ApiError && error.code === 'AVITO_PRICE_APPLY_DISABLED') || message.includes('AVITO_PRICE_APPLY_DISABLED')) {
    return 'Автоматическая отправка цен сейчас отключена. Изменение можно оставить в подтверждениях или отклонить.'
  }
  if (error instanceof ApiError && error.code === 'AVITO_CREDENTIALS_REQUIRED') {
    return 'Не найдены Avito-ключи для отправки цены. Проверь подключение Avito в настройках профиля или организации.'
  }
  if (error instanceof ApiError && error.code === 'AVITO_PRICE_APPLY_FAILED') {
    return `Avito не принял изменение цены: ${message}`
  }
  return error instanceof Error ? error.message : 'Не удалось обработать подтверждение'
}

function avitoRepricerRowsForState(data: AvitoRepricerBackendResponse | null, state: AvitoRepricerState) {
  const query = state.query.trim().toLocaleLowerCase('ru-RU')
  return (data?.rows ?? []).filter((row) => {
    if (state.filter !== 'all' && row.strategySignal !== state.filter) return false
    if (query && !`${row.title} ${row.itemId} ${row.accountName} ${row.category ?? ''}`.toLocaleLowerCase('ru-RU').includes(query)) return false
    return true
  })
}

function AvitoRepricerKpiStripIsland({ replacementKey }: { replacementKey: string }) {
  const live = useAvitoRepricerLiveState()
  const summary = live.data?.summary
  const kpis = [
    ['Написали в чат', 'Сколько пользователей написали по объявлениям', summary ? formatAvitoMetric(summary.contactsMessenger) : '—', 'главный сигнал'],
    ['Поднять', 'Кандидаты на повышение цены', summary ? formatAvitoInt(summary.raiseCandidates) : '—', 'спрос выше порога'],
    ['Снизить', 'Кандидаты на снижение цены', summary ? formatAvitoInt(summary.lowerCandidates) : '—', 'трафик без чатов'],
    ['Без метрики', 'По части объявлений нет метрики чатов', summary ? formatAvitoInt(summary.noData) : '—', 'не применять'],
    ['Просмотры', 'Просмотры за выбранный период', summary ? formatAvitoMetric(summary.views) : '—', 'за период'],
    ['Контакты всего', 'Все контакты вместе: чат, телефон и другие действия', summary ? formatAvitoMetric(summary.contacts) : '—', 'общий показатель'],
  ] as const
  return (
    <div key={replacementKey} className="stats avito-stats-kpis" data-vella-island="avito-repricer-kpi-strip" data-vella-island-status="explicit-jsx">
      {kpis.map(([label, tip, value, note]) => (
        <div className="stat" key={label}>
          <div className="stat-label">{label} <span className="stat-tip" data-tip={tip}>i</span></div>
          <div className="stat-val">{live.loading ? '…' : value}</div>
          <div className={`stat-delta ${live.error ? 'down' : 'neutral'}`}>{live.error ? 'нужна настройка API' : note}</div>
        </div>
      ))}
    </div>
  )
}

function AvitoRepricerToolbarIsland({ replacementKey }: { replacementKey: string }) {
  const state = useAvitoRepricerState()
  const live = useAvitoRepricerLiveState()
  const summary = live.data?.summary
  const cooldownUntil = avitoCooldownUntilFromPayload(live.data)
  const chips: Array<[AvitoRepricerFilter, string, string, string]> = [
    ['all', 'Все', formatAvitoInt(live.data?.rows.length ?? 0), ''],
    ['raise', 'Поднять', formatAvitoInt(summary?.raiseCandidates ?? 0), '#059669'],
    ['lower', 'Снизить', formatAvitoInt(summary?.lowerCandidates ?? 0), '#B45309'],
    ['keep', 'Оставить', formatAvitoInt(summary?.keepCandidates ?? 0), ''],
    ['no_data', 'Нет метрики', formatAvitoInt(summary?.noData ?? 0), '#DC2626'],
  ]
  return (
    <div key={replacementKey} className="toolbar" data-vella-island="avito-repricer-toolbar" data-vella-island-status="explicit-jsx" data-vella-event-owner="react">
      <div className="search">
        <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
          <circle cx="11" cy="11" r="8" />
          <line x1="21" y1="21" x2="16.65" y2="16.65" />
        </svg>
        <input
          id="avitoRepricerSearch"
          type="text"
          aria-label="Поиск по репрайсеру Авито"
          autoComplete="off"
          placeholder="Название или ID Авито"
          value={state.query}
          onInput={(event) => window.__vellaSetAvitoRepricerState?.({ query: event.currentTarget.value })}
        />
      </div>
      <div className="chips">
        {chips.map(([filter, label, count, color]) => (
          <button className={state.filter === filter ? 'chip active' : 'chip'} type="button" data-avito-repricer-filter={filter} onClick={(event) => window.setAvitoRepricerFilter?.(event.currentTarget)} key={filter}>
            {label} <span className="chip-count" style={color ? { color } : undefined}>{count}</span>
          </button>
        ))}
      </div>
      <div className="toolbar-right">
        <AvitoAutoRefreshTimer lastRefreshAt={state.lastRefreshAt} intervalMs={AVITO_REPRICER_AUTO_REFRESH_MS} loading={live.loading} />
        <AvitoRefreshButton loading={live.loading} cooldownUntil={cooldownUntil} onClick={() => window.refreshAvitoRepricer?.()} />
      </div>
    </div>
  )
}

export function AvitoRepricerSettingsPanel({
  accessToken,
  refreshKey,
}: {
  accessToken: string | null
  refreshKey: number
}) {
  const [settings, setSettings] = useState<AvitoRepricerSettings | null>(null)
  const [workerTiming, setWorkerTiming] = useState<AvitoRepricerSettingsResponse['workerTiming'] | null>(null)
  const [pending, setPending] = useState<AvitoRepricerPendingApproval[]>([])
  const [nowTick, setNowTick] = useState(() => Date.now())
  const [scheduleOpen, setScheduleOpen] = useState(false)
  const [draftIntervalMinutes, setDraftIntervalMinutes] = useState(60)
  const [settingsSaving, setSettingsSaving] = useState(false)

  useEffect(() => {
    const timer = window.setInterval(() => setNowTick(Date.now()), 1000)
    return () => window.clearInterval(timer)
  }, [])

  useEffect(() => {
    if (!accessToken) {
      return
    }
    const controller = new AbortController()
    Promise.all([
      loadLiveAvitoRepricerSettings(accessToken, controller.signal),
      loadLiveAvitoRepricerPending(accessToken, controller.signal),
    ])
      .then(([settingsPayload, pendingPayload]) => {
        if (controller.signal.aborted) return
        if (!settingsPayload) throw new Error('Пустой ответ настроек Авито')
        setSettings(settingsPayload.settings)
        setWorkerTiming(settingsPayload.workerTiming ?? null)
        setPending(pendingPayload?.items ?? [])
      })
      .catch((error) => {
        if (controller.signal.aborted) return
        window.showToast?.(error instanceof Error ? error.message : 'Не удалось загрузить настройки репрайсера Авито', 'warn')
      })
    return () => controller.abort()
  }, [accessToken, refreshKey])

  const resolvePending = async (approvalId: string, action: 'approve' | 'reject') => {
    if (!accessToken) return
    try {
      await resolveLiveAvitoRepricerPending(accessToken, approvalId, action)
      const pendingPayload = await loadLiveAvitoRepricerPending(accessToken)
      setPending(pendingPayload?.items ?? [])
      window.showToast?.(action === 'approve' ? 'Цена обработана' : 'Изменение отклонено', 'success')
    } catch (error) {
      window.showToast?.(avitoApprovalErrorLabel(error), 'warn')
    }
  }

  const openScheduleSettings = () => {
    if (!settings) return
    setDraftIntervalMinutes(settings.executeIntervalMinutes)
    setScheduleOpen(true)
  }

  const saveScheduleSettings = async () => {
    if (!accessToken || !settings) return
    const nextInterval = Math.min(1440, Math.max(5, Math.round(draftIntervalMinutes || settings.executeIntervalMinutes)))
    setSettingsSaving(true)
    try {
      const payload = await saveLiveAvitoRepricerSettings(accessToken, {
        ...settings,
        executeIntervalMinutes: nextInterval,
      })
      if (!payload) throw new Error('Пустой ответ настроек Авито')
      setSettings(payload.settings)
      setWorkerTiming(payload.workerTiming ?? null)
      setDraftIntervalMinutes(payload.settings.executeIntervalMinutes)
      setScheduleOpen(false)
      window.showToast?.('Время запуска репрайсера сохранено', 'success')
    } catch (error) {
      window.showToast?.(error instanceof Error ? error.message : 'Не удалось сохранить время запуска репрайсера', 'warn')
    } finally {
      setSettingsSaving(false)
    }
  }

  if (!settings) {
    return (
      <div className="saved-views-panel avito-worker-card" data-vella-island="avito-repricer-settings">
        <AvitoDataState kind="loading" title="Считаем время до следующего пересчёта" />
      </div>
    )
  }

  const secondsUntilNextRun = workerTiming?.nextRunAt
    ? Math.max(0, Math.floor((new Date(workerTiming.nextRunAt).getTime() - nowTick) / 1000))
    : workerTiming?.secondsUntilNextRun
  const countdownLabel = !settings.enabled
    ? 'выключен'
    : secondsUntilNextRun && secondsUntilNextRun > 0
      ? avitoWorkerCountdownLabel(secondsUntilNextRun)
      : 'скоро'

  return (
    <>
      <div
        className="saved-views-panel avito-worker-card"
        data-vella-island="avito-repricer-settings"
        style={{ display: 'inline-flex', width: 'fit-content', maxWidth: '100%', alignSelf: 'flex-start', alignItems: 'center', justifyContent: 'flex-start', gap: 10, padding: '8px 12px', marginLeft: 20 }}
      >
        <div style={{ width: 28, height: 28, borderRadius: 9, display: 'grid', placeItems: 'center', background: 'var(--brand-light)', color: 'var(--brand)', flex: '0 0 auto' }}>
          <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><circle cx="12" cy="12" r="9" /><path d="M12 7v5l3 2" /></svg>
        </div>
        <div className="saved-views-meta avito-worker-copy" style={{ minWidth: 0, textAlign: 'left' }}>
          <span>Время до следующего пересчёта цен</span>
        </div>
        <div
          aria-label="Время до следующего запуска репрайсера Авито"
          style={{ display: 'flex', alignItems: 'baseline', gap: 6, whiteSpace: 'nowrap' }}
        >
          <b style={{ fontSize: 15, fontWeight: 800, color: 'var(--gray-900)', lineHeight: 1 }}>{countdownLabel}</b>
          <span style={{ fontSize: 11.5, color: 'var(--gray-500)' }}>до запуска</span>
        </div>
        <button
          className="btn btn-default btn-sm avito-schedule-btn"
          type="button"
          data-vella-react-handlers="onclick"
          onClick={openScheduleSettings}
        >
          Настроить время
        </button>
      </div>
      {pending.length > 0 && (
        <section className="avito-repricer-pending-shell" aria-label="Подтверждения цен Авито">
          <div className="avito-pending-head">
            <div><b>Подтверждения цен</b><span>{pending.length} изменений ждут решения</span></div>
          </div>
          <div className="avito-pending-strip">
            {pending.slice(0, 8).map((item) => (
              <article className="avito-pending-card" key={item.approvalId}>
                {item.imageUrl ? <img className="avito-row-photo" src={item.imageUrl} alt="" loading="lazy" /> : <div className="avito-row-photo avito-row-photo-empty">AV</div>}
                <div className="avito-pending-main">
                  <b>{item.title ?? item.itemId}</b>
                  <span>{formatAvitoRubNullable(item.currentPriceKopecks ?? null)} → {formatAvitoRubNullable(item.recommendedPriceKopecks ?? null)} · {item.priceDeltaPct && item.priceDeltaPct > 0 ? '+' : ''}{item.priceDeltaPct ?? 0}% · чаты {formatAvitoMetric(item.contactsMessenger ?? null)}</span>
                </div>
                <div className="avito-pending-actions">
                  <button className="btn btn-primary btn-sm" type="button" onClick={() => resolvePending(item.approvalId, 'approve')}>Отправить</button>
                  <button className="btn btn-default btn-sm" type="button" onClick={() => resolvePending(item.approvalId, 'reject')}>Отклонить</button>
                </div>
              </article>
            ))}
            {pending.length > 8 ? <div className="avito-pending-more">+{pending.length - 8}</div> : null}
          </div>
        </section>
      )}
      {scheduleOpen ? (
        <div className="modal-overlay open" role="presentation" onMouseDown={() => !settingsSaving && setScheduleOpen(false)}>
          <div className="modal avito-schedule-modal" role="dialog" aria-modal="true" aria-label="Настройка времени запуска репрайсера Авито" onMouseDown={(event) => event.stopPropagation()}>
            <div className="modal-head">
              <div>
                <div className="modal-title">Время запуска репрайсера</div>
                <div className="modal-sub">Как часто Авито-репрайсер будет запускать пересчёт цен.</div>
              </div>
              <button className="modal-close" type="button" aria-label="Закрыть" onClick={() => setScheduleOpen(false)}>×</button>
            </div>
            <div className="modal-body avito-schedule-body">
              <div className="avito-schedule-summary">
                <span>Текущий интервал</span>
                <b>{settings.executeIntervalMinutes} мин</b>
              </div>
              <div className="avito-schedule-presets" aria-label="Быстрый выбор интервала">
                {[15, 30, 60, 120].map((minutes) => (
                  <button
                    key={minutes}
                    type="button"
                    className={draftIntervalMinutes === minutes ? 'active' : ''}
                    onClick={() => setDraftIntervalMinutes(minutes)}
                  >
                    {minutes} мин
                  </button>
                ))}
              </div>
              <div className="avito-schedule-field">
                <label htmlFor="avitoRepricerScheduleMinutes">Интервал в минутах</label>
                <input
                  id="avitoRepricerScheduleMinutes"
                  type="number"
                  min={5}
                  max={1440}
                  step={5}
                  value={draftIntervalMinutes}
                  onChange={(event) => setDraftIntervalMinutes(Number(event.currentTarget.value))}
                />
                <small>Минимум 5 минут, максимум 24 часа.</small>
              </div>
            </div>
            <div className="modal-foot">
              <button className="btn btn-default" type="button" disabled={settingsSaving} onClick={() => setScheduleOpen(false)}>Отмена</button>
              <button className="btn btn-primary" type="button" disabled={settingsSaving} onClick={() => void saveScheduleSettings()}>
                {settingsSaving ? 'Сохраняем...' : 'Сохранить время'}
              </button>
            </div>
          </div>
        </div>
      ) : null}
    </>
  )
}

function AvitoRepricerPriceHistoryModal({
  state,
  onClose,
}: {
  state: AvitoRepricerHistoryState
  onClose: () => void
}) {
  const row = state.row
  return (
    <div className="modal-overlay open avito-price-history-overlay" role="presentation" onMouseDown={onClose}>
      <div className="modal xl avito-price-history-modal" role="dialog" aria-modal="true" aria-label="История цены Авито" onMouseDown={(event) => event.stopPropagation()}>
        <div className="modal-head">
          <div className="avito-history-title">
            {row.imageUrl ? <img className="avito-row-photo" src={row.imageUrl} alt="" loading="lazy" /> : <div className="avito-row-photo avito-row-photo-empty">AV</div>}
            <div>
              <div className="modal-title">История цены Авито</div>
              <div className="modal-sub">{row.title} · ID: {row.itemId}</div>
            </div>
          </div>
          <button className="icon-btn" type="button" aria-label="Закрыть историю цены Авито" onClick={onClose}>×</button>
        </div>
        <div className="modal-body">
          <div className="avito-history-summary">
            <span>Текущая: <b>{formatAvitoRubNullable(row.priceKopecks)}</b></span>
            <span>Рекомендация: <b>{formatAvitoRubNullable(row.recommendedPriceKopecks)}</b></span>
            <span>Чаты: <b>{formatAvitoMetric(row.contactsMessenger)}</b></span>
            <span>{row.strategyName}</span>
          </div>
          {state.loading ? (
            <div className="avito-history-empty">Загружаем историю цены...</div>
          ) : state.error ? (
            <div className="avito-history-error">{state.error}</div>
          ) : state.entries.length ? (
            <div className="avito-price-history-list">
              {state.entries.map((entry) => (
                <div className="avito-price-history-row" key={entry.id}>
                  <div className="avito-price-history-time">
                    <b>{avitoPriceHistoryTime(entry.happenedAt)}</b>
                    <span>{avitoPriceHistorySourceLabel(entry.source)}</span>
                  </div>
                  <div className={`avito-price-history-delta ${avitoPriceHistoryTone(entry.action)}`}>
                    {entry.priceDeltaPct == null ? '0%' : `${entry.priceDeltaPct > 0 ? '+' : ''}${entry.priceDeltaPct}%`}
                  </div>
                  <div className="avito-price-history-body">
                    <div className="avito-price-history-main">
                      <b>{formatAvitoRubNullable(entry.oldPriceKopecks ?? null)}</b>
                      <span>→</span>
                      <b>{formatAvitoRubNullable(entry.newPriceKopecks ?? null)}</b>
                      <em>{avitoPriceHistoryActionLabel(entry.action)}</em>
                    </div>
                    <div className="avito-price-history-reason">{entry.reason || entry.error || 'Событие репрайсера Авито'}</div>
                    <div className="avito-price-history-meta">
                      {entry.strategyName ? <span>{entry.strategyName}</span> : null}
                      <span>чаты {formatAvitoMetric(entry.contactsMessenger ?? null)}</span>
                      <span>просмотры {formatAvitoMetric(entry.views ?? null)}</span>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          ) : (
            <div className="avito-history-empty">
              <b>Истории пока нет</b>
              <span>Она появится после рекомендации worker, отклонения, одобрения или авто-применения цены.</span>
            </div>
          )}
        </div>
        <div className="modal-foot">
          <button className="btn btn-default" type="button" onClick={onClose}>Закрыть</button>
        </div>
      </div>
    </div>
  )
}

function AvitoRepricerIsland({ replacementKey }: { replacementKey: string; sourceElement?: HTMLElement | SVGElement }) {
  const location = useLocation()
  const { accessToken } = useAuth()
  const state = useAvitoRepricerState()
  const live = useAvitoRepricerLiveState()
  const [openStrategyItemId, setOpenStrategyItemId] = useState<string | null>(null)
  const [savingStrategyItemId, setSavingStrategyItemId] = useState<string | null>(null)
  const [historyState, setHistoryState] = useState<AvitoRepricerHistoryState | null>(null)
  const isRoute = resolveParityRouteTarget(location.pathname, location.search).tab === 'avito-repricer'

  useEffect(() => {
    if (!isRoute) return
    if (!accessToken) {
      setAvitoRepricerLiveState({ loading: false, error: 'Нужна активная сессия', data: null })
      return
    }
    const controller = new AbortController()
    setAvitoRepricerLiveState({ loading: true, error: null, data: window.__vellaAvitoRepricerLiveState?.data ?? null })
    void loadLiveAvitoRepricer(accessToken, { dateFrom: state.dateFrom, dateTo: state.dateTo, forceRefresh: state.forceRefresh }, controller.signal)
      .then((data) => {
        if (controller.signal.aborted) return
        const backendError = avitoBackendErrorMessage(data)
        setAvitoRepricerLiveState({ loading: false, error: backendError, data })
        if (backendError) showAvitoCooldownToast(data)
        if (isAvitoRepricerCacheHit(data)) {
          window.__vellaSetAvitoRepricerState?.({ forceRefresh: false })
          return
        }
        const refreshedAt = Date.now()
        writeAvitoRepricerLastRefreshAt(refreshedAt)
        window.__vellaSetAvitoRepricerState?.({ forceRefresh: false, lastRefreshAt: refreshedAt })
      })
      .catch((error) => {
        if (controller.signal.aborted) return
        console.warn('Failed to load Avito repricer', error)
        setAvitoRepricerLiveState({ loading: false, error: error instanceof Error ? error.message : 'Не удалось загрузить репрайсер Авито', data: null })
      })
    return () => controller.abort()
  }, [accessToken, isRoute, state.dateFrom, state.dateTo, state.forceRefresh, state.requestSeq])

  useEffect(() => {
    if (!isRoute || !accessToken) return
    const elapsedMs = Date.now() - state.lastRefreshAt
    const delayMs = Math.max(1000, AVITO_REPRICER_AUTO_REFRESH_MS - elapsedMs)
    const timer = window.setTimeout(() => {
      const current = window.__vellaAvitoRepricerState ?? defaultAvitoRepricerState()
      window.__vellaSetAvitoRepricerState?.({
        forceRefresh: true,
        requestSeq: (current.requestSeq ?? 0) + 1,
      })
    }, delayMs)
    return () => window.clearTimeout(timer)
  }, [accessToken, isRoute, state.lastRefreshAt])

  const saveRowStrategy = async (row: AvitoRepricerBackendRow, strategyId: string) => {
    if (!accessToken || savingStrategyItemId || strategyId === row.strategyId) {
      setOpenStrategyItemId(null)
      return
    }
    const fallbackStrategy = strategies.find((strategy) => strategy.id === strategyId)
    if (!fallbackStrategy) return
    setSavingStrategyItemId(row.itemId)
    try {
      const result = await saveLiveAvitoRepricerItemStrategy(accessToken, row.itemId, strategyId)
      const savedStrategy = result?.strategy ?? fallbackStrategy
      const currentLive = window.__vellaAvitoRepricerLiveState ?? live
      const currentData = currentLive.data
      if (currentData) {
        setAvitoRepricerLiveState({
          ...currentLive,
          loading: false,
          error: null,
          data: {
            ...currentData,
            rows: currentData.rows.map((item) => item.itemId === row.itemId ? {
              ...item,
              strategyId: savedStrategy.id,
              strategyName: savedStrategy.name,
              strategyDescription: savedStrategy.description,
            } : item),
            strategyAssignments: {
              ...(currentData.strategyAssignments ?? {}),
              [row.itemId]: savedStrategy.id,
            },
          },
        })
      }
      setOpenStrategyItemId(null)
      window.showToast?.(`Стратегия «${savedStrategy.name}» сохранена`, 'success')
    } catch (error) {
      console.warn('Failed to save Avito repricer strategy', error)
      setAvitoRepricerLiveState({ ...live, error: error instanceof Error ? error.message : 'Не удалось сохранить стратегию' })
    } finally {
      setSavingStrategyItemId(null)
    }
  }

  const openPriceHistory = async (row: AvitoRepricerBackendRow) => {
    setHistoryState({ row, loading: true, error: null, entries: [] })
    if (!accessToken) {
      setHistoryState({ row, loading: false, error: 'Нужна активная сессия', entries: [] })
      return
    }
    try {
      const payload = await loadLiveAvitoRepricerPriceHistory(accessToken, row.itemId)
      setHistoryState({ row, loading: false, error: null, entries: payload?.items ?? [] })
    } catch (error) {
      setHistoryState({ row, loading: false, error: error instanceof Error ? error.message : 'Не удалось загрузить историю цены', entries: [] })
    }
  }

  const rows = avitoRepricerRowsForState(live.data, state)
  const hasAnyRows = Boolean(live.data?.rows.length)
  const strategies = live.data?.strategies ?? []
  return (
    <div key={replacementKey} className="tab-content" id="tab-avito-repricer" data-vella-island="avito-repricer" data-vella-island-status="explicit-jsx">
      <AvitoRepricerKpiStripIsland replacementKey={`${replacementKey}-kpis`} />
      <AvitoRepricerToolbarIsland replacementKey={`${replacementKey}-toolbar`} />
      <AvitoRepricerSettingsPanel accessToken={accessToken} refreshKey={state.requestSeq} />
      <section className="avito-listings-shell">
        <div className="avito-listings-main">
          <div className="table-wrap avito-stats-table">
            <table className="report-mid" style={{ minWidth: 1520 }}>
              <thead>
                <tr>
                  <th>Объявление</th>
                  <th>Стратегия</th>
                  <th className="num">Цена</th>
                  <th className="num">Новая цена</th>
                  <th>Решение</th>
                  <th className="num">Написали</th>
                  <th className="num">Контакты</th>
                  <th className="num">Просмотры</th>
                  <th className="num">CR чата</th>
                  <th>Аккаунт</th>
                  <th>Основание</th>
                  <th>История</th>
                </tr>
              </thead>
              <tbody>
                {rows.length ? rows.map((row) => (
                  <tr key={row.itemId}>
                    <td>
                      <div className="avito-item-cell">
                        {row.imageUrl ? <img className="avito-row-photo" src={row.imageUrl} alt="" loading="lazy" /> : <div className="avito-row-photo avito-row-photo-empty">AV</div>}
                        <div className="avito-title-cell">
                          <b>{row.title}</b>
                          <span className="sub">ID: {row.itemId} · {row.category ?? 'без категории'}</span>
                        </div>
                      </div>
                    </td>
                    <td>
                      <div className={openStrategyItemId === row.itemId ? 'avito-strategy-picker open' : 'avito-strategy-picker'}>
                        <button className="avito-strategy-trigger" type="button" disabled={savingStrategyItemId === row.itemId} onClick={() => setOpenStrategyItemId(openStrategyItemId === row.itemId ? null : row.itemId)} aria-expanded={openStrategyItemId === row.itemId}>
                          <span className={row.strategyId === 'none' ? 'avito-strategy-dot muted' : 'avito-strategy-dot'} />
                          <b>{savingStrategyItemId === row.itemId ? 'Сохраняем...' : row.strategyName}</b>
                          <span>⌄</span>
                        </button>
                        {openStrategyItemId === row.itemId ? (
                          <div className="avito-strategy-menu">
                            {strategies.map((strategy) => (
                              <button className={strategy.id === row.strategyId ? 'avito-strategy-option active' : 'avito-strategy-option'} type="button" disabled={Boolean(savingStrategyItemId)} key={strategy.id} onClick={() => void saveRowStrategy(row, strategy.id)}>
                                <b>{strategy.name}</b>
                                <span>{strategy.description}</span>
                              </button>
                            ))}
                          </div>
                        ) : null}
                      </div>
                      <span className="sub">{row.strategyDescription ?? 'метрика чатов'}</span>
                    </td>
                    <td className="num">{formatAvitoRubNullable(row.priceKopecks)}</td>
                    <td className="num"><div className="avito-price-stack"><b>{formatAvitoRubNullable(row.recommendedPriceKopecks)}</b><span>{row.priceDeltaPct === 0 ? 'без изменения' : `${row.priceDeltaPct > 0 ? '+' : ''}${row.priceDeltaPct}% по стратегии`}</span></div></td>
                    <td><span className={avitoRepricerSignalClass(row.strategySignal)}>{avitoRepricerSignalLabel(row.strategySignal)}</span></td>
                    <td className="num"><b>{formatAvitoMetric(row.contactsMessenger)}</b></td>
                    <td className="num">{formatAvitoMetric(row.contacts)}</td>
                    <td className="num">{formatAvitoMetric(row.views)}</td>
                    <td className="num">{formatAvitoPctNullable(row.messengerConversionPct)}</td>
                    <td><span className="avito-account-badge">{row.accountName}</span></td>
                    <td>{row.reason}</td>
                    <td><button className="btn btn-default btn-sm" type="button" onClick={() => void openPriceHistory(row)}>Посмотреть</button></td>
                  </tr>
                )) : (
                  <tr>
                    <td colSpan={12}>
                      {live.loading ? (
                        <AvitoDataState kind="loading" title="Считаем рекомендации" subtitle="Загружаем объявления, цены и сообщения за выбранный период." />
                      ) : live.error ? (
                        <AvitoDataState kind="error" title="Репрайсер Авито ждёт источник" subtitle={live.error} />
                      ) : hasAnyRows ? (
                        <AvitoDataState kind="empty" title="Нет результатов по выбранному фильтру" subtitle="Попробуйте изменить поиск или переключить решение." />
                      ) : (
                        <AvitoDataState kind="empty" title="Нет данных за выбранный период" subtitle={avitoBackendErrorMessage(live.data) || 'За этот период нет объявлений с метриками для пересчёта цены.'} />
                      )}
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </div>
      </section>
      {historyState ? <AvitoRepricerPriceHistoryModal state={historyState} onClose={() => setHistoryState(null)} /> : null}
    </div>
  )
}

async function loadLiveAvitoStats(
  accessToken: string,
  period: { dateFrom: string; dateTo: string; forceRefresh?: boolean },
  signal?: AbortSignal,
) {
  const params = new URLSearchParams({
    dateFrom: period.dateFrom,
    dateTo: period.dateTo,
  })
  if (period.forceRefresh) params.set('forceRefresh', 'true')
  return apiRequest<AvitoStatsBackendResponse>(`/api/v1/avito/stats?${params.toString()}`, {
    headers: authorizationHeaders(accessToken),
    signal,
  })
}

async function loadLiveAvitoOverview(
  accessToken: string,
  period: { dateFrom: string; dateTo: string; forceRefresh?: boolean },
  signal?: AbortSignal,
) {
  const params = new URLSearchParams({
    dateFrom: period.dateFrom,
    dateTo: period.dateTo,
  })
  if (period.forceRefresh) params.set('forceRefresh', 'true')
  return apiRequest<AvitoOverviewBackendResponse>(`/api/v1/avito/overview?${params.toString()}`, {
    headers: authorizationHeaders(accessToken),
    signal,
  })
}

async function loadLiveAvitoChats(
  accessToken: string,
  options: { limit: number; offset: number; accountId?: string; unreadOnly?: boolean; forceRefresh?: boolean },
  signal?: AbortSignal,
) {
  const params = new URLSearchParams({
    limit: String(Math.max(1, Math.min(99, options.limit || 50))),
    offset: String(Math.max(0, options.offset || 0)),
  })
  if (options.unreadOnly) params.set('unreadOnly', 'true')
  if (options.forceRefresh) params.set('forceRefresh', 'true')
  if (options.accountId && options.accountId !== 'all') params.append('accountId', options.accountId)
  return apiRequest<AvitoChatsBackendResponse>(`/api/v1/avito/chats?${params.toString()}`, {
    headers: authorizationHeaders(accessToken),
    signal,
  })
}

async function loadLiveAvitoOrders(
  accessToken: string,
  options: { dateFrom: string; periodDays?: number; status: AvitoOrdersStatus; limit: number; page: number; forceRefresh?: boolean },
  signal?: AbortSignal,
) {
  const safePeriodDays = Math.max(1, Math.min(183, Math.round(options.periodDays || 30)))
  const safeDateFrom = clampDateFromNotFuture(options.dateFrom, toLocalIsoDate(addLocalDays(new Date(), -(safePeriodDays - 1))))
  const params = new URLSearchParams({
    dateFrom: safeDateFrom,
    periodDays: String(safePeriodDays),
    limit: String(Math.max(1, Math.min(20, options.limit || 20))),
    page: String(Math.max(1, options.page || 1)),
  })
  if (options.status && options.status !== 'all') params.append('status', options.status)
  if (options.forceRefresh) params.set('forceRefresh', 'true')
  return apiRequest<AvitoOrdersBackendResponse>(`/api/v1/avito/orders?${params.toString()}`, {
    headers: authorizationHeaders(accessToken),
    signal,
    cache: 'no-store',
  })
}

function buildAvitoOrdersSummary(rows: AvitoOrderRow[], total: number): AvitoOrdersBackendResponse['summary'] {
  const statusCounts = rows.reduce<Record<string, number>>((acc, row) => {
    acc[row.status] = (acc[row.status] ?? 0) + 1
    return acc
  }, {})
  const totalKopecksValues = rows.map((row) => row.totalKopecks).filter((value): value is number => value != null)
  return {
    total: total || rows.length,
    shown: rows.length,
    confirmation: statusCounts.on_confirmation ?? 0,
    readyToShip: statusCounts.ready_to_ship ?? 0,
    inTransit: statusCounts.in_transit ?? 0,
    delivered: statusCounts.delivered ?? 0,
    closed: statusCounts.closed ?? 0,
    canceled: statusCounts.canceled ?? 0,
    returns: rows.filter((row) => row.status === 'on_return' || Boolean(row.returnStatus)).length,
    disputes: statusCounts.in_dispute ?? 0,
    requiredActions: rows.filter((row) => row.availableActions.some((action) => action.required)).length,
    items: rows.reduce((sum, row) => sum + row.items.reduce((itemSum, item) => itemSum + item.quantity, 0), 0),
    totalKopecks: totalKopecksValues.length ? totalKopecksValues.reduce((sum, value) => sum + value, 0) : null,
    statusCounts,
  }
}

async function loadAllLiveAvitoOrders(
  accessToken: string,
  options: { dateFrom: string; periodDays?: number; status: AvitoOrdersStatus; forceRefresh?: boolean },
  signal?: AbortSignal,
): Promise<AvitoOrdersBackendResponse | null> {
  const first = await loadLiveAvitoOrders(accessToken, { ...options, limit: AVITO_ORDERS_PAGE_LIMIT, page: 1 }, signal)
  if (!first || first.status === 'blocked') return first
  const rowsById = new Map<string, AvitoOrderRow>()
  first.rows.forEach((row) => rowsById.set(row.orderId, row))

  for (let page = 2; page <= AVITO_ORDERS_MAX_PAGES && first.rows.length >= AVITO_ORDERS_PAGE_LIMIT; page += 1) {
    if (signal?.aborted) throw new Error('Загрузка заказов Авито отменена')
    const next = await loadLiveAvitoOrders(accessToken, { ...options, limit: AVITO_ORDERS_PAGE_LIMIT, page }, signal)
    if (!next || next.status === 'blocked' || !next.rows.length) break
    const previousCount = rowsById.size
    next.rows.forEach((row) => rowsById.set(row.orderId, row))
    if (rowsById.size === previousCount) break
    if (next.rows.length < AVITO_ORDERS_PAGE_LIMIT) break
  }

  const rows = Array.from(rowsById.values())
  const total = Math.max(first.summary?.total ?? 0, rows.length)
  return {
    ...first,
    filters: { ...first.filters, page: 1, limit: AVITO_ORDERS_PAGE_LIMIT },
    summary: buildAvitoOrdersSummary(rows, total),
    rows,
    source: {
      ...first.source,
      pagination: {
        pageLimit: AVITO_ORDERS_PAGE_LIMIT,
        pagesLoaded: Math.max(1, Math.ceil(rows.length / AVITO_ORDERS_PAGE_LIMIT)),
        total,
      },
    },
  }
}

