function defaultAvitoStatsState(): AvitoStatsState {
  const period = defaultAvitoStatsPeriod()
  return {
    filter: 'all',
    query: '',
    category: 'all',
    mode: 'traffic',
    selectedKey: '',
    dateFrom: period.from,
    dateTo: period.to,
    dateFromDraft: period.from,
    dateToDraft: period.to,
    requestSeq: 0,
    forceRefresh: false,
  }
}

function useAvitoStatsState() {
  const [state, setState] = useState<AvitoStatsState>(() => ({ ...defaultAvitoStatsState(), ...(window.__vellaAvitoStatsState ?? {}) }))
  useEffect(() => {
    const render = () => setState({ ...defaultAvitoStatsState(), ...(window.__vellaAvitoStatsState ?? {}) })
    window.__vellaReactRenderAvitoStats = render
    window.addEventListener('vella:avito-stats-updated', render)
    render()
    return () => {
      if (window.__vellaReactRenderAvitoStats === render) delete window.__vellaReactRenderAvitoStats
      window.removeEventListener('vella:avito-stats-updated', render)
    }
  }, [])
  return state
}

function avitoStatsRowMatches(row: AvitoStatsTableRow, state: AvitoStatsState) {
  const query = state.query.trim().toLocaleLowerCase('ru-RU')
  if (state.filter.startsWith('account:') && row.account !== state.filter.slice('account:'.length)) return false
  if (!state.filter.startsWith('account:') && row.kind !== 'account') return false
  if (state.category !== 'all' && !row.category.split(' ').includes(state.category)) return false
  if (query && !row.search.toLocaleLowerCase('ru-RU').includes(query)) return false
  return true
}

