function AvitoStatsIsland({
  replacementKey,
  sourceElement,
}: {
  replacementKey: string
  sourceElement?: HTMLElement | SVGElement
}) {
  const location = useLocation()
  const { accessToken } = useAuth()
  const state = useAvitoStatsState()
  const isAvitoStatsRoute = resolveParityRouteTarget(location.pathname, location.search).tab === 'avito-stats'

  useEffect(() => {
    if (!isAvitoStatsRoute) return
    if (!accessToken) {
      setAvitoStatsLiveState({ loading: false, error: 'Нужна активная сессия', data: null })
      return
    }

    const controller = new AbortController()
    setAvitoStatsLiveState({ loading: true, error: null, data: window.__vellaAvitoStatsLiveState?.data ?? null })
    void loadLiveAvitoStats(
      accessToken,
      { dateFrom: state.dateFrom, dateTo: state.dateTo, forceRefresh: state.forceRefresh },
      controller.signal,
    )
      .then((data) => {
        if (controller.signal.aborted) return
        if (!data) throw new Error('Пустой ответ статистики Авито')
        setAvitoStatsLiveState({ loading: false, error: null, data })
        if (state.forceRefresh) window.__vellaSetAvitoStatsState?.({ forceRefresh: false })
      })
      .catch((error) => {
        if (controller.signal.aborted) return
        console.warn('Failed to load Avito stats', error)
        setAvitoStatsLiveState({
          loading: false,
          error: error instanceof Error ? error.message : 'Не удалось загрузить статистику Авито',
          data: null,
        })
      })
    return () => controller.abort()
  }, [accessToken, isAvitoStatsRoute, state.dateFrom, state.dateTo, state.forceRefresh, state.requestSeq])

  return (
    <div
      key={replacementKey}
      className="tab-content"
      id="tab-avito-stats"
      data-vella-island="avito-stats"
      data-vella-island-status="explicit-jsx"
    >
      <AvitoStatsKpiStripIsland replacementKey={`${replacementKey}-kpis`} />
      <AvitoStatsToolbarIsland replacementKey={`${replacementKey}-toolbar`} />
      <AvitoStatsShellIsland replacementKey={replacementKey} sourceElement={sourceElement} />
    </div>
  )
}

