const EMPTY_NOTIFICATIONS_SNAPSHOT: NotificationsSnapshot = {
  rows: [],
  bodyCount: 0,
  detail: null,
  workspace: {
    active: false,
    mode: 'events',
    modeTitle: 'Уведомления Авито',
    summary: '',
    rulesRows: [],
    recipientRows: [],
    channelRows: [],
    historyRows: [],
  },
  workspaceClassName: 'avito-notif-workspace',
}

function useNotificationsSnapshot() {
  const [snapshot, setSnapshot] = useState<NotificationsSnapshot>(() => EMPTY_NOTIFICATIONS_SNAPSHOT)

  useEffect(() => {
    const refresh = () => setSnapshot(window.__vellaNotificationsSnapshot?.() ?? EMPTY_NOTIFICATIONS_SNAPSHOT)
    window.__vellaReactRenderNotifications = refresh
    window.addEventListener('vella:notifications-updated', refresh)
    refresh()
    const timers = [0, 250, 750].map((delay) => window.setTimeout(refresh, delay))
    return () => {
      for (const timer of timers) window.clearTimeout(timer)
      window.removeEventListener('vella:notifications-updated', refresh)
      if (window.__vellaReactRenderNotifications === refresh) delete window.__vellaReactRenderNotifications
    }
  }, [])

  useEffect(() => {
    window.initTooltips?.()
    installTooltipUxGuard(document)
  }, [snapshot])

  return snapshot
}

