function settingsImportModeLabel(mode: SettingsImportMode) {
  return mode === 'replace' ? 'замена' : 'прибавление'
}

function settingsImportPreviewValue(row: Record<string, unknown>, keys: string[]) {
  for (const key of keys) {
    const value = row[key]
    if (value !== undefined && value !== null && String(value).trim() !== '') return String(value)
  }
  return '—'
}

function SettingsImportResult({ result }: { result: SettingsExcelImportResult | null }) {
  if (!result) return null
  const unmatchedPreview = (result.unmatched ?? []).slice(0, 4)
  const importedDate = result.importedAt ? new Date(result.importedAt).toLocaleString('ru-RU') : 'только что'

  return (
    <div className="settings-import-result">
      <div className="settings-import-result-head">
        <div>
          <b>{result.filename}</b>
          <span>{settingsImportModeLabel(result.mode)} · {importedDate}</span>
        </div>
        <span className={`report-tag ${result.unmatchedCount > 0 ? 'warn' : 'ok'}`}>
          {result.unmatchedCount > 0 ? 'частично' : 'готово'}
        </span>
      </div>
      <div className="settings-import-stat-grid">
        <div><span>Строк</span><b>{result.rowsTotal}</b></div>
        <div><span>Распознано</span><b>{result.rowsParsed}</b></div>
        <div><span>Применено</span><b>{result.appliedCount}</b></div>
        <div><span>Не найдено</span><b className={result.unmatchedCount > 0 ? 'warn' : ''}>{result.unmatchedCount}</b></div>
      </div>
      {unmatchedPreview.length > 0 && (
        <div className="settings-import-unmatched">
          <div className="s-label">Первые несопоставленные строки</div>
          <div className="settings-import-table-wrap">
            <table>
              <thead>
                <tr>
                  <th>NmId / ID</th>
                  <th>Артикул продавца</th>
                  <th>Значение</th>
                </tr>
              </thead>
              <tbody>
                {unmatchedPreview.map((row, index) => (
                  <tr key={index}>
                    <td>{settingsImportPreviewValue(row, ['nmId', 'articleId', 'article'])}</td>
                    <td>{settingsImportPreviewValue(row, ['vendorCode', 'supplierArticle', 'sku'])}</td>
                    <td>{settingsImportPreviewValue(row, ['cogsKopecks', 'wbStockUnits', 'stock', 'value'])}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
          <div className="report-empty-note visible">Обновите список товаров WB, если часть строк не сопоставилась с SKU-кэшем.</div>
        </div>
      )}
    </div>
  )
}

function SettingsImportCard({
  title,
  description,
  endpoint,
  sourceHint,
  details,
  tone,
}: {
  title: string
  description: string
  endpoint: string
  sourceHint: string
  details: Array<[string, string]>
  tone: 'costs' | 'stocks'
}) {
  const { accessToken } = useAuth()
  const [mode, setMode] = useState<SettingsImportMode>('replace')
  const [file, setFile] = useState<File | null>(null)
  const [result, setResult] = useState<SettingsExcelImportResult | null>(null)
  const [error, setError] = useState<string | null>(null)
  const [loading, setLoading] = useState(false)

  async function uploadFile() {
    if (!file || loading) return
    if (!accessToken) {
      setError('Нужна активная сессия. Войдите заново и повторите импорт.')
      return
    }
    setLoading(true)
    setError(null)
    try {
      const body = new FormData()
      body.append('file', file)
      const payload = await apiRequest<SettingsExcelImportResult>(`${endpoint}?mode=${mode}`, {
        method: 'POST',
        headers: authorizationHeaders(accessToken),
        body,
        cache: 'no-store',
      })
      setResult(payload)
      window.showToast?.(`Импорт ${title.toLowerCase()} применён`, 'success')
    } catch (err) {
      setError(err instanceof ApiError ? err.message : 'Не удалось загрузить XLSX')
    } finally {
      setLoading(false)
    }
  }

  return (
    <section className="settings-card settings-import-card">
      <div className="settings-import-card-head">
        <div className={`settings-import-icon ${tone}`}>
          <FileSpreadsheet size={16} />
        </div>
        <div>
          <div className="card-title" style={{ marginBottom: 4 }}>{title} <span className="card-title-help">XLSX</span></div>
          <div className="s-desc">{description}</div>
        </div>
      </div>

      <label className={`upload-zone settings-import-upload ${file ? 'has-file' : ''}`}>
        <input
          type="file"
          accept=".xlsx,.xls"
          hidden
          onChange={(event) => {
            setFile(event.currentTarget.files?.[0] ?? null)
            setResult(null)
            setError(null)
          }}
        />
        <div className="upload-zone-icon"><Upload size={18} /></div>
        <div className="upload-zone-title">{file ? file.name : 'Выбрать XLSX-файл'}</div>
        <div className="upload-zone-sub">{file ? `${Math.max(1, Math.round(file.size / 1024)).toLocaleString('ru-RU')} КБ` : sourceHint}</div>
      </label>

      <div className="s-row">
        <div>
          <div className="s-label">Режим применения</div>
          <div className="s-desc">Можно полностью заменить данные или прибавить значения к текущим.</div>
        </div>
        <div className="seg-ctl">
          <button className={`seg-btn ${mode === 'replace' ? 'active' : ''}`} type="button" onClick={() => setMode('replace')}>Заменить</button>
          <button className={`seg-btn ${mode === 'add' ? 'active' : ''}`} type="button" onClick={() => setMode('add')}>Прибавить</button>
        </div>
      </div>

      <div className="settings-import-mode-grid">
        {details.map(([label, value]) => (
          <div key={label}>
            <span>{label}</span>
            <b>{value}</b>
          </div>
        ))}
      </div>

      <div className="settings-import-actions">
        <button className="btn btn-primary btn-sm" type="button" disabled={!file || loading} onClick={() => void uploadFile()}>
          <Upload size={14} />
          {loading ? 'Загружаю...' : 'Загрузить'}
        </button>
        {file ? <button className="btn btn-default btn-sm" type="button" onClick={() => { setFile(null); setResult(null); setError(null) }}>Очистить</button> : null}
      </div>

      {error ? (
        <div className="report-empty-note visible settings-import-error">
          <AlertTriangle size={14} />
          <span>{error}</span>
        </div>
      ) : null}
      <SettingsImportResult result={result} />
    </section>
  )
}

