  const cogsValue = kpi.revenueAvailable ? `${formatProductsInteger(kpi.cogsRub)} ₽` : '—'
  const expensesValue = kpi.revenueAvailable ? `${formatProductsInteger(kpi.expensesRub)} ₽` : '—'
