function removeLegacySavedViewButtons() {
  document
    .querySelectorAll<HTMLElement>('#savedViewsList .saved-view-btn[onclick]')
    .forEach((button) => button.remove())
}

function ProductsSavedViewsPanelIsland() {
  useEffect(() => {
    window.__vellaReactRenderSavedViews = () => {
      removeLegacySavedViewButtons()
      window.setTimeout(removeLegacySavedViewButtons, 0)
    }
    window.__vellaReactRenderSavedViews()
    return () => {
      if (window.__vellaReactRenderSavedViews) delete window.__vellaReactRenderSavedViews
    }
  }, [])

  useEffect(removeLegacySavedViewButtons)

  return null
}

function readVellaStrategiesSnapshot() {
  const backend = window.__vellaBackendStrategiesSnapshot?.() ?? []
  if (backend.length) return backend
  return window.__vellaStrategiesSnapshot?.() ?? []
}

function useVellaStrategiesSnapshot() {
  const [strategies, setStrategies] = useState<VellaStrategySnapshotItem[]>(() => readVellaStrategiesSnapshot())

  useEffect(() => {
    const refresh = () => setStrategies(readVellaStrategiesSnapshot())
    window.__vellaReactRenderStrategies = refresh
    window.addEventListener('vella:strategies-updated', refresh)
    refresh()
    const timers = [0, 250, 750].map((delay) => window.setTimeout(refresh, delay))
    return () => {
      for (const timer of timers) window.clearTimeout(timer)
      window.removeEventListener('vella:strategies-updated', refresh)
      if (window.__vellaReactRenderStrategies === refresh) delete window.__vellaReactRenderStrategies
    }
  }, [])

  useEffect(() => {
    window.initTooltips?.()
  }, [strategies])

  return strategies
}

