function ProductsPaginationIsland() {
  const [tick, setTick] = useState(0)
  useEffect(() => {
    const render = () => setTick((value) => value + 1)
    window.addEventListener('vella:products-pagination-updated', render)
    window.addEventListener('vella:products-rows-updated', render)
    render()
    return () => {
      window.removeEventListener('vella:products-pagination-updated', render)
      window.removeEventListener('vella:products-rows-updated', render)
    }
  }, [])
  void tick
  const cache = window.__vellaProductsCacheMeta
  const state = window.__vellaProductsListState ?? { page: 1, pageSize: PRODUCTS_TABLE_RENDER_LIMIT }
  const visibleRows = visibleProductsRowCount()
  const page = Math.max(1, Number(state.page ?? 1))
  const pageSize = Math.max(25, Number(state.pageSize ?? cache?.listItemsLimit ?? PRODUCTS_TABLE_RENDER_LIMIT))
  const rawTotal = Number(cache?.listTotalFiltered ?? cache?.totalCached ?? visibleRows)
  const total = Number.isFinite(rawTotal) && rawTotal > 0 ? rawTotal : visibleRows
  const totalPages = Math.max(1, Math.ceil(total / pageSize))
  const start = total && visibleRows ? (page - 1) * pageSize + 1 : 0
  const end = total && visibleRows ? Math.min(total, start + visibleRows - 1) : 0
  const goPage = (nextPage: number) => {
    window.__vellaProductsListState = { ...state, page: Math.max(1, Math.min(totalPages, nextPage)), pageSize }
    window.__vellaLoadLiveRepricerProducts?.()
  }
  const setPageSize = (nextSize: number) => {
    window.__vellaProductsListState = { ...state, page: 1, pageSize: nextSize }
    window.__vellaLoadLiveRepricerProducts?.()
  }

  return (
    <div className="pagination" data-vella-island="products-pagination" data-vella-island-status="explicit-jsx">
      <span className="page-info">Показано <b>{start}–{end}</b> из <b>{total}</b></span>
      <div className="spacer" />
      <span style={{ fontSize: 12, color: 'var(--gray-500)' }}>Строк на странице:</span>
      <select className="per-page-sel" value={pageSize} data-vella-react-handlers="onchange" onChange={(event) => setPageSize(Number(event.currentTarget.value))}>
        <option value={50}>50</option>
        <option value={100}>100</option>
        <option value={150}>150</option>
        <option value={300}>300</option>
        <option value={500}>500</option>
      </select>
      <div className="page-jump">
        <button className="page-btn" type="button" disabled={page <= 1} data-vella-react-handlers="onclick" onClick={() => goPage(page - 1)}>‹</button>
        <button className="page-btn active" type="button">{page}</button>
        <span style={{ color: 'var(--gray-400)' }}>из {totalPages}</span>
        <button className="page-btn" type="button" disabled={page >= totalPages} data-vella-react-handlers="onclick" onClick={() => goPage(page + 1)}>›</button>
      </div>
    </div>
  )
}

function ProductsToolbarRowCountIsland() {
  const [tick, setTick] = useState(0)
  useEffect(() => {
    const render = () => setTick((value) => value + 1)
    window.addEventListener('vella:products-pagination-updated', render)
    window.addEventListener('vella:products-rows-updated', render)
    render()
    return () => {
      window.removeEventListener('vella:products-pagination-updated', render)
      window.removeEventListener('vella:products-rows-updated', render)
    }
  }, [])
  void tick
  const cache = window.__vellaProductsCacheMeta
  const state = window.__vellaProductsListState ?? { page: 1, pageSize: PRODUCTS_TABLE_RENDER_LIMIT }
  const visibleRows = visibleProductsRowCount()
  const page = Math.max(1, Number(state.page ?? cache?.listPage ?? 1))
  const pageSize = Math.max(1, Number(state.pageSize ?? cache?.listItemsLimit ?? (visibleRows || PRODUCTS_TABLE_RENDER_LIMIT)))
  const rawTotal = Number(cache?.listTotalFiltered ?? cache?.totalCached ?? visibleRows)
  const total = Number.isFinite(rawTotal) && rawTotal > 0 ? rawTotal : visibleRows
  const start = total && visibleRows ? (page - 1) * pageSize + 1 : 0
  const end = total && visibleRows ? Math.min(total, start + visibleRows - 1) : 0
  const shownLabel = start && end && start !== end ? `${start}-${end}` : String(visibleRows)

  return (
    <div
      className="row-count"
      data-vella-island="products-toolbar-row-count"
      data-vella-island-status="explicit-jsx"
    >
      Показано <b id="visibleCount">{shownLabel}</b> из <b id="totalCount">{total}</b>
    </div>
  )
}

function productsProblemCount() {
  return productsForKpi().filter((product) => (
    productNumber(product, 'pmin') <= 0
    || productNumber(product, 'mg') < 0
    || productNumber(product, 'mgRub') < 0
    || productNumber(product, 'stock') <= 20
    || ['illiquid', 'liq'].includes(String(product.status ?? ''))
  )).length
}

function productProblemReasons(product: Record<string, unknown>) {
  const reasons: string[] = []
  if (productNumber(product, 'pmin') <= 0) reasons.push('нет минимальной цены')
  if (productNumber(product, 'mg') < 0 || productNumber(product, 'mgRub') < 0) reasons.push('маржа ниже нуля')
  if (productNumber(product, 'stock') <= 20) reasons.push('низкий остаток')
  const status = String(product.status ?? '')
  if (status === 'illiquid') reasons.push('товар залеживается')
  if (status === 'liq') reasons.push('ликвидация')
  return reasons
}

function productsProblemRows() {
  return productsForKpi()
    .map((product) => ({ product, reasons: productProblemReasons(product) }))
    .filter((row) => row.reasons.length > 0)
    .sort((left, right) => right.reasons.length - left.reasons.length)
}

function productDisplayText(product: Record<string, unknown>, keys: string[], fallback = 'Товар') {
  for (const key of keys) {
    const value = String(product[key] ?? '').trim()
    if (value) return value
  }
  return fallback
}

function ProductsCountValue({ value }: { value: number }) {
  if (window.__vellaProductsLoading) return <ProductsInlineLoader />
  return <>{formatProductsInteger(value)}</>
}

function productsStatusCount(status: string, total: number) {
  if (status === 'all') return total
  const products = productsForKpi()
  return products.filter((product) => {
    if (status === 'nopmin') return productNumber(product, 'pmin') <= 0
    return String(product.status ?? '') === status
  }).length
}

function productsBrandCount(brand: string, total: number) {
  if (brand === 'all') return total
  const normalizedBrand = brand.toLocaleLowerCase('ru-RU')
  return productsForKpi().filter((product) => String(product.brand ?? '').toLocaleLowerCase('ru-RU') === normalizedBrand).length
}

function productsPromoCount(promo: string, total: number) {
  if (promo === 'all') return total
  const expected = promo === 'yes'
  return productsForKpi().filter((product) => Boolean(product.promoActive) === expected).length
}

function productsBrandLabel(brand: string) {
  return brand
    .split(/[\s_-]+/)
    .filter(Boolean)
    .map((part) => part.charAt(0).toLocaleUpperCase('ru-RU') + part.slice(1))
    .join(' ')
}

function productsBrandClassName(brand: string) {
  return /^[a-z0-9_-]+$/i.test(brand) ? `brand-chip ${brand}` : 'brand-chip'
}

function productsAvailableBrands() {
  const brands = productsForKpi()
    .map((product) => String(product.brand ?? '').trim().toLocaleLowerCase('ru-RU'))
    .filter((brand) => brand && brand !== 'all')
  const uniqueBrands = Array.from(new Set(brands)).sort((left, right) => left.localeCompare(right, 'ru'))
  return uniqueBrands
}

function scrollToProductsAdvancedFilters() {
  const target = document.getElementById('advBar') || document.querySelector<HTMLElement>('[data-vella-island="products-advanced-filters"]')
  if (!target) return
  target.scrollIntoView({ behavior: 'smooth', block: 'nearest' })
  target.classList.add('products-advanced-flash')
  window.setTimeout(() => target.classList.remove('products-advanced-flash'), 1100)
}

function toggleProductsAdvancedFilters() {
  window.dispatchEvent(new CustomEvent('vella:products-filters-toggle'))
  window.setTimeout(scrollToProductsAdvancedFilters, 80)
}

function productsLegacyAdvancedFiltersHtml(sourceElement?: HTMLElement) {
  if (!sourceElement) return ''
  const clone = sourceElement.cloneNode(true) as HTMLElement
  clone.querySelector<HTMLElement>('.adv-actions')?.remove()
  return clone.querySelector<HTMLElement>('.adv-grid')?.outerHTML ?? ''
}

function applyProductsAdvancedFilters() {
  window.applyAdvanced?.()
}

function resetProductsAdvancedFilters() {
  window.resetAdvancedFilters?.()
}

