function ProductsStickyPaginationPanel() {
  const [tick, setTick] = useState(0)
  useEffect(() => {
    const render = () => setTick((value) => value + 1)
    const renderAfterNavigation = () => window.setTimeout(render, 0)
    window.addEventListener('vella:products-pagination-updated', render)
    window.addEventListener('vella:products-rows-updated', render)
    window.addEventListener('vella:products-loading-updated', render)
    document.addEventListener('click', renderAfterNavigation, true)
    render()
    return () => {
      window.removeEventListener('vella:products-pagination-updated', render)
      window.removeEventListener('vella:products-rows-updated', render)
      window.removeEventListener('vella:products-loading-updated', render)
      document.removeEventListener('click', renderAfterNavigation, true)
    }
  }, [])
  void tick

  const productsTab = document.getElementById('tab-products')
  if (productsTab && !productsTab.classList.contains('active')) return null

  const cache = window.__vellaProductsCacheMeta
  const state = window.__vellaProductsListState ?? { page: 1, pageSize: PRODUCTS_TABLE_RENDER_LIMIT, topMode: true }
  const visibleRows = visibleProductsRowCount()
  const page = Math.max(1, Number(state.page ?? cache?.listPage ?? 1))
  const pageSize = Math.max(25, Number(state.pageSize ?? cache?.listItemsLimit ?? PRODUCTS_TABLE_RENDER_LIMIT))
  const topMode = state.topMode !== false
  const loading = Boolean(window.__vellaProductsLoading)
  const rawTotal = Number(cache?.listTotalFiltered ?? cache?.totalCached ?? visibleRows)
  const total = Number.isFinite(rawTotal) && rawTotal > 0 ? rawTotal : visibleRows
  const totalPages = Math.max(1, Math.ceil(total / pageSize))
  const start = total && visibleRows ? (page - 1) * pageSize + 1 : 0
  const end = total && visibleRows ? Math.min(total, start + visibleRows - 1) : 0
  const selectedCount = selectedRepricerArticleIds().length
  const loadPage = (nextPage: number, nextTopMode = topMode, nextPageSize = pageSize) => {
    window.__vellaProductsListState = {
      ...state,
      page: Math.max(1, Math.min(Math.max(1, Math.ceil(total / nextPageSize)), nextPage)),
      pageSize: nextPageSize,
      topMode: nextTopMode,
    }
    resetLiveRepricerParityCache()
    window.__vellaLoadLiveRepricerProducts?.()
  }

  return (
    <div className="vella-products-sticky-pagination" data-vella-island="products-sticky-pagination" data-vella-island-status="explicit-jsx">
      <div className="vella-products-sticky-pagination__meta">
        <b>{loading ? 'Загрузка...' : `Страница ${page} из ${totalPages}`}</b>
        <span>{start && end ? `${start}-${end}` : '0'} из {total} SKU</span>
      </div>
      <button
        className="btn btn-default btn-sm vella-products-add-group-btn"
        type="button"
        disabled={loading}
        data-vella-react-handlers="onclick"
        data-tip={selectedCount ? `Добавить выбранные SKU в группу: ${selectedCount}` : 'Сначала отметьте SKU галочкой в таблице'}
        onClick={() => window.__vellaOpenSkuGroupModal?.(selectedRepricerArticleIds())}
      >
        <FolderPlus size={13} />В группу{selectedCount ? ` · ${selectedCount}` : ''}
      </button>
      <div className="vella-products-sticky-pagination__controls">
        <button className="page-btn" type="button" disabled={loading || page <= 1} data-vella-react-handlers="onclick" onClick={() => loadPage(1)}>«</button>
        <button className="page-btn" type="button" disabled={loading || page <= 1} data-vella-react-handlers="onclick" onClick={() => loadPage(page - 1)}>‹</button>
        <button className="page-btn active" type="button" disabled={loading}>{loading ? <span className="vella-products-loading-spinner small" /> : page}</button>
        <button className="page-btn" type="button" disabled={loading || page >= totalPages} data-vella-react-handlers="onclick" onClick={() => loadPage(page + 1)}>›</button>
        <button className="page-btn" type="button" disabled={loading || page >= totalPages} data-vella-react-handlers="onclick" onClick={() => loadPage(totalPages)}>»</button>
      </div>
      <label className="vella-products-sticky-pagination__size">
        <span>Строк</span>
        <select className="per-page-sel" value={pageSize} disabled={loading} data-vella-react-handlers="onchange" onChange={(event) => loadPage(1, topMode, Number(event.currentTarget.value))}>
          <option value={50}>50</option>
          <option value={100}>100</option>
          <option value={150}>150</option>
          <option value={300}>300</option>
          <option value={500}>500</option>
        </select>
      </label>
      <button
        className={`vella-products-top-toggle ${topMode ? 'active' : ''}`}
        type="button"
        disabled={loading}
        data-vella-react-handlers="onclick"
        onClick={() => loadPage(1, !topMode, pageSize)}
      >
        ТОП {topMode ? 'вкл' : 'выкл'}
      </button>
    </div>
  )
}

