function annotateAlgoSetting(root: HTMLElement, selector: string, setting: string) {
  root.querySelector<HTMLElement>(selector)?.setAttribute('data-algo-setting', setting)
}

function clampAlgorithmPriceStepPct(value: unknown) {
  const numeric = Number(value)
  if (!Number.isFinite(numeric)) return 0
  return Math.max(0, Math.min(ALGORITHM_PRICE_STEP_MAX_PCT, Number(numeric.toFixed(1))))
}

function configureAlgorithmPriceStepInput(cards: HTMLElement) {
  const input = cards.querySelector<HTMLInputElement>('[data-algo-setting="priceStepPct"]')
  if (!input) return
  input.min = '0'
  input.max = String(ALGORITHM_PRICE_STEP_MAX_PCT)
  input.step = input.step || '0.1'
}

