function ensureAlgorithmScheduleSettings(cards: HTMLElement) {
  const rules = cards.querySelector<HTMLElement>('#alg-rules')
  if (!rules) return
  const legacySelect = rules.querySelector<HTMLSelectElement>('select:not([data-algo-setting])')
    || rules.querySelector<HTMLSelectElement>('select[data-algo-setting="syncIntervalHours"]')
  const intervalRow = legacySelect?.closest<HTMLElement>('.s-row')
  if (intervalRow) {
    const label = intervalRow.querySelector<HTMLElement>('.s-label')
    if (label) label.textContent = 'Время шага по умолчанию'
    const desc = intervalRow.querySelector<HTMLElement>('.s-desc')
    if (desc) desc.textContent = 'Как часто стратегия может применять новый шаг, если в самой стратегии не задан свой интервал'
  }

  if (legacySelect) {
    legacySelect.setAttribute('data-algo-setting', 'syncIntervalMinutes')
    legacySelect.innerHTML = `
      <option value="5">5 минут</option>
      <option value="15">15 минут</option>
      <option value="30">30 минут</option>
      <option value="60">1 час</option>
      <option value="120">2 часа</option>
      <option value="240">4 часа</option>
      <option value="360">6 часов</option>
      <option value="720">12 часов</option>
    `
  }
  let fullSyncRow = rules.querySelector<HTMLElement>('[data-algo-full-sync-row]')
  if (!fullSyncRow) {
    const html = `
    <div class="s-row" data-algo-full-sync-row style="padding:10px 0;border-color:var(--gray-100)">
      <div>
        <div class="s-label">Полный синк WB</div>
        <div class="s-desc">Как часто фоновый синк обновляет товары, остатки, заказы, корзины и финансы.</div>
      </div>
      <div class="s-right">
        <select class="s-select" data-algo-setting="fullSyncIntervalMinutes">
          <option value="15">15 минут</option>
          <option value="30">30 минут</option>
          <option value="60">1 час</option>
          <option value="120">2 часа</option>
          <option value="240">4 часа</option>
          <option value="360">6 часов</option>
          <option value="720">12 часов</option>
          <option value="1440">1 сутки</option>
        </select>
      </div>
    </div>
  `
    if (intervalRow) intervalRow.insertAdjacentHTML('afterend', html)
    else rules.insertAdjacentHTML('beforeend', html)
    fullSyncRow = rules.querySelector<HTMLElement>('[data-algo-full-sync-row]')
  }
  if (!rules.querySelector('[data-algo-full-sync-promotions-row]')) {
    const promotionsHtml = `
    <div class="s-row" data-algo-full-sync-promotions-row style="padding:10px 0;border-color:var(--gray-100)">
      <div>
        <div class="s-label">Синхронизировать акции WB</div>
        <div class="s-desc">Если выключено, полный WB sync пропускает источник акций и не ждёт календарь промо.</div>
      </div>
      <label class="toggle">
        <input type="checkbox" data-algo-setting="fullSyncPromotionsEnabled">
        <div class="toggle-track"></div>
        <div class="toggle-thumb"></div>
      </label>
    </div>
  `
    if (fullSyncRow) fullSyncRow.insertAdjacentHTML('afterend', promotionsHtml)
    else rules.insertAdjacentHTML('beforeend', promotionsHtml)
  }
  if (rules.querySelector('[data-algo-worker-auto-apply-row]')) return
  const autoApplyHtml = `
    <div class="s-row" data-algo-worker-auto-apply-row style="padding:10px 0;border-color:var(--gray-100)">
      <div>
        <div class="s-label">Автоматически отправлять цены в WB</div>
        <div class="s-desc">Если выключено, worker создает заявку и показывает попап подтверждения перед отправкой цены.</div>
      </div>
      <label class="toggle">
        <input type="checkbox" data-algo-setting="workerAutoApplyPricesEnabled">
        <div class="toggle-track"></div>
        <div class="toggle-thumb"></div>
      </label>
    </div>
  `
  const promotionsRow = rules.querySelector<HTMLElement>('[data-algo-full-sync-promotions-row]')
  if (promotionsRow) promotionsRow.insertAdjacentHTML('afterend', autoApplyHtml)
  else if (fullSyncRow) fullSyncRow.insertAdjacentHTML('afterend', autoApplyHtml)
  else rules.insertAdjacentHTML('beforeend', autoApplyHtml)
}

