function annotateAlgoSettings(cards: HTMLElement) {
  const annotateMany = (selector: string, settings: string[]) => {
    cards.querySelectorAll<HTMLElement>(selector).forEach((node, index) => {
      const setting = settings[index]
      if (setting) node.setAttribute('data-algo-setting', setting)
    })
  }

  annotateMany('#alg-rules input[type="number"]', ['targetMarginPct', 'priceStepPct', 'maxPriceChangeDailyPct'])
  configureAlgorithmPriceStepInput(cards)
  annotateAlgoSetting(cards, '#alg-rules select:not([data-algo-setting])', 'syncIntervalMinutes')
  annotateAlgoSetting(cards, '#alg-rules input[type="checkbox"]', 'priceRoundingEnabled')

  annotateMany('#alg-cart input[type="number"]', [
    'cartHighBasketsThreshold',
    'cartLowBasketsThreshold',
    'warmupExitBaskets',
  ])
  annotateAlgoSetting(cards, '#alg-cart select', 'cartComparisonDays')

  annotateAlgoSetting(cards, '#median-mode', 'nightMedianMode')
  annotateMany('#alg-night input[type="checkbox"]:not([data-algo-setting])', ['nightMedianEnabled', 'nightMedianCollectEnabled'])
  annotateAlgoSetting(cards, '#alg-night input[type="number"]', 'nightMedianApplyDeltaPct')
  annotateAlgoSetting(cards, '#alg-night select', 'nightMedianTimezone')

  annotateMany('#alg-cogs .cogs-item input[type="number"]', [
    'cogsByGarmentRub.tshirt',
    'cogsByGarmentRub.hoodie',
    'cogsByGarmentRub.longsleeve',
  ])

  annotateMany('#alg-promo-protect input[type="checkbox"]', ['minPriceSyncEnabled', 'promoAlertEnabled'])

  annotateAlgoSetting(cards, '#alg-tg-digest input[type="checkbox"]', 'telegramDigestEnabled')
  annotateAlgoSetting(cards, '#alg-tg-digest input[type="time"]', 'telegramDigestTime')
  annotateAlgoSetting(cards, '#alg-tg-digest select', 'telegramDigestTimezone')
  cards.querySelectorAll<HTMLElement>('#alg-tg-digest .chip-toggle').forEach((node, index) => {
    node.setAttribute('data-algo-digest-metric-index', String(index))
  })

  annotateMany('#alg-tg-alerts .alert-threshold input[type="number"]', [
    'telegramAlertStockLowThreshold',
    'telegramAlertLossMarginThresholdPct',
    'telegramAlertCancelRateThresholdPct',
  ])
  annotateMany('#alg-tg-alerts .toggle input[type="checkbox"]', [
    'telegramAlertStockLowEnabled',
    'telegramAlertLossMarginEnabled',
    'telegramAlertCancelRateEnabled',
    'telegramAlertPriceGuardEnabled',
  ])

  annotateMany('#alg-warmup input[type="number"]', ['warmupDays', 'warmupMarginPct', 'warmupDailyLimitPct'])
  annotateAlgoSetting(cards, '#alg-liq input[type="checkbox"]', 'liquidationAutoFlagEnabled')
  annotateMany('#alg-liq input[type="number"]', ['liquidationStepPct', 'liquidationMinCogsPct'])
}

function scrubAlgorithmMockData(cards: HTMLElement) {
  cards.querySelector('.xlsx-preview')?.remove()
  cards.querySelector('.csv-history')?.remove()
  cards.querySelector('#cogs-upload')?.remove()
  cards.querySelector('.tg-preview')?.remove()

  const recipientList = cards.querySelector<HTMLElement>('.recipient-list')
  if (recipientList) {
    recipientList.innerHTML = '<div class="report-empty-note visible" style="margin:0">Получатели берутся из привязанного Telegram-профиля пользователя.</div>'
  }

  const cogsCard = cards.querySelector<HTMLElement>('#alg-cogs')
  if (cogsCard) {
    cogsCard.insertAdjacentHTML(
      'beforeend',
      '<div class="report-empty-note visible" style="margin-top:12px">История XLSX-импортов появится после реальной загрузки файла в профиль.</div>',
    )
  }

  const actions = cards.lastElementChild
  if (actions instanceof HTMLElement) {
    const buttons = Array.from(actions.querySelectorAll<HTMLButtonElement>('button'))
    buttons.find((button) => button.textContent?.includes('Тест'))?.remove()
    buttons.find((button) => button.textContent?.includes('Сбросить'))?.setAttribute('data-algo-action', 'reset')
    buttons.find((button) => button.textContent?.includes('Сохранить'))?.setAttribute('data-algo-action', 'save')
    buttons.forEach((button) => {
      button.type = 'button'
    })
  }
}

function prepareAlgorithmCardsHtml(sourceElement?: HTMLElement | SVGElement) {
  if (!sourceElement || !(sourceElement instanceof HTMLElement)) return ''
  const cards = sourceElement.querySelector<HTMLElement>('.settings-cards')?.cloneNode(true)
  if (!(cards instanceof HTMLElement)) return ''
  scrubAlgorithmMockData(cards)
  ensureAlgorithmScheduleSettings(cards)
  ensureSppAccountingSettings(cards)
  ensurePlanFactSettings(cards)
  ensureNightMedianAutoAllSkusSetting(cards)
  annotateAlgoSettings(cards)
  return cards.innerHTML
}

function selectAlgoOptionByNumber(select: HTMLSelectElement | null, value: unknown) {
  if (!select) return
  const numeric = Number(value)
  if (!Number.isFinite(numeric)) return
  const stringValue = String(Math.trunc(numeric))
  const option = Array.from(select.options).find((item) => item.value === stringValue)
    || Array.from(select.options).find((item) => parseInt(item.textContent || item.value, 10) === numeric)
  if (option) select.value = option.value
}

const NUMERIC_ALGORITHM_SELECT_SETTINGS = new Set([
  'syncIntervalMinutes',
  'syncIntervalHours',
  'fullSyncIntervalMinutes',
  'cartComparisonDays',
  'wbWalletType',
  'basketNormPeriodDays',
  'planFactFactPeriodDays',
  'planFactIntervalHours',
])

function setNestedAlgorithmValue(target: Record<string, unknown>, key: string, value: unknown) {
  if (!key.includes('.')) {
    target[key] = value
    return
  }
  const [parent, child] = key.split('.', 2)
  const parentValue = target[parent]
  const group = typeof parentValue === 'object' && parentValue !== null ? parentValue as Record<string, unknown> : {}
  group[child] = value
  target[parent] = group
}

function nestedAlgorithmValue(source: Record<string, unknown>, key: string) {
  if (!key.includes('.')) return source[key]
  const [parent, child] = key.split('.', 2)
  const group = source[parent]
  if (typeof group !== 'object' || group === null) return undefined
  return (group as Record<string, unknown>)[child]
}

function AlgorithmCardsIsland({ replacementKey, sourceElement }: { replacementKey: string; sourceElement?: HTMLElement | SVGElement }) {
  const rootRef = useRef<HTMLDivElement | null>(null)
  const [html, setHtml] = useState(() => prepareAlgorithmCardsHtml(sourceElement))
  const [settings, setSettings] = useState<Record<string, unknown> | null>(null)
  const [savedAt, setSavedAt] = useState<string | null>(null)
  const [error, setError] = useState<string | null>(null)
  const [saving, setSaving] = useState(false)

  useEffect(() => {
    setHtml(prepareAlgorithmCardsHtml(sourceElement))
  }, [sourceElement])

  useEffect(() => {
    let cancelled = false
    apiRequest('/api/v1/wb-repricer/algorithm')
      .then((payload) => {
        if (cancelled) return
        setSettings(typeof payload === 'object' && payload !== null ? payload as Record<string, unknown> : {})
      })
      .catch((err) => {
        if (cancelled) return
        setError(err instanceof Error ? err.message : 'Не удалось загрузить настройки алгоритма')
      })
    return () => {
      cancelled = true
    }
  }, [])

  useEffect(() => {
    const root = rootRef.current
    if (!root || !settings) return

    root.querySelectorAll<HTMLElement>('[data-algo-setting]').forEach((node) => {
      const key = node.dataset.algoSetting || ''
      const raw = nestedAlgorithmValue(settings, key)
      if (raw === undefined || raw === null) return
      const value = key === 'priceStepPct' ? clampAlgorithmPriceStepPct(raw) : raw
      if (node instanceof HTMLInputElement) {
        if (node.type === 'checkbox') node.checked = Boolean(value)
        else node.value = String(value)
        return
      }
      if (node instanceof HTMLSelectElement) {
        if (NUMERIC_ALGORITHM_SELECT_SETTINGS.has(key)) selectAlgoOptionByNumber(node, value)
        else node.value = String(value)
        return
      }
      if (key === 'nightMedianMode') {
        node.querySelectorAll<HTMLElement>('.seg-btn').forEach((button) => {
          button.classList.toggle('active', button.dataset.mode === String(value))
        })
      }
    })

    const digestMetrics = Array.isArray(settings.telegramDigestMetrics)
      ? settings.telegramDigestMetrics.map(String)
      : null
    if (digestMetrics) {
      root.querySelectorAll<HTMLElement>('[data-algo-digest-metric-index]').forEach((node) => {
        node.classList.toggle('active', digestMetrics.includes(node.textContent?.trim() || ''))
      })
    }
  }, [settings, html])

  useEffect(() => {
    const root = rootRef.current
    if (!root) return undefined

    const collectPayload = () => {
      const payload: Record<string, unknown> = { ...(settings ?? {}) }
      root.querySelectorAll<HTMLElement>('[data-algo-setting]').forEach((node) => {
        const key = node.dataset.algoSetting || ''
        let value: unknown
        if (node instanceof HTMLInputElement) {
          value = node.type === 'checkbox' ? node.checked : node.type === 'number' ? Number(node.value) : node.value
        } else if (node instanceof HTMLSelectElement) {
          value = NUMERIC_ALGORITHM_SELECT_SETTINGS.has(key)
            ? parseInt(node.value, 10)
            : node.value
        } else if (key === 'nightMedianMode') {
          value = node.querySelector<HTMLElement>('.seg-btn.active')?.dataset.mode || 'conservative'
        }
        if (key === 'priceStepPct') value = clampAlgorithmPriceStepPct(value)
        setNestedAlgorithmValue(payload, key, value)
        if (key === 'nightMedianAutoEnableAllSkus') {
          payload.nightMedianGlobal = Boolean(value)
        }
      })
      payload.telegramDigestMetrics = Array.from(root.querySelectorAll<HTMLElement>('#alg-tg-digest .chip-toggle.active'))
        .map((node) => node.textContent?.trim())
        .filter(Boolean)
      return payload
    }

    const markDirty = () => {
      setSavedAt(null)
      setError(null)
    }

    const onClick = (event: globalThis.MouseEvent) => {
      const target = event.target instanceof HTMLElement ? event.target : null
      const segment = target?.closest<HTMLElement>('.seg-btn')
      if (segment?.parentElement?.dataset.algoSetting === 'nightMedianMode') {
        segment.parentElement.querySelectorAll('.seg-btn').forEach((node) => node.classList.remove('active'))
        segment.classList.add('active')
        markDirty()
        return
      }
      const chip = target?.closest<HTMLElement>('#alg-tg-digest .chip-toggle')
      if (chip) {
        chip.classList.toggle('active')
        markDirty()
        return
      }
      const action = target?.closest<HTMLButtonElement>('[data-algo-action]')
      if (!action) return
      if (action.dataset.algoAction === 'reset') {
        if (settings) setSettings({ ...settings })
        markDirty()
        return
      }
      if (action.dataset.algoAction === 'save') {
        const payload = collectPayload()
        setSaving(true)
        setError(null)
        apiRequest('/api/v1/wb-repricer/algorithm', {
          method: 'PUT',
          body: JSON.stringify(payload),
        })
          .then((response) => {
            const normalized = typeof response === 'object' && response !== null ? response as Record<string, unknown> : payload
            setSettings(normalized)
            setSavedAt(String(normalized.savedAt || new Date().toISOString()))
            resetLiveRepricerParityCache()
            void window.__vellaLoadLiveRepricerProducts?.()
          })
          .catch((err) => {
            setError(err instanceof Error ? err.message : 'Не удалось сохранить настройки алгоритма')
          })
          .finally(() => setSaving(false))
      }
    }

    root.addEventListener('click', onClick)
    root.addEventListener('change', markDirty)
    root.addEventListener('input', markDirty)
    return () => {
      root.removeEventListener('click', onClick)
      root.removeEventListener('change', markDirty)
      root.removeEventListener('input', markDirty)
    }
  }, [settings, html])

  useEffect(() => {
    const root = rootRef.current
    if (!root) return
    const saveButton = root.querySelector<HTMLButtonElement>('[data-algo-action="save"]')
    if (saveButton) {
      saveButton.disabled = saving
      saveButton.textContent = saving ? 'Сохранение...' : savedAt ? 'Сохранено' : 'Сохранить изменения'
    }
  }, [saving, savedAt, html])

  if (!html) {
    return <div className="settings-cards"><div className="settings-card">Настройки алгоритма недоступны в Vella snapshot.</div></div>
  }

  return (
    <div
      ref={rootRef}
      className="settings-cards"
      data-vella-island="algo-settings-cards"
      data-vella-island-status="explicit-jsx"
    >
      {error && <div className="report-empty-note visible" style={{ marginBottom: 10 }}>{error}</div>}
      {savedAt && <div className="report-empty-note visible" style={{ marginBottom: 10 }}>Настройки сохранены в профиле.</div>}
      {htmlToReactFragment(html, `${replacementKey}-algo-settings-cards-content`)}
    </div>
  )
}

