type PromoCalcProduct = {
  sku: string
  name: string
  price: number
  cogs: number
  pmin: number
  storagePerSku: number
}

type PromoCalcRow = {
  product: PromoCalcProduct
  actionPrice: number
  marginPct: number
  decClass: 'go' | 'raise' | 'block'
  decLabel: string
}

type PromoListRow = {
  promotion?: LiveWbPromotion
  title: string
  status: 'active' | 'upcoming'
  periodLabel: string
  periodValue: string
  periodColor?: string
  loaded?: number
  total?: number
  pct?: number
  readinessText?: string
  decision: 'warn' | 'ok'
  actionTip?: string
}

function readProductsFilterState() {
  const managerSelect = document.getElementById('managerSelect')
  const manager = managerSelect instanceof HTMLSelectElement ? managerSelect.value : undefined
  const activeStatus = document.querySelector<HTMLElement>('#tab-products .chip[data-status].active')?.dataset.status
  const activeBrand = document.querySelector<HTMLElement>('#tab-products .chip[data-brand].active')?.dataset.brand
  return {
    status: window.__vellaProductsFilters?.status ?? activeStatus ?? 'all',
    brand: window.__vellaProductsFilters?.brand ?? activeBrand ?? 'all',
    manager: window.__vellaProductsFilters?.manager ?? manager ?? 'all',
    promo: window.__vellaProductsFilters?.promo ?? 'all',
  }
}

function setProductsFilterState(next: Partial<{ status: string; brand: string; manager: string; promo: string }>) {
  const current = readProductsFilterState()
  window.__vellaProductsFilters = { ...current, ...next }
  const onlyLocalPromo = Object.keys(next).length > 0 && Object.keys(next).every((key) => key === 'promo')
  if (onlyLocalPromo) {
    window.dispatchEvent(new CustomEvent('vella:products-rows-updated'))
  } else {
    window.__vellaProductsListState = { ...(window.__vellaProductsListState ?? {}), page: 1 }
    resetLiveRepricerParityCache()
    window.__vellaLoadLiveRepricerProducts?.()
  }
  window.dispatchEvent(new CustomEvent('vella:products-filter-updated'))
}

function productsQueryFromRuntime(page = window.__vellaProductsListState?.page ?? 1) {
  const searchInput = document.getElementById('searchTable')
  const q = searchInput instanceof HTMLInputElement ? searchInput.value : ''
  const pageSize = window.__vellaProductsListState?.pageSize ?? PRODUCTS_TABLE_RENDER_LIMIT
  const filters = readProductsFilterState()
  const period = productsPeriodRequest()
  return {
    periodDays: period.periodDays,
    dateFrom: period.dateFrom,
    dateTo: period.dateTo,
    page,
    pageSize,
    topMode: window.__vellaProductsListState?.topMode !== false,
    q,
    status: filters.status,
    brand: filters.brand,
    manager: filters.manager,
  }
}

let productsRuntimeLoadSeq = 0

async function loadProductsPriceChangesCount(accessToken: string, period: LiveRepricerPeriodRequest) {
  const from = period.dateFrom ? `${period.dateFrom}T00:00:00.000Z` : new Date(Date.now() - (Math.max(1, period.periodDays ?? PRODUCTS_DEFAULT_PERIOD_DAYS) - 1) * DAY_MS).toISOString()
  const params = new URLSearchParams({
    from,
    page: '1',
    limit: '1',
  })
  try {
    const payload = await apiRequest<{ total?: number }>(`/api/v1/wb-repricer/changelog?${params.toString()}`, {
      headers: authorizationHeaders(accessToken),
      cache: 'no-store',
    })
    return Number(payload?.total ?? 0)
  } catch (error) {
    console.warn('Failed to load repricer price changes KPI', error)
    return 0
  }
}

function loadProductsPriceChangesCountInBackground(
  accessToken: string,
  period: LiveRepricerPeriodRequest,
  isLatestLoad: () => boolean,
) {
  void loadProductsPriceChangesCount(accessToken, period)
    .then((count) => {
      if (!isLatestLoad()) return
      window.__vellaProductsPriceChanges = count
      syncProductsKpisFromRuntime()
    })
}

function publishProductsLoadTrace(trace?: LiveRepricerLoadTrace | null) {
  if (!trace) return
  const previous = window.__vellaProductsLoadTraces ?? []
  const nextSequence = Number(previous[0]?.sequence ?? 0) + 1
  const entry: ProductsLoadTraceEntry = {
    ...trace,
    sequence: nextSequence,
    receivedAt: new Date().toISOString(),
  }
  window.__vellaProductsLoadTrace = entry
  window.__vellaProductsLoadTraces = [entry, ...previous].slice(0, 20)
  window.dispatchEvent(new CustomEvent('vella:products-trace-updated'))
}

async function loadProductsPageFromRuntime(
  accessToken: string,
  page = window.__vellaProductsListState?.page ?? 1,
  signal?: AbortSignal,
) {
  if (WB_ACCOUNT_PRODUCTS_ENABLED && (isCanonicalProductsRoute(window.location.pathname) || resolveParityRouteTarget(window.location.pathname, window.location.search).tab === 'products')) {
    throw new ApiError('Откройте товары выбранного аккаунта WB. Старое чтение этого экрана отключено.', 409, 'WB_ACCOUNT_REQUIRED')
  }
  const loadSeq = ++productsRuntimeLoadSeq
  const isLatestLoad = () => !signal?.aborted && loadSeq === productsRuntimeLoadSeq
  const requestedPage = Math.max(1, Number(page) || 1)
  window.__vellaProductsListState = {
    ...(window.__vellaProductsListState ?? {}),
    page: requestedPage,
    pageSize: window.__vellaProductsListState?.pageSize ?? PRODUCTS_TABLE_RENDER_LIMIT,
  }
  const query = productsQueryFromRuntime(requestedPage)
  const queryHasKpiFilters = productsQueryHasKpiFilters(query)
  const payload = await loadLiveRepricerParityProducts(accessToken, signal, query)
  if (!isLatestLoad()) return payload
  publishProductsLoadTrace(payload.trace)

  if (requestedPage > 1 && payload.total > 0 && payload.products.length === 0) {
    window.__vellaProductsListState = {
      ...(window.__vellaProductsListState ?? {}),
      page: 1,
      pageSize: window.__vellaProductsListState?.pageSize ?? PRODUCTS_TABLE_RENDER_LIMIT,
    }
    const firstPageQuery = productsQueryFromRuntime(1)
    const firstPageHasKpiFilters = productsQueryHasKpiFilters(firstPageQuery)
    const firstPagePayload = await loadLiveRepricerParityProducts(accessToken, signal, firstPageQuery)
    if (!isLatestLoad()) return firstPagePayload
    publishProductsLoadTrace(firstPagePayload.trace)
    window.__vellaProductsCacheMeta = firstPagePayload.cache
    if (!firstPageHasKpiFilters) {
      window.__vellaProductsSummary = firstPagePayload.summary
    }
    applyLiveProductsToRuntime(firstPagePayload.products, { updateKpiRows: !firstPageHasKpiFilters })
    window.dispatchEvent(new CustomEvent('vella:products-pagination-updated'))
    loadProductsPriceChangesCountInBackground(
      accessToken,
      productsPeriodRequest(),
      isLatestLoad,
    )
    syncProductsKpisFromRuntime()
    return firstPagePayload
  }

  window.__vellaProductsCacheMeta = payload.cache
  if (!queryHasKpiFilters) {
    window.__vellaProductsSummary = payload.summary
  }
  applyLiveProductsToRuntime(payload.products, { updateKpiRows: !queryHasKpiFilters })
  window.dispatchEvent(new CustomEvent('vella:products-pagination-updated'))
  loadProductsPriceChangesCountInBackground(
    accessToken,
    productsPeriodRequest(),
    isLatestLoad,
  )
  syncProductsKpisFromRuntime()
  return payload
}

function formatPromoNumber(value: number) {
  return value.toLocaleString('ru-RU').replace(/,/g, ' ')
}

function promoTypeLabel(type: string | undefined) {
  if (type === 'auto') return 'Автоакция'
  if (type === 'flash') return 'Флеш'
  return 'Спец'
}

function promoExcelStatus(promo: LiveWbPromotion) {
  if (promo.excelStatus === 'error') return { text: 'Ошибка XLSX', decision: 'warn' as const }
  if (promo.excelLoaded || promo.excelStatus === 'loaded' || promo.excelStatus === 'parsed') return { text: 'Готово к защите', decision: 'ok' as const }
  if (promo.excelStatus === 'partial') return { text: 'Частично загружено', decision: 'warn' as const }
  return { text: 'Обновить пороги WB', decision: 'warn' as const }
}

function livePromoToListRow(promo: LiveWbPromotion): PromoListRow {
  const active = promo.status === 'active'
  const upcoming = promo.status === 'upcoming'
  const rowsParsed = Number(promo.thresholdRowsParsed ?? 0)
  const eligible = Number(promo.eligibleSkuCount ?? 0)
  const participationPct = Number(promo.participationPct ?? 0)
  const readinessPct = rowsParsed > 0 && eligible > 0 ? Math.min(100, Math.round((rowsParsed / eligible) * 100)) : participationPct
  const excel = promoExcelStatus(promo)
  return {
    promotion: promo,
    title: promo.name || `Акция ${promo.id}`,
    status: upcoming ? 'upcoming' : 'active',
    periodLabel: active ? 'Дней до окончания:' : upcoming ? 'Дней до начала:' : 'Статус:',
    periodValue: active ? String(Math.max(0, Number(promo.daysUntilEnd ?? 0))) : upcoming ? String(Math.max(0, Number(promo.daysUntilStart ?? 0))) : 'архив',
    periodColor: active && Number(promo.daysUntilEnd ?? 99) <= 2 ? '#DC2626' : active && Number(promo.daysUntilEnd ?? 99) <= 7 ? '#F59E0B' : undefined,
    loaded: rowsParsed || Number(promo.participatingSkuCount ?? 0),
    total: eligible,
    pct: readinessPct,
    readinessText: promo.excelLoaded ? `${rowsParsed} NmId из XLSX` : undefined,
    decision: excel.decision,
    actionTip: excel.text,
  }
}

function useLivePromotionsSnapshot() {
  const [promotions, setPromotions] = useState<LiveWbPromotion[]>(() => window.__vellaPromotionsSnapshot?.() ?? [])
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)

  useEffect(() => {
    let cancelled = false
    const render = () => setPromotions(window.__vellaPromotionsSnapshot?.() ?? [])
    window.addEventListener('vella:promotions-updated', render)
    const load = async () => {
      if (!window.__vellaLoadLivePromotions) return
      setLoading(true)
      setError(null)
      try {
        const rows = await window.__vellaLoadLivePromotions()
        if (!cancelled) setPromotions(rows)
      } catch (err) {
        if (!cancelled) setError(err instanceof Error ? err.message : 'Не удалось загрузить акции')
      } finally {
        if (!cancelled) setLoading(false)
      }
    }
    render()
    void load()
    return () => {
      cancelled = true
      window.removeEventListener('vella:promotions-updated', render)
    }
  }, [])

  return { promotions, loading, error }
}

function usePromoProductsSnapshot() {
  const [products, setProducts] = useState<PromoCalcProduct[]>(() => window.__vellaPromoProductsSnapshot?.() ?? [])
  useEffect(() => {
    const render = () => setProducts(window.__vellaPromoProductsSnapshot?.() ?? [])
    window.__vellaReactRenderPromotions = render
    window.addEventListener('vella:promos-calc-updated', render)
    render()
    return () => {
      if (window.__vellaReactRenderPromotions === render) delete window.__vellaReactRenderPromotions
      window.removeEventListener('vella:promos-calc-updated', render)
    }
  }, [])
  return products
}

function usePromoCalcOpen() {
  const [open, setOpen] = useState(() => Boolean(window.__vellaPromoCalcOpen))
  useEffect(() => {
    const render = () => setOpen(Boolean(window.__vellaPromoCalcOpen))
    window.addEventListener('vella:promos-calc-updated', render)
    render()
    return () => window.removeEventListener('vella:promos-calc-updated', render)
  }, [])
  return open
}

function usePromoFilterState() {
  const [state, setState] = useState(() => window.__vellaPromoFilterState ?? { filter: 'all', query: '' })
  useEffect(() => {
    const render = () => setState(window.__vellaPromoFilterState ?? { filter: 'all', query: '' })
    window.addEventListener('vella:promos-filter-updated', render)
    render()
    return () => window.removeEventListener('vella:promos-filter-updated', render)
  }, [])
  return state
}

function computePromoCalcRows(products: PromoCalcProduct[], discount: number, minMargin: number) {
  let go = 0
  let raise = 0
  let block = 0
  const rows = products
    .filter((product) => product.cogs > 0)
    .map<PromoCalcRow>((product) => {
      const actionPrice = Math.round(product.price * (1 - discount / 100))
      const commission = Math.round(actionPrice * 0.15)
      const marginRub = actionPrice - product.cogs - commission - 53 - product.storagePerSku
      const marginPct = Number(((marginRub / actionPrice) * 100).toFixed(1))
      let decClass: PromoCalcRow['decClass']
      let decLabel: string
      if (actionPrice < product.pmin) {
        decClass = 'block'
        decLabel = 'P_min блокирует'
        block += 1
      } else if (marginPct >= minMargin) {
        decClass = 'go'
        decLabel = '✓ Войти'
        go += 1
      } else if (marginPct > 0) {
        decClass = 'raise'
        decLabel = '↑ Цена ниже порога'
        raise += 1
      } else {
        decClass = 'block'
        decLabel = '✕ Запретить'
        block += 1
      }
      return { product, actionPrice, marginPct, decClass, decLabel }
    })
    .sort((a, b) => {
      const ord = { go: 0, raise: 1, block: 2 }
      return ord[a.decClass] - ord[b.decClass] || b.marginPct - a.marginPct
    })
  return { rows, go, raise, block }
}

