function PromosCalculatorIsland() {
  const products = usePromoProductsSnapshot()
  const open = usePromoCalcOpen()
  const [discount, setDiscount] = useState(30)
  const [minMargin, setMinMargin] = useState(10)
  const calc = useMemo(() => computePromoCalcRows(products, discount || 30, minMargin || 10), [discount, minMargin, products])

  return (
    <div className="promo-calc-card" id="promoCalcCard" data-vella-island="promos-calculator-card" data-vella-island-status="explicit-jsx">
      <div className="promo-calc-card-head">
        <div className="promo-calc-title">
          <div>
            <div className="promo-calc-title-main">Проверка входа в акцию</div>
            <div className="promo-calc-title-sub">Показывает, какие SKU выдержат скидку без ухода ниже P_min.</div>
          </div>
          <button className="help-btn" type="button" data-tip="Что это?" data-vella-react-handlers="onclick" onClick={() => window.showHelp?.('promo-calc')}>?</button>
        </div>
        <div className="promo-calc-card-inputs">
          <div className="promo-calc-field">
            <label className="promo-calc-label">WB требует скидку</label>
            <div style={{ display: 'flex', alignItems: 'center', gap: 5 }}>
              <input
                type="number"
                className="s-input"
                id="promoDiscInput"
                value={discount}
                min="1"
                max="90"
                style={{ width: 58, textAlign: 'center' }}
                data-vella-react-handlers="oninput"
                onInput={(event) => setDiscount(Number(event.currentTarget.value) || 0)}
              />
              <span style={{ fontSize: 12, color: 'var(--gray-600)' }}>%</span>
            </div>
          </div>
          <div className="promo-calc-field">
            <label className="promo-calc-label">Мин. маржа для входа</label>
            <div style={{ display: 'flex', alignItems: 'center', gap: 5 }}>
              <input
                type="number"
                className="s-input"
                id="promoMinMargInput"
                value={minMargin}
                min="0"
                max="50"
                style={{ width: 58, textAlign: 'center' }}
                data-vella-react-handlers="oninput"
                onInput={(event) => setMinMargin(Number(event.currentTarget.value) || 0)}
              />
              <span style={{ fontSize: 12, color: 'var(--gray-600)' }}>%</span>
            </div>
          </div>
        </div>
        <div className="promo-calc-chips" style={{ marginLeft: 'auto' }}>
          <span className="promo-chip green">✓ <span id="promoChipGo">Можно включить: {calc.go}</span></span>
          <span className="promo-chip amber">↑ <span id="promoChipRaise">Цена ниже порога: {calc.raise}</span></span>
          <span className="promo-chip red">× <span id="promoChipBlock">Не пройдут P_min: {calc.block}</span></span>
        </div>
        <button className="promo-calc-expand-btn" id="promoCalcExpandBtn" type="button" data-vella-react-handlers="onclick" onClick={() => window.__vellaSetPromoCalcOpen?.(!open)}>
          Разбор SKU <span id="promoCalcExpandIcon">{open ? '▴' : '▾'}</span>
        </button>
      </div>
      <div className="promo-calc-table-wrap" id="promoCalcTableWrap" style={{ display: open ? 'block' : 'none' }}>
        <table className="promo-calc-table">
          <thead><tr>
            <th>Артикул / Название</th>
            <th style={{ textAlign: 'right' }}>Текущая цена</th>
            <th style={{ textAlign: 'right' }}><div className="th-tip tr">При акции <span className="tip-i">?</span><div className="tip-box">Цена = Текущая × (1 − скидка%). Именно столько WB установит при активации акции.</div></div></th>
            <th style={{ textAlign: 'right' }}><div className="th-tip tr">Маржа <span className="tip-i">?</span><div className="tip-box">Маржа при акционной цене = (Цена акц. − себестоимость − комиссия 15% − логистика 53₽) / Цена акц. Красный — ниже порога или отрицательная.</div></div></th>
            <th style={{ textAlign: 'right' }}>Решение</th>
          </tr></thead>
          <tbody id="promoCalcTbody" data-vella-island="promos-calculator-rows" data-vella-island-status="explicit-jsx">
            {calc.rows.map((row) => (
              <tr key={row.product.sku}>
                <td><div style={{ fontFamily: 'monospace', fontSize: 11, color: 'var(--gray-500)' }}>{row.product.sku}</div><div style={{ fontSize: 12, maxWidth: 220, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis', color: 'var(--gray-700)' }}>{row.product.name}</div></td>
                <td style={{ textAlign: 'right', fontWeight: 600, fontSize: 13 }}>{formatPromoNumber(row.product.price)} ₽</td>
                <td style={{ textAlign: 'right', fontWeight: 600, fontSize: 13, color: row.decClass === 'block' ? 'var(--gray-400)' : 'var(--gray-900)' }}>{formatPromoNumber(row.actionPrice)} ₽</td>
                <td style={{ textAlign: 'right', fontWeight: 700, fontSize: 13, color: row.marginPct < 0 ? '#DC2626' : row.marginPct < minMargin ? '#D97706' : '#059669' }}>{row.marginPct >= 0 ? '+' : ''}{row.marginPct}%</td>
                <td style={{ textAlign: 'right' }}><span className={`promo-calc-dec ${row.decClass}`}>{row.decLabel}</span></td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  )
}

function PromoReadinessCell({ row }: { row: PromoListRow }) {
  if (row.readinessText) return <div style={{ fontSize: 12, color: 'var(--gray-400)' }}>{row.readinessText}</div>
  const pct = row.pct ?? 0
  return (
    <div className="sku-bar">
      <div style={{ fontSize: 12, color: 'var(--gray-600)' }}>{formatPromoNumber(row.loaded ?? 0)} / {formatPromoNumber(row.total ?? 0)} · {pct}%</div>
      <div className="sku-bar-track">
        <div className="sku-bar-fill" style={{ width: `${pct}%`, ...(pct >= 96 ? { background: '#10B981' } : {}) }} />
      </div>
    </div>
  )
}

function PromoListRowIsland({ row, index, onUpload }: { row: PromoListRow; index: number; onUpload: (row: PromoListRow) => void }) {
  const rowStyle = row.status === 'upcoming' ? { cursor: 'pointer', background: 'var(--gray-50)' } : { cursor: 'pointer' }
  const importTip = row.actionTip ?? 'Импорт XLSX'
  const stop = (event: MouseEvent<HTMLDivElement>) => event.stopPropagation()

  return (
    <tr
      style={rowStyle}
      data-status={row.status}
      data-title={row.title}
      data-vella-island="promos-table-row"
      data-vella-island-status="explicit-jsx"
      data-vella-react-handlers="onclick"
      onClick={() => window.openPromoDetail?.(index)}
    >
      <td><div style={{ fontSize: 13, fontWeight: 600, color: 'var(--gray-900)' }}>{row.title}</div></td>
      <td><span className="promo-badge-auto">{promoTypeLabel(row.promotion?.type)}</span></td>
      <td><span style={{ fontSize: 12.5, color: 'var(--gray-600)' }}>{row.periodLabel} <b style={row.periodColor ? { color: row.periodColor } : undefined}>{row.periodValue}</b></span></td>
      <td><PromoReadinessCell row={row} /></td>
      <td>{row.decision === 'warn' ? <span className="promo-status-warn">{row.actionTip ?? 'Обновить пороги WB'}</span> : <span className="promo-status-ok">{row.actionTip ?? 'Готово к защите'}</span>}</td>
      <td>
        <div style={{ display: 'flex', gap: 4, justifyContent: 'flex-end' }}>
          <div className="act" data-tip="На WB" data-vella-react-handlers="onclick" onClick={(event) => { stop(event); window.showToast?.('Открываем на WB…', 'info') }}><PromoExternalLinkIcon /></div>
          <div className="act" data-tip={importTip} data-vella-react-handlers="onclick" onClick={(event) => { stop(event); onUpload(row) }}><PromoUploadIcon /></div>
        </div>
      </td>
    </tr>
  )
}

function PromosBodyIsland() {
  const { accessToken } = useAuth()
  const { promotions, loading, error } = useLivePromotionsSnapshot()
  const state = usePromoFilterState()
  const fileInputRef = useRef<HTMLInputElement>(null)
  const bulkInputRef = useRef<HTMLInputElement>(null)
  const uploadTargetRef = useRef<PromoListRow | null>(null)
  const query = (state.query || '').trim().toLowerCase()
  const filter = state.filter || 'all'
  const sourceRows = promotions
    .filter((promo) => promo.status !== 'ended')
    .map(livePromoToListRow)
  const visibleRows = sourceRows.filter((row) => {
    const matchesFilter = filter === 'all' || filter === row.status
    const matchesSearch = !query || row.title.toLowerCase().includes(query)
    return matchesFilter && matchesSearch
  })
  const counts = {
    all: visibleRows.length,
    active: visibleRows.filter((row) => row.status === 'active').length,
    upcoming: visibleRows.filter((row) => row.status === 'upcoming').length,
  }
  const setFilter = (next: string) => window.__vellaSetPromoFilterState?.({ filter: next })
  const rowsWithIndexes = sourceRows.map((row, index) => ({ row, index }))
    .filter(({ row }) => visibleRows.includes(row))

  async function reloadPromotions() {
    try {
      if (window.__vellaLoadLivePromotions) {
        await window.__vellaLoadLivePromotions()
      } else if (accessToken) {
        const rows = await loadLiveWbPromotions(accessToken)
        window.__vellaPromotionsCache = rows
        window.dispatchEvent(new CustomEvent('vella:promotions-updated'))
      } else {
        throw new ApiError('AUTH_REQUIRED', 401)
      }
    } catch (err) {
      window.showToast?.(err instanceof Error ? err.message : 'Не удалось обновить акции', 'warn')
    }
  }

  async function uploadRowFile(file: File, row: PromoListRow) {
    const promotionId = row.promotion?.id
    if (!promotionId) {
      window.showToast?.('Сначала синхронизируйте список акций WB', 'warn')
      return
    }
    try {
      const updated = window.__vellaUploadPromotionExcel
        ? await window.__vellaUploadPromotionExcel(promotionId, file)
        : accessToken
          ? await uploadLiveWbPromotionExcel(accessToken, promotionId, file)
          : undefined
      if (!updated) throw new ApiError('AUTH_REQUIRED', 401)
      window.showToast?.(
        updated?.excelStatus === 'error'
          ? `XLSX загружен с ошибкой: ${updated.excelErrorText ?? file.name}`
          : `Пороги загружены: ${updated?.thresholdRowsParsed ?? 0} NmId`,
        updated?.excelStatus === 'error' ? 'warn' : 'success',
      )
      await reloadPromotions()
      window.__vellaLoadLiveRepricerProducts?.()
    } catch (err) {
      window.showToast?.(err instanceof Error ? err.message : 'Не удалось загрузить XLSX', 'warn')
    }
  }

  async function uploadBulkFiles(files: FileList | null) {
    const list = Array.from(files ?? [])
    if (!list.length) return
    try {
      const result = window.__vellaUploadPromotionsExcelBulk
        ? await window.__vellaUploadPromotionsExcelBulk(list)
        : accessToken
          ? await uploadLiveWbPromotionsExcelBulk(accessToken, list)
          : undefined
      if (!result) throw new ApiError('AUTH_REQUIRED', 401)
      window.showToast?.(
        `XLSX: распознано ${result?.matchedCount ?? 0}, не распознано ${result?.unmatchedCount ?? 0}, ошибок ${result?.errorCount ?? 0}`,
        result?.unmatchedCount || result?.errorCount ? 'warn' : 'success',
      )
      await reloadPromotions()
      window.__vellaLoadLiveRepricerProducts?.()
    } catch (err) {
      window.showToast?.(err instanceof Error ? err.message : 'Не удалось загрузить XLSX', 'warn')
    }
  }

  return (
    <div className="promo-body" data-vella-island="promos-body" data-vella-island-status="explicit-jsx">
      <input
        ref={fileInputRef}
        type="file"
        accept=".xlsx,.xls"
        hidden
        onChange={(event) => {
          const file = event.currentTarget.files?.[0]
          const target = uploadTargetRef.current
          event.currentTarget.value = ''
          if (file && target) void uploadRowFile(file, target)
        }}
      />
      <input
        ref={bulkInputRef}
        type="file"
        accept=".xlsx,.xls"
        multiple
        hidden
        onChange={(event) => {
          void uploadBulkFiles(event.currentTarget.files)
          event.currentTarget.value = ''
        }}
      />
      <div className="toolbar" style={{ paddingBottom: 0 }}>
        <div className="search">
          <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><circle cx="11" cy="11" r="8" /><line x1="21" y1="21" x2="16.65" y2="16.65" /></svg>
          <input
            type="text"
            placeholder="Поиск по акции..."
            id="promoSearch"
            value={state.query || ''}
            data-vella-react-handlers="oninput"
            onInput={(event) => window.__vellaSetPromoFilterState?.({ query: event.currentTarget.value })}
          />
        </div>
        <div className="chips">
          <div className={`chip ${filter === 'all' ? 'active' : ''}`} data-filter="all" data-vella-react-handlers="onclick" onClick={() => setFilter('all')}>Все <span className="chip-count">{counts.all}</span></div>
          <div className={`chip ${filter === 'active' ? 'active' : ''}`} data-filter="active" data-vella-react-handlers="onclick" onClick={() => setFilter('active')}>Активные <span className="chip-count">{counts.active}</span></div>
          <div className={`chip ${filter === 'upcoming' ? 'active' : ''}`} data-filter="upcoming" data-vella-react-handlers="onclick" onClick={() => setFilter('upcoming')}>Предстоящие <span className="chip-count">{counts.upcoming}</span></div>
        </div>
        <div className="spacer" />
        <button className="btn btn-default btn-sm" type="button" data-vella-react-handlers="onclick" onClick={() => void reloadPromotions()}><svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polyline points="23 4 23 10 17 10" /><path d="M20.49 15a9 9 0 11-2.12-9.36L23 10" /></svg>{loading ? 'Обновляем…' : 'Обновить список'}</button>
        <button className="btn btn-primary" type="button" data-vella-react-handlers="onclick" onClick={() => bulkInputRef.current?.click()}><svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M21 15v4a2 2 0 01-2 2H5a2 2 0 01-2-2v-4" /><polyline points="17 8 12 3 7 8" /><line x1="12" y1="3" x2="12" y2="15" /></svg>Загрузить все</button>
      </div>
      {error ? <div className="api-error show" style={{ margin: '10px 20px' }}><div className="api-error-title">Акции WB недоступны</div><div className="api-error-desc">{error}</div></div> : null}
      <div className="table-wrap" style={{ paddingTop: 0 }}>
        <table>
          <colgroup><col /><col style={{ width: 100 }} /><col style={{ width: 200 }} /><col style={{ width: 200 }} /><col style={{ width: 220 }} /><col style={{ width: 72 }} /></colgroup>
          <thead><tr>
            <th>Название акции</th>
            <th><div className="th-tip tl">Тип <span className="tip-i">?</span><div className="tip-box">Автоакция — WB автоматически снижает цену до заданного порога. Флеш-акция — краткосрочная со скидкой по запросу WB. Спецпредложение — индивидуальные условия.</div></div></th>
            <th><div className="th-tip tl">Срок <span className="tip-i">?</span><div className="tip-box">Время до окончания (для активных) или до начала (для предстоящих). Красный &lt;3 дней, жёлтый &lt;7 дней.</div></div></th>
            <th><div className="th-tip tc">Готовность цен <span className="tip-i">?</span><div className="tip-box">Доля SKU, по которым известны акционные пороги WB и можно проверить участие против P_min. Это показатель готовности данных для решения.</div></div></th>
            <th><div className="th-tip tc">Решение <span className="tip-i">?</span><div className="tip-box">«Готово к защите» — пороги свежие, P_min защищает. «Обновить пороги» — условия акции изменились или XLSX устарел, массовые решения лучше не применять.</div></div></th>
            <th />
          </tr></thead>
          <tbody data-vella-island="promos-table-body" data-vella-island-status="explicit-jsx">
            {!loading && visibleRows.length === 0 ? (
              <tr>
                <td colSpan={6} style={{ padding: '18px 20px', color: 'var(--gray-500)', fontSize: 13 }}>
                  {error ? 'Акции WB не загружены' : 'Нет акций по текущему фильтру'}
                </td>
              </tr>
            ) : null}
            {rowsWithIndexes.map(({ row, index }, visibleIndex) => (
              <Fragment key={row.title}>
                {visibleIndex > 0 && rowsWithIndexes[visibleIndex - 1].row.status === 'active' && row.status === 'upcoming' ? (
                  <tr data-divider="upcoming"><td colSpan={6} style={{ padding: '6px 10px', background: 'var(--gray-50)', fontSize: 11, fontWeight: 700, color: 'var(--gray-500)', letterSpacing: '0.06em', textTransform: 'uppercase', borderBottom: '1px solid var(--gray-100)' }}>Предстоящие</td></tr>
                ) : null}
                <PromoListRowIsland row={row} index={index} onUpload={(target) => {
                  uploadTargetRef.current = target
                  fileInputRef.current?.click()
                }} />
              </Fragment>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  )
}

function PromotionsIsland({ replacementKey, sourceElement: _sourceElement }: { replacementKey: string; sourceElement?: HTMLElement | SVGElement }) {
  void _sourceElement
  return (
    <div
      key={replacementKey}
      className="tab-content"
      id="tab-promos"
      data-vella-island="promos"
      data-vella-island-status="explicit-jsx"
    >
      <PromosStatsIsland />
      <PromosCalculatorIsland />
      <PromosBodyIsland />
      <PromoDetailOverlayIsland replacementKey={`${replacementKey}-detail`} />
    </div>
  )
}

function usePromoDetailState() {
  const [state, setState] = useState(() => window.__vellaPromoDetailState ?? { open: false, index: null })
  useEffect(() => {
    const render = () => setState(window.__vellaPromoDetailState ?? { open: false, index: null })
    window.addEventListener('vella:promos-detail-updated', render)
    render()
    return () => window.removeEventListener('vella:promos-detail-updated', render)
  }, [])
  return state
}

function PromoStatusBox({ status }: { status: 'warn' | 'ok' }) {
  if (status === 'warn') {
    return (
      <div className="promo-warn-box">
        <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="#D97706" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" style={{ flexShrink: 0, marginTop: 1 }}>
          <circle cx="12" cy="12" r="10" />
          <line x1="12" y1="8" x2="12" y2="12" />
          <line x1="12" y1="16" x2="12.01" y2="16" />
        </svg>
        <div><b>Обновить пороги WB</b><br />Цены на товары не подтверждались более 24 часов. Импортируйте свежий XLSX из ЛК WB, чтобы участвовать в акции с актуальными ценами и защитить минимальную маржу.</div>
      </div>
    )
  }
  return (
    <div style={{ display: 'flex', alignItems: 'center', gap: 8, padding: '10px 14px', background: '#F0FDF4', border: '1px solid #BBF7D0', borderRadius: 10, fontSize: 13, color: '#065F46' }}>
      <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="#10B981" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><polyline points="20 6 9 17 4 12" /></svg>
      <b>Готово к защите</b> — обновлений не требуется
    </div>
  )
}

function PromoDetailOverlayIsland({ replacementKey }: { replacementKey: string }) {
  const state = usePromoDetailState()
  const [promotions, setPromotions] = useState<LiveWbPromotion[]>(() => window.__vellaPromotionsSnapshot?.() ?? [])
  useEffect(() => {
    const render = () => setPromotions(window.__vellaPromotionsSnapshot?.() ?? [])
    window.addEventListener('vella:promotions-updated', render)
    render()
    return () => window.removeEventListener('vella:promotions-updated', render)
  }, [])
  const rows = promotions
    .filter((promo) => promo.status !== 'ended')
    .map(livePromoToListRow)
  const item = typeof state.index === 'number' ? rows[state.index] : undefined
  const open = Boolean(state.open && item)
  const pct = Number(item?.pct ?? 0)
  const loaded = Number(item?.loaded ?? 0)
  const total = Number(item?.total ?? 0)
  const promotion = item?.promotion
  const dates = promotion?.startDate && promotion?.endDate
    ? `${promotion.startDate} - ${promotion.endDate}`
    : item?.periodValue
      ? `${item.periodLabel} ${item.periodValue}`
      : ''
  const barColor = pct >= 80 ? '#10B981' : pct >= 40 ? 'var(--brand)' : '#F59E0B'
  const close = () => window.closePromoDetail?.()

  return (
    <div
      key={replacementKey}
      className={`promo-detail-overlay ${open ? 'open' : ''}`}
      id="promoDetailOverlay"
      style={{ position: 'fixed' }}
      data-vella-island="promos-detail-overlay"
      data-vella-island-status="explicit-jsx"
      data-vella-react-handlers="onclick"
      onClick={(event) => {
        if (event.target === event.currentTarget) close()
      }}
    >
      <div className="promo-detail-panel" id="promoDetailPanel" style={{ position: 'relative' }}>
        <div className="promo-detail-close" data-vella-react-handlers="onclick" onClick={close}>✕</div>
        <div className="promo-detail-head">
          <div className="promo-detail-title" id="pdTitle">{item?.title ?? 'Акция WB'}</div>
          <div className="promo-detail-meta">
            <span className="promo-badge-auto">{promoTypeLabel(promotion?.type)}</span>
            <span id="pdDateRange" style={{ fontSize: 12.5, color: 'var(--gray-500)' }}>{dates}</span>
          </div>
        </div>
        <div className="promo-detail-body">
          <div id="pdStatusBox"><PromoStatusBox status={item?.decision ?? 'warn'} /></div>
          <div>
            <div className="promo-section-title">Готовность цен</div>
            <div className="promo-participation">
              <div className="promo-participation-val" id="pdParticipation">{pct}%</div>
              <div className="promo-participation-label">SKU с известными порогами</div>
              <div style={{ marginTop: 10 }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: 12, color: 'var(--gray-500)', marginBottom: 4 }}>
                  <span id="pdBarLabel">{formatPromoNumber(loaded)} / {formatPromoNumber(total)}</span>
                  <span id="pdBarPct">{pct}%</span>
                </div>
                <div className="sku-bar-track" style={{ height: 6 }}>
                  <div className="sku-bar-fill" id="pdBarFill" style={{ width: `${pct}%`, height: '100%', background: barColor }} />
                </div>
              </div>
            </div>
          </div>
          <div>
            <div className="promo-section-title">Готовность по кабинетам</div>
            <table className="promo-detail-table">
              <thead>
                <tr>
                  <th>Кабинет</th>
                  <th>Товаров</th>
                  <th>Подходящих</th>
                  <th>% готовности</th>
                  <th>Бустинг</th>
                  <th>Статус</th>
                </tr>
              </thead>
              <tbody id="pdCabinetRows" data-vella-island="promos-detail-cabinet-rows" data-vella-island-status="explicit-jsx">
                <tr>
                  <td style={{ fontWeight: 500, color: 'var(--gray-900)' }}>Основной кабинет</td>
                  <td>{formatPromoNumber(loaded)}</td>
                  <td>{formatPromoNumber(total)}</td>
                  <td>
                    <div style={{ display: 'flex', flexDirection: 'column', gap: 3 }}>
                      <span style={{ fontWeight: 600, color: 'var(--gray-900)' }}>{pct}%</span>
                      <div className="sku-bar-track" style={{ height: 4, width: 60 }}><div className="sku-bar-fill" style={{ width: `${pct}%`, background: barColor }} /></div>
                    </div>
                  </td>
                  <td style={{ fontWeight: 600, color: 'var(--brand)' }}>{promotion?.type === 'flash' ? 'flash' : 'auto'}</td>
                  <td>{(item?.decision ?? 'warn') === 'warn' ? <span className="promo-status-warn">Обновить пороги</span> : <span className="promo-status-ok">Готово</span>}</td>
                </tr>
              </tbody>
            </table>
          </div>
          <div className="promo-advantages">
            <div className="promo-section-title" style={{ color: '#065F46' }}>Преимущества участия</div>
            <ul>
              <li>Увеличенный трафик: карточки участника выводятся выше в поиске</li>
              <li>Авто-скидка WB применяется сверх вашей цены — покупатель видит сниженную</li>
              <li>Бустинг × 2–3 увеличивает показы в категории и рекламных блоках</li>
              <li>Свежий XLSX фиксирует пороги WB и защищает минимальную маржу</li>
            </ul>
          </div>
        </div>
        <div className="promo-detail-footer">
          <button className="btn btn-default" type="button" data-vella-react-handlers="onclick" onClick={close}>Закрыть</button>
          <button className="btn btn-primary" type="button" data-vella-react-handlers="onclick" onClick={() => { window.showToast?.('Выберите XLSX с порогами акции из ЛК WB', 'info'); close() }}>
            <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M21 15v4a2 2 0 01-2 2H5a2 2 0 01-2-2v-4" /><polyline points="17 8 12 3 7 8" /><line x1="12" y1="3" x2="12" y2="15" /></svg>
            Импорт XLSX
          </button>
        </div>
      </div>
    </div>
  )
}

