function historySourceFromEntry(entry: ParityChangelogEntry): HistoryFilterSource {
  if (entry.source === 'system' || entry.source === 'manager' || entry.source === 'bulk' || entry.source === 'wb_sync') return entry.source
  if (entry.actor?.role === 'finance' || entry.actor?.role === 'admin' || entry.actor?.role === 'manager') return 'manager'
  return 'system'
}

