function HistoryIsland({ replacementKey }: { replacementKey: string }) {
  const { accessToken } = useAuth()
  const [entries, setEntries] = useState<ParityChangelogEntry[]>([])
  const [total, setTotal] = useState(0)
  const [search, setSearch] = useState('')
  const [triggerFilter, setTriggerFilter] = useState<HistoryFilterTrigger>('all')
  const [sourceFilter, setSourceFilter] = useState<HistoryFilterSource>('all')
  const [periodFilter, setPeriodFilter] = useState<HistoryPeriodPreset>('today')
  const [periodFrom, setPeriodFrom] = useState(() => {
    const today = new Date()
    today.setDate(today.getDate() - 30)
    return today.toISOString().slice(0, 10)
  })
  const [page, setPage] = useState(1)
  const [loading, setLoading] = useState(false)
  const [loadingMore, setLoadingMore] = useState(false)
  const [error, setError] = useState<string | null>(null)

  useEffect(() => {
    setPage(1)
    setEntries([])
    setTotal(0)
  }, [triggerFilter, sourceFilter, periodFilter, periodFrom])

  useEffect(() => {
    if (!accessToken) {
      setLoading(false)
      setLoadingMore(false)
      setError('Нужна авторизация')
      setEntries([])
      setTotal(0)
      return
    }

    const controller = new AbortController()
    const requestPage = page
    if (page === 1) setLoading(true)
    else setLoadingMore(true)

    const url = new URL('/api/v1/wb-repricer/changelog', window.location.origin)
    url.searchParams.set('limit', String(HISTORY_PAGE_SIZE))
    url.searchParams.set('page', String(page))
    if (triggerFilter !== 'all') url.searchParams.append('trigger', triggerFilter)
    if (periodFilter === 'custom') {
      if (periodFrom) {
        const fromDate = new Date(periodFrom)
        if (!Number.isNaN(fromDate.getTime())) {
          url.searchParams.set('from', fromDate.toISOString())
        }
      }
    } else {
      const fromDate = new Date(Date.now() - HISTORY_PERIOD_MS[periodFilter as Exclude<HistoryPeriodPreset, 'custom'>])
      url.searchParams.set('from', fromDate.toISOString())
    }

    apiRequest<ParityChangelogResponse>(url.pathname + url.search, {
      headers: authorizationHeaders(accessToken),
      signal: controller.signal,
      cache: 'no-store',
    })
      .then((response) => {
        if (controller.signal.aborted || requestPage !== page) return
        const payload = {
          items: Array.isArray(response?.items) ? response.items : [],
          total: Number(response?.total ?? 0),
        }
        setTotal(payload.total)
        setEntries((previous) => {
          if (page === 1) return payload.items
          const seen = new Set(previous.map((item) => item.id))
          const next = payload.items.filter((item) => !seen.has(item.id))
          return [...previous, ...next]
        })
      })
      .catch((loadError) => {
        if (controller.signal.aborted || requestPage !== page) return
        setError(loadError instanceof Error ? loadError.message : 'Не удалось загрузить историю')
      })
      .finally(() => {
        if (controller.signal.aborted || requestPage !== page) return
        if (page === 1) setLoading(false)
        else setLoadingMore(false)
      })

    return () => {
      controller.abort()
    }
  }, [accessToken, page, periodFilter, periodFrom, triggerFilter])

  const periodLabel = useMemo(() => {
    if (periodFilter === 'custom') {
      const fromDate = new Date(periodFrom)
      return `с ${Number.isNaN(fromDate.getTime()) ? periodFrom : fromDate.toLocaleDateString('ru-RU')}`
    }
    return HISTORY_PERIOD_LABEL[periodFilter]
  }, [periodFilter, periodFrom])

  const filteredEntries = useMemo(() => {
    const searchTerm = search.trim().toLowerCase()
    return entries
      .filter((entry) => {
        if (searchTerm && !`${entry.articleId} ${entry.skuName}`.toLowerCase().includes(searchTerm)) return false
        if (sourceFilter !== 'all' && historySourceFromEntry(entry) !== sourceFilter) return false
        return true
      })
  }, [entries, search, sourceFilter])
  const historyGroups = useMemo(() => toHistoryGroups(filteredEntries), [filteredEntries])
  const canLoadMore = entries.length < total

  return (
    <div
      key={replacementKey}
      className="tab-content"
      id="tab-history"
      data-vella-island="history"
      data-vella-island-status="explicit-jsx"
    >
      <div className="hist-body" data-vella-island="history-body" data-vella-island-status="explicit-jsx">
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 14 }}>
          <div>
            <h3 style={{ fontSize: 16, fontWeight: 600, color: 'var(--gray-900)', marginBottom: 3 }}>История изменений</h3>
            <div style={{ fontSize: 13, color: 'var(--gray-500)' }}>Все действия алгоритма и пользователей. Хранится 90 дней.</div>
          </div>
          <button className="btn btn-default btn-sm">
            <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
              <path d="M21 15v4a2 2 0 01-2 2H5a2 2 0 01-2-2v-4" />
              <polyline points="7 10 12 15 17 10" />
            </svg>
            Экспорт лога
          </button>
        </div>

        <div className="hist-filters" data-vella-island="history-filters" data-vella-island-status="explicit-jsx">
          <div className="search" style={{ minWidth: 220 }}>
            <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
              <circle cx="11" cy="11" r="8" />
              <line x1="21" y1="21" x2="16.65" y2="16.65" />
            </svg>
            <input
              type="text"
              placeholder="По артикулу, действию..."
              value={search}
              onChange={(event: ChangeEvent<HTMLInputElement>) => setSearch(event.target.value)}
            />
          </div>
          <select
            className="adv-select"
            style={{ width: 'auto' }}
            value={triggerFilter}
            onChange={(event) => setTriggerFilter(event.target.value as HistoryFilterTrigger)}
          >
            {HISTORY_TRIGGER_OPTIONS.map((option) => <option key={option.value} value={option.value}>{option.label}</option>)}
          </select>
          <select
            className="adv-select"
            style={{ width: 'auto' }}
            value={sourceFilter}
            onChange={(event) => setSourceFilter(event.target.value as HistoryFilterSource)}
          >
            {HISTORY_SOURCE_OPTIONS.map((option) => <option key={option.value} value={option.value}>{option.label}</option>)}
          </select>
          <select
            className="adv-select"
            style={{ width: 'auto' }}
            value={periodFilter}
            onChange={(event) => setPeriodFilter(event.target.value as HistoryPeriodPreset)}
          >
            <option value="today">Сегодня</option>
            <option value="week">7 дней</option>
            <option value="month">30 дней</option>
            <option value="custom">Период…</option>
          </select>
          {periodFilter === 'custom' ? (
            <input
              type="date"
              value={periodFrom}
              onChange={(event) => setPeriodFrom(event.target.value)}
              style={{ width: 136, fontSize: 12, border: '1px solid var(--gray-200)', borderRadius: 8, padding: '4px 6px' }}
            />
          ) : null}
          <span className="row-count" style={{ marginLeft: 'auto' }}>
            {loading ? '…' : filteredEntries.length}
            {' из '}
            {loading ? '…' : total} событий
          </span>
        </div>

        <div className="hist-list" data-vella-island="history-list" data-vella-island-status="explicit-jsx">
          {loading && page === 1 ? (
            <div className="report-comment-history-row">
              <div className="report-comment-history-text">Загружаем журнал изменений…</div>
              <div className="report-comment-history-meta">Источник: /api/v1/wb-repricer/changelog</div>
            </div>
          ) : null}
          {error ? (
            <div style={{ padding: '12px 14px', border: '1px dashed var(--gray-200)', borderRadius: 10, background: 'var(--gray-50)', color: 'var(--gray-500)', fontSize: 12 }}>
              {error}
            </div>
          ) : null}
          {!error && !loading && historyGroups.length === 0 ? (
            <div className="report-comment-history-row">
              <div className="report-comment-history-text">В журнале пока нет записей для выбранных фильтров.</div>
              <div className="report-comment-history-meta">Фильтры применяются к уже загруженным страницам журнала.</div>
            </div>
          ) : (
            historyGroups.map((group) => (
              <Fragment key={group.day}>
                <div className="hist-day">{group.day}</div>
                {group.entries.map((entry) => <HistoryEntryRow key={`${group.day}-${entry.time}-${entry.actor}-${entry.timestamp}`} entry={entry} />)}
              </Fragment>
            ))
          )}
          <div style={{ textAlign: 'center', padding: 14, borderTop: '1px solid var(--gray-100)' }}>
            <button
              className="btn btn-default btn-sm"
              disabled={!canLoadMore || loading || loadingMore}
              type="button"
              onClick={() => setPage((next) => next + 1)}
            >
              {loadingMore ? 'Загружаем ещё...' : `Загрузить ещё ${HISTORY_PAGE_SIZE} событий`}
            </button>
            <div style={{ marginTop: 8, color: 'var(--gray-500)', fontSize: 12 }}>
              Период: {periodLabel}
            </div>
          </div>
        </div>
      </div>
    </div>
  )
}

