const LIQUIDATION_MUTATION_TIMEOUT_MS = 15_000

async function apiRequestWithTimeout<T>(path: string, init: RequestInit, timeoutMs: number, timeoutMessage: string) {
  const controller = new AbortController()
  const timeoutId = window.setTimeout(() => controller.abort(), timeoutMs)
  try {
    return await apiRequest<T>(path, {
      ...init,
      signal: controller.signal,
    })
  } catch (error) {
    if (controller.signal.aborted) throw new Error(timeoutMessage)
    throw error
  } finally {
    window.clearTimeout(timeoutId)
  }
}

type LiqFilter = 'all' | 'candidates' | 'active'

type LiqTableRow = {
  type: 'candidate' | 'active'
  articleId: string
  name: string
  thumb: LiqThumb
  daysSinceLastSale: number
  currentPriceKopecks: number
  pMinKopecks?: number | null
  stockUnits?: number | null
  marginPct?: number | null
  marginStatus?: 'negative' | 'thin' | 'ok' | 'unknown'
  stepPct: number
  recommendedPriceKopecks?: number | null
  targetPriceKopecks?: number | null
  requiresNegativeMarginConfirm?: boolean
}

function formatLiqInteger(value: number | null | undefined) {
  if (value == null || !Number.isFinite(value)) return '—'
  return Math.round(value).toLocaleString('ru-RU')
}

function formatLiqRub(kopecks: number | null | undefined) {
  if (kopecks == null || !Number.isFinite(kopecks)) return '—'
  return `${Math.round(kopecks / 100).toLocaleString('ru-RU')} ₽`
}

function formatLiqPct(value: number | null | undefined) {
  if (value == null || !Number.isFinite(value)) return '—'
  const sign = value > 0 ? '+' : ''
  return `${sign}${Math.round(value)}%`.replace('-', '−')
}

function liqThumbFromName(name: string): LiqThumb {
  const lower = name.toLowerCase()
  if (lower.includes('худи')) return 'hoodie-black'
  if (lower.includes('лонг')) return 'long-white'
  return 'tee-white'
}

function liqAgeColor(days: number) {
  return days >= 30 ? '#DC2626' : '#F59E0B'
}

function liqStockClass(stockUnits: number | null | undefined) {
  if (stockUnits == null || stockUnits <= 0) return 'zero'
  if (stockUnits <= 10) return 'crit'
  return 'low'
}

function liqMarginClass(status: LiqTableRow['marginStatus'], marginPct: number | null | undefined) {
  if (status === 'negative' || (marginPct != null && marginPct < 0)) return 'mg-neg'
  if (status === 'thin' || (marginPct != null && marginPct < 3)) return 'mg-low'
  return 'mg-mid'
}

function liqPotentialLoss(data: LiquidationResponse | null) {
  if (!data) return 0
  return [...data.candidates, ...data.active].reduce((sum, item) => {
    const stock = Number(item.stockUnits ?? 0)
    const pMin = Number(item.pMinKopecks ?? 0)
    const current = Number(item.currentPriceKopecks ?? 0)
    return sum + Math.max(0, pMin - current) * stock
  }, 0)
}

async function loadParityLiquidation(accessToken: string, signal?: AbortSignal) {
  const periodDays = window.__vellaProductsPeriodDays ?? PRODUCTS_DEFAULT_PERIOD_DAYS
  const payload = await apiRequest<LiquidationResponse>(`/api/v1/wb-repricer/liquidation?periodDays=${periodDays}`, {
    headers: authorizationHeaders(accessToken),
    signal,
    cache: 'no-store',
  })
  return {
    candidates: Array.isArray(payload?.candidates) ? payload.candidates : [],
    active: Array.isArray(payload?.active) ? payload.active : [],
    history: Array.isArray(payload?.history) ? payload.history : [],
  }
}

async function startParityLiquidation(accessToken: string, articleIds: string[]) {
  return apiRequestWithTimeout<{ started: boolean }>(
    '/api/v1/wb-repricer/liquidation/start',
    {
      method: 'POST',
      headers: authorizationHeaders(accessToken),
      body: JSON.stringify({ articleIds }),
    },
    LIQUIDATION_MUTATION_TIMEOUT_MS,
    'Backend не ответил на запуск ликвидации за 15 секунд. Проверьте, что API доступен, и попробуйте ещё раз.',
  )
}

async function stopParityLiquidation(accessToken: string, articleId: string) {
  return apiRequestWithTimeout<{ stopped: boolean }>(
    `/api/v1/wb-repricer/liquidation/${encodeURIComponent(articleId)}/stop`,
    {
      method: 'POST',
      headers: authorizationHeaders(accessToken),
    },
    LIQUIDATION_MUTATION_TIMEOUT_MS,
    'Backend не ответил на остановку ликвидации за 15 секунд. Проверьте, что API доступен, и попробуйте ещё раз.',
  )
}

async function confirmParityLiquidationNegativeMargin(accessToken: string, articleId: string) {
  return apiRequestWithTimeout<{ confirmed: boolean; expiresAt: string }>(
    `/api/v1/wb-repricer/liquidation/${encodeURIComponent(articleId)}/confirm-negative`,
    {
      method: 'POST',
      headers: authorizationHeaders(accessToken),
    },
    LIQUIDATION_MUTATION_TIMEOUT_MS,
    'Backend не ответил на подтверждение отрицательной маржи за 15 секунд. Проверьте, что API доступен, и попробуйте ещё раз.',
  )
}

async function runParityLiquidationStep(accessToken: string, articleId: string) {
  const periodDays = window.__vellaProductsPeriodDays ?? PRODUCTS_DEFAULT_PERIOD_DAYS
  return apiRequestWithTimeout<StrategyExecutionReport>(
    `/api/v1/wb-repricer/liquidation/${encodeURIComponent(articleId)}/run-step?periodDays=${periodDays}`,
    {
      method: 'POST',
      headers: authorizationHeaders(accessToken),
    },
    LIQUIDATION_MUTATION_TIMEOUT_MS,
    'Backend не ответил на запуск шага ликвидации за 15 секунд. Проверьте, что API доступен, и попробуйте ещё раз.',
  )
}

