function applyPricesStatusLabel(status: string, isResult: boolean) {
  if (status === 'executed') return isResult ? 'рассчитано' : 'готово'
  if (status === 'blocked') return 'заблокировано'
  if (status === 'failed') return 'ошибка'
  return 'пропуск'
}

function applyPricesStatusClass(status: string) {
  if (status === 'executed') return 'metric-up'
  if (status === 'blocked' || status === 'failed') return 'metric-down'
  return 'metric-warn'
}

function applyPricesReason(item: LiveRepricerExecutionReport['items'][number]) {
  const blockers = Array.isArray(item.blockedReasons) ? item.blockedReasons.map(workStatusReasonText).join(' · ') : ''
  return item.explanation
    || (item.skipReason ? workStatusReasonText(item.skipReason) : '')
    || blockers
    || 'backend не вернул пояснение'
}

function ApplyPricesModalIsland({ replacementKey }: { replacementKey: string }) {
  const { accessToken } = useAuth()
  const [open, setOpen] = useState(false)
  const [articleIds, setArticleIds] = useState<string[]>([])
  const [preview, setPreview] = useState<LiveRepricerExecutionReport | null>(null)
  const [result, setResult] = useState<LiveRepricerExecutionReport | null>(null)
  const [loadingPreview, setLoadingPreview] = useState(false)
  const [applying, setApplying] = useState(false)
  const [error, setError] = useState<string | null>(null)

  useEffect(() => {
    const openModal = (event: Event) => {
      const customEvent = event as CustomEvent<{ articleIds?: string[] }>
      const nextArticleIds = Array.from(new Set((customEvent.detail?.articleIds ?? []).filter(Boolean)))
      setArticleIds(nextArticleIds)
      setPreview(null)
      setResult(null)
      setError(null)
      setOpen(true)
    }
    window.addEventListener('vella:apply-prices-open', openModal)
    return () => window.removeEventListener('vella:apply-prices-open', openModal)
  }, [])

  useEffect(() => {
    if (!open || !accessToken || !articleIds.length) return
    const controller = new AbortController()
    setLoadingPreview(true)
    setError(null)
    void previewLiveRepricerStrategies(accessToken, articleIds, controller.signal)
      .then((payload) => {
        if (!controller.signal.aborted) setPreview(payload)
      })
      .catch((reason) => {
        if (controller.signal.aborted) return
        console.warn('Failed to preview repricer price apply', reason)
        setError(reason instanceof Error ? reason.message : 'Не удалось получить preview цен')
      })
      .finally(() => {
        if (!controller.signal.aborted) setLoadingPreview(false)
      })
    return () => controller.abort()
  }, [accessToken, articleIds, open])

  if (!open) return null

  const activeReport = result ?? preview
  const items = activeReport?.items ?? []
  const readyCount = preview?.executedCount ?? 0
  const increaseCount = items.filter((item) => (item.deltaKopecks ?? 0) > 0).length
  const decreaseCount = items.filter((item) => (item.deltaKopecks ?? 0) < 0).length
  const skippedCount = activeReport?.skippedCount ?? 0
  const blockedCount = activeReport?.blockedCount ?? 0
  const isResult = Boolean(result)

  const close = () => {
    if (applying) return
    setOpen(false)
  }

  const apply = async () => {
    if (!accessToken || !articleIds.length || applying) return
    setApplying(true)
    setError(null)
    try {
      const payload = await executeLiveRepricerStrategies(accessToken, articleIds, undefined, {
        applyPrices: true,
        simulateLocalPrice: false,
      })
      if (!payload) throw new ApiError('Backend вернул пустой результат применения цен', 204)
      setResult(payload)
      prepareProductsBackendLoad()
      try {
        const result = await loadProductsPageFromRuntime(accessToken, window.__vellaProductsListState?.page ?? 1)
        finalizeProductsBackendLoad(result)
      } catch (reloadError) {
        showProductsBackendError(reloadError)
      }
      window.clearSelection?.()
      window.showToast?.(
        `Цены: применено ${payload.executedCount}, пропущено ${payload.skippedCount}, заблокировано ${payload.blockedCount}`,
        payload.executedCount > 0 ? 'success' : 'warn',
      )
    } catch (reason) {
      console.warn('Failed to apply repricer prices', reason)
      setError(reason instanceof Error ? reason.message : 'Не удалось применить цены')
    } finally {
      setApplying(false)
    }
  }

  return (
    <div
      key={replacementKey}
      className="modal-overlay open vella-apply-prices-modal"
      id="m-apply"
      role="presentation"
      onMouseDown={(event) => {
        if (event.target === event.currentTarget) close()
      }}
    >
      <div className="modal lg" role="dialog" aria-modal="true" aria-label="Применение цен" onMouseDown={(event) => event.stopPropagation()}>
        <div className="modal-head">
          <div className="modal-icon brand"><CheckCircle2 size={22} /></div>
          <h2>{articleIds.length ? `${isResult ? 'Результат применения' : 'Применить цены'} к ${articleIds.length} SKU` : 'Сначала выберите SKU'}</h2>
          <p>
            {articleIds.length
              ? 'Будут отправлены только выбранные строки. Backend заново проверит правила, P_MIN/P_MAX, стратегию, ручной режим и блокировки.'
              : 'Отметьте товары галочками в таблице, потом нажмите «Применить цены». Без выбора массовое действие не запускается.'}
          </p>
        </div>
        <div className="modal-body">
          {articleIds.length ? (
            <>
              <div className="modal-summary vella-apply-prices-summary">
                <div><span>Выбрано</span><b>{articleIds.length} SKU</b></div>
                <div><span>{isResult ? 'Применено' : 'Готово к применению'}</span><b style={{ color: 'var(--green-mid)' }}>{activeReport?.executedCount ?? readyCount}</b></div>
                <div><span>Повышение</span><b>{increaseCount}</b></div>
                <div><span>Снижение</span><b>{decreaseCount}</b></div>
                <div><span>Пропуск / блок</span><b style={{ color: blockedCount ? 'var(--red-mid)' : undefined }}>{skippedCount + blockedCount}</b></div>
              </div>
              {loadingPreview ? (
                <div className="vella-apply-prices-state"><span className="vella-products-loading-spinner small" /> Считаем preview по выбранным SKU…</div>
              ) : error ? (
                <div className="vella-apply-prices-error">{error}</div>
              ) : items.length ? (
                <div className="bulk-preview-table-wrap vella-apply-prices-table-wrap">
                  <table className="bulk-preview-table">
                    <thead><tr><th>SKU</th><th>Было → стало</th><th>Статус</th><th>Причина решения</th></tr></thead>
                    <tbody>
                      {items.map((item) => (
                        <tr key={`${item.articleId}-${item.status}-${item.recommendedPriceKopecks ?? 'none'}`}>
                          <td><span className="sku">{item.articleId}</span></td>
                          <td>
                            {formatDrawerKopecks(item.oldPriceKopecks)}
                            {' → '}
                            {item.recommendedPriceKopecks == null ? '—' : formatDrawerKopecks(item.recommendedPriceKopecks)}
                            {item.deltaKopecks ? ` (${item.deltaKopecks > 0 ? '+' : ''}${formatDrawerKopecks(item.deltaKopecks)})` : ''}
                          </td>
                          <td><span className={applyPricesStatusClass(item.status)}>{applyPricesStatusLabel(item.status, isResult)}</span></td>
                          <td>{applyPricesReason(item)}{item.applyState ? ` · ${item.applyState}` : ''}</td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              ) : (
                <div className="vella-apply-prices-state">Backend не вернул строк для выбранных SKU.</div>
              )}
              <div className="bulk-preview-note">
                <span>!</span>
                <div>
                  Это ручной запуск для выбранных товаров. SKU без назначенной стратегии, в ручном режиме или с нарушением защит не должны менять цену и будут показаны как пропуск или блок.
                </div>
              </div>
            </>
          ) : (
            <div className="vella-apply-prices-empty">
              <b>Ничего не будет отправлено в WB.</b>
              <span>Старая модалка с 47 SKU была статическим макетом; теперь кнопка работает только от реального выбора в таблице.</span>
            </div>
          )}
        </div>
        <div className="modal-foot">
          <button className="btn btn-ghost" type="button" onClick={close} disabled={applying}>{isResult ? 'Закрыть' : 'Отмена'}</button>
          {articleIds.length > 0 && !isResult ? (
            <button
              className="btn btn-primary"
              type="button"
              onClick={() => void apply()}
              disabled={loadingPreview || applying || !preview || readyCount <= 0}
            >
              {applying ? 'Применяем…' : `Применить ${readyCount || articleIds.length} цен`}
            </button>
          ) : null}
        </div>
      </div>
    </div>
  )
}

