const WORK_STATUS_STRATEGY_LABELS: Record<string, string> = {
  night_price_mode: 'ночная медиана',
  illiquid: 'ликвидация',
  baskets_orders: 'корзины+заказы',
  baskets_orders_4599: 'корзины+заказы',
  metric_dynamics: 'динамика выручки',
  revenue_dynamics_4600: 'динамика выручки',
}

function workStatusStrategyLabel(frontendStrategyId?: string | null, strategyId?: string | null) {
  const id = frontendStrategyId || strategyId || ''
  return WORK_STATUS_STRATEGY_LABELS[id] ?? (id || 'strategy')
}

function workStatusReasonText(code: string | null | undefined) {
  if (!code) return ''
  return WORK_STATUS_REASON_LABELS[code] ?? code
}

function workStatusApprovalFailure(response: WorkStatusApprovalDecisionResponse) {
  const state = response.job?.state ?? response.approval?.applyState ?? response.approval?.status
  if (state === 'sent') return 'WB принял заявку на изменение цены. Статус применения ещё уточняется, цена обновится после обработки WB.'

  const rowError = response.job?.rowErrors?.find((item) => item.errorText)?.errorText
    ?? response.approval?.rowErrors?.find((item) => item.errorText)?.errorText
  if (rowError) return rowError

  const note = response.job?.notes?.find(Boolean) ?? response.approval?.notes?.find(Boolean)
  if (note) return note

  const blockers = response.job?.blockerIds?.length
    ? response.job.blockerIds
    : response.approval?.blockedReasons
  if (blockers?.length) return blockers.map(workStatusReasonText).join(' · ')

  if (response.approval?.error) return response.approval.error
  const wbStatus = response.job?.wbStatus ?? response.approval?.wbStatus
  if (wbStatus) return `WB не принял изменение цены, статус ${wbStatus}. Проверьте токен, права записи цен и ограничения WB по этому SKU.`
  return 'WB не подтвердил изменение цены. Проверьте токен, права записи цен и подробности в логах worker.'
}

function workStatusExecutionDetails(item: PricingStatusResponse) {
  const execution = item.lastExecution
  if (!execution) return []
  const reasons = [
    execution.skipReason,
    ...(execution.blockedReasons ?? []),
    ...(execution.blockerDetails ?? []).map((detail) => detail.code),
  ]
    .filter((value): value is string => Boolean(value))
    .map(workStatusReasonText)
  const messages = (execution.blockerDetails ?? [])
    .map((detail) => detail.message)
    .filter((value): value is string => Boolean(value))
  return Array.from(new Set([...reasons, ...messages])).filter(Boolean)
}

function workStatusMatchesFilter(item: PricingStatusResponse, filter: WorkStatusFilter) {
  if (filter === 'all') return true
  if (filter === 'liquidation') return item.stage === 'active_liquidation' || item.stage === 'liquidation_pending'
  if (filter === 'pricing') return item.stage === 'active_pricing'
  if (filter === 'manual') return item.stage === 'manual_hold'
  if (filter === 'warmup') return item.stage === 'warmup'
  return item.changelogTotal === 0
}

function workStatusStageClass(stage: PricingStatusResponse['stage']) {
  if (stage === 'active_liquidation' || stage === 'liquidation_pending') return 'danger'
  if (stage === 'manual_hold') return 'manual'
  if (stage === 'warmup') return 'warn'
  return 'ok'
}

function workStatusStrategyName(item: PricingStatusResponse) {
  return item.strategy.name?.trim() || ''
}

function workStatusStrategySourceLabel(item: PricingStatusResponse) {
  const source = item.strategy.assignmentSource
  if (source === 'manual') return 'назначена вручную'
  if (source === 'xlsx') return 'назначена из XLSX'
  if (source === 'derived') return 'расчётный профиль'
  if (source === 'runtime') return 'активна в runtime'
  return 'источник не задан'
}

function workStatusStageLabel(item: PricingStatusResponse) {
  if (item.stage === 'active_liquidation') return 'Ликвидация активна'
  if (item.stage === 'liquidation_pending') return 'Ликвидация ожидает запуска'
  if (item.stage === 'warmup') return 'Прогрев товара'
  if (item.stage === 'manual_hold') return 'Ручной режим'
  if (workStatusStrategyName(item)) return 'Профиль ценообразования'
  return 'Ценообразование без стратегии'
}

function workStatusDecisionSummary(item: PricingStatusResponse) {
  const decision = item.lastDecision
  const oldPrice = decision?.oldPriceKopecks
  const newPrice = decision?.newPriceKopecks
  if (oldPrice && newPrice && oldPrice !== newPrice) {
    const verb = newPrice > oldPrice ? 'Цена повышена' : 'Цена снижена'
    return `${verb}: ${formatDrawerKopecks(oldPrice)} → ${formatDrawerKopecks(newPrice)}`
  }
  if (decision?.timestamp) return `Цена не изменилась: ${drawerReadableDecisionReason(decision.reason) || 'решение записано без смены цены'}`
  if (workStatusStrategyName(item)) {
    return `Последнего события цены нет. ${item.strategy.name} показан как ${workStatusStrategySourceLabel(item)}; изменение появится после рабочего цикла.`
  }
  return drawerPricingLastDecisionText(item, null)
}

function workStatusExecutionStatusClass(status: string | null | undefined) {
  if (status === 'executed') return 'ok'
  if (status === 'blocked' || status === 'failed') return 'danger'
  if (status === 'skipped') return 'warn'
  return 'manual'
}

function workStatusExecutionStatusLabel(status: string | null | undefined) {
  if (status === 'executed') return 'рассчитано'
  if (status === 'blocked') return 'blocked'
  if (status === 'failed') return 'failed'
  if (status === 'skipped') return 'skipped'
  return status || 'нет попыток'
}

function workStatusRuleText(item: PricingStatusResponse) {
  const rules = item.strategy.rules || []
  if (rules.length) return `${workStatusStrategyName(item) || 'Правила'} (${workStatusStrategySourceLabel(item)}): ${rules.map((rule) => `${rule.label}: ${rule.value}`).join(' · ')}`
  if (!workStatusStrategyName(item)) return 'Стратегия не назначена'
  return `${item.strategy.name} (${workStatusStrategySourceLabel(item)})`
}

function workStatusProgressLabel(item: PricingStatusResponse) {
  const progress = item.progress
  if ((progress.kind === 'liquidation' || progress.kind === 'warmup') && progress.currentDay && progress.totalDays) {
    return `день ${progress.currentDay} из ${progress.totalDays}`
  }
  if (progress.kind === 'pricing') {
    if (!workStatusStrategyName(item)) return 'активного цикла нет'
    return `цикл каждые ${progress.syncIntervalHours} ч`
  }
  return 'прогресс не рассчитан'
}

function workStatusNextStepLabel(item: PricingStatusResponse) {
  const progress = item.progress
  if (progress.kind === 'liquidation') return workStatusDueLabel(progress.nextStepAt, 'Следующий шаг', 'Шаг ликвидации просрочен')
  if (progress.kind === 'warmup') return progress.daysLeft > 0 ? `Осталось ${progress.daysLeft} дн.` : 'Прогрев завершён'
  if (!workStatusStrategyName(item)) return 'Цена не будет меняться без стратегии, ликвидации или ручного действия'
  const cycleLabel = workStatusDueLabel(progress.nextStepAt, 'Следующий пересчёт', 'Пересчёт просрочен')
  if (item.strategy.assignmentSource === 'derived') return `Расчётный профиль. ${cycleLabel}`
  return cycleLabel
}

function workStatusChangeClass(entry: ParityChangelogEntry) {
  if (entry.changePct > 0) return 'up'
  if (entry.changePct < 0) return 'down'
  return 'same'
}

function workStatusSourceLabel(source?: string) {
  if (source === 'system') return 'система'
  if (source === 'manager') return 'менеджер'
  if (source === 'bulk') return 'массовое действие'
  return source || 'источник не указан'
}

function workStatusIsOverdue(item: PricingStatusResponse) {
  const nextStepAt = item.progress.nextStepAt
  if (!nextStepAt) return false
  const date = new Date(nextStepAt)
  return !Number.isNaN(date.getTime()) && date.getTime() < Date.now()
}

function workStatusRecommendation(item: PricingStatusResponse) {
  if (item.progress.kind === 'liquidation' && workStatusIsOverdue(item)) {
    return 'Ликвидация активна, но плановый шаг просрочен. Если товар всё ещё нужно ликвидировать, запустите цикл сейчас. Если ликвидация уже не нужна, остановите её. Если запуск цикла ничего не меняет, проверьте Celery worker/beat и доступность WB API.'
  }
  if (item.progress.kind === 'liquidation') {
    return 'Ликвидация активна. Следующий шаг выполнит worker, когда наступит время. Ручной запуск цикла можно использовать для проверки.'
  }
  if (workStatusIsOverdue(item)) {
    return 'Плановый пересчёт просрочен. Запустите цикл сейчас и проверьте scheduler, если событие не появится.'
  }
  return 'История показывает только реальные события changelog: изменение цены, остановку, запуск или подтверждение. Если событий нет, worker ещё не записывал решение по этому SKU.'
}

function workStatusRunMessage(report: StrategyExecutionReport) {
  const item = report.items?.[0]
  if (item?.applyState === 'approval_required') {
    return 'Шаг рассчитан. Подтвердите применение цены во всплывающем окне worker approvals.'
  }
  if (item?.status === 'blocked') return item.explanation || 'Шаг рассчитан, но заблокирован guard-проверкой.'
  if (item?.status === 'skipped') return item.explanation || `Шаг пропущен: ${item.skipReason || 'нет изменения'}`
  if ((report.executedCount ?? 0) > 0) return 'Шаг рассчитан. Если требуется подтверждение, оно появится в worker approvals.'
  return 'Цикл завершён без применения. Проверьте причину в истории или worker status.'
}

function WorkStatusHistoryOverlay({
  state,
  onClose,
  onRunCycle,
  onStopLiquidation,
  actionBusy,
  actionMessage,
}: {
  state: WorkStatusHistoryState
  onClose: () => void
  onRunCycle: () => void
  onStopLiquidation: () => void
  actionBusy: string | null
  actionMessage: string | null
}) {
  const item = state.item
  const isLiquidation = item.progress.kind === 'liquidation' || item.stage === 'active_liquidation' || item.stage === 'liquidation_pending'
  const execution = item.lastExecution
  const executionDetails = workStatusExecutionDetails(item)
  return (
    <div className="work-status-history-overlay" role="presentation" onMouseDown={onClose}>
      <section className="work-status-history-modal" role="dialog" aria-modal="true" aria-label="История решений" onMouseDown={(event) => event.stopPropagation()}>
        <div className="work-status-history-head">
          <div>
            <h3>{item.articleId}</h3>
            <p>{item.skuName}</p>
          </div>
          <button type="button" className="work-status-history-close" onClick={onClose} aria-label="Закрыть">x</button>
        </div>
        <div className="work-status-history-summary">
          <span>{workStatusStageLabel(item)}</span>
          <span>{workStatusStrategyName(item) || 'стратегия не назначена'} · {workStatusStrategySourceLabel(item)}</span>
          <span>текущая цена {formatDrawerKopecks(item.current.priceKopecks)}</span>
          <span>событий всего: {state.total}</span>
          {workStatusIsOverdue(item) ? <span className="work-status-history-overdue">просрочено</span> : null}
        </div>
        <div className="work-status-history-action">
          <div>
            <b>Что делать</b>
            <span>{workStatusRecommendation(item)}</span>
          </div>
          <div className="work-status-history-actions">
            <button type="button" className="btn btn-primary btn-sm" onClick={onRunCycle} disabled={Boolean(actionBusy)}>
              {actionBusy === 'run' ? 'Запускаем…' : 'Запустить цикл сейчас'}
            </button>
            {isLiquidation ? (
              <button type="button" className="btn btn-default btn-sm" onClick={onStopLiquidation} disabled={Boolean(actionBusy)}>
                {actionBusy === 'stop' ? 'Останавливаем…' : 'Остановить ликвидацию'}
              </button>
            ) : null}
          </div>
          {actionMessage ? <div className="work-status-history-action-message">{actionMessage}</div> : null}
          {execution ? (
            <div className="work-status-execution">
              <span className={`work-status-stage ${workStatusExecutionStatusClass(execution.status)}`}>
                {workStatusExecutionStatusLabel(execution.status)}
              </span>
              <b>Последняя попытка worker: {formatDrawerDateTime(execution.createdAt)} · {workStatusStrategyLabel(execution.frontendStrategyId, execution.strategyId)}</b>
              {execution.recommendedPriceKopecks != null ? (
                <small>{formatDrawerKopecks(execution.oldPriceKopecks)} → {formatDrawerKopecks(execution.recommendedPriceKopecks)}</small>
              ) : null}
              {execution.explanation ? <small>{execution.explanation}</small> : null}
              {executionDetails.length ? <small className="work-status-execution-reason">{executionDetails.join(' · ')}</small> : null}
            </div>
          ) : null}
        </div>
        {state.loading ? (
          <div className="work-status-history-empty">Загружаем историю цены…</div>
        ) : state.error ? (
          <div className="work-status-history-error">{state.error}</div>
        ) : state.entries.length ? (
          <div className="work-status-history-list">
            {state.entries.map((entry) => {
              const parts = formatDrawerDateParts(entry.timestamp)
              const reason = drawerReadableDecisionReason(entry.reason) || drawerTriggerLabel(entry.trigger, entry.reason)
              const actor = entry.actor?.name || entry.actor?.role || 'не указан'
              return (
                <div key={entry.id} className="work-status-history-row">
                  <div className="work-status-history-time">
                    <b>{parts.day}</b>
                    <span>{parts.time}</span>
                  </div>
                  <div className={`work-status-history-delta ${workStatusChangeClass(entry)}`}>
                    {entry.changePct === 0 ? '±0%' : `${entry.changePct > 0 ? '+' : ''}${entry.changePct.toFixed(1)}%`}
                  </div>
                  <div className="work-status-history-body">
                    <div className="work-status-history-price">
                      {formatDrawerKopecks(entry.oldPriceKopecks)} → <b>{formatDrawerKopecks(entry.newPriceKopecks)}</b>
                    </div>
                    <div className="work-status-history-reason">{reason}</div>
                    <div className="work-status-history-meta">
                      {drawerTriggerLabel(entry.trigger, entry.reason)} · {actor} · {workStatusSourceLabel(entry.source)}
                    </div>
                  </div>
                </div>
              )
            })}
          </div>
        ) : (
          <div className="work-status-history-empty">
            <b>В changelog нет событий по этому SKU.</b>
            <span>{workStatusDecisionSummary(item)}</span>
            <span>{workStatusNextStepLabel(item)}</span>
          </div>
        )}
      </section>
    </div>
  )
}

function WorkStatusPageIsland({ replacementKey }: { replacementKey: string }) {
  const { accessToken } = useAuth()
  const [data, setData] = useState<WorkStatusResponse | null>(null)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [filter, setFilter] = useState<WorkStatusFilter>('all')
  const [search, setSearch] = useState('')
  const [history, setHistory] = useState<WorkStatusHistoryState | null>(null)
  const [reloadTick, setReloadTick] = useState(0)
  const [actionBusy, setActionBusy] = useState<string | null>(null)
  const [actionMessage, setActionMessage] = useState<string | null>(null)
  const [approvalBusy, setApprovalBusy] = useState<string | null>(null)
  const [approvalError, setApprovalError] = useState<string | null>(null)
  const [failedApproval, setFailedApproval] = useState<WorkStatusPriceApproval | null>(null)

  useEffect(() => {
    if (!accessToken) {
      setData(null)
      setError('Нужна авторизация')
      return
    }
    const controller = new AbortController()
    setLoading(true)
    setError(null)
    apiRequest<WorkStatusResponse>('/api/v1/wb-repricer/work-status?periodDays=7&limit=160', {
      headers: authorizationHeaders(accessToken),
      signal: controller.signal,
      cache: 'no-store',
    })
      .then((payload) => {
        if (controller.signal.aborted) return
        const response = payload ?? {
          items: [],
          summary: {} as Partial<WorkStatusSummary>,
          pendingApprovals: [],
          generatedAt: new Date().toISOString(),
          periodDays: 7,
          limit: 160,
        }
        setData({
          generatedAt: response.generatedAt || new Date().toISOString(),
          periodDays: Number(response.periodDays ?? 7),
          limit: Number(response.limit ?? 160),
          items: Array.isArray(response.items) ? response.items : [],
          pendingApprovals: Array.isArray(response.pendingApprovals) ? response.pendingApprovals : [],
          summary: {
            total: Number(response.summary?.total ?? 0),
            activeLiquidation: Number(response.summary?.activeLiquidation ?? 0),
            liquidationPending: Number(response.summary?.liquidationPending ?? 0),
            warmup: Number(response.summary?.warmup ?? 0),
            manualHold: Number(response.summary?.manualHold ?? 0),
            activePricing: Number(response.summary?.activePricing ?? 0),
            changed24h: Number(response.summary?.changed24h ?? 0),
            withoutChangelog: Number(response.summary?.withoutChangelog ?? 0),
            failedExecutions: Number(response.summary?.failedExecutions ?? 0),
            negativeMarginConfirmRequired: Number(response.summary?.negativeMarginConfirmRequired ?? 0),
          },
        })
      })
      .catch((loadError) => {
        if (controller.signal.aborted) return
        setError(loadError instanceof Error ? loadError.message : 'Не удалось загрузить статус работы')
      })
      .finally(() => {
        if (!controller.signal.aborted) setLoading(false)
      })
    return () => controller.abort()
  }, [accessToken, reloadTick])

  const items = useMemo(() => {
    const needle = search.trim().toLowerCase()
    return (data?.items ?? []).filter((item) => {
      if (!workStatusMatchesFilter(item, filter)) return false
      if (!needle) return true
      return `${item.articleId} ${item.skuName} ${item.strategy.name ?? ''}`.toLowerCase().includes(needle)
    })
  }, [data?.items, filter, search])

  const summary = data?.summary
  const currentApproval = data?.pendingApprovals?.find((item) => item.status === 'pending') ?? null
  const approvalModal = currentApproval ?? (approvalError && failedApproval ? failedApproval : null)
  const approvalCanDecide = approvalModal?.status === 'pending'
  const pendingApprovalCount = (data?.pendingApprovals ?? []).filter((item) => item.status === 'pending').length

  async function decidePendingApproval(approvalId: string, decision: 'approve' | 'reject') {
    if (!accessToken) return
    setApprovalBusy(`${decision}:${approvalId}`)
    setApprovalError(null)
    setFailedApproval(null)
    try {
      const response = await apiRequest<WorkStatusApprovalDecisionResponse>(
        `/api/v1/wb-repricer/price-approvals/${encodeURIComponent(approvalId)}/${decision}`,
        {
          method: 'POST',
          headers: authorizationHeaders(accessToken),
          body: JSON.stringify({
            reason: decision === 'approve'
              ? 'manager confirmed worker price change from work status'
              : 'manager rejected worker price change from work status',
          }),
          cache: 'no-store',
        },
      )
      if (decision === 'approve') {
        const state = response?.job?.state ?? response?.approval?.applyState ?? response?.approval?.status
        if (!state || !WORK_STATUS_SUCCESSFUL_PRICE_APPLY_STATES.has(state)) {
          setFailedApproval(response?.approval ?? approvalModal ?? null)
          setApprovalError(workStatusApprovalFailure(response ?? {}))
          setReloadTick((tick) => tick + 1)
          return
        }
      }
      resetLiveRepricerParityCache()
      window.dispatchEvent(new CustomEvent('vella:products-rows-updated'))
      window.dispatchEvent(new CustomEvent('vella:products-kpi-updated'))
      if (decision === 'reject') {
        setData((current) => current
          ? {
              ...current,
              pendingApprovals: (current.pendingApprovals ?? []).filter((item) => item.approvalId !== approvalId),
            }
          : current)
      } else {
        setReloadTick((tick) => tick + 1)
      }
    } catch (decisionError) {
      setApprovalError(decisionError instanceof Error ? decisionError.message : 'Не удалось обработать подтверждение цены')
    } finally {
      setApprovalBusy(null)
    }
  }

  async function decideAllPendingApprovals(decision: 'approve' | 'reject') {
    if (!accessToken) return
    const targets = (data?.pendingApprovals ?? []).filter((item) => item.status === 'pending')
    if (!targets.length) return
    setApprovalBusy(`${decision}:all`)
    setApprovalError(null)
    setFailedApproval(null)
    try {
      const response = await apiRequest<WorkStatusApprovalBulkDecisionResponse>(
        '/api/v1/wb-repricer/price-approvals/bulk',
        {
          method: 'POST',
          headers: authorizationHeaders(accessToken),
          body: JSON.stringify({
            approvalIds: targets.map((item) => item.approvalId),
            decision,
            reason: decision === 'approve'
              ? 'manager confirmed all worker price changes from work status'
              : 'manager rejected all worker price changes from work status',
          }),
          cache: 'no-store',
        },
      )
      const results = response?.results ?? []
      if (!results.length) throw new Error('Сервер не вернул результат обработки цен')
      const succeededIds = new Set(results.filter((item) => item.ok).map((item) => item.approvalId))
      setData((current) => current
        ? {
            ...current,
            pendingApprovals: (current.pendingApprovals ?? []).filter((item) => !succeededIds.has(item.approvalId)),
          }
        : current)
      if (succeededIds.size) {
        resetLiveRepricerParityCache()
        window.dispatchEvent(new CustomEvent('vella:products-rows-updated'))
        window.dispatchEvent(new CustomEvent('vella:products-kpi-updated'))
      }
      const failed = results.find((item) => !item.ok)
      if (failed) {
        setFailedApproval(failed.approval ?? targets.find((item) => item.approvalId === failed.approvalId) ?? null)
        setApprovalError(failed.approval || failed.job ? workStatusApprovalFailure(failed) : failed.error || 'Не удалось обработать часть цен')
      }
      if (decision === 'approve' || failed) setReloadTick((tick) => tick + 1)
    } catch (decisionError) {
      const message = decisionError instanceof Error ? decisionError.message : 'Не удалось обработать подтверждения цен'
      setApprovalError(message.includes('PENDING_PRICE_APPROVAL_ALREADY_CLOSED') ? 'Часть цен уже обработана. Обновляем список.' : message)
      setReloadTick((tick) => tick + 1)
    } finally {
      setApprovalBusy(null)
    }
  }

  function openHistory(item: PricingStatusResponse) {
    setActionMessage(null)
    setHistory({
      item,
      entries: item.recentChanges as ParityChangelogEntry[],
      total: item.changelogTotal,
      loading: Boolean(accessToken),
      error: accessToken ? null : 'Нужна авторизация',
    })
    if (!accessToken) return
    apiRequest<ParityChangelogResponse>(`/api/v1/wb-repricer/sku/${encodeURIComponent(item.articleId)}/changelog?limit=100`, {
      headers: authorizationHeaders(accessToken),
      cache: 'no-store',
    })
      .then((payload) => {
        setHistory((current) => current?.item.articleId === item.articleId
          ? {
              item,
              entries: Array.isArray(payload?.items) ? payload.items : [],
              total: Number(payload?.total ?? 0),
              loading: false,
              error: null,
            }
          : current)
      })
      .catch((loadError) => {
        setHistory((current) => current?.item.articleId === item.articleId
          ? {
              ...current,
              loading: false,
              error: loadError instanceof Error ? loadError.message : 'Не удалось загрузить историю цены',
            }
          : current)
      })
  }

  async function runCycleNow() {
    if (!accessToken || !history) return
    setActionBusy('run')
    setActionMessage(null)
    try {
      const item = history.item
      const report = item.progress.kind === 'liquidation' || item.stage === 'active_liquidation' || item.stage === 'liquidation_pending'
        ? await runParityLiquidationStep(accessToken, item.articleId)
        : await apiRequest<StrategyExecutionReport>('/api/v1/wb-repricer/strategies/execute-assigned?applyPrices=false', {
            method: 'POST',
            headers: authorizationHeaders(accessToken),
          })
      setActionMessage(workStatusRunMessage(report ?? {}))
      if (report?.items?.some((result) => result.applyState === 'approval_required')) {
        setHistory(null)
      }
      setReloadTick((tick) => tick + 1)
    } catch (actionError) {
      setActionMessage(actionError instanceof Error ? actionError.message : 'Не удалось запустить цикл')
    } finally {
      setActionBusy(null)
    }
  }

  async function stopHistoryLiquidation() {
    if (!accessToken || !history) return
    setActionBusy('stop')
    setActionMessage(null)
    try {
      await stopParityLiquidation(accessToken, history.item.articleId)
      setActionMessage('Ликвидация остановлена. Статус обновляется.')
      setReloadTick((tick) => tick + 1)
    } catch (actionError) {
      setActionMessage(actionError instanceof Error ? actionError.message : 'Не удалось остановить ликвидацию')
    } finally {
      setActionBusy(null)
    }
  }

  async function runLiquidationStepFromRow(item: PricingStatusResponse) {
    if (!accessToken) return
    setActionBusy(`run:${item.articleId}`)
    setActionMessage(null)
    try {
      const report = await runParityLiquidationStep(accessToken, item.articleId) ?? {}
      window.showToast?.(workStatusRunMessage(report), (report.blockedCount ?? 0) > 0 ? 'warn' : 'info')
      if (report.items?.some((result) => result.applyState === 'approval_required')) {
        setHistory(null)
      }
      setReloadTick((tick) => tick + 1)
    } catch (actionError) {
      window.showToast?.(actionError instanceof Error ? actionError.message : 'Не удалось запустить шаг ликвидации', 'warn')
    } finally {
      setActionBusy(null)
    }
  }

  return (
    <section
      key={replacementKey}
      className="tab-content active work-status-page"
      id="tab-work-status"
      data-vella-island="work-status"
      data-vella-island-status="explicit-jsx"
    >
      <div className="work-status-head">
        <div>
          <h3>Статус работы</h3>
          <p>Ликвидация, стратегии, применённые правила и последние решения воркера.</p>
        </div>
        <div className="work-status-generated">{data?.generatedAt ? `обновлено ${formatDrawerDateTime(data.generatedAt)}` : loading ? 'загрузка…' : 'нет данных'}</div>
      </div>

      <div className="stats work-status-kpis">
        <div className="stat"><div className="stat-label">SKU в проверке</div><div className="stat-value">{summary?.total ?? '—'}</div><div className="stat-sub">лимит {data?.limit ?? 160}</div></div>
        <div className="stat"><div className="stat-label">Ликвидация</div><div className="stat-value">{summary ? summary.activeLiquidation + summary.liquidationPending : '—'}</div><div className="stat-sub">активно {summary?.activeLiquidation ?? 0}</div></div>
        <div className="stat"><div className="stat-label">Стратегии</div><div className="stat-value">{summary?.activePricing ?? '—'}</div><div className="stat-sub">автоциклы</div></div>
        <div className="stat"><div className="stat-label">Ручной / прогрев</div><div className="stat-value">{summary ? summary.manualHold + summary.warmup : '—'}</div><div className="stat-sub">без автоцены</div></div>
        <div className="stat"><div className="stat-label">Обновления за сутки</div><div className="stat-value">{summary?.changed24h ?? '—'}</div><div className="stat-sub">по истории решений</div></div>
        <div className="stat"><div className="stat-label">Неуспешные попытки</div><div className="stat-value">{summary?.failedExecutions ?? '—'}</div><div className="stat-sub">{summary?.withoutChangelog ?? 0} без истории</div></div>
      </div>

      <div className="toolbar work-status-toolbar">
        <div className="search" style={{ minWidth: 260 }}>
          <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
            <circle cx="11" cy="11" r="8" />
            <line x1="21" y1="21" x2="16.65" y2="16.65" />
          </svg>
          <input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Артикул, товар, стратегия" />
        </div>
        <div className="chips">
          {WORK_STATUS_FILTERS.map((option) => (
            <button key={option.value} type="button" className={`chip ${filter === option.value ? 'active' : ''}`} onClick={() => setFilter(option.value)}>
              {option.label}
            </button>
          ))}
        </div>
        <span className="row-count">{loading ? '…' : items.length} строк</span>
      </div>

      {error ? <div className="work-status-error">{error}</div> : null}

      <div className="report-table-wrap work-status-table-wrap">
        <table className="report-wide work-status-table">
          <thead>
            <tr>
              <th>Товар</th>
              <th>Этап</th>
              <th>Цены и защита</th>
              <th>Решение воркера</th>
              <th>Правила</th>
              <th>Следующий шаг</th>
            </tr>
          </thead>
          <tbody>
            {loading && !data ? (
              <tr><td colSpan={6}><div className="work-status-empty">Загружаем статус работы…</div></td></tr>
            ) : null}
            {!loading && !error && items.length === 0 ? (
              <tr><td colSpan={6}><div className="work-status-empty">По текущему фильтру ничего нет.</div></td></tr>
            ) : null}
            {items.map((item) => {
              const execution = item.lastExecution
              const executionDetails = workStatusExecutionDetails(item)
              return (
              <tr key={item.articleId}>
                <td>
                  <div className="work-status-sku">{item.articleId}</div>
                  <div className="work-status-name">{item.skuName}</div>
                  <a className="work-status-link" href={`/wb/repricer/sku/${encodeURIComponent(item.articleId)}`}>карточка товара</a>
                </td>
                <td>
                  <span className={`work-status-stage ${workStatusStageClass(item.stage)}`}>{workStatusStageLabel(item)}</span>
                  <div className="work-status-muted">{workStatusStrategyName(item) || 'стратегия не назначена'} · {workStatusStrategySourceLabel(item)}</div>
                </td>
                <td>
                  <div className="work-status-price">{formatDrawerKopecks(item.current.priceKopecks)}</div>
                  <div className="work-status-muted">P_MIN {formatDrawerKopecks(item.current.pMinKopecks)} · P_MAX {formatDrawerKopecks(item.current.pMaxKopecks)}</div>
                  <div className="work-status-muted">Маржа {item.current.marginPct == null ? '—' : `${Number(item.current.marginPct.toFixed(1))}%`} · остаток {item.current.stockUnits ?? '—'}</div>
                </td>
                <td>
                  <button type="button" className="work-status-decision-button" onClick={() => openHistory(item)}>
                    <span className="work-status-decision">{workStatusDecisionSummary(item)}</span>
                    <span className="work-status-decision-link">история решений</span>
                  </button>
                  <div className="work-status-muted">событий: {item.changelogTotal}</div>
                  {execution ? (
                    <div className="work-status-execution">
                      <span className={`work-status-stage ${workStatusExecutionStatusClass(execution.status)}`}>
                        {workStatusExecutionStatusLabel(execution.status)}
                      </span>
                      <b>{formatDrawerDateTime(execution.createdAt)} · {workStatusStrategyLabel(execution.frontendStrategyId, execution.strategyId)}</b>
                      {execution.recommendedPriceKopecks != null ? (
                        <small>{formatDrawerKopecks(execution.oldPriceKopecks)} → {formatDrawerKopecks(execution.recommendedPriceKopecks)}</small>
                      ) : null}
                      {execution.explanation ? <small>{execution.explanation}</small> : null}
                      {executionDetails.length ? <small className="work-status-execution-reason">{executionDetails.join(' · ')}</small> : null}
                    </div>
                  ) : null}
                </td>
                <td>
                  <div className="work-status-rules">{workStatusRuleText(item)}</div>
                </td>
                <td>
                  <div className="work-status-next">{workStatusProgressLabel(item)}</div>
                  <div className="work-status-muted">{workStatusNextStepLabel(item)}</div>
                  {(item.progress.kind === 'liquidation' || item.stage === 'active_liquidation' || item.stage === 'liquidation_pending') && workStatusIsOverdue(item) ? (
                    <button
                      type="button"
                      className="btn btn-primary btn-sm"
                      style={{ marginTop: 8 }}
                      disabled={actionBusy === `run:${item.articleId}`}
                      onClick={() => runLiquidationStepFromRow(item)}
                    >
                      {actionBusy === `run:${item.articleId}` ? 'Считаем…' : 'Сделать шаг'}
                    </button>
                  ) : null}
                </td>
              </tr>
              )
            })}
          </tbody>
        </table>
      </div>
      {history ? (
        <WorkStatusHistoryOverlay
          state={history}
          onClose={() => setHistory(null)}
          onRunCycle={runCycleNow}
          onStopLiquidation={stopHistoryLiquidation}
          actionBusy={actionBusy}
          actionMessage={actionMessage}
        />
      ) : null}
      {approvalModal ? (
        <div className="worker-approval-backdrop" role="presentation">
          <section className="worker-approval-modal" role="dialog" aria-modal="true" aria-labelledby="work-status-approval-title">
            <div className="worker-approval-head">
              <div className="worker-approval-mark"><AlertTriangle size={20} /></div>
              <div>
                <h2 id="work-status-approval-title">{approvalCanDecide ? 'Worker хочет изменить цену' : 'WB не принял изменение цены'}</h2>
                <p>{approvalModal.articleId} · {approvalModal.strategyName || workStatusStrategyLabel(approvalModal.frontendStrategyId, approvalModal.strategyId)}</p>
              </div>
            </div>
            <div className="worker-approval-price">
              <span>{formatDrawerKopecks(approvalModal.oldPriceKopecks)}</span>
              <b>→</b>
              <strong>{formatDrawerKopecks(approvalModal.recommendedPriceKopecks)}</strong>
              {approvalModal.deltaKopecks ? <em>{approvalModal.deltaKopecks > 0 ? '+' : ''}{formatDrawerKopecks(approvalModal.deltaKopecks)}</em> : null}
            </div>
            <div className="worker-approval-reason">
              {approvalModal.explanation || 'Worker рассчитал цену, но автоотправка в WB выключена. Нужен ручной approve.'}
            </div>
            {approvalError ? <div className="worker-approval-error">{approvalError}</div> : null}
            <div className="worker-approval-actions">
              {approvalCanDecide ? (
                <>
                  {pendingApprovalCount > 1 ? (
                    <>
                      <button
                        type="button"
                        className="worker-approval-btn ghost"
                        onClick={() => void decideAllPendingApprovals('reject')}
                        disabled={approvalBusy !== null}
                      >
                        <X size={15} /> Отклонить все цены {pendingApprovalCount}
                      </button>
                      <button
                        type="button"
                        className="worker-approval-btn primary"
                        onClick={() => void decideAllPendingApprovals('approve')}
                        disabled={approvalBusy !== null}
                      >
                        <CheckCircle2 size={15} /> {approvalBusy === 'approve:all' ? 'Принимаю все…' : `Принять все цены ${pendingApprovalCount}`}
                      </button>
                    </>
                  ) : null}
                  <button
                    type="button"
                    className="worker-approval-btn ghost"
                    onClick={() => void decidePendingApproval(approvalModal.approvalId, 'reject')}
                    disabled={approvalBusy !== null}
                  >
                    <X size={15} /> Не отправлять
                  </button>
                  <button
                    type="button"
                    className="worker-approval-btn primary"
                    onClick={() => void decidePendingApproval(approvalModal.approvalId, 'approve')}
                    disabled={approvalBusy !== null}
                  >
                    <CheckCircle2 size={15} /> {approvalBusy?.startsWith('approve:') ? 'Отправляю…' : 'Отправить в WB'}
                  </button>
                </>
              ) : (
                <button
                  type="button"
                  className="worker-approval-btn ghost"
                  onClick={() => {
                    setApprovalError(null)
                    setFailedApproval(null)
                    setReloadTick((tick) => tick + 1)
                  }}
                >
                  <X size={15} /> Закрыть
                </button>
              )}
            </div>
          </section>
        </div>
      ) : null}
    </section>
  )
}

const VellaShellIsland = memo(function VellaShellIsland({ shellIsland, mode }: { shellIsland: ShellIslandRuntime; mode: 'default' | 'work-status' }) {
  const isWorkStatus = mode === 'work-status'
  return (
    <>
      <ShellSidebarIsland html={shellIsland.sidebarHtml} />
      <main className={shellIsland.mainClassName} style={styleAttributeToObject(shellIsland.mainStyleText)}>
        {htmlFragment(shellIsland.mainBeforeTopbarHtml, 'main-before-topbar')}
        <ShellTopbarIsland html={shellIsland.topbarHtml} />
        {htmlFragment(shellIsland.mainBetweenTopbarAndSubtabsHtml, 'main-between-topbar-and-subtabs')}
        {isWorkStatus ? (
          <WorkStatusPageIsland replacementKey="work-status-page" />
        ) : (
          <>
            <ShellSubtabsIsland html={shellIsland.subtabsHtml} />
            {htmlToReactFragment(shellIsland.mainAfterSubtabsBeforeDigestHtml, 'main-after-subtabs-before-digest', shellReplacements)}
            {htmlToReactFragment(shellIsland.digestHtml, 'digest-content', shellReplacements)}
            {htmlToReactFragment(shellIsland.mainAfterDigestBeforeAbcHtml, 'main-after-digest-before-abc', shellReplacements)}
            {htmlToReactFragment(shellIsland.abcHtml, 'abc-content', shellReplacements)}
            {htmlToReactFragment(shellIsland.mainAfterAbcHtml, 'main-after-abc', shellReplacements)}
          </>
        )}
      </main>
      {htmlFragmentWithTopLevelReplacements(shellIsland.bodyTailHtml, 'body-tail', bodyTailReplacements)}
    </>
  )
})

