  pmaxBeforeSpp?: number
  pminBeforeSpp?: number
  pminAfterSpp?: number
  pmaxAfterSpp?: number
  pminFinal?: number
  pmaxFinal?: number
  bsk?: number
  ordersPeriod?: number | null
  buyout?: number | null
  revenue7d?: number | null
  mg?: number | null
  mgRub?: number | null
  netSku?: number | null
  stock?: number | null
  financeState?: string
  commissionPct?: number | null
  baseWbCommissionPct?: number | null
  cogs?: number | null
  logistics?: number | null
  wbWallet?: number | null
  spp?: number | null
  pureSpp?: number | null
  sppSource?: string | null
  sppState?: string | null
  accountedPlatformDiscountPct?: number | null
  accountedWbWalletPct?: number | null
